const fn sdhci_pio_present_ready_mask(write: bool) -> u32 {
    if write {
        SDHCI_SPACE_AVAILABLE
    } else {
        SDHCI_DATA_AVAILABLE
    }
}

const fn sdhci_pio_interrupt_ready_mask(write: bool) -> u32 {
    if write {
        SDHCI_INT_SPACE_AVAIL
    } else {
        SDHCI_INT_DATA_AVAIL
    }
}

