/// Private bounded staging for one exact DPC event's passive child timings.
///
/// This state is diagnostic only: no scheduler, wake, retry, timeout, queue,
/// or recovery decision reads it.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43DpcChildTimingScratch {
    physical_epoch: u32,
    event_sequence: u32,
    source_cntvct_lo: u32,
    child_count: u16,
    overflow: bool,
    unknown: bool,
    mailbox_mismatch: bool,
    entries:
        [DriverRuntimeCyw43DpcChildTimingEntry; DRIVER_RUNTIME_CYW43_DPC_CHILD_TIMING_ENTRY_CAP],
}

#[cfg(any(target_os = "none", test))]
impl Cyw43DpcChildTimingScratch {
    const fn empty() -> Self {
        Self {
            physical_epoch: 0,
            event_sequence: 0,
            source_cntvct_lo: 0,
            child_count: 0,
            overflow: false,
            unknown: false,
            mailbox_mismatch: false,
            entries: [DriverRuntimeCyw43DpcChildTimingEntry::empty();
                DRIVER_RUNTIME_CYW43_DPC_CHILD_TIMING_ENTRY_CAP],
        }
    }

    fn begin(&mut self, physical_epoch: u32, event_sequence: u32, source_cntvct_lo: u32) {
        *self = Self {
            physical_epoch,
            event_sequence,
            source_cntvct_lo,
            ..Self::empty()
        };
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43DpcChildTimingPublisher {
    publication_sequence: u32,
    physical_epoch: u32,
    last_counted_event_sequence: u32,
    overall_max_source_to_queue_ticks: u32,
    overall_max_source_to_queue_q11: u16,
    overflow_samples: u32,
    unknown_samples: u32,
    mailbox_mismatch_seen: bool,
}

#[cfg(any(target_os = "none", test))]
impl Cyw43DpcChildTimingPublisher {
    const fn empty() -> Self {
        Self {
            publication_sequence: 0,
            physical_epoch: 0,
            last_counted_event_sequence: 0,
            overall_max_source_to_queue_ticks: 0,
            overall_max_source_to_queue_q11: 0,
            overflow_samples: 0,
            unknown_samples: 0,
            mailbox_mismatch_seen: false,
        }
    }

    fn begin_epoch(&mut self, physical_epoch: u32) {
        if self.physical_epoch != physical_epoch {
            *self = Self {
                physical_epoch,
                ..Self::empty()
            };
        }
    }

    fn next_publication_sequence(&mut self) -> u32 {
        self.publication_sequence = self.publication_sequence.wrapping_add(1);
        if self.publication_sequence == 0 {
            self.publication_sequence = 1;
        }
        self.publication_sequence
    }
}

/// Charge one successfully completed physical RX frame to the retained DPC
/// quantum. Glom subframes admitted by that physical frame count separately;
/// a locally consumed or dropped valid frame still charges at least one.
#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_charge_rx_quantum(cursor: &mut Cyw43DpcCursor, admitted_packets: u32) -> bool {
    let charge = admitted_packets.max(1).min(u32::from(CYW43_DPC_RX_BOUND)) as u8;
    cursor.rx_quantum_frames = cursor
        .rx_quantum_frames
        .saturating_add(charge)
        .min(CYW43_DPC_RX_BOUND);
    cursor.rx_quantum_frames == CYW43_DPC_RX_BOUND
}

/// Park only at a complete-frame boundary. No SDIO descriptor or backplane
/// window phase is staged here, so one exact foreground TX may borrow the sole
/// issuer without aliasing DPC payload or controller state.
#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_park_rx_quantum(cursor: &mut Cyw43DpcCursor) {
    cursor.action = Cyw43DpcAction::RxQuantumBoundary;
    cursor.io_kind = Cyw43DpcIoKind::None;
    cursor.io_phase = Cyw43DpcIoPhase::Idle;
    cursor.io_frame = DriverFrameDescriptor::empty();
    cursor.io_block_size = 0;
    cursor.io_block_count = 0;
    cursor.io_preissue_retry_used = false;
}

const fn cyw43_dpc_turn_route(cursor: &Cyw43DpcCursor) -> Cyw43DpcTurnRoute {
    if cursor.child.issued_unknown {
        Cyw43DpcTurnRoute::Quarantine
    } else if cursor.child.active
        && matches!(cursor.child.mode, Cyw43DpcChildMode::OrdinaryContinuation)
        && cursor.child.continuation_grant_required
    {
        Cyw43DpcTurnRoute::GrantChild
    } else if cursor.child.active {
        Cyw43DpcTurnRoute::PollChild
    } else if matches!(cursor.action, Cyw43DpcAction::None) {
        Cyw43DpcTurnRoute::CompleteEvent
    } else if matches!(cursor.io_phase, Cyw43DpcIoPhase::Idle) {
        Cyw43DpcTurnRoute::AdvanceState
    } else {
        Cyw43DpcTurnRoute::SubmitChild
    }
}

const fn cyw43_dpc_normal_exact_continuation_stops(action: Cyw43DpcAction) -> bool {
    matches!(
        action,
        Cyw43DpcAction::None
            | Cyw43DpcAction::RxQuantumBoundary
            | Cyw43DpcAction::RxQueueWait
            | Cyw43DpcAction::RecoverySettle
    )
}

const fn cyw43_dpc_normal_exact_private_step(action: Cyw43DpcAction) -> bool {
    matches!(action, Cyw43DpcAction::FifoWindow)
}

