#[cfg(target_os = "none")]
const MINI_UART_IO_OFFSET: usize = 0x40;
#[cfg(target_os = "none")]
const MINI_UART_IER_OFFSET: usize = 0x44;
#[cfg(target_os = "none")]
const MINI_UART_LSR_OFFSET: usize = 0x54;
const MINI_UART_LSR_RX_READY: u32 = 1;
const MINI_UART_LSR_RX_OVERRUN: u32 = 1 << 1;
#[cfg(target_os = "none")]
const MINI_UART_LSR_TX_EMPTY: u32 = 1 << 5;
#[cfg(target_os = "none")]
const MINI_UART_LSR_TX_IDLE: u32 = 1 << 6;
// The BCM2711 mini-UART FIFO accepts eight bytes. A 26e serial runtime owns a
// 500-us MCS budget, so one activation may fill only one FIFO prefix after an
// empty sample. Re-sampling TX_EMPTY after every byte collapses this safe prefix
// to one byte because the flag describes an empty FIFO, not remaining FIFO
// capacity. The owner blocks on its local TX-empty IRQ between fills, consuming
// no SC while the wire drains, and publishes only the aggregate completion.
const MINI_UART_TX_IMMEDIATE_TURN_BYTES: usize = 8;
const MINI_UART_TX_BACKPRESSURE_TURN_LIMIT: u16 = 64;
const MINI_UART_RX_DRAIN_LIMIT: usize = 128;
const MINI_UART_RX_QUEUE_CAPACITY: usize = 512;
const MINI_UART_IER_RX_INTERRUPT: u32 = 1;
const MINI_UART_IER_TX_INTERRUPT: u32 = 1 << 1;

const fn serial_mini_uart_irq_mask(rx_enabled: bool, tx_enabled: bool) -> u32 {
    (if rx_enabled {
        MINI_UART_IER_RX_INTERRUPT
    } else {
        0
    }) | (if tx_enabled {
        MINI_UART_IER_TX_INTERRUPT
    } else {
        0
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SerialRuntimeRxQueue {
    bytes: [u8; MINI_UART_RX_QUEUE_CAPACITY],
    head: usize,
    len: usize,
    irq_wakes: u32,
    irq_acks: u32,
    irq_ack_failures: u32,
    hardware_overrun_events: u32,
    queue_full_events: u32,
    received_bytes: u32,
    irq_ack_pending: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SerialRuntimeTxCursor {
    command: Option<DriverTaskCommandRecord>,
    admitted_len: usize,
    written: usize,
    backpressure_turns: u16,
}

impl SerialRuntimeTxCursor {
    const fn new() -> Self {
        Self {
            command: None,
            admitted_len: 0,
            written: 0,
            backpressure_turns: 0,
        }
    }

    fn reset(&mut self) {
        *self = Self::new();
    }

    fn service_turn_with<Write>(
        &mut self,
        command: DriverTaskCommandRecord,
        admitted_len: usize,
        mut write: Write,
    ) -> RuntimeCommandTurn
    where
        Write: FnMut(DriverFrameDescriptor, usize, usize) -> usize,
    {
        if admitted_len == 0 {
            self.reset();
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::idle(
                command.sequence,
            ));
        }
        match self.command {
            None => {
                self.command = Some(command);
                self.admitted_len = admitted_len;
                self.written = 0;
                self.backpressure_turns = 0;
            }
            Some(active) if active == command && self.admitted_len == admitted_len => {}
            Some(_) => {
                self.reset();
                return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                    command.sequence,
                    FAULT_REJECTED_COMMAND,
                ));
            }
        }
        let remaining = self.admitted_len.saturating_sub(self.written);
        let accepted = write(command.frame, self.written, remaining);
        if accepted > remaining {
            self.reset();
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                command.sequence,
                FAULT_REJECTED_COMMAND,
            ));
        }
        if accepted == 0 {
            self.backpressure_turns = self.backpressure_turns.saturating_add(1);
            if self.backpressure_turns >= MINI_UART_TX_BACKPRESSURE_TURN_LIMIT {
                self.reset();
                return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                    command.sequence,
                    FAULT_DEVICE_UNAVAILABLE,
                ));
            }
            return RuntimeCommandTurn::Pending;
        }
        self.backpressure_turns = 0;
        self.written = self.written.saturating_add(accepted);
        if self.written != self.admitted_len {
            return RuntimeCommandTurn::Pending;
        }
        let result = self.admitted_len as u32;
        self.reset();
        RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::progress(
            command.sequence,
            result,
        ))
    }
}

impl SerialRuntimeRxQueue {
    const fn new() -> Self {
        Self {
            bytes: [0; MINI_UART_RX_QUEUE_CAPACITY],
            head: 0,
            len: 0,
            irq_wakes: 0,
            irq_acks: 0,
            irq_ack_failures: 0,
            hardware_overrun_events: 0,
            queue_full_events: 0,
            received_bytes: 0,
            irq_ack_pending: false,
        }
    }

    fn reset(&mut self) {
        *self = Self::new();
    }

    fn push(&mut self, byte: u8) -> bool {
        if self.len == MINI_UART_RX_QUEUE_CAPACITY {
            return false;
        }
        let tail = (self.head + self.len) % MINI_UART_RX_QUEUE_CAPACITY;
        self.bytes[tail] = byte;
        self.len += 1;
        self.received_bytes = self.received_bytes.saturating_add(1);
        true
    }

    const fn full(&self) -> bool {
        self.len == MINI_UART_RX_QUEUE_CAPACITY
    }

    fn pop(&mut self) -> Option<u8> {
        if self.len == 0 {
            return None;
        }
        let byte = self.bytes[self.head];
        self.head = (self.head + 1) % MINI_UART_RX_QUEUE_CAPACITY;
        self.len -= 1;
        Some(byte)
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct SerialRxDrainOutcome {
    bytes: usize,
    source_pending: bool,
    hardware_overrun: bool,
}

fn serial_drain_source_to_queue<Status, Read>(
    queue: &mut SerialRuntimeRxQueue,
    limit: usize,
    mut read_status: Status,
    mut read_byte: Read,
) -> SerialRxDrainOutcome
where
    Status: FnMut() -> u32,
    Read: FnMut() -> u8,
{
    let mut outcome = SerialRxDrainOutcome::default();
    while outcome.bytes < limit {
        let status = read_status();
        outcome.hardware_overrun |= status & MINI_UART_LSR_RX_OVERRUN != 0;
        if status & MINI_UART_LSR_RX_READY == 0 {
            break;
        }
        if queue.full() {
            queue.queue_full_events = queue.queue_full_events.saturating_add(1);
            outcome.source_pending = true;
            break;
        }
        let byte = read_byte();
        let queued = queue.push(byte);
        debug_assert!(
            queued,
            "capacity was checked before consuming mini-UART data"
        );
        outcome.bytes = outcome.bytes.saturating_add(1);
    }
    if !outcome.source_pending && outcome.bytes == limit {
        let status = read_status();
        outcome.hardware_overrun |= status & MINI_UART_LSR_RX_OVERRUN != 0;
        outcome.source_pending = status & MINI_UART_LSR_RX_READY != 0;
    }
    if outcome.hardware_overrun {
        queue.hardware_overrun_events = queue.hardware_overrun_events.saturating_add(1);
    }
    outcome
}

fn serial_record_irq_ack(queue: &mut SerialRuntimeRxQueue, acked: bool) {
    queue.irq_ack_pending = !acked;
    if acked {
        queue.irq_acks = queue.irq_acks.saturating_add(1);
    } else {
        queue.irq_ack_failures = queue.irq_ack_failures.saturating_add(1);
    }
}

fn serial_service_irq_with<Drain, Ack>(
    queue: &mut SerialRuntimeRxQueue,
    badge: u32,
    mut drain: Drain,
    mut ack: Ack,
) -> bool
where
    Drain: FnMut(&mut SerialRuntimeRxQueue) -> SerialRxDrainOutcome,
    Ack: FnMut() -> bool,
{
    if badge != DRIVER_RUNTIME_SERIAL_IRQ_BADGE {
        return false;
    }
    queue.irq_wakes = queue.irq_wakes.saturating_add(1);
    let drained = drain(queue);
    if drained.source_pending {
        queue.irq_ack_pending = true;
        return true;
    }
    serial_record_irq_ack(queue, ack());
    true
}

/// Advance one retained serial frame from one owner-local UART IRQ wake.
///
/// The IRQ is a scheduling hint, never counted byte authority. The immutable
/// command and cursor determine the only admissible prefix. Source-clearing
/// work (one TX FIFO fill plus bounded RX drain) precedes handler ACK; the TX
/// source is disabled before ACKing the terminal fill so it cannot immediately
/// reassert after the aggregate completion becomes visible to root.
fn serial_service_tx_irq_turn_with<Drain, Write, SetTxIrq, Ack>(
    queue: &mut SerialRuntimeRxQueue,
    cursor: &mut SerialRuntimeTxCursor,
    command: DriverTaskCommandRecord,
    admitted_len: usize,
    badge: u32,
    mut drain: Drain,
    mut write: Write,
    mut set_tx_irq: SetTxIrq,
    mut ack: Ack,
) -> Option<RuntimeCommandTurn>
where
    Drain: FnMut(&mut SerialRuntimeRxQueue) -> SerialRxDrainOutcome,
    Write: FnMut(DriverFrameDescriptor, usize, usize) -> usize,
    SetTxIrq: FnMut(bool),
    Ack: FnMut() -> bool,
{
    if badge != DRIVER_RUNTIME_SERIAL_IRQ_BADGE {
        return None;
    }
    queue.irq_wakes = queue.irq_wakes.saturating_add(1);
    let turn = cursor.service_turn_with(command, admitted_len, &mut write);
    let drained = drain(queue);
    if drained.source_pending {
        // Root must regain the completion boundary before it can drain a full RX
        // software queue. Leave the level IRQ unacknowledged and fail this TX
        // frame closed instead of sleeping forever behind a masked handler.
        queue.irq_ack_pending = true;
        set_tx_irq(false);
        cursor.reset();
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        ));
    }
    if matches!(turn, RuntimeCommandTurn::Complete(_)) {
        set_tx_irq(false);
    }
    let acked = ack();
    serial_record_irq_ack(queue, acked);
    if !acked {
        set_tx_irq(false);
        cursor.reset();
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        ));
    }
    Some(turn)
}

/// Shared-buffer descriptor passed over the pointer-free driver-task ring.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverFrameDescriptor {
    /// Offset into the ring/shared-buffer arena.
    pub offset: u32,
    /// Valid payload length at `offset`.
    pub len: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
}

impl DriverFrameDescriptor {
    const fn empty() -> Self {
        Self {
            offset: 0,
            len: 0,
            flags: 0,
        }
    }

    fn in_ring_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        len <= MAX_DRIVER_TASK_FRAME_BYTES
            && offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_runtime_init_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset == DRIVER_TASK_RING_FRAME_OFFSET
            && len == core::mem::size_of::<DriverRuntimeInitDescriptor>()
            && len <= usize::from(DRIVER_RUNTIME_INIT_DESCRIPTOR_APERTURE_BYTES)
            && offset.checked_add(len).is_some_and(|end| {
                end <= DRIVER_TASK_RING_FRAME_OFFSET
                    + usize::from(DRIVER_RUNTIME_INIT_DESCRIPTOR_APERTURE_BYTES)
            })
    }

    fn in_ring_page_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_runtime_payload(self, shared_payload_bytes: usize) -> bool {
        if self.in_ring_page_payload() {
            return true;
        }
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES + shared_payload_bytes)
    }
}

/// Primitive budget grant encoded in the root/driver ring ABI.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskBudgetGrant {
    /// Maximum HAL operations admitted for the command.
    pub max_ops: u16,
    /// Maximum frames admitted for the command.
    pub max_frames: u16,
    /// Maximum bytes admitted for the command.
    pub max_bytes: u32,
}

/// Fixed command record consumed by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCommandRecord {
    /// Monotonic root-assigned sequence number.
    pub sequence: u32,
    /// Primitive command opcode.
    pub opcode: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
    /// Opcode-specific primitive argument.
    pub arg0: u32,
    /// Second opcode-specific primitive argument.
    pub arg1: u32,
    /// Auxiliary role-specific argument.
    pub aux0: u32,
    /// Second auxiliary role-specific argument.
    pub aux1: u32,
    /// Per-command service budget.
    pub budget: DriverTaskBudgetGrant,
    /// Shared-buffer descriptor for frame-bearing commands.
    pub frame: DriverFrameDescriptor,
}

impl DriverTaskCommandRecord {
    const fn empty() -> Self {
        Self {
            sequence: 0,
            opcode: 0,
            flags: 0,
            arg0: 0,
            arg1: 0,
            aux0: 0,
            aux1: 0,
            budget: DriverTaskBudgetGrant {
                max_ops: 0,
                max_frames: 0,
                max_bytes: 0,
            },
            frame: DriverFrameDescriptor::empty(),
        }
    }
}

const fn runtime_continuation_action_fingerprint(command: DriverTaskCommandRecord) -> u32 {
    driver_runtime_continuation_action_fingerprint(
        command.opcode,
        command.flags,
        command.arg0,
        command.arg1,
        command.aux0,
        command.aux1,
        command.budget.max_ops,
        command.budget.max_frames,
        command.budget.max_bytes,
        command.frame.offset,
        command.frame.len,
        command.frame.flags,
    )
}

#[cfg(any(target_os = "none", test))]
const fn runtime_delegated_continuation_command(command: DriverTaskCommandRecord) -> bool {
    command.sequence & CYW43_SDIO_BUS_LINK_SEQUENCE_DOMAIN != 0
        && command.arg0 == HOT_PATH_SDIO_HOST
        && command.arg1 == ROLE_SDIO
}

#[cfg(any(target_os = "none", test))]
const fn runtime_continuation_expected_generation(command: DriverTaskCommandRecord) -> Option<u32> {
    if runtime_delegated_continuation_command(command) && command.aux1 != 0 {
        Some(command.aux1)
    } else {
        None
    }
}

#[cfg(any(target_os = "none", test))]
const fn runtime_root_continuation_expected_generation(
    command: DriverTaskCommandRecord,
) -> Option<u32> {
    if driver_runtime_is_cyw43_root_continuation(command.arg0, command.arg1, command.aux0) {
        Some(command.aux1)
    } else {
        None
    }
}

#[cfg(any(target_os = "none", test))]
const fn runtime_command_requires_continuation_grant(command: DriverTaskCommandRecord) -> bool {
    runtime_root_continuation_expected_generation(command).is_some()
        || runtime_delegated_continuation_command(command)
}

#[cfg(any(target_os = "none", test))]
fn runtime_root_generation_admission(
    command: DriverTaskCommandRecord,
    notification_route: RuntimeNotificationRoute,
) -> RuntimeDelegatedGenerationAdmission {
    if notification_route != RuntimeNotificationRoute::Cyw43Client
        || command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        return RuntimeDelegatedGenerationAdmission::NotDelegated;
    }
    match runtime_root_continuation_expected_generation(command) {
        Some(command_generation) => {
            RuntimeDelegatedGenerationAdmission::Admitted(command_generation)
        }
        None => RuntimeDelegatedGenerationAdmission::Rejected,
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeDelegatedGenerationAdmission {
    NotDelegated,
    Admitted(u32),
    Rejected,
}

#[cfg(any(target_os = "none", test))]
fn runtime_delegated_generation_admission(
    command: DriverTaskCommandRecord,
    owner_generation: Option<u32>,
) -> RuntimeDelegatedGenerationAdmission {
    if !runtime_delegated_continuation_command(command) {
        return RuntimeDelegatedGenerationAdmission::NotDelegated;
    }
    let Some(command_generation) = runtime_continuation_expected_generation(command) else {
        return RuntimeDelegatedGenerationAdmission::Rejected;
    };
    if owner_generation == Some(command_generation) {
        RuntimeDelegatedGenerationAdmission::Admitted(command_generation)
    } else {
        RuntimeDelegatedGenerationAdmission::Rejected
    }
}

#[cfg(any(target_os = "none", test))]
const fn runtime_outer_generation_rejection_completion(
    command: DriverTaskCommandRecord,
    delegated: RuntimeDelegatedGenerationAdmission,
    root: RuntimeDelegatedGenerationAdmission,
) -> Option<DriverTaskCompletionRecord> {
    if matches!(delegated, RuntimeDelegatedGenerationAdmission::Rejected)
        || matches!(root, RuntimeDelegatedGenerationAdmission::Rejected)
    {
        Some(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_REJECTED_COMMAND,
            DRIVER_RUNTIME_REJECT_OUTER_GENERATION,
        ))
    } else {
        None
    }
}

#[cfg(any(target_os = "none", test))]
const fn runtime_delegated_command_admission_progress_due(
    admission: RuntimeDelegatedGenerationAdmission,
    last_grant_id: u32,
) -> bool {
    matches!(admission, RuntimeDelegatedGenerationAdmission::Admitted(_)) && last_grant_id == 0
}

#[cfg(any(target_os = "none", test))]
fn runtime_continuation_grant_window(base: usize) -> Option<RuntimeRingWindowKind> {
    if base == DRIVER_TASK_RING_VADDR {
        Some(RuntimeRingWindowKind::Local)
    } else if base == DRIVER_TASK_SDIO_BUS_RING_VADDR {
        Some(RuntimeRingWindowKind::SdioOwner)
    } else {
        None
    }
}

#[cfg(target_os = "none")]
fn runtime_continuation_grant_read_u32(base: usize, field_offset: usize) -> Option<u32> {
    runtime_volatile_read(
        runtime_continuation_grant_window(base)?,
        usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET).checked_add(field_offset)?,
        RuntimeVolatileWidth::U32,
    )
}

#[cfg(all(not(target_os = "none"), test))]
fn runtime_continuation_grant_read_u32(base: usize, field_offset: usize) -> Option<u32> {
    if field_offset.checked_add(core::mem::size_of::<u32>())?
        > usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES)
    {
        return None;
    }
    if let Some(kind) = runtime_continuation_grant_window(base) {
        return runtime_volatile_read(
            kind,
            usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET).checked_add(field_offset)?,
            RuntimeVolatileWidth::U32,
        );
    }
    let address = base
        .checked_add(usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET))?
        .checked_add(field_offset)?;
    if address & (core::mem::align_of::<u32>() - 1) != 0 {
        return None;
    }
    // SAFETY: Host tests pass the base of their live, aligned, page-sized
    // continuation-grant fixture. Checked arithmetic and alignment keep this
    // single primitive access within the fixed 24-byte record.
    Some(unsafe { core::ptr::read_volatile(address as *const u32) })
}

#[cfg(target_os = "none")]
fn runtime_continuation_grant_write_u32(base: usize, field_offset: usize, value: u32) -> bool {
    let Some(offset) =
        usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET).checked_add(field_offset)
    else {
        return false;
    };
    runtime_volatile_write(
        match runtime_continuation_grant_window(base) {
            Some(kind) => kind,
            None => return false,
        },
        offset,
        RuntimeVolatileWidth::U32,
        value,
    )
}

#[cfg(all(not(target_os = "none"), test))]
fn runtime_continuation_grant_write_u32(base: usize, field_offset: usize, value: u32) -> bool {
    if field_offset
        .checked_add(core::mem::size_of::<u32>())
        .is_none_or(|end| end > usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES))
    {
        return false;
    }
    if let Some(kind) = runtime_continuation_grant_window(base) {
        let Some(offset) =
            usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET).checked_add(field_offset)
        else {
            return false;
        };
        return runtime_volatile_write(kind, offset, RuntimeVolatileWidth::U32, value);
    }
    let Some(address) = base
        .checked_add(usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET))
        .and_then(|address| address.checked_add(field_offset))
    else {
        return false;
    };
    if address & (core::mem::align_of::<u32>() - 1) != 0 {
        return false;
    }
    // SAFETY: Host tests pass the base of their live, aligned, page-sized
    // continuation-grant fixture. Checked arithmetic and alignment keep this
    // single primitive access within the fixed 24-byte record.
    unsafe {
        core::ptr::write_volatile(address as *mut u32, value);
    }
    true
}

#[cfg(any(target_os = "none", test))]
fn read_runtime_steady_service_progress_at(
    base: usize,
) -> Option<DriverRuntimeSteadyServiceProgress> {
    let address = base + usize::from(pi4_driver_abi::DRIVER_RUNTIME_STEADY_SERVICE_PROGRESS_OFFSET);
    driver_task_shared_invalidate_range(
        address,
        usize::from(pi4_driver_abi::DRIVER_RUNTIME_STEADY_SERVICE_PROGRESS_BYTES),
    );
    let first_commit = runtime_continuation_grant_read_u32(
        base,
        core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
    )?;
    if first_commit == 0 {
        return None;
    }
    driver_task_shared_load_barrier();
    let observed = DriverRuntimeSteadyServiceProgress {
        magic: runtime_continuation_grant_read_u32(
            base,
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, magic),
        )?,
        request_sequence: runtime_continuation_grant_read_u32(
            base,
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, request_sequence),
        )?,
        action_fingerprint: runtime_continuation_grant_read_u32(
            base,
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, action_fingerprint),
        )?,
        generation: runtime_continuation_grant_read_u32(
            base,
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, generation),
        )?,
        service_slice: runtime_continuation_grant_read_u32(
            base,
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, service_slice),
        )?,
        committed_slice: first_commit,
    };
    driver_task_shared_load_barrier();
    driver_task_shared_invalidate_range(
        address + core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
        core::mem::size_of::<u32>(),
    );
    let second_commit = runtime_continuation_grant_read_u32(
        base,
        core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
    )?;
    (first_commit == second_commit && observed.valid()).then_some(observed)
}

#[cfg(any(target_os = "none", test))]
const fn runtime_steady_service_progress_command_valid(
    command: DriverTaskCommandRecord,
    generation: u32,
) -> bool {
    if command.sequence == 0
        || command.opcode != OPCODE_SERVICE
        || command.flags & DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY == 0
        || command.aux1 != generation
        || generation == 0
    {
        return false;
    }
    let steady = command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0;
    let persistent_sdio = command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0
        && command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE == 0
        && command.arg0 == HOT_PATH_SDIO_HOST
        && command.arg1 == ROLE_SDIO
        && command.aux0 != 0;
    steady || persistent_sdio
}

#[cfg(any(target_os = "none", test))]
fn publish_runtime_steady_service_progress_at(
    base: usize,
    command: DriverTaskCommandRecord,
    generation: u32,
    service_slice: u32,
) -> bool {
    if !runtime_steady_service_progress_command_valid(command, generation) || service_slice == 0 {
        return false;
    }
    let progress = DriverRuntimeSteadyServiceProgress::new(
        command.sequence,
        runtime_continuation_action_fingerprint(command),
        generation,
        service_slice,
    );
    let address = base + usize::from(pi4_driver_abi::DRIVER_RUNTIME_STEADY_SERVICE_PROGRESS_OFFSET);
    if !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
        0,
    ) {
        return false;
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
        core::mem::size_of::<u32>(),
    );
    for (offset, value) in [
        (
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, magic),
            progress.magic,
        ),
        (
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, request_sequence),
            progress.request_sequence,
        ),
        (
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, action_fingerprint),
            progress.action_fingerprint,
        ),
        (
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, generation),
            progress.generation,
        ),
        (
            core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, service_slice),
            progress.service_slice,
        ),
    ] {
        if !runtime_continuation_grant_write_u32(base, offset, value) {
            return false;
        }
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address,
        core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
    );
    if !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
        progress.committed_slice,
    ) {
        return false;
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeSteadyServiceProgress, committed_slice),
        core::mem::size_of::<u32>(),
    );
    true
}

#[cfg(any(target_os = "none", test))]
fn runtime_steady_service_progress_advance(
    progress: Option<DriverRuntimeSteadyServiceProgress>,
    command: DriverTaskCommandRecord,
    generation: u32,
    previous_slice: u32,
) -> Option<u32> {
    let progress = progress?;
    (progress.valid()
        && progress.request_sequence == command.sequence
        && progress.action_fingerprint == runtime_continuation_action_fingerprint(command)
        && progress.generation == generation
        && progress.service_slice > previous_slice)
        .then_some(progress.service_slice)
}

