#[cfg(any(target_os = "none", test))]
fn publish_runtime_continuation_grant_at(
    base: usize,
    command: DriverTaskCommandRecord,
    generation: u32,
    grant_id: u32,
) -> bool {
    let expected_generation = runtime_continuation_expected_generation(command)
        .or_else(|| runtime_root_continuation_expected_generation(command));
    if expected_generation != Some(generation) || grant_id == 0 {
        return false;
    }
    let address = base + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET);
    let grant = DriverRuntimeContinuationGrant::new(
        command.sequence,
        runtime_continuation_action_fingerprint(command),
        generation,
        grant_id,
    );
    if !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        0,
    ) || !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id),
        0,
    ) {
        return false;
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        core::mem::size_of::<u32>() * 2,
    );
    for (offset, value) in [
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, magic),
            grant.magic,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, request_sequence),
            grant.request_sequence,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, action_fingerprint),
            grant.action_fingerprint,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, generation),
            grant.generation,
        ),
    ] {
        if !runtime_continuation_grant_write_u32(base, offset, value) {
            return false;
        }
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
    );
    if !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        grant.grant_id,
    ) {
        return false;
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        core::mem::size_of::<u32>(),
    );
    true
}

#[cfg(any(target_os = "none", test))]
fn acknowledge_runtime_continuation_grant_at(base: usize, grant_id: u32) -> bool {
    if grant_id == 0 {
        return false;
    }
    let address = base + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET);
    let Some(current_id) = runtime_continuation_grant_read_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
    ) else {
        return false;
    };
    if current_id != grant_id {
        return false;
    }
    if !runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id),
        grant_id,
    ) {
        return false;
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id),
        core::mem::size_of::<u32>(),
    );
    // Acknowledgement publication is the irrevocable consumption boundary.
    // The producer may replace this record with the next ID as soon as it
    // observes the acknowledgement, so a post-commit re-read would race a
    // legitimate replacement and could incorrectly roll back spent authority.
    true
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeContinuationGrantProducerState {
    Pending,
    Consumed,
    Invalid,
}

#[cfg(any(target_os = "none", test))]
fn runtime_continuation_grant_producer_state(
    grant: Option<DriverRuntimeContinuationGrant>,
    command: DriverTaskCommandRecord,
    generation: u32,
    grant_id: u32,
) -> RuntimeContinuationGrantProducerState {
    let Some(grant) = grant else {
        return RuntimeContinuationGrantProducerState::Invalid;
    };
    if runtime_continuation_expected_generation(command) != Some(generation)
        || grant.magic != DRIVER_RUNTIME_CONTINUATION_GRANT_MAGIC
        || grant.request_sequence != command.sequence
        || grant.action_fingerprint != runtime_continuation_action_fingerprint(command)
        || grant.generation != generation
        || grant.grant_id != grant_id
        || grant_id == 0
    {
        return RuntimeContinuationGrantProducerState::Invalid;
    }
    if grant.consumed_grant_id == 0 {
        RuntimeContinuationGrantProducerState::Pending
    } else if grant.consumed_grant_id == grant.grant_id {
        RuntimeContinuationGrantProducerState::Consumed
    } else {
        RuntimeContinuationGrantProducerState::Invalid
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_continuation_grant_producer_state_at(
    base: usize,
    command: DriverTaskCommandRecord,
    generation: u32,
    grant_id: u32,
) -> RuntimeContinuationGrantProducerState {
    runtime_continuation_grant_producer_state(
        read_runtime_continuation_grant_at(base),
        command,
        generation,
        grant_id,
    )
}

#[cfg(any(target_os = "none", test))]
const fn runtime_continuation_next_grant_id(current: u32) -> Option<u32> {
    if current == 0 {
        Some(1)
    } else {
        current.checked_add(1)
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeContinuationGrantPlan {
    Publish(u32),
    Resignal(u32),
    Invalid,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_continuation_grant_plan_after_poll(
    current: u32,
    observed: RuntimeContinuationGrantProducerState,
) -> RuntimeContinuationGrantPlan {
    if current == 0 {
        return RuntimeContinuationGrantPlan::Publish(1);
    }
    match observed {
        RuntimeContinuationGrantProducerState::Pending => {
            RuntimeContinuationGrantPlan::Resignal(current)
        }
        RuntimeContinuationGrantProducerState::Consumed => {
            match runtime_continuation_next_grant_id(current) {
                Some(next) => RuntimeContinuationGrantPlan::Publish(next),
                None => RuntimeContinuationGrantPlan::Invalid,
            }
        }
        RuntimeContinuationGrantProducerState::Invalid => RuntimeContinuationGrantPlan::Invalid,
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_continuation_grant_plan_at_poll(
    base: usize,
    command: DriverTaskCommandRecord,
    generation: u32,
    current: u32,
) -> RuntimeContinuationGrantPlan {
    let observed = if current == 0 {
        // No grant exists before the first missed completion poll. Avoid a
        // speculative shared-ring read and plan the first publication locally.
        RuntimeContinuationGrantProducerState::Pending
    } else {
        runtime_continuation_grant_producer_state_at(base, command, generation, current)
    };
    runtime_continuation_grant_plan_after_poll(current, observed)
}

#[cfg(any(target_os = "none", test))]
fn clear_runtime_continuation_grant_at(base: usize) {
    let address = base + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET);
    let _ = runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        0,
    );
    let _ = runtime_continuation_grant_write_u32(
        base,
        core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id),
        0,
    );
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        address + core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id),
        core::mem::size_of::<u32>() * 2,
    );
}

/// Completion record written by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCompletionRecord {
    /// Completed command sequence.
    pub sequence: u32,
    /// Primitive completion code.
    pub code: u16,
    /// Fault code or role-specific detail.
    pub detail: u16,
    /// Role-specific primitive result.
    pub result: u32,
    /// Shared-buffer descriptor for frame-bearing completions.
    pub frame: DriverFrameDescriptor,
}

impl DriverTaskCompletionRecord {
    const fn progress(sequence: u32, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail: FAULT_NONE,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn progress_with_detail(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn frame_ready(sequence: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_at(sequence: u32, offset: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_with_descriptor(sequence: u32, frame: DriverFrameDescriptor) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: frame.len as u32,
            frame,
        }
    }

    const fn keyboard_input_ready(sequence: u32, len: u16) -> Self {
        Self::frame_ready_with_descriptor(
            sequence,
            DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len,
                flags: DRIVER_RUNTIME_USB_KEYBOARD_FRAME_FLAG_INPUT,
            },
        )
    }

    const fn idle(sequence: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail: FAULT_NONE,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn idle_with_detail_and_frame(
        sequence: u32,
        detail: u16,
        result: u32,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail,
            result,
            frame,
        }
    }

    const fn budget_exhausted(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_BUDGET_EXHAUSTED,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result_and_frame(
        sequence: u32,
        detail: u16,
        result: u32,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame,
        }
    }
}

const fn runtime_staged_completion(
    mut completion: DriverTaskCompletionRecord,
) -> DriverTaskCompletionRecord {
    completion.sequence = 0;
    completion
}

/// Primitive record access shared by mapped target rings and the deterministic
/// host reciprocal-ring model.
#[cfg(any(target_os = "none", test))]
trait RuntimeRingRecordIo {
    fn read_u16(&self, offset: usize) -> Option<u16>;
    fn read_u32(&self, offset: usize) -> Option<u32>;
    fn write_u16(&mut self, offset: usize, value: u16) -> bool;
    fn write_u32(&mut self, offset: usize, value: u32) -> bool;
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_write_command_staged<W: RuntimeRingRecordIo>(
    ring: &mut W,
    command: DriverTaskCommandRecord,
) -> bool {
    if command.sequence != 0 {
        return false;
    }
    let budget = core::mem::offset_of!(DriverTaskCommandRecord, budget);
    let frame = core::mem::offset_of!(DriverTaskCommandRecord, frame);
    ring.write_u32(core::mem::offset_of!(DriverTaskCommandRecord, sequence), 0)
        && ring.write_u16(
            core::mem::offset_of!(DriverTaskCommandRecord, opcode),
            command.opcode,
        )
        && ring.write_u16(
            core::mem::offset_of!(DriverTaskCommandRecord, flags),
            command.flags,
        )
        && ring.write_u32(
            core::mem::offset_of!(DriverTaskCommandRecord, arg0),
            command.arg0,
        )
        && ring.write_u32(
            core::mem::offset_of!(DriverTaskCommandRecord, arg1),
            command.arg1,
        )
        && ring.write_u32(
            core::mem::offset_of!(DriverTaskCommandRecord, aux0),
            command.aux0,
        )
        && ring.write_u32(
            core::mem::offset_of!(DriverTaskCommandRecord, aux1),
            command.aux1,
        )
        && ring.write_u16(
            budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_ops),
            command.budget.max_ops,
        )
        && ring.write_u16(
            budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_frames),
            command.budget.max_frames,
        )
        && ring.write_u32(
            budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_bytes),
            command.budget.max_bytes,
        )
        && ring.write_u32(
            frame + core::mem::offset_of!(DriverFrameDescriptor, offset),
            command.frame.offset,
        )
        && ring.write_u16(
            frame + core::mem::offset_of!(DriverFrameDescriptor, len),
            command.frame.len,
        )
        && ring.write_u16(
            frame + core::mem::offset_of!(DriverFrameDescriptor, flags),
            command.frame.flags,
        )
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_commit_command_sequence<W: RuntimeRingRecordIo>(
    ring: &mut W,
    sequence: u32,
) -> bool {
    sequence != 0
        && ring.write_u32(
            core::mem::offset_of!(DriverTaskCommandRecord, sequence),
            sequence,
        )
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_read_command_stable<W: RuntimeRingRecordIo>(
    ring: &W,
) -> Option<DriverTaskCommandRecord> {
    let sequence_offset = core::mem::offset_of!(DriverTaskCommandRecord, sequence);
    let sequence = ring.read_u32(sequence_offset)?;
    if sequence == 0 {
        return None;
    }
    driver_task_shared_load_barrier();
    let budget = core::mem::offset_of!(DriverTaskCommandRecord, budget);
    let frame = core::mem::offset_of!(DriverTaskCommandRecord, frame);
    let command = DriverTaskCommandRecord {
        sequence,
        opcode: ring.read_u16(core::mem::offset_of!(DriverTaskCommandRecord, opcode))?,
        flags: ring.read_u16(core::mem::offset_of!(DriverTaskCommandRecord, flags))?,
        arg0: ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, arg0))?,
        arg1: ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, arg1))?,
        aux0: ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, aux0))?,
        aux1: ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, aux1))?,
        budget: DriverTaskBudgetGrant {
            max_ops: ring
                .read_u16(budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_ops))?,
            max_frames: ring
                .read_u16(budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_frames))?,
            max_bytes: ring
                .read_u32(budget + core::mem::offset_of!(DriverTaskBudgetGrant, max_bytes))?,
        },
        frame: DriverFrameDescriptor {
            offset: ring.read_u32(frame + core::mem::offset_of!(DriverFrameDescriptor, offset))?,
            len: ring.read_u16(frame + core::mem::offset_of!(DriverFrameDescriptor, len))?,
            flags: ring.read_u16(frame + core::mem::offset_of!(DriverFrameDescriptor, flags))?,
        },
    };
    driver_task_shared_load_barrier();
    (ring.read_u32(sequence_offset)? == sequence).then_some(command)
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_write_completion_staged<W: RuntimeRingRecordIo>(
    ring: &mut W,
    completion: DriverTaskCompletionRecord,
) -> bool {
    if completion.sequence != 0 {
        return false;
    }
    let base = DRIVER_TASK_RING_COMPLETION_OFFSET;
    let frame = base + core::mem::offset_of!(DriverTaskCompletionRecord, frame);
    ring.write_u32(
        base + core::mem::offset_of!(DriverTaskCompletionRecord, sequence),
        0,
    ) && ring.write_u16(
        base + core::mem::offset_of!(DriverTaskCompletionRecord, code),
        completion.code,
    ) && ring.write_u16(
        base + core::mem::offset_of!(DriverTaskCompletionRecord, detail),
        completion.detail,
    ) && ring.write_u32(
        base + core::mem::offset_of!(DriverTaskCompletionRecord, result),
        completion.result,
    ) && ring.write_u32(
        frame + core::mem::offset_of!(DriverFrameDescriptor, offset),
        completion.frame.offset,
    ) && ring.write_u16(
        frame + core::mem::offset_of!(DriverFrameDescriptor, len),
        completion.frame.len,
    ) && ring.write_u16(
        frame + core::mem::offset_of!(DriverFrameDescriptor, flags),
        completion.frame.flags,
    )
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_commit_completion_sequence<W: RuntimeRingRecordIo>(
    ring: &mut W,
    sequence: u32,
) -> bool {
    sequence != 0
        && ring.write_u32(
            DRIVER_TASK_RING_COMPLETION_OFFSET
                + core::mem::offset_of!(DriverTaskCompletionRecord, sequence),
            sequence,
        )
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_read_completion_once<W: RuntimeRingRecordIo>(
    ring: &W,
) -> Option<DriverTaskCompletionRecord> {
    let base = DRIVER_TASK_RING_COMPLETION_OFFSET;
    let frame = base + core::mem::offset_of!(DriverTaskCompletionRecord, frame);
    Some(DriverTaskCompletionRecord {
        sequence: ring
            .read_u32(base + core::mem::offset_of!(DriverTaskCompletionRecord, sequence))?,
        code: ring.read_u16(base + core::mem::offset_of!(DriverTaskCompletionRecord, code))?,
        detail: ring.read_u16(base + core::mem::offset_of!(DriverTaskCompletionRecord, detail))?,
        result: ring.read_u32(base + core::mem::offset_of!(DriverTaskCompletionRecord, result))?,
        frame: DriverFrameDescriptor {
            offset: ring.read_u32(frame + core::mem::offset_of!(DriverFrameDescriptor, offset))?,
            len: ring.read_u16(frame + core::mem::offset_of!(DriverFrameDescriptor, len))?,
            flags: ring.read_u16(frame + core::mem::offset_of!(DriverFrameDescriptor, flags))?,
        },
    })
}

#[cfg(any(target_os = "none", test))]
fn runtime_ring_read_completion_stable<W: RuntimeRingRecordIo>(
    ring: &W,
) -> Option<(DriverTaskCompletionRecord, DriverTaskCompletionRecord)> {
    let first = runtime_ring_read_completion_once(ring)?;
    driver_task_shared_load_barrier();
    let second = runtime_ring_read_completion_once(ring)?;
    Some((first, second))
}

/// Service one fixed-layout command without using root pointers.
#[must_use]
#[cfg(not(target_os = "none"))]
pub fn service_command(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    loop {
        match service_command_turn(task_key, command) {
            RuntimeCommandTurn::Pending => {}
            RuntimeCommandTurn::Complete(completion) => return completion,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandTurn {
    Pending,
    Complete(DriverTaskCompletionRecord),
}

const fn cyw43_command_targets_foreground_lane(command: DriverTaskCommandRecord) -> bool {
    command.sequence != 0
        && command.opcode == OPCODE_SERVICE
        && command.arg0 == HOT_PATH_CYW43_WIFI
        && command.arg1 == ROLE_NET
        && command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
}

const fn cyw43_command_uses_foreground_transaction(command: DriverTaskCommandRecord) -> bool {
    cyw43_command_targets_foreground_lane(command)
        && command.frame.offset == DRIVER_RUNTIME_CYW43_COMMAND_DESCRIPTOR_OFFSET as u32
        && command.frame.len as usize == core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>()
}

#[cfg(any(target_os = "none", test))]
fn cyw43_command_foreground_enabled(command: DriverTaskCommandRecord) -> bool {
    if !cyw43_command_uses_foreground_transaction(command) {
        return false;
    }
    #[cfg(target_os = "none")]
    {
        true
    }
    #[cfg(all(not(target_os = "none"), test))]
    {
        TEST_CYW43_FOREGROUND_PRODUCTION_CHAIN_ENABLED.load(Ordering::Acquire)
    }
}

const fn cyw43_legacy_raw_frame_submission(command: DriverTaskCommandRecord) -> bool {
    command.opcode == OPCODE_SERVICE
        && command.arg0 == HOT_PATH_CYW43_WIFI
        && command.arg1 == ROLE_NET
        && command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
        && command.frame.len != 0
}

#[cfg(any(target_os = "none", test))]
const fn cyw43_foreground_admission_rejection_result(command: DriverTaskCommandRecord) -> u32 {
    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0 {
        DRIVER_RUNTIME_REJECT_SDIO_PERSISTENT_TRANSACTION_INVALID
    } else {
        command.sequence
    }
}

fn service_command_turn(task_key: usize, command: DriverTaskCommandRecord) -> RuntimeCommandTurn {
    if cyw43_command_targets_foreground_lane(command)
        && !cyw43_command_uses_foreground_transaction(command)
    {
        // Physical Pi CYW43 has one parent-command lane. Accepting the old
        // front-frame descriptor location here would reintroduce the DPC alias
        // that the dedicated slot removes.
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_DESCRIPTOR_INVALID,
            CYW43_DESCRIPTOR_INVALID_PAYLOAD,
        ));
    }

    #[cfg(any(target_os = "none", test))]
    let cyw43_transaction = cyw43_command_foreground_enabled(command);

    #[cfg(all(not(target_os = "none"), test))]
    if cyw43_transaction && !cyw43_foreground_pre_admit(command) {
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            cyw43_foreground_admission_rejection_result(command),
        ));
    }

    #[cfg(any(target_os = "none", test))]
    if cyw43_transaction {
        if let Some(turn) = service_cyw43_intake_sealed_rx_poll_queue_terminal(command) {
            return turn;
        }
    }

    #[cfg(any(target_os = "none", test))]
    if cyw43_transaction && !cyw43_foreground_begin_turn(command) {
        let turn = cyw43_foreground_finish_turn(
            command,
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                command.sequence,
                FAULT_CYW43_TRANSPORT_BUS_LINK,
                cyw43_foreground_admission_rejection_result(command),
            )),
        );
        return turn;
    }

    let turn = if let Some(turn) = service_usb_controller_init_command_turn(command) {
        turn
    } else if let Some(turn) = service_serial_tx_command_turn(command) {
        turn
    } else if let Some(turn) = service_sdio_pwrseq_command_turn(command) {
        turn
    } else if let Some(turn) = service_sdio_external_dma_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_transport_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_firmware_prep_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_release_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_prompt_poll_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_control_exchange_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_linked_tx_command_turn(command) {
        turn
    } else {
        RuntimeCommandTurn::Complete(service_command_immediate(task_key, command))
    };

    #[cfg(any(target_os = "none", test))]
    if cyw43_transaction {
        let turn = cyw43_foreground_finish_turn(command, turn);
        return turn;
    }
    turn
}

fn service_serial_tx_command_turn(command: DriverTaskCommandRecord) -> Option<RuntimeCommandTurn> {
    if command.sequence == 0
        || command.opcode != OPCODE_SERVICE
        || command.arg0 != HOT_PATH_SERIAL_CONSOLE
        || command.arg1 != ROLE_SERIAL
        || command.aux0 != 0
        || command.frame.len == 0
    {
        return None;
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != HOT_PATH_SERIAL_CONSOLE {
        SERIAL_RUNTIME_TX_CURSOR.with_mut(SerialRuntimeTxCursor::reset);
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        ));
    }
    if !command.frame.in_ring_payload() {
        SERIAL_RUNTIME_TX_CURSOR.with_mut(SerialRuntimeTxCursor::reset);
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
        ));
    }
    let admitted_len = serial_frame_budget_limit(command.budget, command.frame.len);
    let turn = SERIAL_RUNTIME_TX_CURSOR.with_mut(|cursor| {
        cursor.service_turn_with(command, admitted_len, serial_write_frame_from_offset)
    });
    #[cfg(target_os = "none")]
    if matches!(turn, RuntimeCommandTurn::Pending) {
        return Some(serial_finish_pending_tx_from_irqs(command, admitted_len));
    }
    Some(turn)
}

#[cfg(target_os = "none")]
fn serial_finish_pending_tx_from_irqs(
    command: DriverTaskCommandRecord,
    admitted_len: usize,
) -> RuntimeCommandTurn {
    // The first command activation already filled at most one FIFO prefix.
    // Enable TX-empty only after that write so the local notification wakes
    // this retained command lifetime when the wire can accept the next
    // bounded prefix. RX remains enabled throughout the lifetime.
    serial_set_mini_uart_irqs(true, true);
    loop {
        let Some(raw_badge) = wait_runtime_local_notification() else {
            serial_set_mini_uart_irqs(true, false);
            SERIAL_RUNTIME_TX_CURSOR.with_mut(SerialRuntimeTxCursor::reset);
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                command.sequence,
                FAULT_DEVICE_UNAVAILABLE,
            ));
        };
        let badge = runtime_notification_wake_badge(RuntimeNotificationRoute::Serial, raw_badge);
        let turn = SERIAL_RUNTIME_RX_QUEUE.with_mut(|queue| {
            SERIAL_RUNTIME_TX_CURSOR.with_mut(|cursor| {
                serial_service_tx_irq_turn_with(
                    queue,
                    cursor,
                    command,
                    admitted_len,
                    badge,
                    |queue| serial_drain_hardware_to_queue(queue, MINI_UART_RX_DRAIN_LIMIT),
                    serial_write_frame_prefix_from_offset,
                    |enabled| serial_set_mini_uart_irqs(true, enabled),
                    || runtime_irq_handler_ack(DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT),
                )
            })
        });
        match turn {
            Some(RuntimeCommandTurn::Pending) | None => continue,
            Some(RuntimeCommandTurn::Complete(completion)) => {
                return RuntimeCommandTurn::Complete(completion);
            }
        }
    }
}

fn service_command_immediate(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    if command.sequence == 0 {
        return DriverTaskCompletionRecord::idle(0);
    }
    if command.opcode == OPCODE_SHUTDOWN {
        return DriverTaskCompletionRecord::progress(command.sequence, 1);
    }
    if command.opcode == OPCODE_SERVICE && command.arg0 == 0 {
        return DriverTaskCompletionRecord::progress(command.sequence, task_key as u32);
    }
    let Some(role) = role_for_hot_path(command.arg0) else {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    };
    if command.arg1 != role {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_COMMAND_VALIDATED,
        command.aux0,
    );
    if command.aux0 == DRIVER_RUNTIME_INIT_AUX {
        return service_runtime_init(task_key, command);
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != command.arg0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_MISMATCH,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
        command.aux0,
    );
    if command_is_engine_init_aux(command.aux0) {
        publish_service_dispatch_progress(command);
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DISPATCH,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
            command.aux0,
        );
        if command.opcode != OPCODE_SERVICE || command.frame.len != 0 {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
            command.aux0,
        );
        match mark_engine_initialized(command) {
            Ok(detail) => {
                publish_runtime_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
                    command.aux0,
                );
                return DriverTaskCompletionRecord::progress_with_detail(
                    command.sequence,
                    detail,
                    1,
                );
            }
            Err(detail) => {
                if command.arg0 == HOT_PATH_CYW43_WIFI {
                    let exact = cyw43_take_last_fault_detail().unwrap_or(detail);
                    return DriverTaskCompletionRecord::fault_with_result(
                        command.sequence,
                        exact,
                        cyw43_take_last_fault_result(),
                    );
                }
                return DriverTaskCompletionRecord::fault(command.sequence, detail);
            }
        }
    }
    if !opcode_matches_hot_path(command.opcode, command.arg0) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_service_dispatch_progress(command);

    match command.arg0 {
        HOT_PATH_SERIAL_CONSOLE => service_serial(command),
        HOT_PATH_USB_KEYBOARD => service_usb_keyboard(command),
        HOT_PATH_HDMI_TEXT => service_hdmi_text(command),
        HOT_PATH_GENET_NIC => service_genet_runtime(command),
        HOT_PATH_CYW43_WIFI => service_cyw43_runtime(command),
        HOT_PATH_SDIO_HOST => service_sdio_host(command),
        HOT_PATH_PCIE_ROOT => service_pcie_root(command),
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

#[must_use]
const fn command_expects_reply(command: DriverTaskCommandRecord) -> bool {
    command.flags & DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY == 0
}

const RUNTIME_IDLE_POLL_PROGRESS_INTERVAL: u32 = 256;

#[must_use]
const fn runtime_idle_poll_progress_due(idle_polls: u32) -> bool {
    idle_polls == 1 || (idle_polls != 0 && idle_polls % RUNTIME_IDLE_POLL_PROGRESS_INTERVAL == 0)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandAdmission {
    None,
    OneWay,
    NeedsReplyCap,
}

#[must_use]
const fn runtime_command_admission(
    command: DriverTaskCommandRecord,
    last_sequence: u32,
) -> RuntimeCommandAdmission {
    if command.sequence == 0 || command.sequence == last_sequence {
        RuntimeCommandAdmission::None
    } else if command_expects_reply(command) {
        RuntimeCommandAdmission::NeedsReplyCap
    } else {
        RuntimeCommandAdmission::OneWay
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimeCommandIntake {
    command: DriverTaskCommandRecord,
    reply_cap_available: bool,
}

/// Seal every descriptor-shaped command before admitting its runtime turn.
///
/// Pre-admission is an immutable-input optimization, not permission to discard
/// a sequence-last command. A missing or conflicting SDIO seal must still
/// enter the typed dispatcher, which performs no physical I/O without the
/// matching seal and publishes an exact fail-closed terminal. Returning no
/// intake after consuming the peer doorbell could otherwise strand a committed
/// autonomous child forever. CYW43 retains the same typed conflict behavior.
#[cfg(any(target_os = "none", test))]
fn runtime_command_intake_after_pre_admit(
    command: DriverTaskCommandRecord,
    reply_cap_available: bool,
) -> RuntimeCommandIntake {
    let _ = cyw43_foreground_pre_admit(command);
    let _ = sdio_external_dma_pre_admit(command);
    RuntimeCommandIntake {
        command,
        reply_cap_available,
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeWake {
    Command(RuntimeCommandIntake),
    Notification(u32),
    None,
}

/// Result of observing the runtime's combined command/notification boundary.
///
/// Tests retain an explicit unavailable case to prove fail-closed routing; all
/// selected target builds provide the compiler-declared MCS Reply object.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandWait {
    Wake(RuntimeWake),
    #[cfg(test)]
    Unavailable,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandWaitRoute {
    Wake(RuntimeWake),
    #[cfg(test)]
    FailClosed,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_command_wait_route(wait: RuntimeCommandWait) -> RuntimeCommandWaitRoute {
    match wait {
        RuntimeCommandWait::Wake(wake) => RuntimeCommandWaitRoute::Wake(wake),
        #[cfg(test)]
        RuntimeCommandWait::Unavailable => RuntimeCommandWaitRoute::FailClosed,
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimePendingWakeRoute {
    ContinueForeground,
    ServiceNotification(u32),
    Rejected,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_idle_service_badge(route: RuntimeNotificationRoute, badge: u32) -> Option<u32> {
    runtime_notification_service_badge(route, badge)
}

#[cfg(any(target_os = "none", test))]
fn retain_runtime_idle_delegated_wake(
    route: RuntimeNotificationRoute,
    badge: u32,
    gate: &mut RuntimePendingCommandGate,
) -> bool {
    let admitted_badge = runtime_notification_wake_badge(route, badge);
    if admitted_badge & DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE == 0 {
        return false;
    }
    gate.restore_deferred_delegated_wake();
    true
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandLoopRoute {
    WaitForRetainedContinuation,
    WaitForIdleCommand,
    RunForeground,
}

/// Final durable-condition decision before an idle runtime blocks.
///
/// Reply-cap commands rendezvous through the command endpoint. Reciprocal
/// CYW43-to-SDIO children and root-originated one-way CYW43 parents are
/// sequence-last ring commands with coalescing notification hints. Re-read
/// either immediately before `Recv`; a hint consumed while finishing prior
/// durable service cannot carry the successor command's history or liveness.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeIdlePrewaitRoute {
    ReenterCommandPoll,
    Block,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_idle_prewait_route(
    route: RuntimeNotificationRoute,
    admission: RuntimeCommandAdmission,
) -> RuntimeIdlePrewaitRoute {
    if matches!(
        route,
        RuntimeNotificationRoute::SdioOwner | RuntimeNotificationRoute::Cyw43Client
    ) && matches!(admission, RuntimeCommandAdmission::OneWay)
    {
        RuntimeIdlePrewaitRoute::ReenterCommandPoll
    } else {
        RuntimeIdlePrewaitRoute::Block
    }
}

/// Select the receive boundary used by the production runtime loop.
///
/// The idle route deliberately does not depend on whether this runtime has a
/// bound notification. Every non-MCS runtime sleeps on its command endpoint;
/// a retained command sleeps on the combined endpoint/notification receive
/// until root grants its next foreground quantum.
#[cfg(any(target_os = "none", test))]
const fn runtime_command_loop_route(
    retained_command: bool,
    continuation_required: bool,
) -> RuntimeCommandLoopRoute {
    if continuation_required {
        RuntimeCommandLoopRoute::WaitForRetainedContinuation
    } else if retained_command {
        RuntimeCommandLoopRoute::RunForeground
    } else {
        RuntimeCommandLoopRoute::WaitForIdleCommand
    }
}

/// One scheduled state in the retained delegated SDIO owner arbiter.
