#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeSteadySemanticSnapshot {
    Sdio(RuntimeSteadySdioSnapshot),
    Cyw43Foreground(RuntimeSteadyCyw43ForegroundSnapshot),
    PersistentCyw43Foreground(RuntimePersistentCyw43ForegroundSnapshot),
    Cyw43Dpc(RuntimeSteadyCyw43DpcSnapshot),
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeSteadyPendingDisposition {
    SemanticProgress,
    WaitForWake,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeDurablePendingRoute {
    ContinueToQuiescence,
    BlockOnLocalNotification,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_durable_pending_route(
    disposition: RuntimeSteadyPendingDisposition,
) -> RuntimeDurablePendingRoute {
    match disposition {
        RuntimeSteadyPendingDisposition::SemanticProgress => {
            RuntimeDurablePendingRoute::ContinueToQuiescence
        }
        RuntimeSteadyPendingDisposition::WaitForWake => {
            RuntimeDurablePendingRoute::BlockOnLocalNotification
        }
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_steady_semantic_disposition(
    previous: &mut Option<RuntimeSteadySemanticSnapshot>,
    current: RuntimeSteadySemanticSnapshot,
) -> RuntimeSteadyPendingDisposition {
    let semantic_changed = *previous != Some(current);
    if semantic_changed {
        *previous = Some(current);
    }
    match current {
        // SDIO's first changed PollIssued turn performs the live SDHCI/DMA
        // condition sample required before sleeping. The cursor then blocks
        // only when that physical sample leaves semantic state unchanged.
        RuntimeSteadySemanticSnapshot::Sdio(_) => {
            if semantic_changed {
                RuntimeSteadyPendingDisposition::SemanticProgress
            } else {
                RuntimeSteadyPendingDisposition::WaitForWake
            }
        }
        RuntimeSteadySemanticSnapshot::Cyw43Foreground(_)
        | RuntimeSteadySemanticSnapshot::PersistentCyw43Foreground(_)
        | RuntimeSteadySemanticSnapshot::Cyw43Dpc(_) => {
            if runtime_semantic_local_continuation_due(current) {
                RuntimeSteadyPendingDisposition::SemanticProgress
            } else {
                RuntimeSteadyPendingDisposition::WaitForWake
            }
        }
    }
}

/// Route one retained owner from its current durable condition.
///
/// Snapshot change is diagnostic history only: it can publish a liveness
/// revision, but it never grants another service turn. A private deterministic
/// phase continues even when its snapshot is unchanged; a physical child,
/// controller, credit, queue, or peer-owned wait blocks on first observation.
#[cfg(any(target_os = "none", test))]
const fn runtime_semantic_local_continuation_due(current: RuntimeSteadySemanticSnapshot) -> bool {
    match current {
        RuntimeSteadySemanticSnapshot::Sdio(_) => false,
        RuntimeSteadySemanticSnapshot::Cyw43Foreground(snapshot) => snapshot.local_continuation_due,
        RuntimeSteadySemanticSnapshot::PersistentCyw43Foreground(snapshot) => {
            snapshot.local_continuation_due
        }
        RuntimeSteadySemanticSnapshot::Cyw43Dpc(snapshot) => snapshot.local_continuation_due,
    }
}

/// Identity-bound authority for one retained steady-data-plane SDIO child.
///
/// The lease never authorizes another command. It only lets the SDIO owner
/// advance the already intake-sealed controller cursor once per scheduler
/// slice without a reciprocal grant round trip for every internal phase. The
/// marker is admitted either from an exact DPC event or from an explicitly
/// marked one-frame Ethernet TX parent. EAPOL parents additionally prove an
/// intake-sealed M2, M4, or group-key response; no operation is inferred.
/// Its total lifetime follows the existing CNTVCT-scaled controller/child
/// deadline. `max_ops` remains a HAL-operation budget and is deliberately not
/// reused as a scheduler-poll count. Current durable conditions continue only
/// deterministic private work; an exact external wait blocks immediately, so
/// scheduler placement is never a required transaction edge.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimeSteadyServiceLease {
    request_sequence: u32,
    action_fingerprint: u32,
    generation: u32,
    binding_sequence: u32,
    service_slices: u32,
    semantic_snapshot: Option<RuntimeSteadySemanticSnapshot>,
    deadline: RuntimeDeadline,
    exhausted: bool,
}

#[cfg(any(target_os = "none", test))]
impl RuntimeSteadyServiceLease {
    const fn empty() -> Self {
        Self {
            request_sequence: 0,
            action_fingerprint: 0,
            generation: 0,
            binding_sequence: 0,
            service_slices: 0,
            semantic_snapshot: None,
            deadline: RuntimeDeadline::Counter {
                start: 0,
                cycles: 0,
            },
            exhausted: false,
        }
    }

    const fn matches(self, command: DriverTaskCommandRecord) -> bool {
        self.request_sequence != 0
            && self.request_sequence == command.sequence
            && self.action_fingerprint == runtime_continuation_action_fingerprint(command)
            && self.generation == command.aux1
            && self.binding_sequence == command.aux0
    }

    const fn active_for(self, command: DriverTaskCommandRecord) -> bool {
        self.matches(command) && !self.exhausted
    }

    const fn semantic_snapshot_for(
        self,
        command: DriverTaskCommandRecord,
    ) -> Option<RuntimeSteadySemanticSnapshot> {
        if self.matches(command) {
            self.semantic_snapshot
        } else {
            None
        }
    }

    #[cfg(test)]
    const fn exhausted_for(self, command: DriverTaskCommandRecord) -> bool {
        self.matches(command) && self.exhausted
    }

    fn admit(&mut self, command: DriverTaskCommandRecord) -> bool {
        if self.request_sequence != 0 {
            return false;
        }
        *self = Self {
            request_sequence: command.sequence,
            action_fingerprint: runtime_continuation_action_fingerprint(command),
            generation: command.aux1,
            binding_sequence: command.aux0,
            service_slices: 0,
            semantic_snapshot: None,
            deadline: steady_service_lease_deadline(command),
            exhausted: false,
        };
        true
    }

    fn admit_next_slice(&mut self, command: DriverTaskCommandRecord) -> bool {
        if !self.matches(command) {
            return true;
        }
        if self.exhausted || steady_service_lease_deadline_expired(&mut self.deadline) {
            self.exhausted = true;
            return false;
        }
        true
    }

    fn record_service_slice(&mut self) -> bool {
        if self.exhausted {
            return false;
        }
        let Some(next) = self.service_slices.checked_add(1) else {
            self.exhausted = true;
            return false;
        };
        self.service_slices = next;
        true
    }

    const fn completed_slices(self) -> u32 {
        self.service_slices
    }

    fn record_semantic_progress_with<P>(
        &mut self,
        command: DriverTaskCommandRecord,
        current: RuntimeSteadySemanticSnapshot,
        publish: P,
    ) -> Option<RuntimeSteadyPendingDisposition>
    where
        P: FnOnce(DriverTaskCommandRecord, u32, u32) -> bool,
    {
        let semantic_changed = self.semantic_snapshot != Some(current);
        let disposition = runtime_steady_semantic_disposition(&mut self.semantic_snapshot, current);
        if !semantic_changed {
            return Some(disposition);
        }
        if !self.record_service_slice() {
            return None;
        }
        // Progress publication is diagnostic-only. The immutable request
        // deadline and exact lease identity remain authoritative even if this
        // best-effort sequence-last record cannot be written.
        let _ = publish(command, command.aux1, self.completed_slices());
        Some(disposition)
    }

    fn clear(&mut self) {
        *self = Self::empty();
    }
}

/// Scheduler state for one immutable CYW43 control transaction or one of its
/// exact SDIO children.
///
/// Unlike the post-Gate-8 urgent-TX lease above, this state carries no
/// scheduler-created lifetime. The op11 cursor and each physical SDIO request
/// retain their existing CNTVCT-scaled deadlines. This record only remembers
/// identity and diagnostic semantic progress. Current durable conditions keep
/// private transitions local and block exact child, queue, credit, or peer
/// waits immediately. Notifications never renew or authorize the transaction.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimePersistentTransactionService {
    request_sequence: u32,
    action_fingerprint: u32,
    generation: u32,
    binding_sequence: u32,
    service_slices: u32,
    wait_epochs: u32,
    semantic_snapshot: Option<RuntimeSteadySemanticSnapshot>,
}

#[cfg(any(target_os = "none", test))]
impl RuntimePersistentTransactionService {
    const fn empty() -> Self {
        Self {
            request_sequence: 0,
            action_fingerprint: 0,
            generation: 0,
            binding_sequence: 0,
            service_slices: 0,
            wait_epochs: 0,
            semantic_snapshot: None,
        }
    }

    const fn matches(self, command: DriverTaskCommandRecord) -> bool {
        self.request_sequence != 0
            && self.request_sequence == command.sequence
            && self.action_fingerprint == runtime_continuation_action_fingerprint(command)
            && self.generation == command.aux1
            && self.binding_sequence == command.aux0
    }

    const fn active_for(self, command: DriverTaskCommandRecord) -> bool {
        self.matches(command)
    }

    const fn semantic_snapshot_for(
        self,
        command: DriverTaskCommandRecord,
    ) -> Option<RuntimeSteadySemanticSnapshot> {
        if self.matches(command) {
            self.semantic_snapshot
        } else {
            None
        }
    }

    fn admit(&mut self, command: DriverTaskCommandRecord) -> bool {
        if self.request_sequence != 0 {
            return false;
        }
        *self = Self {
            request_sequence: command.sequence,
            action_fingerprint: runtime_continuation_action_fingerprint(command),
            generation: command.aux1,
            binding_sequence: command.aux0,
            service_slices: 0,
            wait_epochs: 0,
            semantic_snapshot: None,
        };
        true
    }

    fn record_semantic_progress_with<P>(
        &mut self,
        command: DriverTaskCommandRecord,
        current: RuntimeSteadySemanticSnapshot,
        publish: P,
    ) -> Option<RuntimeSteadyPendingDisposition>
    where
        P: FnOnce(DriverTaskCommandRecord, u32, u32) -> bool,
    {
        let semantic_changed = self.semantic_snapshot != Some(current);
        let disposition = runtime_steady_semantic_disposition(&mut self.semantic_snapshot, current);
        if !semantic_changed {
            return Some(disposition);
        }
        self.service_slices = self.service_slices.checked_add(1)?;
        // This is diagnostic liveness evidence, not continuation authority.
        // Sequence-last command/completion state remains authoritative even if
        // the best-effort progress record cannot be published.
        let _ = publish(command, command.aux1, self.service_slices);
        Some(disposition)
    }

    fn next_wait_epoch(&mut self, command: DriverTaskCommandRecord) -> Option<u32> {
        if !self.active_for(command) || !runtime_persistent_wait_receipt_command_valid(command) {
            return None;
        }
        let next = self.wait_epochs.checked_add(1)?;
        if next == 0 {
            return None;
        }
        self.wait_epochs = next;
        Some(next)
    }

    fn clear(&mut self) {
        *self = Self::empty();
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_persistent_wait_epoch_for_route(
    service: &mut RuntimePersistentTransactionService,
    command: DriverTaskCommandRecord,
    disposition: RuntimeSteadyPendingDisposition,
    route: RuntimeNotificationRoute,
) -> Option<Option<u32>> {
    if !service.active_for(command) {
        return None;
    }
    if disposition != RuntimeSteadyPendingDisposition::WaitForWake
        || route != RuntimeNotificationRoute::Cyw43Client
    {
        return Some(None);
    }
    service.next_wait_epoch(command).map(Some)
}

#[cfg(any(target_os = "none", test))]
const fn steady_service_lease_lifetime_us(command: DriverTaskCommandRecord) -> u32 {
    let child_lifetimes = if command.arg0 == HOT_PATH_CYW43_WIFI && command.arg1 == ROLE_NET {
        DRIVER_RUNTIME_CYW43_STEADY_TX_LEASE_OPS as u32
    } else {
        1
    };
    DRIVER_RUNTIME_CYW43_SDIO_CHILD_WORST_CASE_US.saturating_mul(child_lifetimes)
}

#[cfg(any(target_os = "none", test))]
const fn steady_service_lease_fallback_slices(command: DriverTaskCommandRecord) -> usize {
    let child_lifetimes = if command.arg0 == HOT_PATH_CYW43_WIFI && command.arg1 == ROLE_NET {
        DRIVER_RUNTIME_CYW43_STEADY_TX_LEASE_OPS as usize
    } else {
        1
    };
    (DRIVER_RUNTIME_SDIO_SERVICE_MAX_OPS as usize).saturating_mul(child_lifetimes)
}

#[cfg(any(target_os = "none", test))]
fn steady_service_lease_deadline(command: DriverTaskCommandRecord) -> RuntimeDeadline {
    let start = runtime_timer_counter_ticks();
    let cycles = runtime_micros_to_cycles(u64::from(steady_service_lease_lifetime_us(command)));
    if start != 0 && cycles != 0 {
        RuntimeDeadline::Counter { start, cycles }
    } else {
        // Hardware profiles require exported CNTVCT. Keep a finite host-test
        // and fail-closed fallback without pretending that this scheduler-call
        // count is the physical request's normal authority bound.
        RuntimeDeadline::Iterations {
            remaining: steady_service_lease_fallback_slices(command),
        }
    }
}

#[cfg(any(target_os = "none", test))]
fn steady_service_lease_deadline_expired(deadline: &mut RuntimeDeadline) -> bool {
    // Do not use `runtime_deadline_expired`: a CYW43 foreground transaction
    // deliberately suspends its replay-local deadlines after consuming one
    // action. This lease is the enclosing physical lifetime and must sample
    // only its own immutable counter/fallback state.
    match deadline {
        RuntimeDeadline::Counter { start, cycles } => {
            runtime_counter_deadline_expired(*start, *cycles, runtime_timer_counter_ticks())
        }
        RuntimeDeadline::Iterations { remaining } => {
            if *remaining == 0 {
                true
            } else {
                *remaining = remaining.saturating_sub(1);
                false
            }
        }
    }
}

/// Retained foreground commands release exactly one physical quantum per
/// admitted wake carrying the required authority.
///
/// Ring sequence commit is the initial issue boundary. A later matching
/// endpoint message cannot replace or replay that intake. Root-owned retained
/// non-CYW43 commands use the exact endpoint rendezvous. Root and delegated
/// CYW43 work instead advance through `RuntimeRetainedOwnerPhase`: one outer
/// turn checks the combined wake source, a later turn checks the immutable
/// grant, and only a separately admitted turn may service CARD_INT or execute
/// the owner action.
/// The wake is a coalescing scheduling hint; the generation-bound grant is the
/// only counted foreground authority.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimePendingCommandGate {
    continuation_required: bool,
    deferred_service_badge: u32,
    deferred_delegated_wake: bool,
    foreground_due_after_service: bool,
    retained_generation: Option<u32>,
    root_generation: Option<u32>,
    last_grant_id: u32,
    owner_phase: RuntimeRetainedOwnerPhase,
}

#[cfg(any(target_os = "none", test))]
impl RuntimePendingCommandGate {
    const fn new() -> Self {
        Self {
            continuation_required: false,
            deferred_service_badge: 0,
            deferred_delegated_wake: false,
            foreground_due_after_service: false,
            retained_generation: None,
            root_generation: None,
            last_grant_id: 0,
            owner_phase: RuntimeRetainedOwnerPhase::Inactive,
        }
    }

    const fn continuation_required(self) -> bool {
        self.continuation_required
    }

    fn retain_after_pending(&mut self) {
        self.continuation_required = true;
        self.owner_phase = RuntimeRetainedOwnerPhase::Inactive;
    }

    fn retain_after_pending_root_generation(&mut self, generation: u32) {
        self.continuation_required = true;
        self.root_generation = Some(generation);
        self.retained_generation = None;
        self.owner_phase = RuntimeRetainedOwnerPhase::CheckWake;
    }

    fn retain_after_pending_generation(&mut self, generation: u32) {
        self.continuation_required = true;
        self.retained_generation = Some(generation);
        self.root_generation = None;
        self.owner_phase = RuntimeRetainedOwnerPhase::CheckWake;
    }

    fn complete(&mut self) {
        self.continuation_required = false;
        self.deferred_delegated_wake = false;
        self.foreground_due_after_service = false;
        self.retained_generation = None;
        self.root_generation = None;
        self.last_grant_id = 0;
        self.owner_phase = RuntimeRetainedOwnerPhase::Inactive;
    }

    const fn delegated_owner_phase(self) -> RuntimeRetainedOwnerPhase {
        self.owner_phase
    }

    const fn grant_generation(self) -> Option<u32> {
        if self.root_generation.is_some() {
            self.root_generation
        } else {
            self.retained_generation
        }
    }

    const fn root_grant_active(self) -> bool {
        self.root_generation.is_some()
    }

    fn set_delegated_owner_phase(&mut self, phase: RuntimeRetainedOwnerPhase) {
        self.owner_phase = phase;
    }

    fn take_deferred_service(&mut self) -> Option<u32> {
        let badge = self.deferred_service_badge;
        self.deferred_service_badge = 0;
        (badge != 0).then_some(badge)
    }

    fn take_deferred_delegated_wake(&mut self) -> bool {
        let pending = self.deferred_delegated_wake;
        self.deferred_delegated_wake = false;
        pending
    }

    const fn has_deferred_delegated_wake(self) -> bool {
        self.deferred_delegated_wake
    }

    fn restore_deferred_delegated_wake(&mut self) {
        self.deferred_delegated_wake = true;
    }

    fn route_wake(
        &mut self,
        retained: &mut RuntimeCommandIntake,
        wake: RuntimeWake,
    ) -> RuntimePendingWakeRoute {
        self.route_wake_with_grant(retained, wake, None)
    }

    fn grant_matches(
        &self,
        retained: RuntimeCommandIntake,
        grant: DriverRuntimeContinuationGrant,
    ) -> bool {
        self.grant_identity_matches(retained, grant)
            && grant.consumed_grant_id == 0
            && grant.grant_id > self.last_grant_id
    }

    fn consumed_grant_matches(
        &self,
        retained: RuntimeCommandIntake,
        grant: DriverRuntimeContinuationGrant,
    ) -> bool {
        self.grant_identity_matches(retained, grant)
            && grant.consumed_grant_id == grant.grant_id
            && grant.grant_id == self.last_grant_id
    }

    fn grant_identity_matches(
        &self,
        retained: RuntimeCommandIntake,
        grant: DriverRuntimeContinuationGrant,
    ) -> bool {
        let expected_generation = if self.root_grant_active() {
            runtime_root_continuation_expected_generation(retained.command)
        } else {
            runtime_continuation_expected_generation(retained.command)
        };
        let Some(expected_generation) = expected_generation else {
            return false;
        };
        grant.magic == DRIVER_RUNTIME_CONTINUATION_GRANT_MAGIC
            && grant.request_sequence == retained.command.sequence
            && grant.action_fingerprint == runtime_continuation_action_fingerprint(retained.command)
            && grant.generation == expected_generation
            && grant.grant_id != 0
            && self.grant_generation() == Some(expected_generation)
    }

    fn consume_grant(&mut self, grant: DriverRuntimeContinuationGrant) {
        self.last_grant_id = grant.grant_id;
    }

    fn route_wake_with_grant(
        &mut self,
        retained: &mut RuntimeCommandIntake,
        wake: RuntimeWake,
        grant: Option<DriverRuntimeContinuationGrant>,
    ) -> RuntimePendingWakeRoute {
        if !self.continuation_required {
            return RuntimePendingWakeRoute::Rejected;
        }
        match wake {
            RuntimeWake::Command(candidate) => {
                // The endpoint message is only a rendezvous for the already
                // retained immutable one-way command. It cannot replace the
                // intake, introduce a reply cap, or change any action ticket
                // field. Delegated CYW43 work additionally requires the exact
                // sequence-last generation grant; the endpoint payload alone
                // is never continuation authority. Delegated production turns
                // use the peer notification below, while this branch keeps
                // stale or accidentally retained endpoint payloads fail-closed.
                if candidate != *retained || candidate.reply_cap_available {
                    return RuntimePendingWakeRoute::Rejected;
                }
                if self.grant_generation().is_some()
                    || runtime_command_requires_continuation_grant(retained.command)
                {
                    // Generation-bound continuations have one production lane:
                    // a typed notification plus the exact immutable shared
                    // grant. Derive that requirement from the immutable command
                    // as well as mutable gate state so a recovery-state loss
                    // cannot recreate an endpoint fallback.
                    return RuntimePendingWakeRoute::Rejected;
                }
                if self.foreground_due_after_service {
                    self.continuation_required = false;
                    self.foreground_due_after_service = false;
                    return RuntimePendingWakeRoute::ContinueForeground;
                }
                if let Some(service_badge) = self.take_deferred_service() {
                    self.foreground_due_after_service = true;
                    return RuntimePendingWakeRoute::ServiceNotification(service_badge);
                }
                self.continuation_required = false;
                self.foreground_due_after_service = false;
                RuntimePendingWakeRoute::ContinueForeground
            }
            RuntimeWake::Notification(badge) => {
                let root_wake = badge & DRIVER_RUNTIME_RESERVED_ROOT_BADGE != 0;
                let delegated_wake = badge & DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE != 0;
                let grant_wake = if self.root_grant_active() {
                    root_wake
                } else {
                    delegated_wake
                };
                let service_badge = badge
                    & !(DRIVER_RUNTIME_RESERVED_ROOT_BADGE
                        | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE);
                self.deferred_service_badge |= service_badge;
                if grant_wake {
                    // A notification is a coalescing scheduler hint, not
                    // counted authority. Retain every observed grant edge
                    // until an exact grant is acknowledged. This covers both
                    // IRQ-first arbitration and a pure peer wake that arrives
                    // between the one stable grant probe and the receive.
                    self.deferred_delegated_wake = true;
                }
                if self.foreground_due_after_service {
                    // A priority-255 linked runtime must not turn a continuously
                    // reasserted level source into a private service loop. The
                    // typed notification is a durable scheduling edge,
                    // while the exact shared grant remains the authority.
                    if !grant_wake {
                        return RuntimePendingWakeRoute::Rejected;
                    }
                    if let Some(grant) = grant.filter(|grant| self.grant_matches(*retained, *grant))
                    {
                        self.deferred_delegated_wake = false;
                        self.consume_grant(grant);
                        self.continuation_required = false;
                        self.foreground_due_after_service = false;
                        RuntimePendingWakeRoute::ContinueForeground
                    } else {
                        RuntimePendingWakeRoute::Rejected
                    }
                } else if let Some(service_badge) = self.take_deferred_service() {
                    // Service at most one persistent-source quantum. A
                    // notification cannot spend the foreground grant in the
                    // same wake. The exact grant and typed peer edge remain
                    // durable for the later post-service scheduler slice.
                    self.foreground_due_after_service = true;
                    RuntimePendingWakeRoute::ServiceNotification(service_badge)
                } else if grant_wake {
                    if let Some(grant) = grant.filter(|grant| self.grant_matches(*retained, *grant))
                    {
                        self.deferred_delegated_wake = false;
                        self.consume_grant(grant);
                        self.continuation_required = false;
                        RuntimePendingWakeRoute::ContinueForeground
                    } else {
                        RuntimePendingWakeRoute::Rejected
                    }
                } else {
                    RuntimePendingWakeRoute::Rejected
                }
            }
            RuntimeWake::None => RuntimePendingWakeRoute::Rejected,
        }
    }
}

/// Re-arm a retained intake after one separately scheduled arbitration turn.
///
/// A fresh CYW43 command can encounter already-watermarked DPC work before its
/// first foreground action. Classify that intake through the same root-grant
/// predicate used after every later `Pending` result so DPC coexistence cannot
/// accidentally select the legacy endpoint rendezvous.
#[cfg(any(target_os = "none", test))]
fn retain_runtime_command_after_arbitration_turn(
    gate: &mut RuntimePendingCommandGate,
    intake: RuntimeCommandIntake,
    route: RuntimeNotificationRoute,
) {
    if route == RuntimeNotificationRoute::Cyw43Client
        && matches!(
            runtime_root_generation_admission(intake.command, route),
            RuntimeDelegatedGenerationAdmission::Admitted(_)
        )
        && (cyw43_steady_parent_marker_present(intake.command)
            || cyw43_persistent_parent_marker_present(intake.command))
    {
        // The specialized sequence-last command already carries complete
        // parent syntax. A DPC arbitration slice may delay it, but cannot
        // force root to publish a grant or renew immutable identity. The main
        // classifier either resumes the same valid parent or publishes its
        // typed autonomous-lane rejection.
        gate.complete();
        return;
    }
    match runtime_root_generation_admission(intake.command, route) {
        RuntimeDelegatedGenerationAdmission::Admitted(generation) => {
            gate.retain_after_pending_root_generation(generation);
        }
        RuntimeDelegatedGenerationAdmission::NotDelegated => {
            gate.retain_after_pending();
        }
        RuntimeDelegatedGenerationAdmission::Rejected => {
            // The main command classifier publishes the typed rejection before
            // any foreground action. Do not manufacture an endpoint fallback
            // while an earlier DPC quantum drains.
            gate.complete();
        }
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeRetainedGrantProbe {
    Inactive,
    Empty,
    Rejected(DriverRuntimeContinuationGrant),
    Ready(DriverRuntimeContinuationGrant),
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeRetainedWaitRecheck {
    Block,
    Rejected(DriverRuntimeContinuationGrant),
    Execute(DriverRuntimeContinuationGrant),
}

/// Complete one retained wait-phase observation after polling the combined
/// endpoint/notification source.
///
/// This helper exists only for legacy state-machine fixtures. Production keeps
/// the wake poll and grant probe in distinct outer turns.
#[cfg(test)]
fn runtime_retained_wait_observation_after_poll<F>(
    wake: RuntimeWake,
    grant_probe: RuntimeRetainedGrantProbe,
    recheck: F,
) -> Option<(RuntimeWake, RuntimeRetainedGrantProbe)>
where
    F: FnOnce() -> RuntimeRetainedWaitRecheck,
{
    if wake != RuntimeWake::None
        || !matches!(
            grant_probe,
            RuntimeRetainedGrantProbe::Inactive | RuntimeRetainedGrantProbe::Empty
        )
    {
        return Some((wake, grant_probe));
    }
    match recheck() {
        RuntimeRetainedWaitRecheck::Block => None,
        RuntimeRetainedWaitRecheck::Rejected(grant) => Some((
            RuntimeWake::None,
            RuntimeRetainedGrantProbe::Rejected(grant),
        )),
        RuntimeRetainedWaitRecheck::Execute(grant) => {
            Some((RuntimeWake::None, RuntimeRetainedGrantProbe::Ready(grant)))
        }
    }
}

/// Inspect the delegated SDIO continuation condition exactly once before a
/// retained receive.
///
/// seL4 notification badges coalesce, just like Linux workqueue scheduling
/// hints. The immutable shared grant is the durable condition. `Ready` may
/// therefore resume without another receive after the preceding delegated
/// turn's mandatory scheduler handoff. Requiring a second badge here would
/// strand a valid grant when the initial-command and continuation signals
/// coalesced and were consumed before the grant became observable.
#[cfg(any(target_os = "none", test))]
fn probe_runtime_retained_continuation_grant(
    gate: &RuntimePendingCommandGate,
    retained: Option<RuntimeCommandIntake>,
    base: usize,
) -> RuntimeRetainedGrantProbe {
    let Some(retained) = retained.filter(|_| gate.grant_generation().is_some()) else {
        return RuntimeRetainedGrantProbe::Inactive;
    };
    let Some(grant) = read_runtime_continuation_grant_at(base) else {
        return RuntimeRetainedGrantProbe::Empty;
    };
    if gate.grant_matches(retained, grant) {
        RuntimeRetainedGrantProbe::Ready(grant)
    } else if gate.consumed_grant_matches(retained, grant) {
        // The producer has not published the next grant yet. The exact prior
        // grant remains sequence-stable with its acknowledgement, which is a
        // normal wait condition rather than an identity rejection. It cannot
        // authorize another owner quantum because only `Ready` is executable.
        RuntimeRetainedGrantProbe::Empty
    } else {
        RuntimeRetainedGrantProbe::Rejected(grant)
    }
}

/// Re-read the durable continuation condition immediately before sleeping.
///
/// `CheckGrant` and `Wait` are distinct scheduler turns. The producer can
/// publish and signal the next exact grant between them. seL4 preserves a
/// signal that races after this recheck, while this stable shared-memory read
/// observes a publication that raced before it. A ready decision only freezes
/// the immutable grant for a later `Execute` turn; it never authorizes
/// same-turn physical I/O.
#[cfg(any(target_os = "none", test))]
fn recheck_runtime_retained_continuation_grant_before_wait(
    gate: &RuntimePendingCommandGate,
    retained: Option<RuntimeCommandIntake>,
    base: usize,
) -> RuntimeRetainedWaitRecheck {
    match probe_runtime_retained_continuation_grant(gate, retained, base) {
        RuntimeRetainedGrantProbe::Inactive | RuntimeRetainedGrantProbe::Empty => {
            RuntimeRetainedWaitRecheck::Block
        }
        RuntimeRetainedGrantProbe::Rejected(grant) => RuntimeRetainedWaitRecheck::Rejected(grant),
        RuntimeRetainedGrantProbe::Ready(grant) => RuntimeRetainedWaitRecheck::Execute(grant),
    }
}

/// Select the synthetic scheduler wake for one durable delegated grant.
///
/// The wake carries no authority: `RuntimePendingCommandGate` still validates
/// and consumes the exact generation-bound grant before one owner quantum can
/// run. Returning a wake for every `Ready` probe mirrors Linux's
/// condition-before-sleep rule and prevents a coalesced notification from
/// becoming an accidental counted semaphore.
#[cfg(any(target_os = "none", test))]
const fn runtime_ready_grant_scheduler_wake(
    probe: RuntimeRetainedGrantProbe,
    root_grant: bool,
) -> Option<RuntimeWake> {
    if matches!(probe, RuntimeRetainedGrantProbe::Ready(_)) {
        Some(RuntimeWake::Notification(if root_grant {
            DRIVER_RUNTIME_RESERVED_ROOT_BADGE
        } else {
            DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE
        }))
    } else {
        None
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_retained_owner_phase_after_wake(
    gate: &mut RuntimePendingCommandGate,
    retained: Option<&mut RuntimeCommandIntake>,
    wake: RuntimeWake,
) -> RuntimeRetainedOwnerPhase {
    let route = if let Some(retained) = retained {
        gate.route_wake(retained, wake)
    } else {
        RuntimePendingWakeRoute::Rejected
    };
    match route {
        RuntimePendingWakeRoute::ServiceNotification(badge) => {
            RuntimeRetainedOwnerPhase::Service(badge)
        }
        RuntimePendingWakeRoute::ContinueForeground | RuntimePendingWakeRoute::Rejected => {
            RuntimeRetainedOwnerPhase::CheckGrant
        }
    }
}

#[cfg(any(target_os = "none", test))]
const fn runtime_retained_owner_phase_after_grant(
    probe: RuntimeRetainedGrantProbe,
) -> RuntimeRetainedOwnerPhase {
    match probe {
        RuntimeRetainedGrantProbe::Ready(grant) => RuntimeRetainedOwnerPhase::Execute(grant),
        RuntimeRetainedGrantProbe::Inactive
        | RuntimeRetainedGrantProbe::Empty
        | RuntimeRetainedGrantProbe::Rejected(_) => RuntimeRetainedOwnerPhase::Wait,
    }
}

#[cfg(any(target_os = "none", test))]
fn runtime_retained_owner_prepare_execute(
    gate: &mut RuntimePendingCommandGate,
    retained: &mut RuntimeCommandIntake,
    grant: DriverRuntimeContinuationGrant,
) -> RuntimePendingWakeRoute {
    let wake = runtime_ready_grant_scheduler_wake(
        RuntimeRetainedGrantProbe::Ready(grant),
        gate.root_grant_active(),
    )
    .unwrap_or(RuntimeWake::None);
    if gate.has_deferred_delegated_wake() {
        let _ = gate.take_deferred_delegated_wake();
    }
    gate.route_wake_with_grant(retained, wake, Some(grant))
}

/// Outcome used by legacy retained-owner state-machine fixtures.
///
/// This is deliberately not a multi-operation grant. `Execute` means that one
/// exact immutable grant passed wake/source arbitration; the caller must still
/// acknowledge it before issuing exactly one bounded owner quantum.
#[cfg(test)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeRetainedOwnerAdmission {
    Service(u32),
    Execute(DriverRuntimeContinuationGrant),
    Wait,
    Rejected(DriverRuntimeContinuationGrant),
}

/// Collapse pure phase calculations for legacy fixtures only.
///
/// Production must never use this helper because its caller cannot represent
/// the mandatory scheduler handoffs between wake, grant, and execute phases.
#[cfg(test)]
fn runtime_retained_owner_fused_admission(
    gate: &mut RuntimePendingCommandGate,
    retained: &mut RuntimeCommandIntake,
    wake: RuntimeWake,
    grant_probe: RuntimeRetainedGrantProbe,
) -> RuntimeRetainedOwnerAdmission {
    match runtime_retained_owner_phase_after_wake(gate, Some(retained), wake) {
        RuntimeRetainedOwnerPhase::Service(badge) => RuntimeRetainedOwnerAdmission::Service(badge),
        RuntimeRetainedOwnerPhase::CheckGrant => {
            match runtime_retained_owner_phase_after_grant(grant_probe) {
                RuntimeRetainedOwnerPhase::Execute(grant) => {
                    match runtime_retained_owner_prepare_execute(gate, retained, grant) {
                        RuntimePendingWakeRoute::ContinueForeground => {
                            RuntimeRetainedOwnerAdmission::Execute(grant)
                        }
                        RuntimePendingWakeRoute::ServiceNotification(badge) => {
                            RuntimeRetainedOwnerAdmission::Service(badge)
                        }
                        RuntimePendingWakeRoute::Rejected => {
                            RuntimeRetainedOwnerAdmission::Rejected(grant)
                        }
                    }
                }
                RuntimeRetainedOwnerPhase::Wait => match grant_probe {
                    RuntimeRetainedGrantProbe::Rejected(grant) => {
                        RuntimeRetainedOwnerAdmission::Rejected(grant)
                    }
                    RuntimeRetainedGrantProbe::Inactive
                    | RuntimeRetainedGrantProbe::Empty
                    | RuntimeRetainedGrantProbe::Ready(_) => RuntimeRetainedOwnerAdmission::Wait,
                },
                RuntimeRetainedOwnerPhase::Inactive
                | RuntimeRetainedOwnerPhase::CheckWake
                | RuntimeRetainedOwnerPhase::CheckGrant
                | RuntimeRetainedOwnerPhase::Service(_) => RuntimeRetainedOwnerAdmission::Wait,
            }
        }
        RuntimeRetainedOwnerPhase::Inactive
        | RuntimeRetainedOwnerPhase::CheckWake
        | RuntimeRetainedOwnerPhase::Wait
        | RuntimeRetainedOwnerPhase::Execute(_) => RuntimeRetainedOwnerAdmission::Wait,
    }
}

/// Commit ACK-before-I/O for one separately frozen exact grant.
///
/// Failure restores the complete pre-admission gate and a durable scheduling
/// condition. The caller therefore cannot reach physical service until the
/// same exact unconsumed grant is re-read and acknowledged on a later turn.
#[cfg(test)]
fn runtime_retained_owner_commit_grant_with<F>(
    gate: &mut RuntimePendingCommandGate,
    gate_before_grant: RuntimePendingCommandGate,
    grant: DriverRuntimeContinuationGrant,
    acknowledge: F,
) -> bool
where
    F: FnOnce(u32) -> bool,
{
    if acknowledge(grant.grant_id) {
        gate.set_delegated_owner_phase(RuntimeRetainedOwnerPhase::Inactive);
        true
    } else {
        *gate = gate_before_grant;
        gate.set_delegated_owner_phase(RuntimeRetainedOwnerPhase::CheckGrant);
        false
    }
}

#[cfg(target_os = "none")]
fn read_runtime_command_record() -> DriverTaskCommandRecord {
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR,
        core::mem::size_of::<DriverTaskCommandRecord>(),
    );
    runtime_ring_read_command_stable(&RuntimeRingWindow::local())
        .unwrap_or(DriverTaskCommandRecord::empty())
}

#[cfg(target_os = "none")]
fn poll_runtime_command(
    last_sequence: u32,
    task_key_marker: u32,
    publish_ring_read_begin: bool,
) -> Option<RuntimeCommandIntake> {
    if publish_ring_read_begin {
        publish_runtime_progress(
            0,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_RING_READ_BEGIN,
            task_key_marker,
        );
    }
    let mut command = read_runtime_command_record();
    match runtime_command_admission(command, last_sequence) {
        RuntimeCommandAdmission::None => return None,
        RuntimeCommandAdmission::OneWay => {
            return Some(runtime_command_intake_after_pre_admit(command, false));
        }
        RuntimeCommandAdmission::NeedsReplyCap => {}
    }

    publish_runtime_progress(
        command.sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_POLL_BEGIN,
        command.aux0,
    );

    let mut badge: sel4_sys::seL4_Word = 0;
    // SAFETY: The root task minted `DRIVER_TASK_CHILD_COMMAND_SLOT` into the
    // child CSpace before resuming this TCB. The runtime reads the shared ring
    // before this endpoint poll so one-way bounded turns can make progress even
    // if endpoint wakeup telemetry is inconclusive. Endpoint polling is still
    // required for commands that need a reply cap.
    let tag = unsafe { sel4_sys::seL4_Poll(DRIVER_TASK_CHILD_COMMAND_SLOT, &mut badge) };
    let ipc_delivered = tag.length() != 0;
    let ipc_sequence = if ipc_delivered {
        // SAFETY: Root uses MR0 to carry the primitive request sequence when it
        // sends or calls the command endpoint.
        unsafe { sel4_sys::seL4_GetMR(0) as u32 }
    } else {
        0
    };
    if ipc_delivered {
        // The producer publishes the durable record sequence-last before the
        // endpoint hint. Re-read it exactly once after consuming the hint; a
        // mismatch is deferred to a later outer turn and producer re-signal,
        // never converted into a private polling loop.
        command = read_runtime_command_record();
    }
    if command.sequence == 0 || command.sequence == last_sequence {
        return None;
    }
    let expects_reply = command_expects_reply(command);
    if expects_reply && !ipc_delivered {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            command.aux0,
        );
        return None;
    }
    if expects_reply && ipc_sequence != 0 && command.sequence != ipc_sequence {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            ipc_sequence,
        );
        return None;
    }
    Some(runtime_command_intake_after_pre_admit(
        command,
        expects_reply,
    ))
}

#[cfg(target_os = "none")]
fn runtime_wake_from_received_tag(
    tag: sel4_sys::seL4_MessageInfo,
    badge: sel4_sys::seL4_Word,
    last_sequence: u32,
    task_key: u32,
) -> RuntimeWake {
    if tag.length() == 0 {
        return if badge == 0 {
            RuntimeWake::None
        } else {
            RuntimeWake::Notification(badge as u32)
        };
    }
    #[cfg(sel4_config_kernel_mcs)]
    if badge as u64 != pi4_driver_abi::driver_runtime_command_badge(task_key) {
        return RuntimeWake::None;
    }
    // SAFETY: The fixed endpoint ABI carries the shared-ring sequence in MR0.
    let ipc_sequence = unsafe { sel4_sys::seL4_GetMR(0) as u32 };
    // The sequence-last ring record is authoritative. One stable read per
    // endpoint rendezvous preserves the one-operation outer-turn bound; a
    // stale, duplicate, zero, or early hint is rejected and the producer's
    // exact re-signal supplies liveness on a later turn.
    let command = read_runtime_command_record();
    if command.sequence == 0
        || command.sequence == last_sequence
        || command.sequence != ipc_sequence
    {
        return RuntimeWake::None;
    }
    let reply_cap_available = command_expects_reply(command);
    RuntimeWake::Command(runtime_command_intake_after_pre_admit(
        command,
        reply_cap_available,
    ))
}

#[cfg(target_os = "none")]
fn poll_runtime_command_or_notification(last_sequence: u32, task_key: u32) -> RuntimeCommandWait {
    let mut badge: sel4_sys::seL4_Word = 0;
    // SAFETY: Root installs the command endpoint in slot 2 and binds the
    // generated local notification to this TCB. This single nonblocking poll
    // is the retained-owner arbitration linearization point: a CARD_INT that
    // is pending here wins before any exact-granted foreground owner action in
    // this child slice.
    #[cfg(not(sel4_config_kernel_mcs))]
    let tag = unsafe { sel4_sys::seL4_Poll(DRIVER_TASK_CHILD_COMMAND_SLOT, &mut badge) };
    #[cfg(sel4_config_kernel_mcs)]
    // SAFETY: The compiler-generated child CSpace contains a read-only command
    // endpoint in slot 2 and the runtime's sole explicit Reply object in slot
    // 6. NBRecv either leaves that object unassociated or installs exactly one
    // caller association; the one-in-flight contract prevents replacement.
    let tag = unsafe {
        sel4_sys::seL4_NBRecv(
            DRIVER_TASK_CHILD_COMMAND_SLOT,
            &mut badge,
            pi4_driver_abi::DRIVER_RUNTIME_COMMAND_REPLY_SLOT as sel4_sys::seL4_CPtr,
        )
    };
    RuntimeCommandWait::Wake(runtime_wake_from_received_tag(
        tag,
        badge,
        last_sequence,
        task_key,
    ))
}

#[cfg(target_os = "none")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeBlockingWaitTarget {
    CommandOrNotification,
    LocalNotification,
}

#[cfg(target_os = "none")]
fn runtime_blocking_wait(
    target: RuntimeBlockingWaitTarget,
    badge: &mut sel4_sys::seL4_Word,
) -> sel4_sys::seL4_MessageInfo {
    // SAFETY: Root installs the command endpoint in fixed child slot 2 and
    // HAL installs the generated local notification in fixed child slot 3,
    // binding that same notification to this TCB. The typed target admits
    // only those two capabilities: Recv preserves the combined endpoint plus
    // bound-notification intake, while Wait observes only slot 3 and cannot
    // consume or replace a retained endpoint reply capability.
    unsafe {
        match target {
            RuntimeBlockingWaitTarget::CommandOrNotification => {
                #[cfg(not(sel4_config_kernel_mcs))]
                {
                    sel4_sys::seL4_Recv(DRIVER_TASK_CHILD_COMMAND_SLOT, badge)
                }
                #[cfg(sel4_config_kernel_mcs)]
                {
                    sel4_sys::seL4_Recv(
                        DRIVER_TASK_CHILD_COMMAND_SLOT,
                        badge,
                        pi4_driver_abi::DRIVER_RUNTIME_COMMAND_REPLY_SLOT as sel4_sys::seL4_CPtr,
                    )
                }
            }
            RuntimeBlockingWaitTarget::LocalNotification => {
                sel4_sys::seL4_Wait(DRIVER_TASK_CHILD_LOCAL_NOTIFICATION_SLOT, badge)
            }
        }
    }
}

#[cfg(target_os = "none")]
fn wait_runtime_command_or_notification(last_sequence: u32, task_key: u32) -> RuntimeCommandWait {
    let mut badge: sel4_sys::seL4_Word = 0;
    let tag = runtime_blocking_wait(RuntimeBlockingWaitTarget::CommandOrNotification, &mut badge);
    RuntimeCommandWait::Wake(runtime_wake_from_received_tag(
        tag,
        badge,
        last_sequence,
        task_key,
    ))
}

const fn runtime_exact_command_wait_supported() -> bool {
    true
}

#[must_use]
fn validate_runtime_init_descriptor(
    task_key: usize,
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    validate_runtime_init_descriptor_with_wait_support(
        task_key,
        command,
        descriptor,
        runtime_exact_command_wait_supported(),
    )
}

#[must_use]
fn validate_runtime_init_descriptor_with_wait_support(
    task_key: usize,
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
    exact_command_wait_supported: bool,
) -> DriverTaskCompletionRecord {
    if command.opcode != OPCODE_SERVICE
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if !exact_command_wait_supported {
        // The MCS endpoint ABI needs a generated reply object. Reject the
        // descriptor before publishing any runtime authority until that
        // resource is part of the compiler-defined init contract.
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if !descriptor.valid()
        || descriptor.hot_path != command.arg0
        || descriptor.role_bit != command.arg1
        || !descriptor.sealed_identity_valid_for_task(task_key as u32)
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if descriptor.hot_path == HOT_PATH_USB_KEYBOARD {
        USB_CONTROLLER_INIT_CURSOR.with_mut(UsbControllerInitCursor::reset);
    }
    RUNTIME_DESCRIPTOR.store(descriptor);
    RUNTIME_INIT_HOT_PATH.store(descriptor.hot_path, Ordering::Release);
    RUNTIME_INIT_FLAGS.store(descriptor.flags, Ordering::Release);
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_VALID,
        command.aux0,
    );
    mark_descriptor_ready(descriptor.hot_path);
    if descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor_resources_ready_with_progress(
            &descriptor,
            HOT_PATH_HDMI_TEXT,
            command.sequence,
            command.aux0,
        )
    {
        // Runtime-init publishes immutable framebuffer authority only. A full
        // physical clear used to run here before the descriptor Reply, which
        // cannot fit the generated HDMI MCS service turn on the Pi. Keep every
        // framebuffer mutation behind an explicit bounded display command.
        HDMI_RUNTIME_FLAGS.fetch_or(
            ENGINE_STATE_INITIALIZED
                | ENGINE_STATE_DESCRIPTOR_READY
                | ENGINE_STATE_RESOURCE_READY
                | ENGINE_STATE_HW_READY,
            Ordering::AcqRel,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
            command.aux0,
        );
    }
    if descriptor.hot_path == HOT_PATH_PCIE_ROOT {
        let _ = adopt_hal_prepared_pcie_runtime_descriptor(descriptor);
    }
    DriverTaskCompletionRecord::progress(command.sequence, descriptor.hot_path)
}

#[cfg(target_os = "none")]
fn service_runtime_init(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    if !command.frame.in_runtime_init_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let descriptor_addr = DRIVER_TASK_RING_VADDR + command.frame.offset as usize;
    // SAFETY: The frame descriptor is bounds-checked against the fixed ring
    // page. Root stages `DriverRuntimeInitDescriptor` at an aligned offset in
    // the ring payload before submitting the init command.
    let descriptor =
        unsafe { core::ptr::read_volatile(descriptor_addr as *const DriverRuntimeInitDescriptor) };
    validate_runtime_init_descriptor(task_key, command, descriptor)
}

#[cfg(not(target_os = "none"))]
fn service_runtime_init(
    _task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE)
}

/// Host-test helper for exercising runtime init without mapping the fixed ring.
#[cfg(test)]
#[must_use]
fn service_runtime_init_for_test(
    task_key: usize,
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    validate_runtime_init_descriptor(task_key, command, descriptor)
}

fn role_for_hot_path(hot_path: u32) -> Option<u32> {
    match hot_path {
        HOT_PATH_SERIAL_CONSOLE => Some(ROLE_SERIAL),
        HOT_PATH_USB_KEYBOARD => Some(ROLE_USB),
        HOT_PATH_HDMI_TEXT => Some(ROLE_DISPLAY),
        HOT_PATH_GENET_NIC | HOT_PATH_CYW43_WIFI => Some(ROLE_NET),
        HOT_PATH_SDIO_HOST => Some(ROLE_SDIO),
        HOT_PATH_PCIE_ROOT => Some(ROLE_PCIE),
        _ => None,
    }
}

fn opcode_matches_hot_path(opcode: u16, hot_path: u32) -> bool {
    if hot_path == HOT_PATH_HDMI_TEXT {
        opcode == OPCODE_SUBMIT_FRAME
    } else {
        opcode == OPCODE_SERVICE
    }
}

const fn command_is_engine_init_aux(aux0: u32) -> bool {
    matches!(
        aux0,
        DRIVER_RUNTIME_ENGINE_INIT_AUX
            | DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
            | DRIVER_RUNTIME_NET_INIT_AUX
    )
}

fn publish_service_dispatch_progress(command: DriverTaskCommandRecord) {
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
        command.aux0,
    );
    let phase = match command.arg0 {
        HOT_PATH_HDMI_TEXT => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_HDMI,
        HOT_PATH_USB_KEYBOARD => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_USB,
        HOT_PATH_SDIO_HOST => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_SDIO,
        HOT_PATH_CYW43_WIFI => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_CYW43,
        _ => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
    };
    if phase != DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH {
        publish_runtime_progress(command.sequence, phase, command.aux0);
    }
}

fn runtime_flags_for_hot_path(hot_path: u32) -> Option<&'static AtomicU32> {
    match hot_path {
        HOT_PATH_USB_KEYBOARD => Some(&USB_RUNTIME_FLAGS),
        HOT_PATH_HDMI_TEXT => Some(&HDMI_RUNTIME_FLAGS),
        HOT_PATH_GENET_NIC => Some(&GENET_RUNTIME_FLAGS),
        HOT_PATH_CYW43_WIFI => Some(&CYW43_RUNTIME_FLAGS),
        HOT_PATH_SDIO_HOST => Some(&SDIO_RUNTIME_FLAGS),
        HOT_PATH_PCIE_ROOT => Some(&PCIE_RUNTIME_FLAGS),
        _ => None,
    }
}

fn mark_descriptor_ready(hot_path: u32) {
    if let Some(flags) = runtime_flags_for_hot_path(hot_path) {
        flags.fetch_or(ENGINE_STATE_DESCRIPTOR_READY, Ordering::AcqRel);
    }
}

fn adopt_hal_prepared_pcie_runtime_descriptor(descriptor: DriverRuntimeInitDescriptor) -> bool {
    if !descriptor_resources_ready(&descriptor, HOT_PATH_PCIE_ROOT) {
        return false;
    }
    PCIE_RUNTIME_STATE.with_mut(|state| {
        state.reset();
        state.initialized = true;
        state.link_ready = true;
        state.last_status = PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP;
        state.cfg_vendor_device = PCIE_VL805_PCI_VENDOR_DEVICE;
        state.cfg_class_revision = PCIE_VL805_EXPECTED_CLASS_REV;
    });
    PCIE_RUNTIME_FLAGS.fetch_or(
        ENGINE_STATE_INITIALIZED
            | ENGINE_STATE_DESCRIPTOR_READY
            | ENGINE_STATE_RESOURCE_READY
            | ENGINE_STATE_HW_READY,
        Ordering::AcqRel,
    );
    true
}

#[inline(never)]
fn mark_engine_initialized(command: DriverTaskCommandRecord) -> Result<u16, u16> {
    let hot_path = command.arg0;
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_LOADED,
        command.aux0,
    );
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        if descriptor.hot_path != hot_path
            || RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != hot_path
        {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_READY,
            command.aux0,
        );
        let Some(flags) = runtime_flags_for_hot_path(hot_path) else {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        };
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_BEGIN,
            command.aux0,
        );
        if !descriptor_resources_ready_with_progress(
            descriptor,
            hot_path,
            command.sequence,
            command.aux0,
        ) {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCES_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_BEGIN,
            command.aux0,
        );
        let detail = runtime_engine_init(command.sequence, command.aux0, hot_path, descriptor);
        match detail {
            Ok(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_DONE,
                command.aux0,
            ),
            Err(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
                command.aux0,
            ),
        }
        let detail = detail?;
        let mut bits = ENGINE_STATE_INITIALIZED | ENGINE_STATE_DESCRIPTOR_READY;
        bits |= ENGINE_STATE_RESOURCE_READY | ENGINE_STATE_HW_READY;
        flags.fetch_or(bits, Ordering::AcqRel);
        Ok(detail)
    })
}

fn reset_sdio_register_shadows() {
    SDIO_TRANSFER_MODE_SHADOW.store(0, Ordering::Release);
    SDIO_TRANSFER_MODE_SHADOW_VALID.store(false, Ordering::Release);
    SDIO_ACTIVE_CLOCK_HZ.store(0, Ordering::Release);
    SDIO_REQUESTED_CLOCK_HZ.store(0, Ordering::Release);
    #[cfg(all(not(target_os = "none"), test))]
    {
        TEST_SDIO_HOST_INT_STATUS_RESPONSE.store(0, Ordering::Release);
        TEST_SDIO_HOST_INT_STATUS_ZERO_READS_REMAINING.store(0, Ordering::Release);
        TEST_SDIO_HOST_INT_ENABLE_RESPONSE.store(0, Ordering::Release);
        TEST_SDIO_HOST_SIGNAL_ENABLE_RESPONSE.store(0, Ordering::Release);
        TEST_SDIO_HOST_RESET_STUCK_MASK.store(0, Ordering::Release);
        TEST_SDIO_HOST_INT_STATUS_W1C_FAILURES_REMAINING.store(0, Ordering::Release);
        TEST_SDIO_HOST_CLOCK_STABLE.store(true, Ordering::Release);
        TEST_RUNTIME_IRQ_ACK_CALLS.store(0, Ordering::Release);
        TEST_RUNTIME_IRQ_ACK_FAILURES_REMAINING.store(0, Ordering::Release);
        TEST_RUNTIME_SDIO_IRQ_ACK_CALLS.store(0, Ordering::Release);
        TEST_RUNTIME_SDIO_DMA_IRQ_ACK_CALLS.store(0, Ordering::Release);
        TEST_SDIO_DMA_CS_RESPONSE.store(0, Ordering::Release);
        TEST_SDIO_DMA_CONBLK_RESPONSE.store(0, Ordering::Release);
        TEST_SDIO_DMA_INIT_ABORT_WRITES.store(0, Ordering::Release);
        TEST_SDIO_DMA_INIT_W1C_WRITES.store(0, Ordering::Release);
        TEST_SDIO_DMA_INIT_RESET_WRITES.store(0, Ordering::Release);
    }
}

fn reset_cyw43_sdio_pair_runtime_entry_state() {
    // Root enters this scrub only after suspending both linked peers, so the
    // SDIO owner is the sole writer of its durable lifetime record. Fence an
    // abandoned in-progress power cycle before erasing the role-local cursor;
    // a later begin must not be required to make that failure observable.
    let _ = sdio_physical_lifetime_fail_active_on_restart();
    RUNTIME_DESCRIPTOR.store(DriverRuntimeInitDescriptor::empty());
    RUNTIME_INIT_HOT_PATH.store(0, Ordering::Release);
    RUNTIME_INIT_FLAGS.store(0, Ordering::Release);
    CYW43_RUNTIME_FLAGS.store(0, Ordering::Release);
    CYW43_TX_COUNT.store(0, Ordering::Release);
    CYW43_SDIO_BUS_LINK_SEQ.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_ACTIVE.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_ISSUED_UNKNOWN.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_LATE_POLLS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_START_TICKS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_TIMEOUT_CYCLES.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_RESTART_SIGNALLED.store(false, Ordering::Release);
    CYW43_SDIO_PAIR_RESTART_REQUIRED.store(false, Ordering::Release);
    CYW43_DPC_DEFERRED.store(false, Ordering::Release);
    CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(0, Ordering::Release);
    CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_DPC_CONSUMED_WATERMARK_PROOF.store(0, Ordering::Release);
    CYW43_ACTIVE_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_LAST_FAULT_DETAIL.store(FAULT_NONE as u32, Ordering::Release);
    CYW43_LAST_FAULT_RESULT.store(0, Ordering::Release);
    CYW43_LAST_RELEASE_PHASE.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(0, Ordering::Release);
    SDIO_RUNTIME_FLAGS.store(0, Ordering::Release);
    SDIO_CMD_COUNT.store(0, Ordering::Release);
    SDIO_LAST_TRANSFER_FAILURE.store(0, Ordering::Release);
    SDIO_LAST_TRANSFER_RAW_ERROR_STATUS.store(0, Ordering::Release);
    reset_sdio_register_shadows();
    CYW43_CONTROL_REQUEST.clear();
    #[cfg(target_os = "none")]
    CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
    SDIO_RUNTIME_STATE.with_mut(SdioRuntimeState::reset);
    CYW43_RUNTIME_STATE.with_mut(Cyw43RuntimeState::reset_for_pair_restart);
}

#[inline(never)]
fn runtime_engine_init(
    sequence: u32,
    aux0: u32,
    hot_path: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RUNTIME_ENTRY,
        aux0,
    );
    match hot_path {
        HOT_PATH_USB_KEYBOARD => runtime_engine_init_usb(sequence, aux0, descriptor),
        HOT_PATH_HDMI_TEXT => runtime_engine_init_hdmi(descriptor),
        HOT_PATH_GENET_NIC => runtime_engine_init_genet(),
        HOT_PATH_CYW43_WIFI => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_ENGINE_INIT_BRANCH,
                aux0,
            );
            runtime_engine_init_cyw43(sequence, aux0, descriptor)
        }
        HOT_PATH_SDIO_HOST => runtime_engine_init_sdio(sequence, aux0, descriptor),
        HOT_PATH_PCIE_ROOT => runtime_engine_init_pcie(),
        _ => Ok(FAULT_NONE),
    }
}

#[inline(never)]
fn runtime_engine_init_usb(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    #[cfg(target_os = "none")]
    {
        // Production USB engine initialization is admitted only by
        // `service_usb_controller_init_command_turn`, which retains the exact
        // command across bounded DMA-maintenance phases. Never reintroduce a
        // synchronous whole-controller fallback under an MCS service turn.
        let _ = (sequence, aux0, descriptor);
        Err(FAULT_DEVICE_UNAVAILABLE)
    }
    #[cfg(not(target_os = "none"))]
    {
        usb_runtime_init(sequence, aux0, descriptor).ok_or(FAULT_DEVICE_UNAVAILABLE)
    }
}

#[inline(never)]
fn runtime_engine_init_hdmi(_descriptor: &DriverRuntimeInitDescriptor) -> Result<u16, u16> {
    // Descriptor validation already proves the framebuffer mapping. Engine
    // admission must not perform an unbounded physical clear; the first
    // explicit HDMI frame owns the first display mutation.
    Ok(FAULT_NONE)
}

#[inline(never)]
fn runtime_engine_init_genet() -> Result<u16, u16> {
    GENET_RUNTIME_STATE.with_mut(|state| {
        genet_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_cyw43(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    CYW43_RUNTIME_STATE.with_mut(|state| {
        cyw43_runtime_init(sequence, aux0, state, descriptor)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_sdio(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_ENGINE_INIT_BRANCH,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_BEGIN,
        aux0,
    );
    reset_sdio_register_shadows();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_DONE,
        aux0,
    );
    #[cfg(test)]
    {
        sdio_runtime_init(sequence, aux0, descriptor)
    }
    #[cfg(not(test))]
    {
        // Production SDIO engine initialization is admitted only by
        // `service_sdio_pwrseq_command_turn`, which retains the command across
        // bounded phases. Reaching this immediate path is a fail-closed
        // programming error, never a synchronous power-sequence fallback.
        let _ = descriptor;
        Err(DRIVER_RUNTIME_SDIO_INIT_DETAIL_INVALID_DESCRIPTOR)
    }
}

#[inline(never)]
fn runtime_engine_init_pcie() -> Result<u16, u16> {
    PCIE_RUNTIME_STATE.with_mut(|state| {
        pcie_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

fn descriptor_resource_range_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.resource_range_count).min(DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES)
}

fn descriptor_bus_link_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.bus_link_count).min(DRIVER_RUNTIME_INIT_MAX_BUS_LINKS)
}

fn descriptor_valid_resource_ranges(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        if !descriptor.resource_ranges[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_bus_links(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        if !descriptor.bus_links[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_irqs(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.irq_count) > DRIVER_RUNTIME_INIT_MAX_IRQS {
        return false;
    }
    let mut index = 0usize;
    while index < usize::from(descriptor.irq_count) {
        if !descriptor.irqs[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_ref(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if descriptor.magic != DRIVER_RUNTIME_INIT_MAGIC
        || descriptor.version != DRIVER_RUNTIME_INIT_VERSION
        || descriptor.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
        || descriptor.hot_path < HOT_PATH_SERIAL_CONSOLE
        || descriptor.hot_path > HOT_PATH_PCIE_ROOT
        || descriptor.role_bit == 0
        || (descriptor.flags & DRIVER_RUNTIME_INIT_REQUIRED_FLAGS)
            != DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
        || descriptor.shared_page_count == 0
        || usize::from(descriptor.mmio_page_count) > DRIVER_RUNTIME_INIT_MAX_MMIO_PAGES
        || usize::from(descriptor.dma_page_count) > DRIVER_RUNTIME_INIT_MAX_DMA_PAGES
        || usize::from(descriptor.shared_page_count) > DRIVER_RUNTIME_INIT_MAX_SHARED_PAGES
        || usize::from(descriptor.irq_count) > DRIVER_RUNTIME_INIT_MAX_IRQS
        || usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS
        || usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES
    {
        return false;
    }
    if descriptor.irq_count == 0 {
        if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY == 0 {
            return false;
        }
    } else if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0 {
        return false;
    }
    if descriptor.bus_link_count != 0 && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS == 0
    {
        return false;
    }
    descriptor_valid_resource_ranges(descriptor)
        && descriptor_valid_irqs(descriptor)
        && descriptor_valid_bus_links(descriptor)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeNotificationRoute {
    Unavailable,
    Serial,
    SdioOwner,
    Cyw43Client,
}

const DPC_REASON_SDIO_CARD_INTERRUPT: u16 = 1;
const DPC_REASON_SDIO_SOURCE_PENDING: u16 = 2;
const SDIO_DPC_IRQ_ACK_ATTEMPTS: u8 = 3;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcRingPublishResult {
    Published(u32),
    Full,
    BadEpoch,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcRingConsumeResult {
    Event(DriverRuntimeDpcEventEntry),
    Empty,
    BadEpoch,
    BadSequence,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcConsumerWakeRoute {
    SelfSignal,
    OwnerRearm,
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioDpcCaptureDisposition {
    HoldPending,
    InspectSource,
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcReadinessAction {
    Drain,
    AdvanceAndRearm,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcRxStartRoute {
    PostStatus,
    Firstread,
    NextFrame(usize),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcEventFrameHint {
    None,
    Frame(usize),
    Invalid,
}

const fn cyw43_dpc_event_frame_hint(flags: u16, signal_status: u32) -> Cyw43DpcEventFrameHint {
    if flags & DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING == 0 {
        return Cyw43DpcEventFrameHint::None;
    }
    // A zero-valued SOURCE_PENDING event is a generation-bound request to
    // inspect the dongle source through the ordinary DPC cursor. It carries no
    // speculative RFRAME length; only a nonzero producer hint may seed the
    // retained Function-2 read length.
    if signal_status == 0 {
        return Cyw43DpcEventFrameHint::None;
    }
    let frame_len = signal_status as usize;
    if cyw43_sdpcm_frame_len_valid(frame_len) {
        Cyw43DpcEventFrameHint::Frame(frame_len)
    } else {
        Cyw43DpcEventFrameHint::Invalid
    }
}

const fn cyw43_dpc_post_route_marks_quiescent(route: Cyw43DpcRxStartRoute) -> bool {
    matches!(route, Cyw43DpcRxStartRoute::PostStatus)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcInvalidFirstreadRoute {
    Quiescent,
    Recover,
}

const fn cyw43_dpc_invalid_firstread_route(prefix_empty: bool) -> Cyw43DpcInvalidFirstreadRoute {
    if prefix_empty {
        Cyw43DpcInvalidFirstreadRoute::Quiescent
    } else {
        Cyw43DpcInvalidFirstreadRoute::Recover
    }
}

const fn cyw43_engine_local_generation(static_epoch: u32, active_epoch: u32) -> u32 {
    if active_epoch == 0 {
        static_epoch
    } else {
        active_epoch
    }
}

const fn cyw43_dpc_activation_completion_exact(
    completion: DriverTaskCompletionRecord,
    sequence: u32,
    requested: u32,
) -> bool {
    completion.sequence == sequence
        && completion.code == COMPLETION_PROGRESS
        && completion.detail == FAULT_NONE
        && completion.result == requested
        && completion.frame.offset == 0
        && completion.frame.len == 0
        && completion.frame.flags == 0
}

const fn cyw43_dpc_source_probe_completion_exact(
    completion: DriverTaskCompletionRecord,
    sequence: u32,
) -> bool {
    completion.sequence == sequence
        && completion.code == COMPLETION_PROGRESS
        && completion.detail == FAULT_NONE
        && completion.frame.offset == 0
        && completion.frame.len == 0
        && completion.frame.flags == 0
}

const fn cyw43_dpc_activation_failure_result(completion: DriverTaskCompletionRecord) -> u32 {
    if completion.result != 0 {
        // Site-tagged SDIO owner rejections and controller failures are the
        // primitive cause. Preserve them unchanged through the CYW43 parent.
        completion.result
    } else {
        // A result-less terminal still carries its primitive completion class
        // and detail: rejection is 0x0005_0001, transfer failure is
        // 0x0005_5103, and malformed success is 0x0001_0000. Zero remains
        // reserved for no exact completion (issued-unknown/link timeout).
        (completion.code as u32) << 16 | completion.detail as u32
    }
}

/// Publish one immutable exact-image source location on the first transition.
///
/// `line!()` is evaluated at the call site. The value is diagnostic only and
/// cannot change queue, DPC, scheduler, or recovery authority.
macro_rules! cyw43_poison_rx_queue_state {
    ($state:expr) => {
        cyw43_poison_rx_queue_state_from($state, line!())
    };
}

fn cyw43_mark_issued_unknown(state: &mut Cyw43RuntimeState) {
    state.sdpcm_tx_write_ambiguous = true;
    state.invalidate_steady_data_plane();
    cyw43_poison_rx_queue_state!(state);
    state.initialized = false;
    state.transport_ready = false;
    state.firmware_released = false;
}

const fn cyw43_dpc_rx_start_route(
    rxskip: bool,
    pending_intstatus: u32,
    next_frame_len: u16,
    next_frame_from_rframe: bool,
) -> Cyw43DpcRxStartRoute {
    if rxskip {
        return Cyw43DpcRxStartRoute::PostStatus;
    }
    let next_frame_len = next_frame_len as usize;
    if cyw43_sdpcm_frame_len_valid(next_frame_len) {
        if next_frame_from_rframe {
            // RFRAME is only a readiness hint. Linux still obtains the
            // authoritative length/complement pair from the fixed first read.
            return Cyw43DpcRxStartRoute::Firstread;
        }
        return Cyw43DpcRxStartRoute::NextFrame(next_frame_len);
    }
    if pending_intstatus & I_HMB_FRAME_IND != 0 {
        // A latched FRAME_IND authorizes the fixed Function 2 first read even
        // when the diagnostic RFRAME count is zero. Match Linux brcmfmac:
        // a source wake with zero firmware status is spurious/quiescent and
        // does not by itself authorize a Function 2 FIFO transfer.
        Cyw43DpcRxStartRoute::Firstread
    } else {
        Cyw43DpcRxStartRoute::PostStatus
    }
}

const fn cyw43_dpc_rx_queue_reserve(state: &Cyw43RuntimeState) -> usize {
    let glom_subframes = state.glom_subframe_count as usize;
    if glom_subframes == 0 {
        1
    } else {
        glom_subframes
    }
}

const fn cyw43_dpc_rx_queue_backpressured(state: &Cyw43RuntimeState) -> bool {
    state.rx_queue_count as usize + cyw43_dpc_rx_queue_reserve(state) > CYW43_RX_QUEUE_CAP
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcDurableWorkRoute {
    None,
    ExternalWait,
    Service,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcIdlePrewaitRoute {
    Block,
    ExternalWait,
    ReenterService,
}

const fn cyw43_dpc_idle_prewait_route(
    durable_work: Cyw43DpcDurableWorkRoute,
) -> Cyw43DpcIdlePrewaitRoute {
    match durable_work {
        Cyw43DpcDurableWorkRoute::None => Cyw43DpcIdlePrewaitRoute::Block,
        Cyw43DpcDurableWorkRoute::ExternalWait => Cyw43DpcIdlePrewaitRoute::ExternalWait,
        Cyw43DpcDurableWorkRoute::Service => Cyw43DpcIdlePrewaitRoute::ReenterService,
    }
}

const fn cyw43_should_run_durable_dpc(
    command_ready: bool,
    durable_work: Cyw43DpcDurableWorkRoute,
    child_active: bool,
) -> bool {
    matches!(durable_work, Cyw43DpcDurableWorkRoute::Service) && !command_ready && !child_active
}

/// Classify the current DPC lifetime from durable state only.
///
/// A current-generation source-bearing front event admits the lifetime. Once
/// admitted, the exact active cursor retains that authority through every
/// private phase. The deferred atomic and notification history are deliberately
/// absent: they can prompt this recheck, but cannot create or renew work.
#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_durable_work_route() -> Cyw43DpcDurableWorkRoute {
    CYW43_RUNTIME_STATE.with_ref(|state| {
        if !state.dpc_link_ready
            || state.dpc_shared_epoch == 0
            || state.recovery_required
            || state.dpc_terminal_cause.active()
            || CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire)
        {
            return Cyw43DpcDurableWorkRoute::None;
        }

        let base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let front_event = match dpc_event_ring_peek_at(base, state.dpc_shared_epoch) {
            DpcRingConsumeResult::Event(event) if cyw43_dpc_event_has_source(event.flags) => {
                Some(event)
            }
            DpcRingConsumeResult::Event(_)
            | DpcRingConsumeResult::Empty
            | DpcRingConsumeResult::BadEpoch
            | DpcRingConsumeResult::BadSequence => None,
        };
        let cursor = state.dpc_cursor;
        if cursor.event_sequence == 0 {
            return if front_event.is_some() {
                Cyw43DpcDurableWorkRoute::Service
            } else {
                Cyw43DpcDurableWorkRoute::None
            };
        }

        let cursor_exact = state.dpc_active_sequence == cursor.event_sequence
            && front_event.is_some_and(|event| event.sequence == cursor.event_sequence);
        if !cursor_exact {
            // A cursor without its immutable source event cannot authorize bus
            // access. The normal generation fault path remains responsible for
            // containment; never turn a stale scheduling hint into work.
            return Cyw43DpcDurableWorkRoute::ExternalWait;
        }
        if cursor.child.issued_unknown || CYW43_SDIO_CHILD_ISSUED_UNKNOWN.load(Ordering::Acquire) {
            return Cyw43DpcDurableWorkRoute::None;
        }
        if cursor.child.active {
            if !cyw43_dpc_child_steady_service_lease_exact(&cursor)
                || !CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire)
                || CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire)
                    != cursor.child.expected_sequence
            {
                // Re-enter once so the exact DPC child poll records the typed
                // identity failure and quarantines this generation.
                return Cyw43DpcDurableWorkRoute::Service;
            }
            return match cyw43_sdio_child_poll_exact(Cyw43SdioChildState::new(
                cursor.child.expected_sequence,
            )) {
                Cyw43SdioChildCompletion::Exact(_) => Cyw43DpcDurableWorkRoute::Service,
                Cyw43SdioChildCompletion::Waiting => Cyw43DpcDurableWorkRoute::ExternalWait,
            };
        }
        if CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire) {
            return Cyw43DpcDurableWorkRoute::ExternalWait;
        }
        if cursor.action == Cyw43DpcAction::RxQueueWait && cyw43_dpc_rx_queue_backpressured(state) {
            return Cyw43DpcDurableWorkRoute::ExternalWait;
        }
        Cyw43DpcDurableWorkRoute::Service
    })
}

const fn cyw43_dpc_child_blocks_cursor(global_child_active: bool, dpc_child_active: bool) -> bool {
    global_child_active && !dpc_child_active
}

const fn cyw43_dpc_wait_services_cursor(
    dpc_cursor_active: bool,
    blocking_child_active: bool,
) -> bool {
    dpc_cursor_active && !blocking_child_active
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcPendingCommandRoute {
    Execute,
    ExecuteTxInterleave,
    Wait,
    ExecuteRecovery,
    FailQuarantined,
}

/// Immutable permission for one Linux-style TX interleave at an RX quantum
/// boundary. It names the retained event and exact sealed foreground parent;
/// consuming it changes only the cursor's fairness count.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43DpcTxInterleavePermit {
    /// Root-owned logical connection generation carried by the parent.
    owner_generation: u32,
    /// SDIO-owner physical bus-link epoch carried by every child.
    generation: u32,
    event_sequence: u32,
    parent_sequence: u32,
}

#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_tx_interleave_permit(
    command: DriverTaskCommandRecord,
    global_child_active: bool,
    quarantined: bool,
) -> Option<Cyw43DpcTxInterleavePermit> {
    if global_child_active
        || quarantined
        || CYW43_SDIO_CHILD_ISSUED_UNKNOWN.load(Ordering::Acquire)
        || CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire)
    {
        return None;
    }
    let permit = CYW43_RUNTIME_STATE.with_ref(|state| {
        let cursor = state.dpc_cursor;
        if !state.initialized
            || !state.transport_ready
            || !state.firmware_released
            || !state.dpc_link_ready
            || state.dpc_shared_epoch == 0
            || state.recovery_required
            || state.dpc_terminal_cause.active()
            || state.control_exchange.active()
            || state.sdpcm_tx_write_ambiguous
            || !state.rx_service_active
            || state.dpc_active_sequence == 0
            || state.dpc_active_sequence != cursor.event_sequence
            || cursor.event_sequence == 0
            || cursor.action != Cyw43DpcAction::RxQuantumBoundary
            || cursor.io_kind != Cyw43DpcIoKind::None
            || cursor.io_phase != Cyw43DpcIoPhase::Idle
            || cursor.child.active
            || cursor.child.issued_unknown
            || cursor.rx_quantum_frames != CYW43_DPC_RX_BOUND
        {
            return None;
        }
        Some(Cyw43DpcTxInterleavePermit {
            owner_generation: command.aux1,
            generation: state.dpc_shared_epoch,
            event_sequence: cursor.event_sequence,
            parent_sequence: command.sequence,
        })
    })?;
    if cyw43_steady_parent_service_lease_admission(command, permit.owner_generation)
        != Cyw43SteadyParentAdmission::Admitted
    {
        return None;
    }
    let ring = dpc_event_ring_read_at(
        DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
    );
    if !ring.valid()
        || ring.epoch != permit.generation
        || ring.consumer.wrapping_add(1) != permit.event_sequence
    {
        return None;
    }
    match cyw43_runtime_dpc_event_peek() {
        DpcRingConsumeResult::Event(event) if event.sequence == permit.event_sequence => {
            Some(permit)
        }
        DpcRingConsumeResult::Event(_)
        | DpcRingConsumeResult::Empty
        | DpcRingConsumeResult::BadEpoch
        | DpcRingConsumeResult::BadSequence => None,
    }
}

#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_consume_tx_interleave_permit(
    state: &mut Cyw43RuntimeState,
    command: DriverTaskCommandRecord,
    permit: Cyw43DpcTxInterleavePermit,
) -> bool {
    let cursor = &mut state.dpc_cursor;
    if command.sequence != permit.parent_sequence
        || command.aux1 != permit.owner_generation
        || state.dpc_shared_epoch != permit.generation
        || state.dpc_active_sequence != permit.event_sequence
        || cursor.event_sequence != permit.event_sequence
        || cursor.action != Cyw43DpcAction::RxQuantumBoundary
        || cursor.io_kind != Cyw43DpcIoKind::None
        || cursor.io_phase != Cyw43DpcIoPhase::Idle
        || cursor.child.active
        || cursor.child.issued_unknown
        || cursor.rx_quantum_frames != CYW43_DPC_RX_BOUND
        || state.recovery_required
        || state.dpc_terminal_cause.active()
    {
        return false;
    }
    cursor.rx_quantum_frames = 0;
    true
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43ForegroundDpcWatermark {
    command_sequence: u32,
    captured_consumer: u32,
    producer_watermark: u32,
    armed: bool,
}

impl Cyw43ForegroundDpcWatermark {
    const fn empty() -> Self {
        Self {
            command_sequence: 0,
            captured_consumer: 0,
            producer_watermark: 0,
            armed: false,
        }
    }

    const fn capture(command_sequence: u32, consumer: u32, producer: u32) -> Self {
        Self {
            command_sequence,
            captured_consumer: consumer,
            producer_watermark: producer,
            armed: producer.wrapping_sub(consumer) <= DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32,
        }
    }

    const fn belongs_to(self, command_sequence: u32) -> bool {
        self.armed && self.command_sequence == command_sequence
    }

    const fn includes(self, event_sequence: u32) -> bool {
        if !self.armed {
            return false;
        }
        let captured = self.producer_watermark.wrapping_sub(self.captured_consumer);
        let event_offset = event_sequence.wrapping_sub(self.captured_consumer);
        event_offset != 0 && event_offset <= captured
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43ForegroundDpcWatermarkRefresh {
    Ready(Cyw43ForegroundDpcWatermark),
    InvariantFault { event_sequence: u32 },
}

impl Cyw43ForegroundDpcWatermarkRefresh {
    #[cfg(test)]
    const fn ready(self) -> Option<Cyw43ForegroundDpcWatermark> {
        match self {
            Self::Ready(watermark) => Some(watermark),
            Self::InvariantFault { .. } => None,
        }
    }
}

const fn cyw43_dpc_pending_command_route(
    cursor_active: bool,
    child_active: bool,
    quarantined: bool,
    explicit_recovery: bool,
    queue_only_ready: bool,
    tx_interleave_ready: bool,
) -> Cyw43DpcPendingCommandRoute {
    if queue_only_ready && !quarantined {
        Cyw43DpcPendingCommandRoute::Execute
    } else if child_active {
        Cyw43DpcPendingCommandRoute::Wait
    } else if quarantined && explicit_recovery {
        Cyw43DpcPendingCommandRoute::ExecuteRecovery
    } else if quarantined {
        Cyw43DpcPendingCommandRoute::FailQuarantined
    } else if cursor_active && tx_interleave_ready {
        Cyw43DpcPendingCommandRoute::ExecuteTxInterleave
    } else if cursor_active || child_active {
        Cyw43DpcPendingCommandRoute::Wait
    } else {
        Cyw43DpcPendingCommandRoute::Execute
    }
}

#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_queue_only_delivery_ready(
    command: DriverTaskCommandRecord,
    state: &Cyw43RuntimeState,
    quarantined: bool,
) -> bool {
    if quarantined
        || state.recovery_required
        || state.rx_queue_count == 0
        || state.dpc_shared_epoch == 0
        || command.aux1 == 0
        || !cyw43_command_uses_foreground_transaction(command)
    {
        return false;
    }
    let owner_ring = dpc_event_ring_read_at(
        DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
    );
    if !cyw43_foreground_new_frontier_generation_valid(state.dpc_shared_epoch, Some(&owner_ring))
        || owner_ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE == 0
    {
        return false;
    }
    CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        let descriptor = transaction.parent_descriptor;
        let prompt_cursor = state.prompt_poll;
        let prompt_identity_safe = !prompt_cursor.active()
            || (prompt_cursor.parent_matches(command.sequence)
                && prompt_cursor.generation == state.dpc_shared_epoch
                && prompt_cursor.descriptor == descriptor);
        transaction.parent_input_sealed
            && transaction.parent == command
            && transaction.parent_descriptor_valid
            && cyw43_prompt_poll_descriptor_strict(descriptor)
            && descriptor.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD == 0
            && prompt_identity_safe
            && !state.control_exchange.active()
    })
}

#[cfg(any(target_os = "none", test))]
fn cyw43_dpc_pending_intake_route(
    intake: RuntimeCommandIntake,
    state: &Cyw43RuntimeState,
    cursor_active: bool,
    child_active: bool,
    quarantined: bool,
    explicit_recovery: bool,
    tx_interleave_ready: bool,
) -> Cyw43DpcPendingCommandRoute {
    cyw43_dpc_pending_command_route(
        cursor_active,
        child_active,
        quarantined,
        explicit_recovery,
        cyw43_dpc_queue_only_delivery_ready(intake.command, state, quarantined),
        tx_interleave_ready,
    )
}

fn cyw43_dpc_command_requires_preflight(
    pending_command: bool,
    cursor_active: bool,
    child_active: bool,
    quarantined: bool,
    event: DpcRingConsumeResult,
    watermark: Cyw43ForegroundDpcWatermark,
    foreground_condition_admits_event: bool,
) -> bool {
    if !pending_command || cursor_active || child_active || quarantined {
        return false;
    }
    match event {
        DpcRingConsumeResult::Event(event) => {
            watermark.includes(event.sequence) || foreground_condition_admits_event
        }
        // A malformed or wrong-generation ring is never bypassed by a
        // foreground card operation. Its normal service path records the
        // precise fault and preserves CARD_INT quarantine semantics.
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => true,
        DpcRingConsumeResult::Empty => false,
    }
}

fn cyw43_dpc_explicit_recovery_command(command: DriverTaskCommandRecord) -> bool {
    command.opcode == OPCODE_SERVICE
        && command.frame.len == 0
        && command_is_engine_init_aux(command.aux0)
}

const fn cyw43_dpc_generation_quarantined(recovery_required: bool, issued_unknown: bool) -> bool {
    recovery_required || issued_unknown
}

const fn cyw43_dpc_post_capture_has_work(
    rxskip: bool,
    rx_service_quiescent: bool,
    next_frame_len: u16,
    pending_intstatus: u32,
) -> bool {
    pending_intstatus & (I_HMB_FC_CHANGE | I_HMB_HOST_INT) != 0
        || (!rxskip
            && (pending_intstatus & I_HMB_FRAME_IND != 0
                || !rx_service_quiescent
                || next_frame_len != 0))
}

const fn cyw43_dpc_latched_causes(sampled_status: u32) -> u32 {
    sampled_status & (I_HMB_FRAME_IND | I_HMB_FC_CHANGE | I_HMB_HOST_INT)
}

const fn cyw43_dpc_w1c_status(sampled_status: u32) -> u32 {
    sampled_status & HOSTINTMASK
}

const fn cyw43_dpc_status_requires_ack(sampled_status: u32) -> bool {
    cyw43_dpc_w1c_status(sampled_status) != 0
}

fn cyw43_dpc_record_initial_source(state: &mut Cyw43RuntimeState, sampled_status: u32) {
    // Classify the exact initial SDIO-core status sample before the service
    // mask selects W1C ownership. This keeps masked error/out-of-sync causes
    // visible as `other` instead of mislabelling a nonzero episode spurious.
    let sampled = sampled_status;
    let known = I_HMB_FRAME_IND | I_HMB_HOST_INT | I_HMB_FC_CHANGE | I_HMB_FC_STATE | I_CHIPACTIVE;
    state.dpc_source_samples = state.dpc_source_samples.saturating_add(1);
    if sampled & I_HMB_FRAME_IND != 0 {
        state.dpc_source_frame = state.dpc_source_frame.saturating_add(1);
    }
    if sampled & I_HMB_HOST_INT != 0 {
        state.dpc_source_hostmail = state.dpc_source_hostmail.saturating_add(1);
    }
    if sampled & I_HMB_FC_CHANGE != 0 {
        state.dpc_source_fc_change = state.dpc_source_fc_change.saturating_add(1);
    }
    if sampled & I_HMB_FC_STATE != 0 {
        state.dpc_source_fc_state = state.dpc_source_fc_state.saturating_add(1);
    }
    if sampled & I_CHIPACTIVE != 0 {
        state.dpc_source_chipactive = state.dpc_source_chipactive.saturating_add(1);
    }
    if sampled & !known != 0 {
        state.dpc_source_other = state.dpc_source_other.saturating_add(1);
    }
    if sampled == 0 {
        state.dpc_source_spurious = state.dpc_source_spurious.saturating_add(1);
    }
}

fn cyw43_dpc_record_event_turn(state: &mut Cyw43RuntimeState) {
    state.dpc_turns = state.dpc_turns.saturating_add(1);
}

fn cyw43_dpc_record_owner_child(state: &mut Cyw43RuntimeState) {
    state.dpc_owner_children = state.dpc_owner_children.saturating_add(1);
    // Account for the eventual terminal owner slice at child publication.
    // Every earlier retained Pending slice is reported separately by the
    // exact monotonic service-progress record.
    state.dpc_owner_turns = state.dpc_owner_turns.saturating_add(1);
}

fn cyw43_dpc_record_owner_progress(
    state: &mut Cyw43RuntimeState,
    previous_slice: u32,
    current_slice: u32,
) {
    if current_slice > previous_slice {
        state.dpc_owner_turns = state
            .dpc_owner_turns
            .saturating_add(current_slice - previous_slice);
    }
}

fn cyw43_dpc_record_owner_grant(state: &mut Cyw43RuntimeState, published: bool) {
    if published {
        state.dpc_owner_turns = state.dpc_owner_turns.saturating_add(1);
    }
}

fn cyw43_dpc_record_completed_frame(state: &mut Cyw43RuntimeState) {
    let frame_turns = state
        .dpc_turns
        .saturating_sub(state.dpc_last_frame_turn_mark);
    let owner_turns = state
        .dpc_owner_turns
        .saturating_sub(state.dpc_last_frame_owner_turn_mark);
    state.dpc_frames_completed = state.dpc_frames_completed.saturating_add(1);
    state.dpc_frame_turns = state.dpc_frame_turns.saturating_add(frame_turns);
    state.dpc_frame_owner_turns = state.dpc_frame_owner_turns.saturating_add(owner_turns);
    state.dpc_last_frame_turn_mark = state.dpc_turns;
    state.dpc_last_frame_owner_turn_mark = state.dpc_owner_turns;
}

const fn runtime_command_poll_due(pending_intake: bool) -> bool {
    !pending_intake
}

const fn cyw43_post_release_dpc_missing(firmware_released: bool, dpc_link_ready: bool) -> bool {
    firmware_released && !dpc_link_ready
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcRecoveryDrainRoute {
    PostNak,
    Retry,
    Quarantine,
}

const fn cyw43_dpc_recovery_drain_route(
    frame_count: u16,
    completed_polls: usize,
    deadline_expired: bool,
) -> Cyw43DpcRecoveryDrainRoute {
    if frame_count == 0 {
        Cyw43DpcRecoveryDrainRoute::PostNak
    } else if completed_polls >= CYW43_RX_SOURCE_RECOVERY_DRAIN_POLLS || deadline_expired {
        Cyw43DpcRecoveryDrainRoute::Quarantine
    } else {
        Cyw43DpcRecoveryDrainRoute::Retry
    }
}

const fn cyw43_dpc_recovery_settle_ready(
    start_ticks: u64,
    settle_cycles: u64,
    current_ticks: u64,
    fallback_turns: u8,
) -> bool {
    if start_ticks != 0 && settle_cycles != 0 && current_ticks != 0 {
        current_ticks.wrapping_sub(start_ticks) >= settle_cycles
    } else {
        fallback_turns == 0
    }
}

fn cyw43_dpc_child_completion_matches(
    child: Cyw43DpcChild,
    completion: DriverTaskCompletionRecord,
) -> bool {
    completion.code == child.expected_code
        && completion.detail == FAULT_NONE
        && completion.result == child.expected_result
        && completion.frame.offset == child.expected_frame_offset
        && completion.frame.len == child.expected_frame_len
        && completion.frame.flags == 0
}

const fn cyw43_dpc_readiness_action(
    initialized: bool,
    transport_ready: bool,
    firmware_execution_started: bool,
    firmware_released: bool,
) -> Cyw43DpcReadinessAction {
    if initialized && transport_ready && firmware_execution_started && firmware_released {
        Cyw43DpcReadinessAction::Drain
    } else {
        // Pre-release CARD_INT edges are advisory: firmware/card bring-up uses
        // synchronous register polling. Completing the event prevents an early
        // edge from leaving SDHCI signaling masked across firmware release.
        Cyw43DpcReadinessAction::AdvanceAndRearm
    }
}

fn dpc_event_ring_publish(
    ring: &mut DriverRuntimeDpcEventRing,
    epoch: u32,
    host_int_status: u32,
    signal_status: u32,
    reason: u16,
    flags: u16,
) -> DpcRingPublishResult {
    if !ring.valid() || ring.epoch != epoch {
        return DpcRingPublishResult::BadEpoch;
    }
    if ring.producer.wrapping_sub(ring.consumer) >= DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32 {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN;
        ring.overruns = ring.overruns.saturating_add(1);
        return DpcRingPublishResult::Full;
    }
    let sequence = ring.producer.wrapping_add(1);
    let slot = ring.producer as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
    ring.entries[slot] = DriverRuntimeDpcEventEntry {
        sequence,
        host_int_status,
        signal_status,
        reason,
        flags,
    };
    ring.producer = sequence;
    DpcRingPublishResult::Published(sequence)
}

fn dpc_event_ring_publish_sequence_last(
    sequence: u32,
    event: DriverRuntimeDpcEventEntry,
    mut write_sequence: impl FnMut(u32) -> bool,
    mut write_body: impl FnMut(DriverRuntimeDpcEventEntry) -> bool,
    mut release: impl FnMut(),
    mut write_producer: impl FnMut(u32) -> bool,
) -> bool {
    if !write_sequence(0) || !write_body(event) {
        return false;
    }
    release();
    if !write_sequence(sequence) {
        return false;
    }
    release();
    write_producer(sequence)
}

fn dpc_event_ring_peek(ring: &DriverRuntimeDpcEventRing, epoch: u32) -> DpcRingConsumeResult {
    if !ring.valid() || ring.epoch != epoch {
        return DpcRingConsumeResult::BadEpoch;
    }
    if ring.producer == ring.consumer {
        return DpcRingConsumeResult::Empty;
    }
    let expected = ring.consumer.wrapping_add(1);
    let slot = ring.consumer as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
    let event = ring.entries[slot];
    if event.sequence != expected || !event.valid() {
        return DpcRingConsumeResult::BadSequence;
    }
    DpcRingConsumeResult::Event(event)
}

fn dpc_event_ring_advance(ring: &mut DriverRuntimeDpcEventRing, epoch: u32, sequence: u32) -> bool {
    if !matches!(
        dpc_event_ring_peek(ring, epoch),
        DpcRingConsumeResult::Event(event) if event.sequence == sequence
    ) {
        return false;
    }
    ring.consumer = sequence;
    true
}

fn dpc_event_ring_set_owner_health(
    ring: &mut DriverRuntimeDpcEventRing,
    card_irq_masked: bool,
    ack_pending: bool,
    poisoned: bool,
    ack_failed: bool,
) {
    // These flags describe only the current admitted epoch. Historical owner
    // failures remain visible through cumulative overrun/ack counters when a
    // clean post-re-enumeration generation replaces a poisoned ring.
    ring.flags &= !(DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED
        | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING
        | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED);
    if card_irq_masked {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED;
    }
    if ack_pending {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING;
    }
    if poisoned {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED;
    }
    if ack_failed {
        ring.ack_failures = ring.ack_failures.saturating_add(1);
    }
}

fn dpc_event_ring_set_owner_active(ring: &mut DriverRuntimeDpcEventRing, owner_active: bool) {
    ring.flags &= !DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE;
    if owner_active {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE;
    }
}

fn dpc_consumer_wake_route(ring: &DriverRuntimeDpcEventRing, epoch: u32) -> DpcConsumerWakeRoute {
    match dpc_event_ring_peek(ring, epoch) {
        DpcRingConsumeResult::Event(_) => DpcConsumerWakeRoute::SelfSignal,
        DpcRingConsumeResult::Empty => DpcConsumerWakeRoute::OwnerRearm,
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => {
            DpcConsumerWakeRoute::Fault
        }
    }
}

const fn cyw43_dpc_event_has_source(flags: u16) -> bool {
    flags
        & (DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT
            | DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING)
        != 0
}

fn sdio_dpc_capture_disposition(
    ring: &DriverRuntimeDpcEventRing,
    epoch: u32,
    append_behind_active: bool,
) -> SdioDpcCaptureDisposition {
    match dpc_event_ring_peek(ring, epoch) {
        DpcRingConsumeResult::Event(_) if append_behind_active => {
            SdioDpcCaptureDisposition::InspectSource
        }
        DpcRingConsumeResult::Event(_) => SdioDpcCaptureDisposition::HoldPending,
        DpcRingConsumeResult::Empty => SdioDpcCaptureDisposition::InspectSource,
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => {
            SdioDpcCaptureDisposition::Fault
        }
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy)]
enum RuntimeRingWindowKind {
    Local,
    SdioOwner,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy)]
enum RuntimeVolatileWidth {
    U8,
    U16,
    U32,
}

#[cfg(any(target_os = "none", test))]
impl RuntimeVolatileWidth {
    const fn bytes(self) -> usize {
        match self {
            Self::U8 => core::mem::size_of::<u8>(),
            Self::U16 => core::mem::size_of::<u16>(),
            Self::U32 => core::mem::size_of::<u32>(),
        }
    }
}

#[cfg(target_os = "none")]
fn runtime_volatile_read(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
) -> Option<u32> {
    let (base, len) = match kind {
        RuntimeRingWindowKind::Local => (DRIVER_TASK_RING_VADDR, DRIVER_TASK_RING_PAGE_BYTES),
        RuntimeRingWindowKind::SdioOwner => (
            DRIVER_TASK_SDIO_BUS_RING_VADDR,
            DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
        ),
    };
    let bytes = width.bytes();
    let end = offset.checked_add(bytes)?;
    let address = base.checked_add(offset)?;
    if base == 0 || end > len || address & (bytes - 1) != 0 {
        return None;
    }
    // SAFETY: The caller supplies one of the fixed HAL-admitted runtime
    // mappings. Checked arithmetic, range validation, and natural alignment
    // keep this single volatile primitive access inside that mapping.
    unsafe {
        Some(match width {
            RuntimeVolatileWidth::U8 => u32::from(core::ptr::read_volatile(address as *const u8)),
            RuntimeVolatileWidth::U16 => u32::from(u16::from_le(core::ptr::read_volatile(
                address as *const u16,
            ))),
            RuntimeVolatileWidth::U32 => {
                u32::from_le(core::ptr::read_volatile(address as *const u32))
            }
        })
    }
}

#[cfg(target_os = "none")]
fn runtime_volatile_write(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
    value: u32,
) -> bool {
    let (base, len) = match kind {
        RuntimeRingWindowKind::Local => (DRIVER_TASK_RING_VADDR, DRIVER_TASK_RING_PAGE_BYTES),
        RuntimeRingWindowKind::SdioOwner => (
            DRIVER_TASK_SDIO_BUS_RING_VADDR,
            DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
        ),
    };
    let bytes = width.bytes();
    let Some(end) = offset.checked_add(bytes) else {
        return false;
    };
    let Some(address) = base.checked_add(offset) else {
        return false;
    };
    if base == 0 || end > len || address & (bytes - 1) != 0 {
        return false;
    }
    // SAFETY: The caller supplies one of the fixed HAL-admitted runtime
    // mappings. Checked arithmetic, range validation, and natural alignment
    // keep this single volatile primitive access inside that mapping.
    unsafe {
        match width {
            RuntimeVolatileWidth::U8 => {
                core::ptr::write_volatile(address as *mut u8, value as u8);
            }
            RuntimeVolatileWidth::U16 => {
                core::ptr::write_volatile(address as *mut u16, (value as u16).to_le());
            }
            RuntimeVolatileWidth::U32 => {
                core::ptr::write_volatile(address as *mut u32, value.to_le());
            }
        }
    }
    true
}

#[cfg(all(not(target_os = "none"), test))]
fn runtime_test_window(kind: RuntimeRingWindowKind) -> (*mut u8, usize) {
    assert_test_state_guard_held();
    match kind {
        RuntimeRingWindowKind::Local => {
            (TEST_RING.0.get().cast::<u8>(), DRIVER_TASK_RING_PAGE_BYTES)
        }
        RuntimeRingWindowKind::SdioOwner => (
            TEST_SDIO_OWNER_RING.0.get().cast::<u8>(),
            TEST_SDIO_OWNER_RING_BYTES,
        ),
    }
}

#[cfg(all(not(target_os = "none"), test))]
fn runtime_volatile_read(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
) -> Option<u32> {
    let (base, len) = runtime_test_window(kind);
    let bytes = width.bytes();
    let end = offset.checked_add(bytes)?;
    if end > len || offset & (bytes - 1) != 0 {
        return None;
    }
    let mut value = 0u32;
    for index in 0..bytes {
        // SAFETY: `runtime_test_window` returns one process-local fixed test
        // buffer, the checked range remains inside it, and `test_guard`
        // serializes every access. Byte-wise volatile access avoids imposing
        // an alignment requirement on the backing array.
        let byte = unsafe { core::ptr::read_volatile(base.add(offset + index)) };
        value |= u32::from(byte) << (index * 8);
    }
    Some(value)
}

#[cfg(all(not(target_os = "none"), test))]
fn runtime_volatile_write(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
    value: u32,
) -> bool {
    let (base, len) = runtime_test_window(kind);
    let bytes = width.bytes();
    let Some(end) = offset.checked_add(bytes) else {
        return false;
    };
    if end > len || offset & (bytes - 1) != 0 {
        return false;
    }
    for index in 0..bytes {
        // SAFETY: `runtime_test_window` returns one process-local fixed test
        // buffer, the checked range remains inside it, and `test_guard`
        // serializes every access. Byte-wise volatile access avoids imposing
        // an alignment requirement on the backing array.
        unsafe {
            core::ptr::write_volatile(base.add(offset + index), (value >> (index * 8)) as u8);
        }
    }
    true
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy)]
struct RuntimeRingWindow {
    kind: RuntimeRingWindowKind,
    start: usize,
    len: usize,
}

#[cfg(any(target_os = "none", test))]
impl RuntimeRingWindow {
    const fn local() -> Self {
        Self {
            kind: RuntimeRingWindowKind::Local,
            start: 0,
            len: DRIVER_TASK_RING_PAGE_BYTES,
        }
    }

    fn sdio_owner() -> Option<Self> {
        RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
            let link = descriptor_notification_dpc_link(descriptor)?;
            (descriptor.hot_path == HOT_PATH_CYW43_WIFI
                && link.owner_hot_path == HOT_PATH_SDIO_HOST
                && usize::from(link.event_offset).checked_add(usize::from(link.event_len))?
                    <= DRIVER_TASK_RING_PAGE_BYTES)
                .then_some(Self {
                    kind: RuntimeRingWindowKind::SdioOwner,
                    start: 0,
                    len: DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
                })
        })
    }

    fn dpc_at(base: usize) -> Option<Self> {
        let offset = usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let len = core::mem::size_of::<DriverRuntimeDpcEventRing>();
        if base == DRIVER_TASK_RING_VADDR.checked_add(offset)? {
            let link_valid = RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
                descriptor_notification_dpc_link(descriptor).is_some_and(|link| {
                    descriptor.hot_path == HOT_PATH_SDIO_HOST
                        && usize::from(link.event_offset) == offset
                        && usize::from(link.event_len) == len
                })
            });
            return link_valid.then_some(Self {
                kind: RuntimeRingWindowKind::Local,
                start: offset,
                len,
            });
        }
        if base == DRIVER_TASK_SDIO_BUS_RING_VADDR.checked_add(offset)? {
            let owner = Self::sdio_owner()?;
            return Some(Self {
                kind: owner.kind,
                start: offset,
                len,
            });
        }
        None
    }

    fn primitive_offset(self, offset: usize, width: RuntimeVolatileWidth) -> Option<usize> {
        let end = offset.checked_add(width.bytes())?;
        if end > self.len {
            return None;
        }
        self.start.checked_add(offset)
    }

    fn read_u8(self, offset: usize) -> Option<u8> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U8)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U8)
            .map(|value| value as u8)
    }

    fn write_u8(self, offset: usize, value: u8) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U8) else {
            return false;
        };
        runtime_volatile_write(
            self.kind,
            absolute,
            RuntimeVolatileWidth::U8,
            u32::from(value),
        )
    }

    fn read_u16(self, offset: usize) -> Option<u16> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U16)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U16)
            .map(|value| value as u16)
    }

    fn write_u16(self, offset: usize, value: u16) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U16) else {
            return false;
        };
        runtime_volatile_write(
            self.kind,
            absolute,
            RuntimeVolatileWidth::U16,
            u32::from(value),
        )
    }

    fn read_u32(self, offset: usize) -> Option<u32> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U32)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U32)
    }

    fn write_u32(self, offset: usize, value: u32) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U32) else {
            return false;
        };
        runtime_volatile_write(self.kind, absolute, RuntimeVolatileWidth::U32, value)
    }
}

#[cfg(any(target_os = "none", test))]
impl RuntimeRingRecordIo for RuntimeRingWindow {
    fn read_u16(&self, offset: usize) -> Option<u16> {
        RuntimeRingWindow::read_u16(*self, offset)
    }

    fn read_u32(&self, offset: usize) -> Option<u32> {
        RuntimeRingWindow::read_u32(*self, offset)
    }

    fn write_u16(&mut self, offset: usize, value: u16) -> bool {
        RuntimeRingWindow::write_u16(*self, offset, value)
    }

    fn write_u32(&mut self, offset: usize, value: u32) -> bool {
        RuntimeRingWindow::write_u32(*self, offset, value)
    }
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_decode(window: RuntimeRingWindow) -> Option<DriverRuntimeDpcEventRing> {
    let mut ring = DriverRuntimeDpcEventRing::empty(
        window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, epoch))?,
    );
    ring.magic = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, magic))?;
    ring.version = window.read_u16(core::mem::offset_of!(DriverRuntimeDpcEventRing, version))?;
    ring.len = window.read_u16(core::mem::offset_of!(DriverRuntimeDpcEventRing, len))?;
    ring.producer = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, producer))?;
    ring.consumer = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer))?;
    ring.flags = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, flags))?;
    ring.overruns = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns))?;
    ring.ack_failures = window.read_u32(core::mem::offset_of!(
        DriverRuntimeDpcEventRing,
        ack_failures
    ))?;
    // The producer is the ring-level commit word. The SDIO owner publishes it
    // only after the selected entry's sequence and body are globally visible.
    // Acquire before observing any entry so body loads cannot move ahead of
    // that publication boundary.
    driver_task_shared_load_barrier();
    let entries_offset = core::mem::offset_of!(DriverRuntimeDpcEventRing, entries);
    for (index, entry) in ring.entries.iter_mut().enumerate() {
        let offset = entries_offset
            .checked_add(index.checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())?)?;
        entry.sequence = window
            .read_u32(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence))?;
        // Each entry sequence is its slot-level commit word. An acquire here
        // pairs with the publisher's sequence-last release, preventing a valid
        // sequence from being combined with a stale or partially written body.
        driver_task_shared_load_barrier();
        entry.host_int_status = window.read_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
        )?;
        entry.signal_status = window
            .read_u32(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status))?;
        entry.reason =
            window.read_u16(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason))?;
        entry.flags =
            window.read_u16(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags))?;
    }
    Some(ring)
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_encode(window: RuntimeRingWindow, ring: DriverRuntimeDpcEventRing) -> bool {
    let header_written = window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, magic),
        ring.magic,
    ) && window.write_u16(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, version),
        ring.version,
    ) && window.write_u16(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, len),
        ring.len,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, epoch),
        ring.epoch,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, producer),
        ring.producer,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        ring.consumer,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        ring.flags,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns),
        ring.overruns,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        ring.ack_failures,
    );
    if !header_written {
        return false;
    }
    let entries_offset = core::mem::offset_of!(DriverRuntimeDpcEventRing, entries);
    ring.entries.iter().enumerate().all(|(index, entry)| {
        let Some(offset) = index
            .checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())
            .and_then(|entry_offset| entries_offset.checked_add(entry_offset))
        else {
            return false;
        };
        window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence),
            entry.sequence,
        ) && window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
            entry.host_int_status,
        ) && window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status),
            entry.signal_status,
        ) && window.write_u16(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason),
            entry.reason,
        ) && window.write_u16(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags),
            entry.flags,
        )
    })
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_read_at(base: usize) -> DriverRuntimeDpcEventRing {
    driver_task_shared_invalidate_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
    RuntimeRingWindow::dpc_at(base)
        .and_then(dpc_event_ring_decode)
        .unwrap_or_else(|| DriverRuntimeDpcEventRing::empty(0))
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_initialize_at(base: usize, epoch: u32) {
    let ring = DriverRuntimeDpcEventRing::empty(epoch);
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return;
    };
    if !dpc_event_ring_encode(window, ring) {
        return;
    }
    driver_task_shared_clean_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_publish_at(
    base: usize,
    epoch: u32,
    host_int_status: u32,
    signal_status: u32,
    reason: u16,
    flags: u16,
) -> DpcRingPublishResult {
    let mut snapshot = dpc_event_ring_read_at(base);
    let result = dpc_event_ring_publish(
        &mut snapshot,
        epoch,
        host_int_status,
        signal_status,
        reason,
        flags,
    );
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return DpcRingPublishResult::BadEpoch;
    };
    match result {
        DpcRingPublishResult::Published(sequence) => {
            let slot = sequence.wrapping_sub(1) as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
            let event = snapshot.entries[slot];
            let Some(entry_offset) = slot
                .checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())
                .and_then(|offset| {
                    core::mem::offset_of!(DriverRuntimeDpcEventRing, entries).checked_add(offset)
                })
            else {
                return DpcRingPublishResult::BadEpoch;
            };
            if !dpc_event_ring_publish_sequence_last(
                sequence,
                event,
                |value| {
                    window.write_u32(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence),
                        value,
                    )
                },
                |event| {
                    window.write_u32(
                        entry_offset
                            + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
                        event.host_int_status,
                    ) && window.write_u32(
                        entry_offset
                            + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status),
                        event.signal_status,
                    ) && window.write_u16(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason),
                        event.reason,
                    ) && window.write_u16(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags),
                        event.flags,
                    )
                },
                driver_task_shared_store_barrier,
                |value| {
                    window.write_u32(
                        core::mem::offset_of!(DriverRuntimeDpcEventRing, producer),
                        value,
                    )
                },
            ) {
                return DpcRingPublishResult::BadEpoch;
            }
        }
        DpcRingPublishResult::Full => {
            if !window.write_u32(
                core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
                snapshot.flags,
            ) || !window.write_u32(
                core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns),
                snapshot.overruns,
            ) {
                return DpcRingPublishResult::BadEpoch;
            }
        }
        DpcRingPublishResult::BadEpoch => {}
    }
    driver_task_shared_clean_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
    result
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_peek_at(base: usize, epoch: u32) -> DpcRingConsumeResult {
    let ring = dpc_event_ring_read_at(base);
    dpc_event_ring_peek(&ring, epoch)
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_advance_at(base: usize, epoch: u32, sequence: u32) -> bool {
    let mut ring = dpc_event_ring_read_at(base);
    if !dpc_event_ring_advance(&mut ring, epoch, sequence) {
        return false;
    }
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return false;
    };
    if !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        sequence,
    ) {
        return false;
    }
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        core::mem::size_of::<u32>(),
    );
    true
}

#[cfg(test)]
fn dpc_event_ring_set_owner_health_at(
    base: usize,
    card_irq_masked: bool,
    ack_pending: bool,
    poisoned: bool,
    ack_failed: bool,
) -> bool {
    dpc_event_ring_set_owner_state_at(
        base,
        card_irq_masked,
        None,
        ack_pending,
        poisoned,
        ack_failed,
    )
}

#[cfg(any(target_os = "none", test))]
fn dpc_event_ring_set_owner_state_at(
    base: usize,
    card_irq_masked: bool,
    owner_active: Option<bool>,
    ack_pending: bool,
    poisoned: bool,
    ack_failed: bool,
) -> bool {
    let mut snapshot = dpc_event_ring_read_at(base);
    if !snapshot.valid() {
        return false;
    }
    dpc_event_ring_set_owner_health(
        &mut snapshot,
        card_irq_masked,
        ack_pending,
        poisoned,
        ack_failed,
    );
    if let Some(owner_active) = owner_active {
        dpc_event_ring_set_owner_active(&mut snapshot, owner_active);
    }
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return false;
    };
    if !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        snapshot.flags,
    ) || !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        snapshot.ack_failures,
    ) {
        return false;
    }
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        core::mem::size_of::<u32>(),
    );
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        core::mem::size_of::<u32>(),
    );
    true
}

fn descriptor_notification_dpc_link(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeBusLinkDescriptor> {
    if descriptor.bus_link_count != 1
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS == 0
        || !descriptor_valid_bus_links(descriptor)
    {
        return None;
    }
    let link = descriptor.bus_links[0];
    if !link.notification_dpc_valid()
        || !link.sealed_for_client(descriptor.task_key, descriptor.hot_path)
    {
        return None;
    }
    let role =
        link.flags & (DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER);
    let topology_matches = match descriptor.hot_path {
        HOT_PATH_CYW43_WIFI => {
            role == DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT
                && link.peer_hot_path == HOT_PATH_SDIO_HOST
                && link.local_notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
                && link.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT
        }
        HOT_PATH_SDIO_HOST => {
            role == DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER
                && link.peer_hot_path == HOT_PATH_CYW43_WIFI
                && link.local_notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
                && link.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT
        }
        _ => false,
    };
    topology_matches.then_some(link)
}

fn descriptor_sdio_irq(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeIrqDescriptor> {
    if descriptor.hot_path != HOT_PATH_SDIO_HOST
        || descriptor.irq_count != 2
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY != 0
    {
        return None;
    }
    let irq = descriptor.irqs[0];
    (irq.valid()
        && irq.irq == DRIVER_RUNTIME_SDIO_IRQ
        && irq.badge == DRIVER_RUNTIME_SDIO_IRQ_BADGE
        && irq.handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
        && irq.notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        && irq.trigger == DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL)
        .then_some(irq)
}

fn descriptor_sdio_dma_irq(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeIrqDescriptor> {
    if descriptor.hot_path != HOT_PATH_SDIO_HOST
        || descriptor.irq_count != 2
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY != 0
    {
        return None;
    }
    let irq = descriptor.irqs[1];
    (irq.valid()
        && irq.irq == DRIVER_RUNTIME_SDIO_DMA_IRQ
        && irq.badge == DRIVER_RUNTIME_SDIO_DMA_IRQ_BADGE
        && irq.handler_slot == DRIVER_TASK_CHILD_SDIO_DMA_IRQ_HANDLER_SLOT
        && irq.notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        && irq.trigger == DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL)
        .then_some(irq)
}

fn descriptor_serial_irq(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeIrqDescriptor> {
    if descriptor.hot_path != HOT_PATH_SERIAL_CONSOLE
        || descriptor.irq_count != 1
        || descriptor.bus_link_count != 0
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY != 0
    {
        return None;
    }
    let irq = descriptor.irqs[0];
    (irq.valid()
        && irq.irq == DRIVER_RUNTIME_SERIAL_IRQ
        && irq.badge == DRIVER_RUNTIME_SERIAL_IRQ_BADGE
        && irq.handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
        && irq.notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        && irq.trigger == DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL)
        .then_some(irq)
}

fn runtime_notification_route(
    descriptor: &DriverRuntimeInitDescriptor,
) -> RuntimeNotificationRoute {
    match descriptor.hot_path {
        HOT_PATH_SERIAL_CONSOLE if descriptor_serial_irq(descriptor).is_some() => {
            RuntimeNotificationRoute::Serial
        }
        HOT_PATH_SDIO_HOST
            if descriptor_notification_dpc_link(descriptor).is_some()
                && descriptor_sdio_irq(descriptor).is_some()
                && descriptor_sdio_dma_irq(descriptor).is_some() =>
        {
            RuntimeNotificationRoute::SdioOwner
        }
        HOT_PATH_CYW43_WIFI if descriptor_notification_dpc_link(descriptor).is_some() => {
            RuntimeNotificationRoute::Cyw43Client
        }
        _ => RuntimeNotificationRoute::Unavailable,
    }
}

fn descriptor_resource_pages_by_kind(descriptor: &DriverRuntimeInitDescriptor, kind: u16) -> u16 {
    let mut total = 0u16;
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind {
            total = total.saturating_add(range.page_count);
        }
        index += 1;
    }
    total
}

fn descriptor_resource_pages_or_count(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    fallback: u16,
) -> u16 {
    let pages = descriptor_resource_pages_by_kind(descriptor, kind);
    if pages == 0 {
        fallback
    } else {
        pages
    }
}

fn descriptor_has_resource_range_at(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
    expected_vaddr: u64,
    min_pages: u16,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind
            && range.tag == tag
            && range.vaddr == expected_vaddr
            && range.page_count >= min_pages
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag && range.page_count != 0 {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_pointer_free_bus_link(
    descriptor: &DriverRuntimeInitDescriptor,
    owner_hot_path: u32,
    channel_id: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        let link = descriptor.bus_links[index];
        if link.owner_hot_path == owner_hot_path
            && link.channel_id == channel_id
            && link.sealed_for_client(descriptor.task_key, descriptor.hot_path)
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_hdmi_ready(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    descriptor_valid_ref(descriptor)
        && descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER != 0
        && descriptor.framebuffer.valid()
}

fn publish_resource_check_progress(progress: Option<(u32, u32)>, phase: u32) {
    if let Some((sequence, aux0)) = progress {
        publish_runtime_progress(sequence, phase, aux0);
    }
}

fn descriptor_resources_ready_with_progress(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    sequence: u32,
    aux0: u32,
) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, Some((sequence, aux0)))
}

fn descriptor_resources_ready(descriptor: &DriverRuntimeInitDescriptor, hot_path: u32) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, None)
}

fn descriptor_resources_ready_checked(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    progress: Option<(u32, u32)>,
) -> bool {
    if !descriptor_valid_ref(descriptor) {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_INVALID,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_VALID,
    );
    if descriptor.hot_path != hot_path {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_READY,
    );
    let mmio_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        descriptor.mmio_page_count,
    );
    let dma_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        descriptor.dma_page_count,
    );
    let shared_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
        descriptor.shared_page_count,
    );
    publish_resource_check_progress(progress, DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_TOTALS_READY);
    match hot_path {
        HOT_PATH_USB_KEYBOARD => {
            if mmio_pages < USB_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_USB_XHCI,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    USB_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < USB_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    USB_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < USB_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_has_pointer_free_bus_link(
                descriptor,
                HOT_PATH_PCIE_ROOT,
                DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_HDMI_TEXT => {
            if mmio_pages < HDMI_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < HDMI_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < HDMI_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_hdmi_ready(descriptor)
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_FRAMEBUFFER,
                    DRIVER_RUNTIME_RESOURCE_TAG_HDMI_FRAMEBUFFER,
                    DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_GENET_NIC => {
            if mmio_pages < GENET_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_GENET_REGS,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    GENET_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < GENET_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    GENET_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < GENET_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_CYW43_WIFI => {
            if mmio_pages < CYW43_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < CYW43_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < CYW43_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    CYW43_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if descriptor_has_resource_range(
                descriptor,
                DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FORBIDDEN_PRESENT,
                );
                return false;
            }
            if descriptor_notification_dpc_link(descriptor).is_none() {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_SDIO_HOST => {
            let pwrseq_vaddr =
                DRIVER_TASK_DEVICE_MMIO_VADDR.saturating_add(DRIVER_TASK_RING_PAGE_BYTES);
            let dma_mmio_vaddr = DRIVER_TASK_DEVICE_MMIO_VADDR.saturating_add(
                SDIO_DMA_MMIO_PAGE_INDEX.saturating_mul(DRIVER_TASK_RING_PAGE_BYTES),
            );
            if mmio_pages < SDIO_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    1,
                )
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
                    pwrseq_vaddr as u64,
                    1,
                )
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_BCM2835_DMA,
                    dma_mmio_vaddr as u64,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < SDIO_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    1,
                )
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR.saturating_add(
                        SDIO_DMA_CONTROL_BLOCK_PAGE_INDEX
                            .saturating_mul(DRIVER_TASK_RING_PAGE_BYTES),
                    ) as u64,
                    (1 + SDIO_DMA_BOUNCE_PAGE_COUNT) as u16,
                )
                || sdio_external_dma_authority_from_descriptor(descriptor).is_none()
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < SDIO_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if descriptor_notification_dpc_link(descriptor).is_none() {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_PCIE_ROOT => {
            if mmio_pages < PCIE_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_PCIE_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    PCIE_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if shared_pages < PCIE_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    PCIE_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        _ => {
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
            );
            false
        }
    }
}

fn engine_initialized(flags: &AtomicU32) -> bool {
    flags.load(Ordering::Acquire) & ENGINE_STATE_INITIALIZED != 0
}

fn runtime_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> Option<DriverRuntimeResourceRangeDescriptor> {
    let mut index = 0usize;
    while index < descriptor.resource_range_count as usize {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag {
            return Some(range);
        }
        index += 1;
    }
    None
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_read(base: usize, offset: usize) -> u32 {
    // SAFETY: descriptor admission proves `base` is the single uncached Pi 4
    // firmware-mailbox page whose active call authority was handed to the SDIO
    // owner; root retains only a dormant, software-guarded mapping. Every caller
    // supplies a 32-bit register offset within that page.
    unsafe { core::ptr::read_volatile((base + offset) as *const u32) }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_write(base: usize, offset: usize, value: u32) {
    // SAFETY: descriptor admission proves `base` is the single uncached Pi 4
    // firmware-mailbox page whose active call authority was handed to the SDIO
    // owner; root retains only a dormant, software-guarded mapping. Every caller
    // supplies a writable 32-bit register offset within that page.
    unsafe { core::ptr::write_volatile((base + offset) as *mut u32, value) };
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_request(vaddr: usize, level: u32) {
    for index in 0..8usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 8 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_SET_GPIO_STATE);
    write_dma_u32(vaddr + 12, 8);
    // Linux's Raspberry Pi firmware transport always submits property tags
    // with a zero request/response-size word. The firmware replaces this word
    // with its response flag and returned-byte count.
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    write_dma_u32(vaddr + 24, level);
    dma_store_barrier();
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_get_config_request(vaddr: usize) {
    for index in 0..11usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 11 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_GET_GPIO_CONFIG);
    write_dma_u32(vaddr + 12, 20);
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    dma_store_barrier();
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_config_request(vaddr: usize, polarity: u32) {
    for index in 0..12usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 12 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_SET_GPIO_CONFIG);
    write_dma_u32(vaddr + 12, 24);
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    write_dma_u32(vaddr + 24, PI4_WIFI_PWRSEQ_GPIO_DIRECTION_OUT);
    write_dma_u32(vaddr + 28, polarity);
    write_dma_u32(vaddr + 32, 0);
    write_dma_u32(vaddr + 36, 0);
    write_dma_u32(vaddr + 40, 0);
    dma_store_barrier();
}

fn sdio_wifi_pwrseq_linux_response_fault(status: u32, returned_gpio: u32) -> u32 {
    let mut reason = 0;
    if status != PI4_WIFI_PWRSEQ_MAILBOX_RESPONSE_SUCCESS {
        reason |= DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GLOBAL_STATUS;
    }
    if returned_gpio != 0 {
        reason |= DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GPIO_TOKEN;
    }
    reason
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_response_complete(vaddr: usize) -> Result<(), u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0).then_some(()).ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_config_response_complete(vaddr: usize) -> Result<(), u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0).then_some(()).ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_get_config_response(vaddr: usize) -> Result<u32, u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0)
        .then(|| read_dma_u32(vaddr + 28))
        .ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_resources() -> Option<(usize, usize, u32)> {
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let mailbox = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
    )?;
    let request = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST,
    )?;
    if mailbox.page_count != 1
        || request.page_count < 1
        || request.paddr > 0x3fff_ffff
        || request.paddr & 0xf != 0
    {
        return None;
    }
    Some((
        mailbox.vaddr as usize,
        request.vaddr as usize,
        request.paddr as u32 & 0x3fff_fff0,
    ))
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_mailbox_op(request_vaddr: usize, op: SdioWifiPwrseqMailboxOp) {
    match op {
        SdioWifiPwrseqMailboxOp::GetConfig => {
            sdio_wifi_pwrseq_encode_get_config_request(request_vaddr);
        }
        SdioWifiPwrseqMailboxOp::SetConfig { polarity } => {
            sdio_wifi_pwrseq_encode_config_request(request_vaddr, polarity);
        }
        SdioWifiPwrseqMailboxOp::SetState { level } => {
            sdio_wifi_pwrseq_encode_request(request_vaddr, level);
        }
    }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_response(
    request_vaddr: usize,
    op: SdioWifiPwrseqMailboxOp,
) -> Result<u32, u32> {
    match op {
        SdioWifiPwrseqMailboxOp::GetConfig => sdio_wifi_pwrseq_get_config_response(request_vaddr),
        SdioWifiPwrseqMailboxOp::SetConfig { .. } => {
            sdio_wifi_pwrseq_config_response_complete(request_vaddr).map(|()| 0)
        }
        SdioWifiPwrseqMailboxOp::SetState { .. } => {
            sdio_wifi_pwrseq_response_complete(request_vaddr).map(|()| 0)
        }
    }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_turn(
    cursor: &mut SdioPwrseqMailboxCursor,
    op: SdioWifiPwrseqMailboxOp,
) -> SdioPwrseqMailboxTurn {
    let Some((mailbox_vaddr, request_vaddr, request_addr)) = sdio_wifi_pwrseq_mailbox_resources()
    else {
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Resource);
    };
    if !cursor.active() {
        let deadline = runtime_deadline_from_millis_or_iterations(
            PI4_WIFI_PWRSEQ_MAILBOX_TIMEOUT_MS,
            PI4_WIFI_PWRSEQ_MAILBOX_FALLBACK_TURNS,
        );
        if !matches!(deadline, RuntimeDeadline::Counter { .. }) {
            return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Timer);
        }
        sdio_wifi_pwrseq_encode_mailbox_op(request_vaddr, op);
        for _ in 0..PI4_WIFI_PWRSEQ_DRAIN_LIMIT {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS0)
                & PI4_WIFI_PWRSEQ_MAILBOX_EMPTY
                != 0
            {
                break;
            }
            let _ = sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_READ);
        }
        *cursor = SdioPwrseqMailboxCursor {
            phase: SdioPwrseqMailboxPhase::WaitSend,
            op,
            request_addr,
            overall_deadline: deadline,
        };
    } else if cursor.op != op || cursor.request_addr != request_addr {
        *cursor = SdioPwrseqMailboxCursor::idle();
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
            reason: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_CURSOR,
        });
    }

    if runtime_deadline_expired(&mut cursor.overall_deadline) {
        *cursor = SdioPwrseqMailboxCursor::idle();
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Timeout);
    }
    match cursor.phase {
        SdioPwrseqMailboxPhase::Idle => {
            SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
                reason: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_PHASE,
            })
        }
        SdioPwrseqMailboxPhase::WaitSend => {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS1)
                & PI4_WIFI_PWRSEQ_MAILBOX_FULL
                != 0
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            // The primary 0xc000_0000 VC alias is the hardware-proven Pi 4
            // property-channel address. Post this request exactly once. After
            // publication the request page is firmware-owned until a matching
            // reply or terminal timeout, so no alias retry may re-encode it.
            let token =
                cursor.request_addr | 0xc000_0000 | PI4_WIFI_PWRSEQ_MAILBOX_CHANNEL_PROPERTY;
            sdio_wifi_pwrseq_mailbox_write(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_WRITE, token);
            dma_store_barrier();
            cursor.phase = SdioPwrseqMailboxPhase::WaitReply;
            SdioPwrseqMailboxTurn::Pending
        }
        SdioPwrseqMailboxPhase::WaitReply => {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS0)
                & PI4_WIFI_PWRSEQ_MAILBOX_EMPTY
                != 0
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            let reply = sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_READ);
            if reply & 0xf != PI4_WIFI_PWRSEQ_MAILBOX_CHANNEL_PROPERTY
                || reply & 0x3fff_fff0 != cursor.request_addr
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            let value = match sdio_wifi_pwrseq_mailbox_response(request_vaddr, op) {
                Ok(value) => value,
                Err(reason) => {
                    *cursor = SdioPwrseqMailboxCursor::idle();
                    return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
                        reason,
                    });
                }
            };
            *cursor = SdioPwrseqMailboxCursor::idle();
            SdioPwrseqMailboxTurn::Complete(value)
        }
    }
}

