#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_retain_deadline(
    kind: u8,
    amount: u64,
    fallback: usize,
    fresh: RuntimeDeadline,
) -> RuntimeDeadline {
    if !cyw43_foreground_transaction_executing() {
        return fresh;
    }
    CYW43_FOREGROUND_TRANSACTION
        .with_mut(|transaction| transaction.retain_deadline(kind, amount, fallback, fresh))
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_exact_control_function2_tx_completed() -> bool {
    cyw43_foreground_transaction_executing()
        && CYW43_FOREGROUND_TRANSACTION
            .with_ref(Cyw43ForegroundTransaction::exact_control_function2_tx_completed)
}

#[cfg(not(any(target_os = "none", test)))]
const fn cyw43_foreground_exact_control_function2_tx_completed() -> bool {
    false
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_poll_retained_deadline(deadline: RuntimeDeadline) -> Option<bool> {
    if !cyw43_foreground_transaction_executing() {
        return None;
    }
    let current = runtime_timer_counter_ticks();
    CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.turn.action_consumed
            || transaction.turn.pending
            || transaction.issued_unknown
            || transaction.poisoned
        {
            return Some(true);
        }
        let mut index = usize::from(transaction.deadline_replay_index);
        let (retained_index, retained) = loop {
            if index == 0 {
                return None;
            }
            index -= 1;
            let candidate = transaction.deadlines[index];
            if candidate.deadline == deadline {
                break (index, candidate);
            }
        };
        if retained.completed {
            // The terminal counter observation consumed the preceding outer
            // turn. This is its local replay: the caller may now observe the
            // expired deadline and proceed without spending a second action.
            return None;
        }
        let expired = match retained.deadline {
            RuntimeDeadline::Counter { start, cycles } => {
                runtime_counter_deadline_expired(start, cycles, current)
            }
            RuntimeDeadline::Iterations { remaining } => remaining == 0,
        };
        transaction.deadlines[retained_index].completed = expired;
        // Both a not-yet-expired observation and the terminal observation are
        // retained poll actions. The terminal result is replayed locally on a
        // later turn before any following child operation may be submitted.
        transaction.turn.action_consumed = true;
        transaction.turn.pending = true;
        Some(expired)
    })
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_restore_baseline() -> bool {
    let baseline_state_valid =
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| transaction.baseline_state_valid);
    if !baseline_state_valid || !cyw43_foreground_restore_runtime_state() {
        return false;
    }
    CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        CYW43_CONTROL_REQUEST.restore_snapshot(transaction.baseline_control_request);
        CYW43_RUNTIME_FLAGS.store(transaction.baseline_runtime_flags, Ordering::Release);
        CYW43_TX_COUNT.store(transaction.baseline_tx_count, Ordering::Release);
        CYW43_LAST_FAULT_DETAIL.store(transaction.baseline_fault_detail, Ordering::Release);
        CYW43_LAST_FAULT_RESULT.store(transaction.baseline_fault_result, Ordering::Release);
        CYW43_LAST_FAULT_FRAME_OFFSET
            .store(transaction.baseline_fault_frame_offset, Ordering::Release);
        CYW43_LAST_FAULT_FRAME_META.store(transaction.baseline_fault_frame_meta, Ordering::Release);
        CYW43_LAST_RELEASE_PHASE.store(transaction.baseline_release_phase, Ordering::Release);
        transaction.restore_parent_input();
        true
    })
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_initialize_control_cursor_before_baseline(
    command: DriverTaskCommandRecord,
) -> bool {
    let descriptor = CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        (transaction.parent == command
            && transaction.parent_input_sealed
            && transaction.parent_descriptor_valid
            && transaction.parent_descriptor.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE)
            .then_some(transaction.parent_descriptor)
    });
    let Some(descriptor) = descriptor else {
        return true;
    };
    CYW43_RUNTIME_STATE.with_mut(|state| {
        if state.control_exchange.active()
            || !cyw43_control_exchange_descriptor_strict(descriptor)
            || !cyw43_control_exchange_start_ready(state)
        {
            // An existing cursor and every typed rejection remain owned by
            // the ordinary command-turn validator below.
            return true;
        }
        // The control cursor is durable parent state, not a physical action.
        // Commit it before the foreground rollback baseline is captured so
        // publishing the first SDIO child cannot restore the cursor to Idle.
        cyw43_control_exchange_begin(state, descriptor, command.aux1)
    })
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_begin_turn(command: DriverTaskCommandRecord) -> bool {
    let (active, same_parent, poisoned) = CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        (
            transaction.active,
            transaction.parent == command,
            transaction.poisoned,
        )
    });
    if active && !same_parent {
        CYW43_FOREGROUND_TRANSACTION.with_mut(cyw43_foreground_poison_active_frontier);
        return false;
    }
    if poisoned {
        return false;
    }
    if active
        && !CYW43_FOREGROUND_TRANSACTION.with_ref(cyw43_foreground_retained_generation_is_current)
    {
        // A pair restart may replace the DPC epoch while an old parent is
        // retained. Never restore that parent's baseline over the new
        // generation, and never accept or replay its outstanding child.
        CYW43_FOREGROUND_TRANSACTION.with_mut(cyw43_foreground_abandon_stale_transaction);
        return false;
    }
    if !active {
        let parent_input_sealed = CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            transaction.parent_input_sealed && transaction.parent == command
        });
        if !parent_input_sealed {
            // Production seals at command intake, before DPC arbitration.
            // Re-reading reciprocal scratch here would reopen the exact
            // publication-to-first-service race that the seal closes.
            return false;
        }
        // Materialize the intake-sealed descriptor and payload together before
        // the first private service phase. The accessors below already prefer
        // the sealed parent while `executing`, but restoring the whole aperture
        // here also protects helpers that consume a physical frame directly and
        // prevents a mixed old-descriptor/new-payload view at initial dispatch.
        CYW43_FOREGROUND_TRANSACTION.with_ref(Cyw43ForegroundTransaction::restore_parent_input);
        if !cyw43_foreground_initialize_control_cursor_before_baseline(command) {
            CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| transaction.poisoned = true);
            return false;
        }
        let generation = cyw43_foreground_snapshot_runtime_state();
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.baseline_state_valid = true;
            transaction.generation = generation;
            transaction.baseline_control_request = CYW43_CONTROL_REQUEST.snapshot();
            transaction.baseline_runtime_flags = CYW43_RUNTIME_FLAGS.load(Ordering::Acquire);
            transaction.baseline_tx_count = CYW43_TX_COUNT.load(Ordering::Acquire);
            transaction.baseline_fault_detail = CYW43_LAST_FAULT_DETAIL.load(Ordering::Acquire);
            transaction.baseline_fault_result = CYW43_LAST_FAULT_RESULT.load(Ordering::Acquire);
            transaction.baseline_fault_frame_offset =
                CYW43_LAST_FAULT_FRAME_OFFSET.load(Ordering::Acquire);
            transaction.baseline_fault_frame_meta =
                CYW43_LAST_FAULT_FRAME_META.load(Ordering::Acquire);
            transaction.baseline_release_phase = CYW43_LAST_RELEASE_PHASE.load(Ordering::Acquire);
        });
    } else if !cyw43_foreground_restore_baseline() {
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| transaction.poisoned = true);
        return false;
    }
    let turn_id = CYW43_FOREGROUND_TURN_ID
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1);
    let begun = CYW43_FOREGROUND_TRANSACTION
        .with_mut(|transaction| transaction.begin_turn(command, turn_id));
    if begun {
        let (descriptor, generation) = CYW43_FOREGROUND_TRANSACTION
            .with_ref(|transaction| (transaction.parent_descriptor, transaction.generation));
        cyw43_bus_episode_begin_foreground(command, descriptor, generation);
    }
    begun
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_poison_after_reap(expected_sequence: u32) {
    CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.active
            && transaction.issued_unknown
            && transaction.frontier_valid
            && transaction.frontier.command.sequence == expected_sequence
        {
            transaction.issued_unknown = false;
            transaction.turn.pending = false;
            transaction.poisoned = true;
            transaction.frontier_submitted = false;
        }
    });
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_reaped_terminal_ready() -> bool {
    CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        transaction.active
            && transaction.poisoned
            && !transaction.issued_unknown
            && transaction.frontier_valid
            && !transaction.frontier_submitted
            && transaction.frontier.command.sequence != 0
    })
}

fn cyw43_poison_retained_generation(state: &mut Cyw43RuntimeState) {
    // An issued-but-unknown reciprocal action invalidates every derived
    // readiness fact from this generation. Force the next admitted transport
    // command through START so it must complete the typed SDIO generation
    // reset before any old attach edge can be considered again.
    cyw43_mark_issued_unknown(state);
    state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_START;
    state.backplane_window_valid = false;
    state.invalidate_card_adoption_facts();
    state.card_lane.poisoned = true;
    state.f1_enable.poisoned = true;
    state.backplane_attach.poisoned = true;
    state.firmware_prep.poisoned = true;
}

fn cyw43_fence_preissue_status_clear_generation(state: &mut Cyw43RuntimeState) {
    // The child proved that SDHCI_COMMAND was not written, so this is not an
    // issued-unknown action. It nevertheless proved that the owner could not
    // establish a clean request boundary. Invalidate every same-generation
    // readiness fact and let the paired-runtime supervisor perform the sole
    // cold recovery lane after the exact child terminal has reached its parent.
    state.invalidate_steady_data_plane();
    cyw43_poison_rx_queue_state!(state);
    state.initialized = false;
    state.transport_ready = false;
    state.firmware_released = false;
    state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_START;
    state.backplane_window_valid = false;
    state.invalidate_card_adoption_facts();
    state.card_lane.poisoned = true;
    state.f1_enable.poisoned = true;
    state.backplane_attach.poisoned = true;
    state.firmware_prep.poisoned = true;
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_finish_turn(
    command: DriverTaskCommandRecord,
    turn: RuntimeCommandTurn,
) -> RuntimeCommandTurn {
    let (same_parent, pending, issued_unknown, poisoned, result, preissue_status_clear_failure) =
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.executing = false;
            (
                transaction.parent == command,
                transaction.turn.pending,
                transaction.issued_unknown,
                transaction.poisoned,
                if transaction.frontier_valid {
                    cyw43_sdio_bus_link_command_result_from_descriptor(
                        transaction.frontier.command,
                        transaction.frontier.descriptor,
                    )
                } else {
                    0
                },
                transaction.replayed_preissue_status_clear_failure(),
            )
        });
    if !same_parent {
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            command.sequence,
        ));
    }
    if (poisoned || pending || issued_unknown)
        && !CYW43_FOREGROUND_TRANSACTION.with_ref(cyw43_foreground_retained_generation_is_current)
    {
        // The current runtime and owner ring already belong to a replacement
        // generation. Preserve them byte-for-byte; only fence the abandoned
        // child and ask root to perform the deterministic pair restart.
        CYW43_FOREGROUND_TRANSACTION.with_mut(cyw43_foreground_abandon_stale_transaction);
        CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            result,
        ));
    }
    if let Some(completion) = preissue_status_clear_failure {
        // Do not latch the pair restart while the child completion is merely
        // polled and cached: that would make the runtime hold the parent before
        // it can replay the exact terminal. Once replayed, discard any partial
        // parent mutations, preserve the child's primitive telemetry, and
        // fence both runtime images before another child claim can succeed.
        let _ = cyw43_foreground_restore_baseline();
        CYW43_RUNTIME_STATE.with_mut(cyw43_fence_preissue_status_clear_generation);
        CYW43_SDIO_PAIR_RESTART_REQUIRED.store(true, Ordering::Release);
        CYW43_DPC_DEFERRED.store(true, Ordering::Release);
        CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
        cyw43_record_last_fault_with_result(completion.detail, completion.result);
        cyw43_record_last_fault_frame(completion.frame);
        return match turn {
            RuntimeCommandTurn::Complete(_) => turn,
            RuntimeCommandTurn::Pending => RuntimeCommandTurn::Complete(
                DriverTaskCompletionRecord::fault_with_result_and_frame(
                    command.sequence,
                    FAULT_CYW43_TRANSPORT_BUS_LINK,
                    completion.result,
                    completion.frame,
                ),
            ),
        };
    }
    if poisoned {
        let _ = cyw43_foreground_restore_baseline();
        CYW43_RUNTIME_STATE.with_mut(cyw43_poison_retained_generation);
        if issued_unknown || CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire) {
            CYW43_SDIO_PAIR_RESTART_REQUIRED.store(true, Ordering::Release);
            CYW43_DPC_DEFERRED.store(true, Ordering::Release);
        }
        CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
        cyw43_record_last_fault_with_result(FAULT_CYW43_TRANSPORT_BUS_LINK, result);
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            result,
        ));
    }
    if pending || issued_unknown {
        if !cyw43_foreground_restore_baseline() {
            CYW43_RUNTIME_STATE.with_mut(cyw43_poison_retained_generation);
            CYW43_SDIO_PAIR_RESTART_REQUIRED.store(true, Ordering::Release);
            CYW43_DPC_DEFERRED.store(true, Ordering::Release);
            CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
            cyw43_record_last_fault_with_result(FAULT_CYW43_TRANSPORT_BUS_LINK, result);
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                command.sequence,
                FAULT_CYW43_TRANSPORT_BUS_LINK,
                result,
            ));
        }
        return RuntimeCommandTurn::Pending;
    }
    if matches!(turn, RuntimeCommandTurn::Pending) {
        // Explicit CYW43 cursors can advance one purely private phase before
        // their first reciprocal SDIO child. Keep the intake-sealed parent
        // across that retained-command handoff even though the straight-line
        // child trace has no pending frontier. DPC may reuse the shared
        // descriptor/payload aperture before root grants the next phase.
        CYW43_FOREGROUND_TRANSACTION
            .with_mut(Cyw43ForegroundTransaction::clear_turn_keep_parent_input);
        return RuntimeCommandTurn::Pending;
    }
    CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
    turn
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_prepare_sequence() -> Option<u32> {
    if !cyw43_foreground_transaction_executing() {
        return None;
    }
    if cyw43_foreground_action_suspended() {
        return None;
    }
    if let Some(sequence) = CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
        let index = transaction.turn.replay_index as usize;
        if index < transaction.turn.completed_count as usize {
            Some(transaction.entries[index].command.sequence)
        } else if transaction.frontier_valid {
            Some(transaction.frontier.command.sequence)
        } else if transaction.prepared_sequence != 0 {
            Some(transaction.prepared_sequence)
        } else {
            None
        }
    }) {
        return Some(sequence);
    }
    let sequence = cyw43_sdio_bus_link_allocate_sequence();
    CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.executing && transaction.prepared_sequence == 0 {
            transaction.prepared_sequence = sequence;
        }
    });
    Some(sequence)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_scope_prepared_descriptor(
    transaction: &Cyw43ForegroundTransaction,
    mut desc: DriverRuntimeSdioCommandDescriptor,
) -> Option<DriverRuntimeSdioCommandDescriptor> {
    let caller_marked_transaction_authority = desc.flags
        & (DriverRuntimeSdioCommandDescriptor::FLAG_STEADY_SERVICE_LEASE
            | DriverRuntimeSdioCommandDescriptor::FLAG_STEADY_TX_SERVICE_LEASE
            | DriverRuntimeSdioCommandDescriptor::FLAG_PERSISTENT_TRANSACTION)
        != 0;
    if caller_marked_transaction_authority {
        return None;
    }
    if transaction.persistent_transaction_parent_authorized() {
        // The sealed op11 parent, not the helper or operation number, mints
        // this child marker. `valid` below constrains the result to one exact
        // Function-1/2 primitive or DPC activation owned by that transaction.
        desc.flags |= DriverRuntimeSdioCommandDescriptor::FLAG_PERSISTENT_TRANSACTION;
        if desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE && desc.function == 2 {
            // Every control TX can make a reply source visible. Bind physical
            // CARD_INT arm proof to the immutable child rather than relying on
            // a preceding DPC-rearm scheduling edge or an operation-specific
            // CYW43 flag. Steady op7 traffic remains on its existing exact lane.
            desc.flags |= DriverRuntimeSdioCommandDescriptor::FLAG_PRE_TX_DPC_FENCE;
        }
    } else if transaction.steady_tx_service_lease_parent_authorized()
        && desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE
        && desc.function == 2
    {
        desc.flags |= DriverRuntimeSdioCommandDescriptor::FLAG_STEADY_SERVICE_LEASE
            | DriverRuntimeSdioCommandDescriptor::FLAG_STEADY_TX_SERVICE_LEASE;
        // A sealed M2/M4/group response is one finite Function-2 write, just
        // like other exact steady TX. A concurrent committed CARD_INT remains
        // DPC work beside that immutable child; it cannot retroactively turn
        // the already-published write into a pre-issue fence failure. Persistent
        // control/Join transactions retain their explicit fence above.
    }
    desc.valid().then_some(desc)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_prepare_descriptor(desc: DriverRuntimeSdioCommandDescriptor) -> Option<bool> {
    if !cyw43_foreground_transaction_executing() {
        return None;
    }
    let accepted = CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.turn.action_consumed
            || transaction.turn.pending
            || transaction.issued_unknown
            || transaction.poisoned
        {
            return false;
        }
        let Some(desc) = cyw43_foreground_scope_prepared_descriptor(transaction, desc) else {
            transaction.poisoned = true;
            return false;
        };
        if transaction.prepared_descriptor_valid && transaction.prepared_descriptor != desc {
            transaction.poisoned = true;
            false
        } else {
            transaction.prepared_descriptor = desc;
            transaction.prepared_descriptor_valid = true;
            true
        }
    });
    Some(accepted)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_prepare_write_byte(offset: usize, value: u8) -> Option<bool> {
    if !cyw43_foreground_transaction_executing() {
        return None;
    }
    let Some(index) = offset.checked_sub(CYW43_SDIO_BUS_LINK_DATA_OFFSET) else {
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| transaction.poisoned = true);
        return Some(false);
    };
    let accepted = CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.turn.action_consumed
            || transaction.turn.pending
            || transaction.issued_unknown
            || transaction.poisoned
        {
            return false;
        }
        if index >= transaction.prepared_write.len() {
            transaction.poisoned = true;
            return false;
        }
        transaction.prepared_write[index] = value;
        transaction.prepared_write_len = transaction
            .prepared_write_len
            .max(u16::try_from(index.saturating_add(1)).unwrap_or(u16::MAX));
        true
    });
    Some(accepted)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_foreground_prepare_write_frame(
    frame: DriverFrameDescriptor,
    dst_offset: usize,
) -> Option<Option<()>> {
    if !cyw43_foreground_transaction_executing() {
        return None;
    }
    let len = usize::from(frame.len);
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    if dst_offset != CYW43_SDIO_BUS_LINK_DATA_OFFSET
        || !frame.in_runtime_payload(shared_payload_bytes)
        || len > DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize
    {
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| transaction.poisoned = true);
        return Some(None);
    }
    let result = CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
        if transaction.turn.action_consumed
            || transaction.turn.pending
            || transaction.issued_unknown
            || transaction.poisoned
        {
            return None;
        }
        for index in 0..len {
            let offset = frame.offset as usize + index;
            transaction.prepared_write[index] = transaction
                .read_parent_payload(offset)
                .unwrap_or_else(|| read_runtime_payload_byte_physical(offset));
        }
        transaction.prepared_write_len = frame.len;
        Some(())
    });
    Some(result)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43SdioChildCompletion {
    Waiting,
    Exact(DriverTaskCompletionRecord),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcChildPoll {
    Pending,
    Exact(DriverTaskCompletionRecord),
    TerminalMalformed,
    IssuedUnknown,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43SdioChildState {
    expected_sequence: u32,
}

impl Cyw43SdioChildState {
    const fn new(expected_sequence: u32) -> Self {
        Self { expected_sequence }
    }

    fn completion(
        self,
        first: DriverTaskCompletionRecord,
        second: DriverTaskCompletionRecord,
    ) -> Cyw43SdioChildCompletion {
        if first.sequence == self.expected_sequence
            && second.sequence == self.expected_sequence
            && first == second
        {
            Cyw43SdioChildCompletion::Exact(second)
        } else {
            Cyw43SdioChildCompletion::Waiting
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43IssuedUnknownReapResult {
    Inactive,
    Waiting,
    Reaped { sequence: u32 },
}

fn cyw43_sdio_child_claim(expected_sequence: u32) -> bool {
    if expected_sequence == 0
        || CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire)
        || CYW43_SDIO_CHILD_ACTIVE
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return false;
    }
    CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.store(expected_sequence, Ordering::Release);
    CYW43_SDIO_CHILD_ISSUED_UNKNOWN.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_LATE_POLLS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_START_TICKS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_TIMEOUT_CYCLES.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_RESTART_SIGNALLED.store(false, Ordering::Release);
    true
}

fn cyw43_sdio_child_mark_issued_unknown(expected_sequence: u32) -> bool {
    if !CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire)
        || CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire) != expected_sequence
    {
        return false;
    }
    CYW43_SDIO_CHILD_PARENT_SEQUENCE.store(
        CYW43_ACTIVE_PARENT_SEQUENCE.load(Ordering::Acquire),
        Ordering::Release,
    );
    CYW43_SDIO_CHILD_REAP_START_TICKS.store(runtime_timer_counter_ticks(), Ordering::Release);
    CYW43_SDIO_CHILD_REAP_TIMEOUT_CYCLES.store(
        runtime_micros_to_cycles(u64::from(CYW43_SDIO_CHILD_REAP_GRACE_US)),
        Ordering::Release,
    );
    CYW43_SDIO_CHILD_ISSUED_UNKNOWN.store(true, Ordering::Release);
    CYW43_SDIO_CHILD_LATE_POLLS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_RESTART_SIGNALLED.store(false, Ordering::Release);
    CYW43_DPC_DEFERRED.store(true, Ordering::Release);
    true
}

fn cyw43_sdio_child_mark_issued_unknown_or_restart(expected_sequence: u32) -> bool {
    if cyw43_sdio_child_mark_issued_unknown(expected_sequence) {
        return true;
    }
    CYW43_SDIO_PAIR_RESTART_REQUIRED.store(true, Ordering::Release);
    CYW43_DPC_DEFERRED.store(true, Ordering::Release);
    false
}

fn cyw43_sdio_child_release_exact(expected_sequence: u32) -> bool {
    if !CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire)
        || CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire) != expected_sequence
    {
        return false;
    }
    CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_ISSUED_UNKNOWN.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_LATE_POLLS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_START_TICKS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_TIMEOUT_CYCLES.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_RESTART_SIGNALLED.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_ACTIVE.store(false, Ordering::Release);
    true
}

fn cyw43_sdio_child_release_exact_or_restart(expected_sequence: u32) -> bool {
    if cyw43_sdio_child_release_exact(expected_sequence) {
        return true;
    }
    CYW43_SDIO_PAIR_RESTART_REQUIRED.store(true, Ordering::Release);
    CYW43_DPC_DEFERRED.store(true, Ordering::Release);
    false
}

const fn cyw43_sdio_child_reap_restart_due(
    polls: u32,
    start_ticks: u64,
    timeout_cycles: u64,
    now_ticks: u64,
) -> bool {
    if start_ticks != 0 && timeout_cycles != 0 && now_ticks != 0 {
        runtime_counter_deadline_expired(start_ticks, timeout_cycles, now_ticks)
    } else {
        polls >= CYW43_SDIO_CHILD_REAP_FALLBACK_POLLS
    }
}

#[cfg(test)]
fn cyw43_sdio_child_reap_stable_completion(
    expected_sequence: u32,
    first: DriverTaskCompletionRecord,
    second: DriverTaskCompletionRecord,
) -> Cyw43IssuedUnknownReapResult {
    if !CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire)
        || !CYW43_SDIO_CHILD_ISSUED_UNKNOWN.load(Ordering::Acquire)
        || CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire) != expected_sequence
    {
        return Cyw43IssuedUnknownReapResult::Inactive;
    }
    if !matches!(
        Cyw43SdioChildState::new(expected_sequence).completion(first, second),
        Cyw43SdioChildCompletion::Exact(_)
    ) {
        return Cyw43IssuedUnknownReapResult::Waiting;
    }
    if cyw43_sdio_child_release_exact(expected_sequence) {
        Cyw43IssuedUnknownReapResult::Reaped {
            sequence: expected_sequence,
        }
    } else {
        Cyw43IssuedUnknownReapResult::Inactive
    }
}

fn cyw43_quarantine_reaped_child_state(state: &mut Cyw43RuntimeState, expected_sequence: u32) {
    state.invalidate_steady_data_plane();
    cyw43_poison_rx_queue_state!(state);
    if state.dpc_cursor.child.expected_sequence == expected_sequence {
        state.dpc_cursor.child = Cyw43DpcChild::empty();
    }
}

const fn cyw43_sdio_bus_link_sequence_seed(shared_epoch: u32) -> u32 {
    let mixed = shared_epoch ^ (shared_epoch >> 16) ^ shared_epoch.wrapping_shl(7);
    let value = mixed & CYW43_SDIO_BUS_LINK_SEQUENCE_VALUE_MASK;
    CYW43_SDIO_BUS_LINK_SEQUENCE_DOMAIN | if value == 0 { 1 } else { value }
}

const fn cyw43_sdio_bus_link_sequence_advance(current: u32) -> u32 {
    let next = current.wrapping_add(1) & CYW43_SDIO_BUS_LINK_SEQUENCE_VALUE_MASK;
    CYW43_SDIO_BUS_LINK_SEQUENCE_DOMAIN | if next == 0 { 1 } else { next }
}

fn cyw43_sdio_bus_link_allocate_sequence() -> u32 {
    let mut current = CYW43_SDIO_BUS_LINK_SEQ.load(Ordering::Acquire);
    loop {
        let next = cyw43_sdio_bus_link_sequence_advance(current);
        match CYW43_SDIO_BUS_LINK_SEQ.compare_exchange_weak(
            current,
            next,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => return next,
            Err(observed) => current = observed,
        }
    }
}

fn cyw43_sdio_bus_link_next_sequence() -> u32 {
    #[cfg(any(target_os = "none", test))]
    {
        if cyw43_foreground_transaction_executing() {
            return cyw43_foreground_prepare_sequence().unwrap_or(0);
        }
    }
    cyw43_sdio_bus_link_allocate_sequence()
}

const fn cyw43_sdio_bus_link_staged_command(
    mut command: DriverTaskCommandRecord,
) -> DriverTaskCommandRecord {
    command.sequence = 0;
    command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
    command
}

#[cfg(any(target_os = "none", test))]
fn cyw43_sdio_bus_link_command_result(command: DriverTaskCommandRecord) -> u32 {
    if command.frame.offset as usize != CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return (u32::from(command.opcode) << 24)
            | ((command.arg0 & 0xff) << 16)
            | u32::from(command.frame.len);
    }
    let Some(desc) = sdio_bus_link_read_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET) else {
        return (u32::from(command.opcode) << 24)
            | ((command.arg0 & 0xff) << 16)
            | u32::from(command.frame.len);
    };
    cyw43_sdio_bus_link_command_result_from_descriptor(command, desc)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_sdio_bus_link_command_result_from_descriptor(
    _command: DriverTaskCommandRecord,
    desc: DriverRuntimeSdioCommandDescriptor,
) -> u32 {
    (u32::from(desc.op) << 24)
        | (u32::from(desc.function) << 20)
        | (u32::from(desc.flags & 0x1f) << 16)
        | u32::from(desc.len)
}

#[cfg(any(target_os = "none", test))]
fn cyw43_sdio_bus_link_child_wait_timeout_us(command: DriverTaskCommandRecord) -> u32 {
    if command.frame.offset as usize != CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return cyw43_sdio_child_wait_timeout_us(0, SDIO_OWNER_DESCRIPTOR_DEFAULT_TIMEOUT_US);
    }
    let Some(desc) = sdio_bus_link_read_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET) else {
        return cyw43_sdio_child_wait_timeout_us(0, SDIO_OWNER_DESCRIPTOR_DEFAULT_TIMEOUT_US);
    };
    if desc.valid() {
        cyw43_sdio_child_wait_timeout_us(desc.op, desc.timeout_us)
    } else {
        cyw43_sdio_child_wait_timeout_us(0, SDIO_OWNER_DESCRIPTOR_DEFAULT_TIMEOUT_US)
    }
}

const fn sdio_owner_descriptor_timeout_us(timeout_us: u32) -> u32 {
    if timeout_us == 0 {
        SDIO_OWNER_DESCRIPTOR_DEFAULT_TIMEOUT_US
    } else {
        timeout_us
    }
}

const fn sdio_linux_request_timeout_us(_timeout_us: u32) -> u32 {
    // bcm2835-mmc arms one fixed ten-second watchdog for every request. A
    // descriptor-provided value is not authority to shorten or extend that
    // lifetime; accepting a longer value would outrun the ABI-derived parent
    // bound and accepting a shorter one recreated the live 100-ms abort.
    BCM2835_SDIO_REQUEST_TIMEOUT_US
}

const fn sdio_descriptor_owner_worst_case_timeout_us(owner_timeout_us: u32) -> u32 {
    let owner_timeout_us = sdio_linux_request_timeout_us(owner_timeout_us);
    let recovery_timeout_us = (BCM2835_SDIO_RECOVERY_TIMEOUT_MS as u32).saturating_mul(1_000);
    owner_timeout_us
        .saturating_add(DRIVER_RUNTIME_SDIO_INHIBIT_TIMEOUT_US)
        .saturating_mul(SDIO_DESCRIPTOR_MAX_TRANSFER_ATTEMPTS)
        .saturating_add(
            recovery_timeout_us.saturating_mul(SDIO_DESCRIPTOR_MAX_CONTAINMENT_ATTEMPTS),
        )
}

const fn cyw43_sdio_child_wait_timeout_us(owner_op: u16, owner_timeout_us: u32) -> u32 {
    let _ = owner_op;
    let owner_worst_case_us = sdio_descriptor_owner_worst_case_timeout_us(owner_timeout_us);
    owner_worst_case_us.saturating_add(CYW43_SDIO_CHILD_WAIT_MARGIN_US)
}

