#[cfg(all(not(target_os = "none"), test))]
fn test_cyw43_backplane_read_u32_response(addr: u32) -> Option<u32> {
    if addr == CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS {
        let value = TEST_CYW43_SDIO_INT_STATUS_RESPONSE.load(Ordering::Acquire);
        if value != TEST_SDIO_CMD52_RESPONSE_UNSET {
            return Some(value);
        }
    }
    if addr == CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOHOSTMAILBOXDATA {
        let value = TEST_CYW43_TOHOST_MAILBOX_RESPONSE.load(Ordering::Acquire);
        if value != TEST_SDIO_CMD52_RESPONSE_UNSET {
            return Some(value);
        }
    }
    if !TEST_CYW43_FOREGROUND_PRODUCTION_CHAIN_ENABLED.load(Ordering::Acquire) {
        if addr == CYW43_SDIO_CORE_BASE + SDIO_CORECONTROL {
            return Some(CC_F2RDY);
        }
        if addr == CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOHOSTMAILBOXDATA {
            return Some(HMB_DATA_DEVREADY | HMB_DATA_FWREADY | cyw43_mailbox_version_payload());
        }
    }
    None
}

