fn usb_write64(offset: usize, value: u64) {
    usb_write32(offset, value as u32);
    usb_write32(offset + 4, (value >> 32) as u32);
}

fn xhci_flush_posted_write(
    _state: &UsbRuntimeState,
    stage: u16,
    offset: usize,
    _value: u32,
) -> bool {
    if stage == XHCI_FLUSH_STAGE_DOORBELL {
        dma_store_barrier();
        xhci_dma_publish_barrier();
        true
    } else {
        if stage != XHCI_FLUSH_STAGE_DOORBELL {
            let _ = usb_read32(offset & !0x3);
        }
        true
    }
}

fn xhci_flush_posted_write_progress(
    _sequence: u32,
    _aux0: u32,
    state: &UsbRuntimeState,
    stage: u16,
    offset: usize,
    value: u32,
) -> bool {
    xhci_flush_posted_write(state, stage, offset, value)
}

fn xhci_write64_flush_posted(
    sequence: u32,
    aux0: u32,
    state: &UsbRuntimeState,
    offset: usize,
    value: u64,
    low_stage: u16,
    high_stage: u16,
    low_written_phase: u32,
    high_written_phase: u32,
    high_flushed_phase: u32,
) -> bool {
    usb_write32(offset, value as u32);
    publish_runtime_progress(sequence, low_written_phase, aux0);
    if !xhci_flush_posted_write_progress(sequence, aux0, state, low_stage, offset, value as u32) {
        return false;
    }
    usb_write32(offset + 4, (value >> 32) as u32);
    publish_runtime_progress(sequence, high_written_phase, aux0);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        high_stage,
        offset + 4,
        (value >> 32) as u32,
    ) {
        return false;
    }
    publish_runtime_progress(sequence, high_flushed_phase, aux0);
    true
}

const fn xhci_portsc_neutral(status: u32) -> u32 {
    status & XHCI_PORTSC_NEUTRAL_MASK
}

fn zero_dma_range(vaddr: usize, len: usize) {
    let mut offset = 0usize;
    while offset < len && (vaddr + offset) & (DMA_ZERO_WORD_BYTES - 1) != 0 {
        write_dma_byte(vaddr + offset, 0);
        offset += 1;
    }

    let burst_bytes = DMA_ZERO_WORD_BYTES * DMA_ZERO_BURST_WORDS;
    while len.saturating_sub(offset) >= burst_bytes {
        for word in 0..DMA_ZERO_BURST_WORDS {
            write_dma_zero_word(vaddr + offset + word * DMA_ZERO_WORD_BYTES);
        }
        offset += burst_bytes;
    }
    while len.saturating_sub(offset) >= DMA_ZERO_WORD_BYTES {
        write_dma_zero_word(vaddr + offset);
        offset += DMA_ZERO_WORD_BYTES;
    }
    while offset < len {
        write_dma_byte(vaddr + offset, 0);
        offset += 1;
    }
}

fn write_dma_u32(addr: usize, value: u32) {
    for index in 0..4 {
        write_dma_byte(addr + index, ((value >> (index * 8)) & 0xff) as u8);
    }
}

fn write_dma_u64(addr: usize, value: u64) {
    for index in 0..8 {
        write_dma_byte(addr + index, ((value >> (index * 8)) & 0xff) as u8);
    }
}

fn read_dma_u32(addr: usize) -> u32 {
    let mut value = 0u32;
    for index in 0..4 {
        value |= u32::from(read_dma_byte(addr + index)) << (index * 8);
    }
    value
}

fn read_dma_u64(addr: usize) -> u64 {
    let mut value = 0u64;
    for index in 0..8 {
        value |= u64::from(read_dma_byte(addr + index)) << (index * 8);
    }
    value
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct XhciTrb {
    parameter: u64,
    status: u32,
    control: u32,
}

fn xhci_trb_addr(base: usize, index: usize) -> usize {
    base + index.saturating_mul(XHCI_TRB_BYTES)
}

fn write_xhci_trb(base: usize, index: usize, trb: XhciTrb) {
    let addr = xhci_trb_addr(base, index);
    write_dma_u64(addr, trb.parameter);
    write_dma_u32(addr + 8, trb.status);
    dma_store_barrier();
    write_dma_u32(addr + 12, trb.control);
    dma_clean_range(addr, XHCI_TRB_BYTES);
}

fn publish_xhci_command_ring(base: usize) {
    dma_clean_range(base, XHCI_COMMAND_RING_BYTES);
    xhci_dma_publish_barrier();
}

fn publish_xhci_transfer_ring(base: usize) {
    dma_clean_range(base, XHCI_COMMAND_RING_BYTES);
    xhci_dma_publish_barrier();
}

fn read_xhci_trb(base: usize, index: usize) -> XhciTrb {
    let addr = xhci_trb_addr(base, index);
    dma_invalidate_range(addr, XHCI_TRB_BYTES);
    XhciTrb {
        parameter: read_dma_u64(addr),
        status: read_dma_u32(addr + 8),
        control: read_dma_u32(addr + 12),
    }
}

fn read_xhci_trb_for_command_proof(
    base: usize,
    index: usize,
    ack_mode: XhciEventAckMode,
) -> XhciTrb {
    let addr = xhci_trb_addr(base, index);
    dma_invalidate_range(addr, XHCI_TRB_BYTES);
    xhci_publish_command_proof_event_invalidate_done(ack_mode);
    XhciTrb {
        parameter: read_dma_u64(addr),
        status: read_dma_u32(addr + 8),
        control: read_dma_u32(addr + 12),
    }
}

const fn xhci_trb_type(control: u32) -> u32 {
    (control >> 10) & 0x3f
}

const fn xhci_completion_code(status: u32) -> u32 {
    (status >> 24) & 0xff
}

const fn xhci_slot_id(control: u32) -> u8 {
    ((control >> 24) & 0xff) as u8
}

const fn xhci_endpoint_id(control: u32) -> u8 {
    ((control >> 16) & 0x1f) as u8
}

const fn xhci_port_status_change_event_mask(trb_type: u32, parameter: u64, max_ports: u8) -> u32 {
    if trb_type != XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT {
        return 0;
    }
    let port_id = ((parameter >> 24) & 0xff) as u8;
    if port_id == 0 || port_id > max_ports || port_id > u32::BITS as u8 {
        return 0;
    }
    1u32 << (port_id - 1)
}

fn xhci_preserve_port_status_change_event(state: &mut UsbRuntimeState, event: XhciTrb) {
    let mask = xhci_port_status_change_event_mask(
        xhci_trb_type(event.control),
        event.parameter,
        state.max_ports,
    );
    if mask == 0 {
        return;
    }
    state.port_event_candidate_mask |= mask;
    state.port_event_count = state.port_event_count.saturating_add(1);
}

fn xhci_drain_events_preserving_port_changes(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) {
    while let Some(event) = xhci_next_event(state, descriptor) {
        if !xhci_ack_event_dequeue(state, descriptor) {
            break;
        }
        if xhci_trb_type(event.control) == XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT {
            xhci_preserve_port_status_change_event(state, event);
        } else if xhci_keyboard_transfer_event_matches(state, event) {
            let _ = xhci_preserve_keyboard_transfer_event(state, event);
        }
    }
}

fn xhci_cycle_bit(cycle: bool) -> u32 {
    if cycle {
        XHCI_TRB_CYCLE
    } else {
        0
    }
}

fn xhci_dma_bus_addr(
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    offset: usize,
) -> Option<u64> {
    runtime_resource_bus_addr_at(descriptor, dma_range, offset)
}

fn xhci_ring_doorbell(state: &UsbRuntimeState, slot: u8, endpoint_id: u8) -> bool {
    let offset = state.db_offset as usize + usize::from(slot).saturating_mul(4);
    let value = u32::from(endpoint_id);
    dma_store_barrier();
    xhci_dma_publish_barrier();
    usb_write32(offset, value);
    xhci_flush_posted_write(state, XHCI_FLUSH_STAGE_DOORBELL, offset, value)
}

fn xhci_next_event_dequeue_state(state: &UsbRuntimeState) -> (u16, bool) {
    let mut next_dequeue = state.event_dequeue.wrapping_add(1);
    let mut next_cycle = state.event_cycle;
    if usize::from(next_dequeue) >= XHCI_EVENT_RING_TRBS {
        next_dequeue = 0;
        next_cycle = !next_cycle;
    }
    (next_dequeue, next_cycle)
}

fn xhci_transfer_ring_link_control(cycle: bool) -> u32 {
    (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT | xhci_cycle_bit(cycle)
}

fn xhci_publish_transfer_ring_link(base: usize, ring_bus: u64, cycle: bool) {
    write_xhci_trb(
        base,
        XHCI_COMMAND_RING_TRBS - 1,
        XhciTrb {
            parameter: ring_bus,
            status: 0,
            control: xhci_transfer_ring_link_control(cycle),
        },
    );
}

fn xhci_advance_transfer_ring(
    base: usize,
    ring_bus: u64,
    enqueue: &mut u16,
    cycle: &mut bool,
) -> bool {
    *enqueue = enqueue.wrapping_add(1);
    if usize::from(*enqueue) < XHCI_COMMAND_RING_TRBS - 1 {
        return false;
    }
    xhci_publish_transfer_ring_link(base, ring_bus, *cycle);
    *enqueue = 0;
    *cycle = !*cycle;
    true
}

fn xhci_ack_event_dequeue(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return false;
    };
    let (next_dequeue, next_cycle) = xhci_next_event_dequeue_state(state);
    let Some(event) = xhci_dma_bus_addr(
        descriptor,
        dma_range,
        XHCI_DMA_EVENT_RING_OFFSET + usize::from(next_dequeue).saturating_mul(XHCI_TRB_BYTES),
    ) else {
        return false;
    };
    usb_write64(
        state.rt_offset as usize + 0x20 + XHCI_ERDP,
        event | (1 << 3),
    );
    let low_ok = xhci_flush_posted_write(
        state,
        XHCI_FLUSH_STAGE_ERDP_LOW,
        state.rt_offset as usize + 0x20 + XHCI_ERDP,
        event as u32 | (1 << 3),
    );
    let high_ok = xhci_flush_posted_write(
        state,
        XHCI_FLUSH_STAGE_ERDP_HIGH,
        state.rt_offset as usize + 0x20 + XHCI_ERDP + 4,
        (event >> 32) as u32,
    );
    if low_ok && high_ok {
        state.event_dequeue = next_dequeue;
        state.event_cycle = next_cycle;
        true
    } else {
        false
    }
}

fn xhci_ack_event_dequeue_barrier_only(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return false;
    };
    let (next_dequeue, next_cycle) = xhci_next_event_dequeue_state(state);
    let Some(event) = xhci_dma_bus_addr(
        descriptor,
        dma_range,
        XHCI_DMA_EVENT_RING_OFFSET + usize::from(next_dequeue).saturating_mul(XHCI_TRB_BYTES),
    ) else {
        return false;
    };
    usb_write64(
        state.rt_offset as usize + 0x20 + XHCI_ERDP,
        event | (1 << 3),
    );
    dma_store_barrier();
    xhci_dma_publish_barrier();
    state.event_dequeue = next_dequeue;
    state.event_cycle = next_cycle;
    true
}

fn xhci_ack_event_dequeue_prompt_safe(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_ERDP_ACK_BEGIN,
        aux0,
    );
    if !xhci_ack_event_dequeue_barrier_only(state, descriptor) {
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_ERDP_ACK_DONE,
        aux0,
    );
    true
}

fn xhci_ack_control_event_dequeue(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    xhci_ack_event_dequeue(state, descriptor)
}

fn xhci_peek_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<XhciTrb> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    let base = dma_range.vaddr as usize + XHCI_DMA_EVENT_RING_OFFSET;
    dma_load_barrier();
    Some(read_xhci_trb(base, usize::from(state.event_dequeue)))
}

fn xhci_peek_command_proof_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    ack_mode: XhciEventAckMode,
) -> Option<XhciTrb> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    let base = dma_range.vaddr as usize + XHCI_DMA_EVENT_RING_OFFSET;
    xhci_publish_command_proof_event_read_begin(ack_mode);
    dma_load_barrier();
    xhci_publish_command_proof_event_dma_load_done(ack_mode);
    let trb = read_xhci_trb_for_command_proof(base, usize::from(state.event_dequeue), ack_mode);
    xhci_publish_command_proof_event_read_done(ack_mode);
    Some(trb)
}

fn xhci_next_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<XhciTrb> {
    let trb = xhci_peek_event(state, descriptor)?;
    if (trb.control & XHCI_TRB_CYCLE != 0) != state.event_cycle {
        return None;
    }
    Some(trb)
}

fn xhci_next_command_proof_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    ack_mode: XhciEventAckMode,
) -> Option<XhciTrb> {
    let trb = xhci_peek_command_proof_event(state, descriptor, ack_mode)?;
    if (trb.control & XHCI_TRB_CYCLE != 0) != state.event_cycle {
        return None;
    }
    Some(trb)
}

fn xhci_submit_command_internal(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    mut trb: XhciTrb,
    proof_progress: Option<(u32, u32)>,
) -> bool {
    if let Some((sequence, aux0)) = proof_progress {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_SUBMIT_BEGIN,
            aux0,
        );
    }
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    );
    let Some(dma_range) = dma_range else {
        return false;
    };
    let base = dma_range.vaddr as usize + XHCI_DMA_COMMAND_RING_OFFSET;
    let index = usize::from(state.cmd_enqueue);
    if index >= XHCI_COMMAND_RING_TRBS - 1 {
        return false;
    }
    trb.control |= xhci_cycle_bit(state.cmd_cycle);
    write_xhci_trb(base, index, trb);
    publish_xhci_command_ring(base);
    if let Some((sequence, aux0)) = proof_progress {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_TRB_WRITTEN,
            aux0,
        );
    }
    state.cmd_enqueue = state.cmd_enqueue.wrapping_add(1);
    if usize::from(state.cmd_enqueue) >= XHCI_COMMAND_RING_TRBS - 1 {
        state.cmd_enqueue = 0;
        state.cmd_cycle = !state.cmd_cycle;
    }
    dma_store_barrier();
    if let Some((sequence, aux0)) = proof_progress {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_DOORBELL_BEGIN,
            aux0,
        );
    }
    let doorbell_ready = xhci_ring_doorbell(state, 0, 0);
    if doorbell_ready {
        if let Some((sequence, aux0)) = proof_progress {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_DOORBELL_DONE,
                aux0,
            );
        }
    }
    doorbell_ready
}

const fn usb_command_proof_should_rering(poll_slices: u8, events_seen: u8) -> bool {
    USB_COMMAND_PROOF_RERINGS_PENDING_DOORBELL
        && events_seen == 0
        && poll_slices != 0
        && poll_slices % USB_COMMAND_PROOF_RERING_INTERVAL_SLICES == 0
}

fn xhci_submit_command(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    trb: XhciTrb,
) -> bool {
    xhci_submit_command_internal(state, descriptor, trb, None)
}

fn xhci_submit_command_for_proof(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    trb: XhciTrb,
) -> bool {
    xhci_submit_command_internal(state, descriptor, trb, Some((sequence, aux0)))
}

fn xhci_enqueue_command(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    trb: XhciTrb,
) -> Option<XhciTrb> {
    if !xhci_submit_command(state, descriptor, trb) {
        return None;
    }
    xhci_wait_command_completion(state, descriptor)
}

fn xhci_enqueue_address_command(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    trb: XhciTrb,
) -> Option<XhciTrb> {
    if !xhci_submit_command(state, descriptor, trb) {
        return None;
    }
    match xhci_poll_command_completion(
        state,
        descriptor,
        USB_COMMAND_COMPLETION_SPINS,
        XhciEventAckMode::AddressCommand { sequence, aux0 },
        None,
    ) {
        XhciCommandCompletionPoll::Complete(event) => Some(event),
        XhciCommandCompletionPoll::CommandFailed(_)
        | XhciCommandCompletionPoll::Failed
        | XhciCommandCompletionPoll::Pending(_) => None,
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum XhciCommandCompletionPoll {
    Complete(XhciTrb),
    CommandFailed(XhciTrb),
    Failed,
    Pending(XhciCommandCompletionPending),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum XhciCommandCompletionPending {
    PollBudget,
    EventSlotEmpty,
    EventCycleMismatch,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum XhciEventAckMode {
    Readback,
    EndpointRecovery,
    PromptSafe { sequence: u32, aux0: u32 },
    AddressCommand { sequence: u32, aux0: u32 },
}

fn xhci_record_command_proof_event(state: &mut UsbRuntimeState, event: XhciTrb) {
    state.command_proof_events_seen = state.command_proof_events_seen.saturating_add(1);
    state.command_proof_last_event_type = xhci_trb_type(event.control) as u8;
}

fn xhci_publish_command_proof_event_progress(ack_mode: XhciEventAckMode, event: XhciTrb) {
    let (sequence, aux0, phase) = match ack_mode {
        XhciEventAckMode::PromptSafe { sequence, aux0 } => {
            let phase = match xhci_trb_type(event.control) {
                XHCI_TRB_TYPE_COMMAND_COMPLETION => {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_COMMAND
                }
                XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT => {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_PORT_STATUS
                }
                _ => DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_OTHER,
            };
            (sequence, aux0, phase)
        }
        XhciEventAckMode::AddressCommand { sequence, aux0 } => {
            let phase = match xhci_trb_type(event.control) {
                XHCI_TRB_TYPE_COMMAND_COMPLETION => {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_COMMAND
                }
                XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT => {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_PORT_STATUS
                }
                _ => DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_OTHER,
            };
            (sequence, aux0, phase)
        }
        XhciEventAckMode::Readback | XhciEventAckMode::EndpointRecovery => return,
    };
    publish_runtime_progress(sequence, phase, aux0);
}

const fn xhci_command_proof_pending_progress_phase(pending: XhciCommandCompletionPending) -> u32 {
    match pending {
        XhciCommandCompletionPending::PollBudget => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_PENDING
        }
        XhciCommandCompletionPending::EventSlotEmpty => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_SLOT_EMPTY
        }
        XhciCommandCompletionPending::EventCycleMismatch => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_CYCLE_MISMATCH
        }
    }
}

const fn xhci_address_command_pending_progress_phase(pending: XhciCommandCompletionPending) -> u32 {
    match pending {
        XhciCommandCompletionPending::PollBudget => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_POLL_PENDING
        }
        XhciCommandCompletionPending::EventSlotEmpty => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_SLOT_EMPTY
        }
        XhciCommandCompletionPending::EventCycleMismatch => {
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_CYCLE_MISMATCH
        }
    }
}

fn xhci_publish_command_poll_begin(ack_mode: XhciEventAckMode) {
    match ack_mode {
        XhciEventAckMode::PromptSafe { sequence, aux0 } => publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_BEGIN,
            aux0,
        ),
        XhciEventAckMode::AddressCommand { sequence, aux0 } => publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_POLL_BEGIN,
            aux0,
        ),
        XhciEventAckMode::Readback | XhciEventAckMode::EndpointRecovery => {}
    }
}

fn xhci_publish_command_poll_heartbeat(
    ack_mode: XhciEventAckMode,
    pending: XhciCommandCompletionPending,
    tick: usize,
) {
    if tick & 1 == 0 {
        xhci_publish_command_poll_begin(ack_mode);
    } else {
        xhci_publish_command_proof_pending_progress(ack_mode, pending);
    }
}

fn xhci_command_proof_pending_reason(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    ack_mode: XhciEventAckMode,
) -> XhciCommandCompletionPending {
    let Some(event) = xhci_peek_command_proof_event(state, descriptor, ack_mode) else {
        return XhciCommandCompletionPending::EventSlotEmpty;
    };
    xhci_command_proof_pending_reason_for_event(event, state.event_cycle)
}

const fn xhci_command_proof_pending_reason_for_event(
    event: XhciTrb,
    expected_cycle: bool,
) -> XhciCommandCompletionPending {
    if event.parameter == 0 && event.status == 0 && event.control == 0 {
        return XhciCommandCompletionPending::EventSlotEmpty;
    }
    if (event.control & XHCI_TRB_CYCLE != 0) != expected_cycle {
        return XhciCommandCompletionPending::EventCycleMismatch;
    }
    XhciCommandCompletionPending::PollBudget
}

fn xhci_publish_command_proof_pending_progress(
    ack_mode: XhciEventAckMode,
    pending: XhciCommandCompletionPending,
) {
    match ack_mode {
        XhciEventAckMode::PromptSafe { sequence, aux0 } => publish_runtime_progress(
            sequence,
            xhci_command_proof_pending_progress_phase(pending),
            aux0,
        ),
        XhciEventAckMode::AddressCommand { sequence, aux0 } => publish_runtime_progress(
            sequence,
            xhci_address_command_pending_progress_phase(pending),
            aux0,
        ),
        XhciEventAckMode::Readback | XhciEventAckMode::EndpointRecovery => {}
    };
}

fn xhci_publish_command_proof_event_peek_begin(ack_mode: XhciEventAckMode) {
    match ack_mode {
        XhciEventAckMode::PromptSafe { sequence, aux0 } => publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_PEEK_BEGIN,
            aux0,
        ),
        XhciEventAckMode::AddressCommand { sequence, aux0 } => publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_EVENT_PEEK_BEGIN,
            aux0,
        ),
        XhciEventAckMode::Readback | XhciEventAckMode::EndpointRecovery => {}
    };
}

fn xhci_publish_command_proof_event_read_done(ack_mode: XhciEventAckMode) {
    if let XhciEventAckMode::PromptSafe { sequence, aux0 } = ack_mode {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_READ_DONE,
            aux0,
        );
    }
}

fn xhci_publish_command_proof_event_dma_load_done(ack_mode: XhciEventAckMode) {
    if let XhciEventAckMode::PromptSafe { sequence, aux0 } = ack_mode {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_DMA_LOAD_DONE,
            aux0,
        );
    }
}

fn xhci_publish_command_proof_event_invalidate_done(ack_mode: XhciEventAckMode) {
    if let XhciEventAckMode::PromptSafe { sequence, aux0 } = ack_mode {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_INVALIDATE_DONE,
            aux0,
        );
    }
}

fn xhci_publish_command_proof_event_read_begin(ack_mode: XhciEventAckMode) {
    if let XhciEventAckMode::PromptSafe { sequence, aux0 } = ack_mode {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_EVENT_READ_BEGIN,
            aux0,
        );
    }
}

fn xhci_ack_command_poll_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    ack_mode: XhciEventAckMode,
) -> bool {
    match ack_mode {
        XhciEventAckMode::Readback | XhciEventAckMode::EndpointRecovery => {
            xhci_ack_event_dequeue(state, descriptor)
        }
        XhciEventAckMode::PromptSafe { sequence, aux0 } => {
            xhci_ack_event_dequeue_prompt_safe(sequence, aux0, state, descriptor)
        }
        XhciEventAckMode::AddressCommand { .. } => xhci_ack_event_dequeue(state, descriptor),
    }
}

fn xhci_command_completion_events_per_slice(ack_mode: XhciEventAckMode) -> usize {
    match ack_mode {
        XhciEventAckMode::EndpointRecovery => USB_ENDPOINT_RECOVERY_COMMAND_EVENTS_PER_SLICE,
        XhciEventAckMode::Readback
        | XhciEventAckMode::PromptSafe { .. }
        | XhciEventAckMode::AddressCommand { .. } => USB_COMMAND_COMPLETION_EVENTS_PER_SLICE,
    }
}

const fn xhci_command_poll_preserves_keyboard_transfer_events(ack_mode: XhciEventAckMode) -> bool {
    !matches!(ack_mode, XhciEventAckMode::EndpointRecovery)
}

fn xhci_poll_command_completion(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    spins: usize,
    ack_mode: XhciEventAckMode,
    expected_command_trb_bus: Option<u64>,
) -> XhciCommandCompletionPoll {
    let mut events = 0usize;
    let mut pending = XhciCommandCompletionPending::PollBudget;
    let mut published_pending = None;
    let mut peek_begin_published = false;
    let events_per_slice = xhci_command_completion_events_per_slice(ack_mode);
    xhci_publish_command_poll_begin(ack_mode);
    let mut spin = 0usize;
    let mut deadline = runtime_deadline_from_legacy_spins(spins);
    while spin < spins && !runtime_deadline_expired(&mut deadline) {
        if !peek_begin_published {
            xhci_publish_command_proof_event_peek_begin(ack_mode);
            peek_begin_published = true;
        }
        while let Some(event) = xhci_next_command_proof_event(state, descriptor, ack_mode) {
            events = events.saturating_add(1);
            xhci_record_command_proof_event(state, event);
            xhci_publish_command_proof_event_progress(ack_mode, event);
            if !xhci_ack_command_poll_event(state, descriptor, ack_mode) {
                state.command_proof_ack_failures =
                    state.command_proof_ack_failures.saturating_add(1);
                return XhciCommandCompletionPoll::Failed;
            }
            if xhci_trb_type(event.control) == XHCI_TRB_TYPE_COMMAND_COMPLETION {
                if expected_command_trb_bus.is_some_and(|expected| {
                    xhci_command_completion_pointer(event.parameter) != expected
                }) {
                    if events >= events_per_slice {
                        return XhciCommandCompletionPoll::Pending(
                            XhciCommandCompletionPending::PollBudget,
                        );
                    }
                    continue;
                }
                let code = xhci_completion_code(event.status);
                if code == XHCI_COMPLETION_SUCCESS {
                    return XhciCommandCompletionPoll::Complete(event);
                }
                return XhciCommandCompletionPoll::CommandFailed(event);
            }
            if xhci_trb_type(event.control) == XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT {
                xhci_preserve_port_status_change_event(state, event);
            } else if xhci_keyboard_transfer_event_matches(state, event) {
                if xhci_command_poll_preserves_keyboard_transfer_events(ack_mode) {
                    if !xhci_preserve_keyboard_transfer_event(state, event) {
                        return XhciCommandCompletionPoll::Failed;
                    }
                } else {
                    state.keyboard_transfer_events =
                        state.keyboard_transfer_events.saturating_add(1);
                    state.keyboard_unmatched_streak =
                        state.keyboard_unmatched_streak.saturating_add(1);
                    if xhci_completion_code(event.status) == XHCI_COMPLETION_STALL_ERROR {
                        state.keyboard_endpoint_reset_required = true;
                    }
                }
            }
            if events >= events_per_slice {
                return XhciCommandCompletionPoll::Pending(
                    XhciCommandCompletionPending::PollBudget,
                );
            }
        }
        pending = xhci_command_proof_pending_reason(state, descriptor, ack_mode);
        if published_pending != Some(pending) {
            xhci_publish_command_proof_pending_progress(ack_mode, pending);
            published_pending = Some(pending);
        }
        if spin != 0 && spin % USB_COMMAND_COMPLETION_PROGRESS_SPINS == 0 {
            xhci_publish_command_poll_heartbeat(
                ack_mode,
                pending,
                spin / USB_COMMAND_COMPLETION_PROGRESS_SPINS,
            );
        }
        spin = spin.saturating_add(1);
        runtime_poll_pause();
    }
    XhciCommandCompletionPoll::Pending(pending)
}

fn xhci_wait_command_completion(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<XhciTrb> {
    match xhci_poll_command_completion(
        state,
        descriptor,
        USB_COMMAND_COMPLETION_SPINS,
        XhciEventAckMode::Readback,
        None,
    ) {
        XhciCommandCompletionPoll::Complete(event) => Some(event),
        XhciCommandCompletionPoll::CommandFailed(_)
        | XhciCommandCompletionPoll::Failed
        | XhciCommandCompletionPoll::Pending(_) => None,
    }
}

const fn xhci_endpoint_command_control(command_type: u32, slot: u8, endpoint_id: u8) -> u32 {
    (command_type << 10) | ((endpoint_id as u32) << 16) | ((slot as u32) << 24)
}

const fn xhci_transfer_dequeue_pointer(ring_bus: u64, cycle: bool) -> u64 {
    (ring_bus & !0xf) | if cycle { 1 } else { 0 }
}

const fn xhci_command_completion_pointer(parameter: u64) -> u64 {
    parameter & !0xf
}

fn xhci_next_command_trb_bus(
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<u64> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    xhci_dma_bus_addr(
        descriptor,
        dma_range,
        XHCI_DMA_COMMAND_RING_OFFSET
            + usize::from(state.cmd_enqueue).saturating_mul(XHCI_TRB_BYTES),
    )
}

fn xhci_stop_endpoint_command(slot: u8, endpoint_id: u8) -> XhciTrb {
    XhciTrb {
        parameter: 0,
        status: 0,
        control: xhci_endpoint_command_control(XHCI_TRB_TYPE_STOP_ENDPOINT, slot, endpoint_id),
    }
}

fn xhci_reset_endpoint_command(slot: u8, endpoint_id: u8) -> XhciTrb {
    XhciTrb {
        parameter: 0,
        status: 0,
        control: xhci_endpoint_command_control(XHCI_TRB_TYPE_RESET_ENDPOINT, slot, endpoint_id),
    }
}

fn xhci_set_tr_dequeue_pointer_command(
    slot: u8,
    endpoint_id: u8,
    ring_bus: u64,
    cycle: bool,
) -> XhciTrb {
    XhciTrb {
        parameter: xhci_transfer_dequeue_pointer(ring_bus, cycle),
        status: 0,
        control: xhci_endpoint_command_control(
            XHCI_TRB_TYPE_SET_TR_DEQUEUE_POINTER,
            slot,
            endpoint_id,
        ),
    }
}

fn xhci_enqueue_endpoint_recovery_command(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    trb: XhciTrb,
    accept_context_state: bool,
) -> bool {
    let Some(command_trb_bus) = xhci_next_command_trb_bus(state, descriptor) else {
        return false;
    };
    if !xhci_submit_command(state, descriptor, trb) {
        return false;
    }
    match xhci_poll_command_completion(
        state,
        descriptor,
        USB_ENDPOINT_RECOVERY_COMMAND_SPINS,
        XhciEventAckMode::EndpointRecovery,
        Some(command_trb_bus),
    ) {
        XhciCommandCompletionPoll::Complete(event)
            if xhci_command_completion_pointer(event.parameter) == command_trb_bus =>
        {
            true
        }
        XhciCommandCompletionPoll::CommandFailed(event)
            if accept_context_state
                && xhci_command_completion_pointer(event.parameter) == command_trb_bus
                && xhci_completion_code(event.status) == XHCI_COMPLETION_CONTEXT_STATE_ERROR =>
        {
            true
        }
        XhciCommandCompletionPoll::Complete(_)
        | XhciCommandCompletionPoll::CommandFailed(_)
        | XhciCommandCompletionPoll::Failed
        | XhciCommandCompletionPoll::Pending(_) => false,
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct XhciControlTransferPlan {
    setup_trb: u64,
    data_trb: u64,
    status_trb: u64,
    data_len: usize,
    data_stage_event_expected: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct XhciControlProgress {
    sequence: u32,
    aux0: u32,
    doorbell_done: u32,
    wait_begin: u32,
    data_event: u32,
    status_event: u32,
    failed: u32,
    transfer_timeout: u32,
    status_timeout: u32,
}

fn xhci_publish_control_progress(progress: Option<XhciControlProgress>, phase: u32) {
    if let Some(progress) = progress {
        publish_runtime_progress(progress.sequence, phase, progress.aux0);
    }
}

fn xhci_publish_hub_port_status_tail_progress(progress: Option<XhciControlProgress>, phase: u32) {
    if let Some(progress) = progress {
        if progress.status_event == DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT {
            publish_runtime_progress(progress.sequence, phase, progress.aux0);
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct XhciControlEventDiagnosticPhases {
    slot_empty: u32,
    cycle_mismatch: u32,
    ignored: u32,
}

const fn xhci_control_transfer_event_diagnostic_phases(
    progress: XhciControlProgress,
    status_stage: bool,
) -> XhciControlEventDiagnosticPhases {
    match progress.transfer_timeout {
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_TIMEOUT => {
            XhciControlEventDiagnosticPhases {
                slot_empty:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_SLOT_EMPTY,
                cycle_mismatch:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_CYCLE_MISMATCH,
                ignored:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_IGNORED,
            }
        }
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_TIMEOUT => {
            if status_stage {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_IGNORED,
                }
            } else {
                XhciControlEventDiagnosticPhases {
                    slot_empty:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_SLOT_EMPTY,
                    cycle_mismatch:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_CYCLE_MISMATCH,
                    ignored:
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_IGNORED,
                }
            }
        }
        _ => XhciControlEventDiagnosticPhases {
            slot_empty: 0,
            cycle_mismatch: 0,
            ignored: 0,
        },
    }
}

const fn xhci_control_event_is_empty(event: XhciTrb) -> bool {
    event.parameter == 0 && event.status == 0 && event.control == 0
}

const fn xhci_control_pending_event_phase_for_event(
    event: XhciTrb,
    expected_cycle: bool,
    progress: XhciControlProgress,
    status_stage: bool,
) -> u32 {
    let phases = xhci_control_transfer_event_diagnostic_phases(progress, status_stage);
    if xhci_control_event_is_empty(event) {
        return phases.slot_empty;
    }
    if (event.control & XHCI_TRB_CYCLE != 0) != expected_cycle {
        return phases.cycle_mismatch;
    }
    0
}

fn xhci_control_pending_event_phase_rank(phase: u32) -> u8 {
    match phase {
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_IGNORED
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_IGNORED => 3,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_CYCLE_MISMATCH
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_CYCLE_MISMATCH => 2,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_SLOT_EMPTY
        | DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_SLOT_EMPTY => 1,
        _ => 0,
    }
}

fn xhci_publish_control_pending_event_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    progress: Option<XhciControlProgress>,
    status_stage: bool,
    published_pending: &mut Option<u32>,
) {
    let Some(progress) = progress else {
        return;
    };
    let Some(event) = xhci_peek_event(state, descriptor) else {
        return;
    };
    let phase = xhci_control_pending_event_phase_for_event(
        event,
        state.event_cycle,
        progress,
        status_stage,
    );
    let phase_rank = xhci_control_pending_event_phase_rank(phase);
    let published_rank =
        xhci_control_pending_event_phase_rank(published_pending.unwrap_or_default());
    if phase != 0 && phase_rank > published_rank {
        xhci_publish_control_progress(Some(progress), phase);
        *published_pending = Some(phase);
    }
}

fn xhci_publish_control_ignored_event_progress(
    progress: Option<XhciControlProgress>,
    status_stage: bool,
) -> Option<u32> {
    let Some(progress) = progress else {
        return None;
    };
    let phase = xhci_control_transfer_event_diagnostic_phases(progress, status_stage).ignored;
    if phase != 0 {
        xhci_publish_control_progress(Some(progress), phase);
        return Some(phase);
    }
    None
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum XhciControlTransferEvent {
    Ignore,
    Fail { code: u32 },
    DataStage { transferred: usize },
    Complete,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum XhciControlTransferOutcome {
    Complete(usize),
    Failed { code: u32 },
    PendingData,
    PendingStatus,
}

fn xhci_control_data_stage_control(data_in: bool, data_stage_ioc: bool, cycle: bool) -> u32 {
    (XHCI_TRB_TYPE_DATA_STAGE << 10)
        | (if data_in { XHCI_TRB_DIR_IN } else { 0 })
        | (if data_stage_ioc { XHCI_TRB_IOC } else { 0 })
        | XHCI_TRB_ISP
        | xhci_cycle_bit(cycle)
}

fn xhci_control_setup_stage_control(setup_transfer_type: u32, cycle: bool) -> u32 {
    (XHCI_TRB_TYPE_SETUP_STAGE << 10) | XHCI_TRB_IDT | setup_transfer_type | xhci_cycle_bit(cycle)
}

const fn xhci_transfer_event_remaining(status: u32) -> usize {
    (status & 0x00ff_ffff) as usize
}

const fn xhci_transfer_event_trb_pointer(parameter: u64) -> u64 {
    parameter & !0x0f
}

const fn xhci_control_completion_ok(code: u32) -> bool {
    code == XHCI_COMPLETION_SUCCESS || code == XHCI_COMPLETION_SHORT_PACKET
}

const fn xhci_classify_control_transfer_event(
    plan: XhciControlTransferPlan,
    slot: u8,
    endpoint_id: u8,
    event: XhciTrb,
    status_stage: bool,
) -> XhciControlTransferEvent {
    if xhci_trb_type(event.control) != XHCI_TRB_TYPE_TRANSFER_EVENT
        || xhci_slot_id(event.control) != slot
        || xhci_endpoint_id(event.control) != endpoint_id
    {
        return XhciControlTransferEvent::Ignore;
    }
    let code = xhci_completion_code(event.status);
    if !xhci_control_completion_ok(code) {
        return XhciControlTransferEvent::Fail { code };
    }
    let completion_ptr = xhci_transfer_event_trb_pointer(event.parameter);
    let event_remaining = xhci_transfer_event_remaining(event.status);
    if completion_ptr == plan.status_trb {
        return XhciControlTransferEvent::Complete;
    }
    if completion_ptr == plan.setup_trb {
        if event_remaining == 0 && (plan.data_len == 0 || !plan.data_stage_event_expected) {
            return XhciControlTransferEvent::Complete;
        }
        return XhciControlTransferEvent::Ignore;
    }
    if !status_stage
        && plan.data_len != 0
        && !plan.data_stage_event_expected
        && code == XHCI_COMPLETION_SUCCESS
        && event_remaining == 0
    {
        return XhciControlTransferEvent::Complete;
    }
    if completion_ptr == plan.data_trb && plan.data_len != 0 {
        let remaining = if event_remaining > plan.data_len {
            plan.data_len
        } else {
            event_remaining
        };
        return XhciControlTransferEvent::DataStage {
            transferred: plan.data_len - remaining,
        };
    }
    if !status_stage && plan.data_len != 0 && event_remaining <= plan.data_len {
        // Hub GET_STATUS clears data-stage IOC; a full-length same-EP success
        // event with an implementation-specific pointer is the status event.
        if !plan.data_stage_event_expected
            && code == XHCI_COMPLETION_SUCCESS
            && event_remaining == 0
        {
            return XhciControlTransferEvent::Complete;
        }
        return XhciControlTransferEvent::DataStage {
            transferred: plan.data_len - event_remaining,
        };
    }
    if status_stage && event_remaining == 0 {
        return XhciControlTransferEvent::Complete;
    }
    XhciControlTransferEvent::Ignore
}

fn xhci_wait_control_transfer_completion_outcome(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    slot: u8,
    endpoint_id: u8,
    plan: XhciControlTransferPlan,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> XhciControlTransferOutcome {
    let mut transferred = if plan.data_len == 0 { Some(0) } else { None };
    let mut published_pending = None;
    let mut spin = 0usize;
    let mut deadline = runtime_deadline_from_legacy_spins(completion_spins);
    xhci_publish_control_progress(progress, progress.map_or(0, |progress| progress.wait_begin));
    while spin < completion_spins && !runtime_deadline_expired(&mut deadline) {
        while let Some(event) = xhci_next_event(state, descriptor) {
            published_pending = None;
            match xhci_classify_control_transfer_event(
                plan,
                slot,
                endpoint_id,
                event,
                transferred.is_some(),
            ) {
                XhciControlTransferEvent::Complete => {
                    xhci_publish_control_progress(
                        progress,
                        progress.map_or(0, |progress| progress.status_event),
                    );
                    if !xhci_ack_control_event_dequeue(state, descriptor) {
                        xhci_publish_control_progress(
                            progress,
                            progress.map_or(0, |progress| progress.failed),
                        );
                        return XhciControlTransferOutcome::Failed { code: 0 };
                    }
                    xhci_publish_hub_port_status_tail_progress(
                        progress,
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_ACK_DONE,
                    );
                    return XhciControlTransferOutcome::Complete(
                        transferred.unwrap_or(plan.data_len),
                    );
                }
                XhciControlTransferEvent::DataStage { transferred: bytes } => {
                    xhci_publish_control_progress(
                        progress,
                        progress.map_or(0, |progress| progress.data_event),
                    );
                    if !xhci_ack_control_event_dequeue(state, descriptor) {
                        xhci_publish_control_progress(
                            progress,
                            progress.map_or(0, |progress| progress.failed),
                        );
                        return XhciControlTransferOutcome::Failed { code: 0 };
                    }
                    transferred = Some(bytes);
                }
                XhciControlTransferEvent::Fail { code } => {
                    xhci_publish_control_progress(
                        progress,
                        progress.map_or(0, |progress| progress.failed),
                    );
                    let _ = xhci_ack_control_event_dequeue(state, descriptor);
                    return XhciControlTransferOutcome::Failed { code };
                }
                XhciControlTransferEvent::Ignore => {
                    if let Some(phase) =
                        xhci_publish_control_ignored_event_progress(progress, transferred.is_some())
                    {
                        published_pending = Some(phase);
                    }
                    let mut ignored_event_failed = false;
                    if xhci_trb_type(event.control) == XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT {
                        xhci_preserve_port_status_change_event(state, event);
                    } else if xhci_keyboard_transfer_event_matches(state, event)
                        && !xhci_preserve_keyboard_transfer_event(state, event)
                    {
                        ignored_event_failed = true;
                    }
                    if !xhci_ack_control_event_dequeue(state, descriptor) {
                        xhci_publish_control_progress(
                            progress,
                            progress.map_or(0, |progress| progress.failed),
                        );
                        return XhciControlTransferOutcome::Failed { code: 0 };
                    }
                    if ignored_event_failed {
                        xhci_publish_control_progress(
                            progress,
                            progress.map_or(0, |progress| progress.failed),
                        );
                        return XhciControlTransferOutcome::Failed { code: 0 };
                    }
                }
            }
        }
        xhci_publish_control_pending_event_progress(
            state,
            descriptor,
            progress,
            transferred.is_some(),
            &mut published_pending,
        );
        spin = spin.saturating_add(1);
        runtime_poll_pause();
    }
    xhci_publish_control_progress(
        progress,
        progress.map_or(0, |progress| {
            if transferred.is_some() {
                progress.status_timeout
            } else {
                progress.transfer_timeout
            }
        }),
    );
    if transferred.is_some() {
        XhciControlTransferOutcome::PendingStatus
    } else {
        XhciControlTransferOutcome::PendingData
    }
}

#[cfg(test)]
fn xhci_wait_control_transfer_completion(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    slot: u8,
    endpoint_id: u8,
    plan: XhciControlTransferPlan,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> Option<usize> {
    match xhci_wait_control_transfer_completion_outcome(
        state,
        descriptor,
        slot,
        endpoint_id,
        plan,
        progress,
        completion_spins,
    ) {
        XhciControlTransferOutcome::Complete(transferred) => Some(transferred),
        XhciControlTransferOutcome::Failed { .. }
        | XhciControlTransferOutcome::PendingData
        | XhciControlTransferOutcome::PendingStatus => None,
    }
}

fn xhci_context_addr(dma_base: usize, offset: usize, context_bytes: usize, index: usize) -> usize {
    dma_base + offset + context_bytes.saturating_mul(index)
}

fn xhci_write_context_u32(
    dma_base: usize,
    offset: usize,
    context_bytes: usize,
    index: usize,
    word: usize,
    value: u32,
) {
    write_dma_u32(
        xhci_context_addr(dma_base, offset, context_bytes, index) + word.saturating_mul(4),
        value,
    );
}

const fn xhci_default_control_packet(speed: u32) -> u32 {
    match speed {
        XHCI_SPEED_LOW => 8,
        XHCI_SPEED_SUPER => 512,
        _ => XHCI_DEFAULT_CONTROL_PACKET,
    }
}

fn xhci_control_packet_candidates(speed: u32) -> ([u32; 3], usize) {
    match speed {
        XHCI_SPEED_LOW => ([8, 0, 0], 1),
        XHCI_SPEED_FULL => ([64, 8, 0], 2),
        XHCI_SPEED_HIGH => ([64, 0, 0], 1),
        XHCI_SPEED_SUPER => ([512, 64, 0], 2),
        _ => ([64, 8, 512], 3),
    }
}

const fn xhci_keyboard_interval_exponent(speed: u32, interval: u8) -> u8 {
    if matches!(speed, XHCI_SPEED_LOW | XHCI_SPEED_FULL) {
        6
    } else {
        interval
    }
}

const fn xhci_keyboard_transfer_payload(max_packet: u16) -> u32 {
    let packet = if max_packet < XHCI_BOOT_REPORT_BYTES as u16 {
        XHCI_BOOT_REPORT_BYTES as u16
    } else {
        max_packet
    };
    packet as u32
}

const fn xhci_device_context_offset(index: usize) -> usize {
    XHCI_DMA_DEVICE_CONTEXT_OFFSET + index * XHCI_DMA_DEVICE_CONTEXT_STRIDE
}

const fn xhci_ep0_ring_offset(index: usize) -> usize {
    XHCI_DMA_EP0_RING_OFFSET + index * XHCI_DMA_EP0_RING_STRIDE
}

fn xhci_address_tt_info(device: &UsbEnumerationDevice) -> u32 {
    if !matches!(device.speed, XHCI_SPEED_LOW | XHCI_SPEED_FULL) || device.parent_hub_slot == 0 {
        return 0;
    }
    // Pi 4 VL805 follows the Linux-observed Address Device shape: publish the
    // parent TT hub slot and downstream port, but leave TT think time clear.
    let tt_port = if device.parent_tt_port == 0 {
        device.parent_hub_port
    } else {
        device.parent_tt_port
    };
    u32::from(device.parent_hub_slot) | (u32::from(tt_port) << XHCI_SLOT_TT_PORT_SHIFT)
}

fn xhci_prepare_contexts(
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    device: &UsbEnumerationDevice,
    endpoint_id: u8,
    hub_ports: u8,
    multi_tt: bool,
    control_packet: u32,
) -> bool {
    let dma_base = dma_range.vaddr as usize;
    zero_dma_range(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET, 0x2000);
    let add_flags = if endpoint_id == 0 {
        (1 << 0) | (1 << 1)
    } else {
        (1 << 0) | (1u32 << endpoint_id)
    };
    write_dma_u32(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET + 4, add_flags);
    let context_entries = if endpoint_id == 0 {
        1
    } else {
        u32::from(endpoint_id)
    };
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_SLOT_CONTEXT_INDEX,
        0,
        (device.route & 0x000f_ffff)
            | (device.speed << XHCI_SLOT_SPEED_SHIFT)
            | (if hub_ports != 0 { XHCI_SLOT_HUB } else { 0 })
            | (if multi_tt { XHCI_SLOT_MULTI_TT } else { 0 })
            | (context_entries << XHCI_CONTEXT_ENTRIES_SHIFT),
    );
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_SLOT_CONTEXT_INDEX,
        1,
        (u32::from(device.root_port) << XHCI_SLOT_ROOT_HUB_PORT_SHIFT)
            | (u32::from(hub_ports) << XHCI_SLOT_PORTS_SHIFT),
    );
    let tt_info = xhci_address_tt_info(device);
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_SLOT_CONTEXT_INDEX,
        2,
        tt_info,
    );
    let Some(ep0_ring) = xhci_dma_bus_addr(descriptor, dma_range, device.ep0_ring_offset) else {
        return false;
    };
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_EP0_CONTEXT_INDEX,
        1,
        (XHCI_ENDPOINT_TYPE_CONTROL << XHCI_EP_TYPE_SHIFT)
            | (control_packet << XHCI_EP_MAX_PACKET_SHIFT),
    );
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_EP0_CONTEXT_INDEX,
        2,
        ep0_ring as u32 | 1,
    );
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_EP0_CONTEXT_INDEX,
        3,
        (ep0_ring >> 32) as u32,
    );
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_EP0_CONTEXT_INDEX,
        4,
        8,
    );
    if endpoint_id != 0 {
        let Some(kbd_ring) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET)
        else {
            return false;
        };
        xhci_write_context_u32(
            dma_base,
            XHCI_DMA_INPUT_CONTEXT_OFFSET,
            state.context_bytes,
            usize::from(endpoint_id) + 1,
            0,
            u32::from(xhci_keyboard_interval_exponent(
                device.speed,
                state.keyboard_ep_interval,
            )) << 16,
        );
        let transfer_payload = xhci_keyboard_transfer_payload(state.keyboard_ep_max_packet);
        xhci_write_context_u32(
            dma_base,
            XHCI_DMA_INPUT_CONTEXT_OFFSET,
            state.context_bytes,
            usize::from(endpoint_id) + 1,
            1,
            (3 << 1)
                | (XHCI_ENDPOINT_TYPE_INTERRUPT_IN << XHCI_EP_TYPE_SHIFT)
                | (transfer_payload << XHCI_EP_MAX_PACKET_SHIFT),
        );
        xhci_write_context_u32(
            dma_base,
            XHCI_DMA_INPUT_CONTEXT_OFFSET,
            state.context_bytes,
            usize::from(endpoint_id) + 1,
            2,
            kbd_ring as u32 | 1,
        );
        xhci_write_context_u32(
            dma_base,
            XHCI_DMA_INPUT_CONTEXT_OFFSET,
            state.context_bytes,
            usize::from(endpoint_id) + 1,
            3,
            (kbd_ring >> 32) as u32,
        );
        xhci_write_context_u32(
            dma_base,
            XHCI_DMA_INPUT_CONTEXT_OFFSET,
            state.context_bytes,
            usize::from(endpoint_id) + 1,
            4,
            transfer_payload | (transfer_payload << 16),
        );
    }
    dma_clean_range(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET, 0x2000);
    true
}

fn xhci_evaluate_hub_context(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    device: &UsbEnumerationDevice,
    ports: u8,
    multi_tt: bool,
) -> bool {
    let dma_base = dma_range.vaddr as usize;
    zero_dma_range(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET, 0x2000);
    write_dma_u32(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET + 4, 1 << 0);
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_SLOT_CONTEXT_INDEX,
        0,
        (device.route & 0x000f_ffff)
            | (device.speed << XHCI_SLOT_SPEED_SHIFT)
            | XHCI_SLOT_HUB
            | (if multi_tt { XHCI_SLOT_MULTI_TT } else { 0 })
            | (1 << XHCI_CONTEXT_ENTRIES_SHIFT),
    );
    xhci_write_context_u32(
        dma_base,
        XHCI_DMA_INPUT_CONTEXT_OFFSET,
        state.context_bytes,
        XHCI_SLOT_CONTEXT_INDEX,
        1,
        (u32::from(device.root_port) << XHCI_SLOT_ROOT_HUB_PORT_SHIFT)
            | (u32::from(ports) << XHCI_SLOT_PORTS_SHIFT),
    );
    dma_clean_range(dma_base + XHCI_DMA_INPUT_CONTEXT_OFFSET, 0x2000);
    let Some(input_ctx) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_INPUT_CONTEXT_OFFSET)
    else {
        return false;
    };
    xhci_enqueue_command(
        state,
        descriptor,
        XhciTrb {
            parameter: input_ctx,
            status: 0,
            control: (XHCI_TRB_TYPE_EVALUATE_CONTEXT << 10) | (u32::from(device.slot) << 24),
        },
    )
    .is_some()
}

fn xhci_begin_dma_zero(sequence: u32, aux0: u32) {
    publish_runtime_progress(
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_BEGIN,
        aux0,
    );
    publish_runtime_cadence(
        HOT_PATH_USB_KEYBOARD,
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_BEGIN,
        0,
        XHCI_DMA_ZERO_BYTES as u32,
        pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
        pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_REMAINS
            | pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_BYTES,
    );
}

fn xhci_zero_dma_turn(sequence: u32, aux0: u32, dma_base: usize, zeroed: usize) -> usize {
    let chunk = XHCI_DMA_ZERO_BYTES
        .saturating_sub(zeroed)
        .min(XHCI_DMA_ZERO_DIAGNOSTIC_CHUNK_BYTES);
    zero_dma_range(dma_base.saturating_add(zeroed), chunk);
    let next = zeroed.saturating_add(chunk).min(XHCI_DMA_ZERO_BYTES);
    publish_runtime_progress(
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_PROGRESS,
        aux0,
    );
    publish_runtime_cadence(
        HOT_PATH_USB_KEYBOARD,
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_PROGRESS,
        next as u32,
        XHCI_DMA_ZERO_BYTES as u32,
        pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
        (if next < XHCI_DMA_ZERO_BYTES {
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_REMAINS
        } else {
            0
        }) | pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_BYTES,
    );
    if next == XHCI_DMA_ZERO_BYTES {
        publish_runtime_progress(
            sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_DONE,
            aux0,
        );
        publish_runtime_cadence(
            HOT_PATH_USB_KEYBOARD,
            sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_ZERO_DONE,
            XHCI_DMA_ZERO_BYTES as u32,
            XHCI_DMA_ZERO_BYTES as u32,
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_BYTES,
        );
    }
    next
}

fn xhci_prepare_dma_ring_graph(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    let dma_base = dma_range.vaddr as usize;
    publish_runtime_progress(
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_RING_GRAPH_BEGIN,
        aux0,
    );
    let Some(cmd_ring_bus) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_COMMAND_RING_OFFSET)
    else {
        return false;
    };
    let Some(event_ring_bus) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_EVENT_RING_OFFSET)
    else {
        return false;
    };
    let cmd_base = dma_base + XHCI_DMA_COMMAND_RING_OFFSET;
    write_xhci_trb(
        cmd_base,
        XHCI_COMMAND_RING_TRBS - 1,
        XhciTrb {
            parameter: cmd_ring_bus,
            status: 0,
            control: (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT,
        },
    );
    for index in 0..USB_ENUM_MAX_DEVICES {
        let ep0_offset = xhci_ep0_ring_offset(index);
        write_xhci_trb(
            dma_base + ep0_offset,
            XHCI_COMMAND_RING_TRBS - 1,
            XhciTrb {
                parameter: match xhci_dma_bus_addr(descriptor, dma_range, ep0_offset) {
                    Some(addr) => addr,
                    None => return false,
                },
                status: 0,
                control: (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT,
            },
        );
    }
    write_xhci_trb(
        dma_base + XHCI_DMA_KBD_RING_OFFSET,
        XHCI_COMMAND_RING_TRBS - 1,
        XhciTrb {
            parameter: match xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET) {
                Some(addr) => addr,
                None => return false,
            },
            status: 0,
            control: (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT,
        },
    );
    write_dma_u64(dma_base + XHCI_DMA_ERST_OFFSET, event_ring_bus);
    write_dma_u32(
        dma_base + XHCI_DMA_ERST_OFFSET + 8,
        XHCI_EVENT_RING_TRBS as u32,
    );
    state.cmd_enqueue = 0;
    state.cmd_cycle = true;
    state.event_dequeue = 0;
    state.event_cycle = true;
    state.ep0_enqueue = 0;
    state.ep0_cycle = true;
    state.kbd_enqueue = 0;
    state.kbd_cycle = true;
    usb_reset_keyboard_interrupt_queue(state);
    state.port_event_candidate_mask = 0;
    state.port_event_count = 0;
    state.enumeration_retry_cooldown = 0;
    state.enumeration_retry_window_exhausted = false;
    usb_reset_enumeration_cursor(state);
    publish_runtime_progress(
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_RING_GRAPH_DONE,
        aux0,
    );
    publish_runtime_cadence(
        HOT_PATH_USB_KEYBOARD,
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_RING_GRAPH_DONE,
        1,
        1,
        pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
        0,
    );
    true
}

fn xhci_begin_dma_clean(sequence: u32, aux0: u32) {
    publish_runtime_progress(
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_CLEAN_BEGIN,
        aux0,
    );
}

fn xhci_clean_dma_turn(sequence: u32, aux0: u32, dma_base: usize, cleaned: usize) -> usize {
    let chunk = XHCI_DMA_ZERO_BYTES
        .saturating_sub(cleaned)
        .min(XHCI_DMA_ZERO_DIAGNOSTIC_CHUNK_BYTES);
    dma_clean_range(dma_base.saturating_add(cleaned), chunk);
    let next = cleaned.saturating_add(chunk).min(XHCI_DMA_ZERO_BYTES);
    publish_runtime_cadence(
        HOT_PATH_USB_KEYBOARD,
        sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_CLEAN_BEGIN,
        next as u32,
        XHCI_DMA_ZERO_BYTES as u32,
        pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
        (if next < XHCI_DMA_ZERO_BYTES {
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_REMAINS
        } else {
            0
        }) | pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_BYTES,
    );
    if next == XHCI_DMA_ZERO_BYTES {
        publish_runtime_progress(
            sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_CLEAN_DONE,
            aux0,
        );
        publish_runtime_cadence(
            HOT_PATH_USB_KEYBOARD,
            sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_CLEAN_DONE,
            XHCI_DMA_ZERO_BYTES as u32,
            XHCI_DMA_ZERO_BYTES as u32,
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_EXIT_PROGRESS,
            pi4_driver_abi::DRIVER_RUNTIME_CADENCE_FLAG_WORK_BYTES,
        );
    }
    next
}

#[cfg(not(target_os = "none"))]
fn xhci_prepare_dma_structures(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    let dma_base = dma_range.vaddr as usize;
    xhci_begin_dma_zero(sequence, aux0);
    let mut zeroed = 0usize;
    while zeroed < XHCI_DMA_ZERO_BYTES {
        zeroed = xhci_zero_dma_turn(sequence, aux0, dma_base, zeroed);
    }
    if !xhci_prepare_dma_ring_graph(sequence, aux0, state, descriptor, dma_range) {
        return false;
    }
    xhci_begin_dma_clean(sequence, aux0);
    let mut cleaned = 0usize;
    while cleaned < XHCI_DMA_ZERO_BYTES {
        cleaned = xhci_clean_dma_turn(sequence, aux0, dma_base, cleaned);
    }
    true
}

fn xhci_publish_scratchpad_structures(
    sequence: u32,
    aux0: u32,
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    if state.scratchpad_count == 0 {
        return true;
    }
    let dma_base = dma_range.vaddr as usize;
    let Some(array_bus) =
        xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_SCRATCHPAD_ARRAY_OFFSET)
    else {
        return false;
    };
    write_dma_u64(dma_base + XHCI_DMA_DCBBA_OFFSET, array_bus);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_SCRATCHPAD_SLOT0_WRITTEN,
        aux0,
    );
    dma_clean_range(dma_base + XHCI_DMA_DCBBA_OFFSET, 8);
    xhci_dma_publish_barrier();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_SCRATCHPAD_SLOT0_CLEANED,
        aux0,
    );
    let count = state.scratchpad_count.min(XHCI_MAX_SCRATCHPAD_BUFFERS);
    for index in 0..count {
        let Some(scratch_bus) = xhci_dma_bus_addr(
            descriptor,
            dma_range,
            XHCI_DMA_SCRATCHPAD_OFFSET + index * DRIVER_TASK_RING_PAGE_BYTES,
        ) else {
            return false;
        };
        write_dma_u64(
            dma_base + XHCI_DMA_SCRATCHPAD_ARRAY_OFFSET + index.saturating_mul(8),
            scratch_bus,
        );
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_SCRATCHPAD_ARRAY_FILLED,
        aux0,
    );
    dma_clean_range(
        dma_base + XHCI_DMA_SCRATCHPAD_ARRAY_OFFSET,
        count.saturating_mul(8),
    );
    xhci_dma_publish_barrier();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_SCRATCHPAD_ARRAY_CLEANED,
        aux0,
    );
    true
}

fn xhci_root_portsc_offset(state: &UsbRuntimeState, port: u8) -> Option<usize> {
    if port == 0 || port > state.max_ports {
        return None;
    }
    let op_base = state.cap_length as usize;
    Some(op_base + XHCI_PORTSC_BASE + (usize::from(port) - 1) * XHCI_PORTSC_STRIDE)
}

fn xhci_write_portsc(state: &UsbRuntimeState, portsc: usize, value: u32) -> bool {
    usb_write32(portsc, value);
    xhci_flush_posted_write(state, XHCI_FLUSH_STAGE_PORTSC, portsc, value)
}

fn xhci_power_root_ports(state: &UsbRuntimeState) -> bool {
    for port in 1..=state.max_ports.min(u32::BITS as u8) {
        if let Some(portsc) = xhci_root_portsc_offset(state, port) {
            let status = usb_read32(portsc);
            if !xhci_write_portsc(
                state,
                portsc,
                xhci_portsc_neutral(status) | XHCI_PORTSC_PP | XHCI_PORTSC_CHANGE_BITS,
            ) {
                return false;
            }
        }
    }
    true
}

fn xhci_live_connected_root_port_mask(state: &UsbRuntimeState) -> u32 {
    let mut mask = 0u32;
    for port in 1..=state.max_ports.min(u32::BITS as u8) {
        let Some(portsc) = xhci_root_portsc_offset(state, port) else {
            continue;
        };
        let status = usb_read32(portsc);
        if status & XHCI_PORTSC_CCS != 0 {
            mask |= 1u32 << (port - 1);
        }
    }
    mask
}

fn xhci_root_port_candidate_mask(state: &UsbRuntimeState) -> u32 {
    let capped = state.max_ports.min(u32::BITS as u8);
    if capped == 0 {
        return 0;
    }
    let valid_mask = if capped == u32::BITS as u8 {
        u32::MAX
    } else {
        (1u32 << capped) - 1
    };
    xhci_live_connected_root_port_mask(state) & valid_mask
}

fn xhci_reset_root_port_once(
    sequence: u32,
    aux0: u32,
    state: &UsbRuntimeState,
    port: u8,
    force_probe: bool,
) -> Option<u32> {
    let portsc = xhci_root_portsc_offset(state, port)?;
    let mut status = usb_read32(portsc);
    if status & XHCI_PORTSC_CCS == 0 {
        if !xhci_write_portsc(
            state,
            portsc,
            xhci_portsc_neutral(status) | XHCI_PORTSC_PP | XHCI_PORTSC_CHANGE_BITS,
        ) {
            return None;
        }
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_POWER_WRITE_DONE,
            aux0,
        );
        if !force_probe {
            return None;
        }
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_CONNECT_WAIT_BEGIN,
            aux0,
        );
        let mut deadline = runtime_deadline_from_legacy_spins(USB_ROOT_PORT_POWER_SETTLE_SPINS);
        while !runtime_deadline_expired(&mut deadline) {
            status = usb_read32(portsc);
            if status & XHCI_PORTSC_CCS != 0 {
                break;
            }
            runtime_poll_pause();
        }
    }
    if status & XHCI_PORTSC_CCS == 0 {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_CONNECT_TIMEOUT,
            aux0,
        );
        return None;
    }
    if !xhci_write_portsc(
        state,
        portsc,
        xhci_portsc_neutral(status) | XHCI_PORTSC_PP | XHCI_PORTSC_PR,
    ) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_PR_SET,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_POLL_BEGIN,
        aux0,
    );
    let mut deadline = runtime_deadline_from_legacy_spins(USB_XHCI_SPINS);
    while !runtime_deadline_expired(&mut deadline) {
        let next = usb_read32(portsc);
        if next & XHCI_PORTSC_PR == 0 && next & XHCI_PORTSC_PRC != 0 {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_PRC_SEEN,
                aux0,
            );
            if !xhci_write_portsc(
                state,
                portsc,
                xhci_portsc_neutral(next) | XHCI_PORTSC_CHANGE_BITS,
            ) {
                return None;
            }
            if next & XHCI_PORTSC_PED != 0 {
                usb_spin_wait(USB_ROOT_PORT_POWER_SETTLE_SPINS);
                return Some((next >> XHCI_PORTSC_SPEED_SHIFT) & XHCI_PORTSC_SPEED_MASK);
            }
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_ENABLE_TIMEOUT,
                aux0,
            );
        }
        runtime_poll_pause();
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_TIMEOUT,
        aux0,
    );
    None
}

const fn usb_root_port_reset_retry_delay_spins(attempt: usize) -> usize {
    if attempt == 0 {
        USB_ROOT_PORT_RESET_SHORT_RETRY_SPINS
    } else {
        USB_ROOT_PORT_RESET_LONG_RETRY_SPINS
    }
}

fn xhci_reset_root_port_with_uboot_retries(
    sequence: u32,
    aux0: u32,
    state: &UsbRuntimeState,
    port: u8,
    force_probe: bool,
) -> Option<u32> {
    let mut attempt = 0usize;
    while attempt < USB_ROOT_PORT_RESET_MAX_TRIES {
        if let Some(speed) = xhci_reset_root_port_once(sequence, aux0, state, port, force_probe) {
            return Some(speed);
        }
        let next_attempt = attempt.saturating_add(1);
        if next_attempt < USB_ROOT_PORT_RESET_MAX_TRIES {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_RETRY,
                aux0,
            );
        }
        usb_spin_wait(usb_root_port_reset_retry_delay_spins(attempt));
        attempt = next_attempt;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_FAILED,
        aux0,
    );
    None
}

fn xhci_reset_root_port(
    sequence: u32,
    aux0: u32,
    state: &UsbRuntimeState,
    port: u8,
    force_probe: bool,
) -> Option<u32> {
    let first_speed =
        xhci_reset_root_port_with_uboot_retries(sequence, aux0, state, port, force_probe)?;
    usb_spin_wait(USB_STALE_UBOOT_ROOT_PORT_RESET_SETTLE_SPINS);
    if USB_LINKED_RUNTIME_SECOND_ROOT_PORT_RESET {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_STALE_CLEANUP_BEGIN,
            aux0,
        );
        if let Some(speed) =
            xhci_reset_root_port_with_uboot_retries(sequence, aux0, state, port, true)
        {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_STALE_CLEANUP_DONE,
                aux0,
            );
            Some(speed)
        } else {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_STALE_CLEANUP_FAILED,
                aux0,
            );
            Some(first_speed)
        }
    } else {
        Some(first_speed)
    }
}

fn xhci_enable_slot(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<u8> {
    let command = XhciTrb {
        parameter: 0,
        status: 0,
        control: XHCI_TRB_TYPE_ENABLE_SLOT << 10,
    };
    let event = xhci_enqueue_address_command(sequence, aux0, state, descriptor, command)?;
    let slot = xhci_slot_id(event.control);
    if slot != 0 {
        state.command_path_proven = true;
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY;
        Some(slot)
    } else {
        None
    }
}

fn xhci_disable_slot(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    slot: u8,
) -> bool {
    if slot == 0 {
        return false;
    }
    let command = XhciTrb {
        parameter: 0,
        status: 0,
        control: (XHCI_TRB_TYPE_DISABLE_SLOT << 10) | (u32::from(slot) << 24),
    };
    xhci_enqueue_command(state, descriptor, command).is_some()
}

fn xhci_address_device(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    device: &UsbEnumerationDevice,
    control_packet: u32,
) -> bool {
    let dma_base = dma_range.vaddr as usize;
    zero_dma_range(
        dma_base + device.device_context_offset,
        XHCI_DMA_DEVICE_CONTEXT_STRIDE,
    );
    zero_dma_range(dma_base + device.ep0_ring_offset, XHCI_DMA_EP0_RING_STRIDE);
    if !xhci_prepare_contexts(
        state,
        descriptor,
        dma_range,
        device,
        0,
        0,
        false,
        control_packet,
    ) {
        return false;
    }
    let Some(input_ctx) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_INPUT_CONTEXT_OFFSET)
    else {
        return false;
    };
    let Some(device_ctx) = xhci_dma_bus_addr(descriptor, dma_range, device.device_context_offset)
    else {
        return false;
    };
    state.last_address_slot = device.slot;
    write_dma_u64(
        dma_base + usize::from(device.slot).saturating_mul(8),
        device_ctx,
    );
    dma_clean_range(
        dma_base + device.device_context_offset,
        XHCI_DMA_DEVICE_CONTEXT_STRIDE,
    );
    dma_clean_range(dma_base + device.ep0_ring_offset, XHCI_DMA_EP0_RING_STRIDE);
    dma_clean_range(dma_base + usize::from(device.slot).saturating_mul(8), 8);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_CONTEXTS_PUBLISHED,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_BEGIN,
        aux0,
    );
    let addressed = xhci_enqueue_address_command(
        sequence,
        aux0,
        state,
        descriptor,
        XhciTrb {
            parameter: input_ctx,
            status: 0,
            control: (XHCI_TRB_TYPE_ADDRESS_DEVICE << 10) | (u32::from(device.slot) << 24),
        },
    )
    .is_some();
    publish_runtime_progress(
        sequence,
        if addressed {
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_DONE
        } else {
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_COMMAND_FAILED
        },
        aux0,
    );
    addressed
}

fn xhci_control_transfer(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    data_offset: usize,
    data_len: usize,
    data_in: bool,
) -> Option<usize> {
    xhci_control_transfer_with_progress(
        state,
        descriptor,
        device,
        setup,
        data_offset,
        data_len,
        data_in,
        None,
    )
}

fn xhci_control_transfer_with_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    data_offset: usize,
    data_len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
) -> Option<usize> {
    xhci_control_transfer_with_progress_and_spins(
        state,
        descriptor,
        device,
        setup,
        data_offset,
        data_len,
        data_in,
        progress,
        USB_CONTROL_TRANSFER_SPINS,
    )
}

fn xhci_control_transfer_with_progress_and_spins(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    data_offset: usize,
    data_len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> Option<usize> {
    match xhci_control_transfer_with_progress_and_spins_outcome(
        state,
        descriptor,
        device,
        setup,
        data_offset,
        data_len,
        data_in,
        progress,
        completion_spins,
    ) {
        XhciControlTransferOutcome::Complete(transferred) => Some(transferred),
        XhciControlTransferOutcome::Failed { .. }
        | XhciControlTransferOutcome::PendingData
        | XhciControlTransferOutcome::PendingStatus => None,
    }
}

fn xhci_control_transfer_with_progress_and_spins_outcome(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    data_offset: usize,
    data_len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> XhciControlTransferOutcome {
    xhci_control_transfer_with_progress_and_spins_outcome_with_data_ioc(
        state,
        descriptor,
        device,
        setup,
        data_offset,
        data_len,
        data_in,
        progress,
        completion_spins,
        true,
    )
}

fn xhci_control_transfer_with_progress_and_spins_outcome_with_data_ioc(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    data_offset: usize,
    data_len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
    data_stage_ioc: bool,
) -> XhciControlTransferOutcome {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return XhciControlTransferOutcome::Failed { code: 0 };
    };
    let base = dma_range.vaddr as usize + device.ep0_ring_offset;
    let Some(ep0_ring_bus) = xhci_dma_bus_addr(descriptor, dma_range, device.ep0_ring_offset)
    else {
        return XhciControlTransferOutcome::Failed { code: 0 };
    };
    let Some(data_bus) = xhci_dma_bus_addr(descriptor, dma_range, data_offset) else {
        return XhciControlTransferOutcome::Failed { code: 0 };
    };
    let data_vaddr = dma_range.vaddr as usize + data_offset;
    let setup_value = u64::from(setup[0])
        | (u64::from(setup[1]) << 8)
        | (u64::from(setup[2]) << 16)
        | (u64::from(setup[3]) << 24)
        | (u64::from(setup[4]) << 32)
        | (u64::from(setup[5]) << 40)
        | (u64::from(setup[6]) << 48)
        | (u64::from(setup[7]) << 56);
    let setup_index = usize::from(device.ep0_enqueue);
    let setup_cycle = device.ep0_cycle;
    let Some(setup_trb) = xhci_dma_bus_addr(
        descriptor,
        dma_range,
        device
            .ep0_ring_offset
            .saturating_add(setup_index.saturating_mul(XHCI_TRB_BYTES)),
    ) else {
        return XhciControlTransferOutcome::Failed { code: 0 };
    };
    let setup_transfer_type = if data_len == 0 {
        0
    } else if data_in {
        XHCI_TRB_TRANSFER_TYPE_IN
    } else {
        XHCI_TRB_TRANSFER_TYPE_OUT
    };
    write_xhci_trb(
        base,
        setup_index,
        XhciTrb {
            parameter: setup_value,
            status: 8,
            control: xhci_control_setup_stage_control(setup_transfer_type, !setup_cycle),
        },
    );
    xhci_advance_transfer_ring(
        base,
        ep0_ring_bus,
        &mut device.ep0_enqueue,
        &mut device.ep0_cycle,
    );
    let data_trb = if data_len != 0 {
        let Some(data_trb) = xhci_dma_bus_addr(
            descriptor,
            dma_range,
            device
                .ep0_ring_offset
                .saturating_add(usize::from(device.ep0_enqueue).saturating_mul(XHCI_TRB_BYTES)),
        ) else {
            return XhciControlTransferOutcome::Failed { code: 0 };
        };
        data_trb
    } else {
        0
    };
    if data_len != 0 {
        write_xhci_trb(
            base,
            usize::from(device.ep0_enqueue),
            XhciTrb {
                parameter: data_bus,
                status: data_len as u32,
                control: xhci_control_data_stage_control(data_in, data_stage_ioc, device.ep0_cycle),
            },
        );
        xhci_advance_transfer_ring(
            base,
            ep0_ring_bus,
            &mut device.ep0_enqueue,
            &mut device.ep0_cycle,
        );
    }
    let status_index = usize::from(device.ep0_enqueue);
    let Some(status_trb) = xhci_dma_bus_addr(
        descriptor,
        dma_range,
        device
            .ep0_ring_offset
            .saturating_add(status_index.saturating_mul(XHCI_TRB_BYTES)),
    ) else {
        return XhciControlTransferOutcome::Failed { code: 0 };
    };
    write_xhci_trb(
        base,
        status_index,
        XhciTrb {
            parameter: 0,
            status: 0,
            control: (XHCI_TRB_TYPE_STATUS_STAGE << 10)
                | (if data_in { 0 } else { XHCI_TRB_DIR_IN })
                | XHCI_TRB_IOC
                | xhci_cycle_bit(device.ep0_cycle),
        },
    );
    xhci_advance_transfer_ring(
        base,
        ep0_ring_bus,
        &mut device.ep0_enqueue,
        &mut device.ep0_cycle,
    );
    write_xhci_trb(
        base,
        setup_index,
        XhciTrb {
            parameter: setup_value,
            status: 8,
            control: xhci_control_setup_stage_control(setup_transfer_type, setup_cycle),
        },
    );
    if data_len != 0 {
        dma_clean_range(data_vaddr, data_len);
    }
    publish_xhci_transfer_ring(base);
    dma_store_barrier();
    if !xhci_ring_doorbell(state, device.slot, 1) {
        xhci_publish_control_progress(progress, progress.map_or(0, |progress| progress.failed));
        return XhciControlTransferOutcome::Failed { code: 0 };
    }
    xhci_publish_control_progress(
        progress,
        progress.map_or(0, |progress| progress.doorbell_done),
    );
    let outcome = xhci_wait_control_transfer_completion_outcome(
        state,
        descriptor,
        device.slot,
        1,
        XhciControlTransferPlan {
            setup_trb,
            data_trb,
            status_trb,
            data_len,
            data_stage_event_expected: data_stage_ioc,
        },
        progress,
        completion_spins,
    );
    if matches!(outcome, XhciControlTransferOutcome::Complete(_)) && data_in {
        dma_invalidate_range(data_vaddr, data_len);
    }
    outcome
}

fn usb_get_descriptor_with_progress(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    desc_type: u8,
    index: u8,
    offset: usize,
    len: usize,
    begin_phase: u32,
    progress: XhciControlProgress,
) -> Option<usize> {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return None;
    };
    publish_runtime_progress(sequence, begin_phase, aux0);
    zero_dma_range(dma_range.vaddr as usize + offset, len);
    let setup = [
        0x80,
        XHCI_SETUP_GET_DESCRIPTOR,
        index,
        desc_type,
        0,
        0,
        (len & 0xff) as u8,
        (len >> 8) as u8,
    ];
    xhci_control_transfer_with_progress(
        state,
        descriptor,
        device,
        setup,
        offset,
        len,
        true,
        Some(progress),
    )
}

fn usb_get_device_descriptor_with_progress(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    offset: usize,
    len: usize,
    begin_phase: u32,
    progress: XhciControlProgress,
) -> Option<usize> {
    usb_get_descriptor_with_progress(
        sequence,
        aux0,
        state,
        descriptor,
        device,
        USB_DESCRIPTOR_DEVICE,
        0,
        offset,
        len,
        begin_phase,
        progress,
    )
}

fn usb_get_config_descriptor_with_progress(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    offset: usize,
    len: usize,
    begin_phase: u32,
    progress: XhciControlProgress,
) -> Option<usize> {
    usb_get_descriptor_with_progress(
        sequence,
        aux0,
        state,
        descriptor,
        device,
        USB_DESCRIPTOR_CONFIGURATION,
        0,
        offset,
        len,
        begin_phase,
        progress,
    )
}

fn usb_prime_full_speed_device_descriptor(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
) -> bool {
    if device.speed != XHCI_SPEED_FULL {
        return true;
    }
    let transferred = usb_get_device_descriptor_with_progress(
        sequence,
        aux0,
        state,
        descriptor,
        device,
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        USB_FULL_SPEED_DESCRIPTOR_PRIME_LEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_BEGIN,
        XhciControlProgress {
            sequence,
            aux0,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_DATA_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_FAILED,
            transfer_timeout:
                DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_TRANSFER_TIMEOUT,
            status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_PRIME_STATUS_TIMEOUT,
        },
    );
    match transferred {
        Some(len) if len >= USB_FULL_SPEED_DESCRIPTOR_PRIME_EXPECT_MIN => {}
        _ => return false,
    }
    usb_spin_wait(USB_FULL_SPEED_DESCRIPTOR_SETTLE_SPINS);
    true
}

fn usb_read_device_descriptor(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
) -> Option<usize> {
    let _ = usb_prime_full_speed_device_descriptor(sequence, aux0, state, descriptor, device);
    let mut attempts = 0usize;
    while attempts < USB_DEVICE_DESCRIPTOR_RETRY_ATTEMPTS {
        if let Some(transferred) = usb_get_device_descriptor_with_progress(
            sequence,
            aux0,
            state,
            descriptor,
            device,
            XHCI_DMA_CONTROL_BUFFER_OFFSET,
            USB_DEVICE_DESCRIPTOR_BYTES,
            DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_BEGIN,
            XhciControlProgress {
                sequence,
                aux0,
                doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_DOORBELL_DONE,
                wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_WAIT_BEGIN,
                data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_DATA_EVENT,
                status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_EVENT,
                failed: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_FAILED,
                transfer_timeout:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_TRANSFER_TIMEOUT,
                status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_DESCRIPTOR_STATUS_TIMEOUT,
            },
        ) {
            usb_record_device_identity_from_descriptor(descriptor, device, transferred);
            return Some(transferred);
        }
        xhci_drain_events_preserving_port_changes(state, descriptor);
        usb_spin_wait(USB_FULL_SPEED_DESCRIPTOR_SETTLE_SPINS);
        attempts = attempts.saturating_add(1);
    }
    None
}

fn usb_record_device_identity_from_descriptor(
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    transferred: usize,
) {
    if transferred < 12 {
        return;
    }
    let Some(range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return;
    };
    let base = range.vaddr as usize + XHCI_DMA_CONTROL_BUFFER_OFFSET;
    if read_dma_byte(base) < USB_DEVICE_DESCRIPTOR_BYTES as u8
        || read_dma_byte(base + 1) != USB_DESCRIPTOR_TYPE_DEVICE
    {
        return;
    }
    device.vendor_id =
        u16::from(read_dma_byte(base + 8)) | (u16::from(read_dma_byte(base + 9)) << 8);
    device.product_id =
        u16::from(read_dma_byte(base + 10)) | (u16::from(read_dma_byte(base + 11)) << 8);
}

fn usb_set_configuration(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    configuration: u8,
) -> bool {
    let setup = [
        0x00,
        XHCI_SETUP_SET_CONFIGURATION,
        configuration,
        0,
        0,
        0,
        0,
        0,
    ];
    xhci_control_transfer(
        state,
        descriptor,
        device,
        setup,
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        0,
        false,
    )
    .is_some()
}

fn usb_set_configuration_with_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    configuration: u8,
    progress: XhciControlProgress,
) -> bool {
    let setup = [
        0x00,
        XHCI_SETUP_SET_CONFIGURATION,
        configuration,
        0,
        0,
        0,
        0,
        0,
    ];
    xhci_control_transfer_with_progress(
        state,
        descriptor,
        device,
        setup,
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        0,
        false,
        Some(progress),
    )
    .is_some()
}

fn usb_set_hid_boot_protocol(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
) -> bool {
    let setup = [
        0x21,
        XHCI_SETUP_SET_PROTOCOL,
        0,
        0,
        state.keyboard_interface,
        0,
        0,
        0,
    ];
    xhci_control_transfer(
        state,
        descriptor,
        device,
        setup,
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        0,
        false,
    )
    .is_some()
}

fn usb_set_idle(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
) -> bool {
    let setup = usb_hid_set_idle_setup(state.keyboard_interface);
    xhci_control_transfer(
        state,
        descriptor,
        device,
        setup,
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        0,
        false,
    )
    .is_some()
}

const fn usb_hid_set_idle_setup(interface: u8) -> [u8; 8] {
    [
        0x21,
        XHCI_SETUP_SET_IDLE,
        0,
        USB_HID_BOOT_IDLE_DURATION,
        interface,
        0,
        0,
        0,
    ]
}

const fn usb_hid_get_input_report_setup(interface: u8, len: usize) -> [u8; 8] {
    [
        0xa1,
        XHCI_SETUP_GET_REPORT,
        0,
        1,
        interface,
        0,
        (len & 0xff) as u8,
        ((len >> 8) & 0xff) as u8,
    ]
}

fn usb_keyboard_control_device(state: &UsbRuntimeState) -> Option<UsbEnumerationDevice> {
    if state.keyboard_slot == 0 || state.keyboard_ep0_ring_offset == 0 {
        return None;
    }
    Some(UsbEnumerationDevice {
        slot: state.keyboard_slot,
        root_port: state.keyboard_port,
        vendor_id: 0,
        product_id: 0,
        route: 0,
        speed: 0,
        depth: 0,
        parent_hub_slot: 0,
        parent_hub_port: 0,
        parent_tt_port: 0,
        parent_tt_think_time: 0,
        device_context_offset: 0,
        ep0_ring_offset: state.keyboard_ep0_ring_offset,
        ep0_enqueue: state.ep0_enqueue,
        ep0_cycle: state.ep0_cycle,
    })
}

fn usb_poll_keyboard_control_report(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    sequence: u32,
    aux0: u32,
) -> usize {
    if state.keyboard_control_poll_disabled {
        return 0;
    }
    if state.keyboard_control_poll_cooldown != 0 {
        state.keyboard_control_poll_cooldown =
            state.keyboard_control_poll_cooldown.saturating_sub(1);
        return 0;
    }
    let Some(mut device) = usb_keyboard_control_device(state) else {
        state.keyboard_control_poll_disabled = true;
        return 0;
    };
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return 0;
    };
    let report_len = usb_keyboard_report_request_len(state);
    if report_len < USB_FLEXIBLE_KEYBOARD_REPORT_MIN_BYTES
        || report_len > USB_KEYBOARD_REPORT_BUFFER_BYTES
    {
        state.keyboard_control_poll_disabled = true;
        return 0;
    }
    let data_vaddr = dma_range.vaddr as usize + XHCI_DMA_CONTROL_BUFFER_OFFSET;
    zero_dma_range(data_vaddr, report_len);
    let transferred = xhci_control_transfer(
        state,
        descriptor,
        &mut device,
        usb_hid_get_input_report_setup(state.keyboard_interface, report_len),
        XHCI_DMA_CONTROL_BUFFER_OFFSET,
        report_len,
        true,
    );
    state.ep0_enqueue = device.ep0_enqueue;
    state.ep0_cycle = device.ep0_cycle;
    state.keyboard_control_poll_cooldown = USB_HID_CONTROL_GET_REPORT_COOLDOWN_POLLS;
    let Some(payload_len) = transferred else {
        return 0;
    };
    if payload_len < USB_FLEXIBLE_KEYBOARD_REPORT_MIN_BYTES {
        return 0;
    }
    let bounded_len = payload_len.min(report_len);
    let mut payload = [0u8; USB_KEYBOARD_REPORT_BUFFER_BYTES];
    for (index, byte) in payload.iter_mut().take(bounded_len).enumerate() {
        *byte = read_dma_byte(data_vaddr + index);
    }
    let bytes = usb_keyboard_report_payload_to_frame_at_inner(
        state,
        &payload[..bounded_len],
        0,
        Some((sequence, aux0)),
    );
    let _ = usb_keyboard_note_valid_report_status(state);
    bytes
}

fn usb_set_hid_leds(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    leds: u8,
) -> bool {
    let Some(mut device) = usb_keyboard_control_device(state) else {
        return false;
    };
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return false;
    };
    write_dma_byte(
        dma_range.vaddr as usize + XHCI_DMA_HID_OUTPUT_BUFFER_OFFSET,
        leds,
    );
    let setup = [
        0x21,
        XHCI_SETUP_SET_REPORT,
        0,
        2,
        state.keyboard_interface,
        0,
        1,
        0,
    ];
    let ok = xhci_control_transfer(
        state,
        descriptor,
        &mut device,
        setup,
        XHCI_DMA_HID_OUTPUT_BUFFER_OFFSET,
        1,
        false,
    )
    .is_some();
    state.ep0_enqueue = device.ep0_enqueue;
    state.ep0_cycle = device.ep0_cycle;
    ok
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum UsbKeyboardEndpointParse {
    Found,
    NoKeyboardInterface,
    NoInterruptInEndpoint,
    Malformed,
}

impl UsbKeyboardEndpointParse {
    const fn missing_phase(self) -> u32 {
        match self {
            Self::Found => DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_FOUND,
            Self::NoKeyboardInterface => {
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_NO_INTERFACE
            }
            Self::NoInterruptInEndpoint => {
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_NO_INTERRUPT_IN
            }
            Self::Malformed => DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_MALFORMED,
        }
    }
}

fn usb_parse_keyboard_endpoint_with_reader<F>(
    state: &mut UsbRuntimeState,
    len: usize,
    mut read: F,
) -> UsbKeyboardEndpointParse
where
    F: FnMut(usize) -> u8,
{
    if len < 9 {
        return UsbKeyboardEndpointParse::Malformed;
    }
    let configuration_value = read(5);
    let mut offset = 0usize;
    let mut current_keyboard_iface = None;
    let mut best_rank = USB_KEYBOARD_ATTACH_RANK_NONE;
    let mut found = false;
    let mut keyboard_interface_seen = false;
    while offset + 2 <= len {
        let desc_len = read(offset) as usize;
        let desc_type = read(offset + 1);
        if desc_len < 2 || offset + desc_len > len {
            return UsbKeyboardEndpointParse::Malformed;
        }
        if desc_type == USB_DESCRIPTOR_INTERFACE && desc_len >= 9 {
            let interface = read(offset + 2);
            let class = read(offset + 5);
            let subclass = read(offset + 6);
            let protocol = read(offset + 7);
            let rank = usb_hid_keyboard_attach_rank(class, subclass, protocol);
            if rank != USB_KEYBOARD_ATTACH_RANK_NONE {
                keyboard_interface_seen = true;
            }
            current_keyboard_iface =
                (rank != USB_KEYBOARD_ATTACH_RANK_NONE).then_some((interface, rank));
        } else if desc_type == USB_DESCRIPTOR_ENDPOINT && desc_len >= 7 {
            if let Some((interface, rank)) = current_keyboard_iface {
                let address = read(offset + 2);
                let attrs = read(offset + 3);
                if address & USB_ENDPOINT_DIR_IN != 0
                    && (attrs & 0x3) == USB_ENDPOINT_ATTR_INTERRUPT
                    && rank <= best_rank
                {
                    let endpoint_num = address & 0x0f;
                    let max_packet =
                        u16::from(read(offset + 4)) | (u16::from(read(offset + 5)) << 8);
                    best_rank = rank;
                    found = true;
                    state.keyboard_endpoint_address = address;
                    state.keyboard_endpoint_id = endpoint_num.saturating_mul(2).saturating_add(1);
                    state.keyboard_interface = interface;
                    state.keyboard_attach_rank = rank;
                    state.keyboard_ep_interval = read(offset + 6);
                    state.keyboard_ep_max_packet = max_packet.max(XHCI_BOOT_REPORT_BYTES as u16);
                    if rank == USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT {
                        break;
                    }
                }
            }
        }
        offset += desc_len;
    }
    if found {
        if configuration_value != 0 {
            UsbKeyboardEndpointParse::Found
        } else {
            UsbKeyboardEndpointParse::Malformed
        }
    } else if keyboard_interface_seen {
        UsbKeyboardEndpointParse::NoInterruptInEndpoint
    } else {
        UsbKeyboardEndpointParse::NoKeyboardInterface
    }
}

fn usb_parse_keyboard_endpoint(
    state: &mut UsbRuntimeState,
    config_vaddr: usize,
    len: usize,
) -> UsbKeyboardEndpointParse {
    usb_parse_keyboard_endpoint_with_reader(state, len, |offset| {
        read_dma_byte(config_vaddr + offset)
    })
}

const fn usb_hid_keyboard_attach_rank(class: u8, subclass: u8, protocol: u8) -> u8 {
    if class != USB_CLASS_HID {
        USB_KEYBOARD_ATTACH_RANK_NONE
    } else if subclass == USB_SUBCLASS_BOOT && protocol == USB_PROTOCOL_KEYBOARD {
        USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT
    } else if protocol == USB_PROTOCOL_KEYBOARD {
        USB_KEYBOARD_ATTACH_RANK_PROTOCOL_KEYBOARD
    } else if protocol == USB_PROTOCOL_NONE {
        USB_KEYBOARD_ATTACH_RANK_PROTOCOL_NONE
    } else {
        USB_KEYBOARD_ATTACH_RANK_NONE
    }
}

const fn usb_hid_boot_control_required(rank: u8) -> bool {
    rank == USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT
}

fn xhci_configure_keyboard_endpoint(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    device: &UsbEnumerationDevice,
) -> bool {
    if !xhci_prepare_contexts(
        state,
        descriptor,
        dma_range,
        device,
        state.keyboard_endpoint_id,
        0,
        false,
        xhci_default_control_packet(device.speed),
    ) {
        return false;
    }
    let Some(input_ctx) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_INPUT_CONTEXT_OFFSET)
    else {
        return false;
    };
    xhci_enqueue_command(
        state,
        descriptor,
        XhciTrb {
            parameter: input_ctx,
            status: 0,
            control: (XHCI_TRB_TYPE_CONFIGURE_ENDPOINT << 10)
                | (u32::from(state.keyboard_slot) << 24),
        },
    )
    .is_some()
}

fn usb_spin_wait(spins: usize) {
    runtime_spin(spins);
}

fn usb_read_configuration(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> Option<(usize, u8)> {
    for attempt in 0..USB_CONFIGURATION_DESCRIPTOR_RETRY_ATTEMPTS {
        if attempt != 0 {
            usb_spin_wait(USB_ROOT_PORT_RESET_SHORT_RETRY_SPINS);
        }
        if !usb_read_configuration_header(sequence, aux0, state, descriptor, device, dma_range) {
            xhci_drain_events_preserving_port_changes(state, descriptor);
            continue;
        }
        let config_vaddr = dma_range.vaddr as usize + XHCI_DMA_CONFIG_BUFFER_OFFSET;
        let total_len = usize::from(read_dma_byte(config_vaddr + 2))
            | (usize::from(read_dma_byte(config_vaddr + 3)) << 8);
        let config_len = total_len
            .min(USB_CONFIG_BUFFER_BYTES)
            .max(USB_CONFIGURATION_DESCRIPTOR_HEADER_BYTES);
        let Some(transferred) = usb_get_config_descriptor_with_progress(
            sequence,
            aux0,
            state,
            descriptor,
            device,
            XHCI_DMA_CONFIG_BUFFER_OFFSET,
            config_len,
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_BEGIN,
            XhciControlProgress {
                sequence,
                aux0,
                doorbell_done:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_DOORBELL_DONE,
                wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_WAIT_BEGIN,
                data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_DATA_EVENT,
                status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_EVENT,
                failed: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_FAILED,
                transfer_timeout:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_TRANSFER_TIMEOUT,
                status_timeout:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_FULL_STATUS_TIMEOUT,
            },
        ) else {
            xhci_drain_events_preserving_port_changes(state, descriptor);
            continue;
        };
        if transferred < config_len {
            xhci_drain_events_preserving_port_changes(state, descriptor);
            continue;
        }
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR;
        return Some((config_len, read_dma_byte(config_vaddr + 5)));
    }
    None
}

fn usb_read_configuration_header(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    let Some(transferred) = usb_get_config_descriptor_with_progress(
        sequence,
        aux0,
        state,
        descriptor,
        device,
        XHCI_DMA_CONFIG_BUFFER_OFFSET,
        USB_CONFIGURATION_DESCRIPTOR_HEADER_BYTES,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_BEGIN,
        XhciControlProgress {
            sequence,
            aux0,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_DATA_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_FAILED,
            transfer_timeout:
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_TIMEOUT,
            status_timeout:
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_TIMEOUT,
        },
    ) else {
        return false;
    };
    if transferred < USB_CONFIGURATION_DESCRIPTOR_HEADER_BYTES {
        return false;
    }
    let config_vaddr = dma_range.vaddr as usize + XHCI_DMA_CONFIG_BUFFER_OFFSET;
    let desc_len = read_dma_byte(config_vaddr);
    let desc_type = read_dma_byte(config_vaddr + 1);
    let total_len = usize::from(read_dma_byte(config_vaddr + 2))
        | (usize::from(read_dma_byte(config_vaddr + 3)) << 8);
    desc_len >= 9 && desc_type == USB_DESCRIPTOR_CONFIGURATION && total_len >= 9
}

fn usb_parse_hub_info(config_vaddr: usize, len: usize) -> Option<UsbHubInfo> {
    let mut offset = 0usize;
    while offset + 2 <= len {
        let desc_len = read_dma_byte(config_vaddr + offset) as usize;
        let desc_type = read_dma_byte(config_vaddr + offset + 1);
        if desc_len < 2 || offset + desc_len > len {
            break;
        }
        if desc_type == USB_DESCRIPTOR_INTERFACE && desc_len >= 9 {
            let interface = read_dma_byte(config_vaddr + offset + 2);
            let class = read_dma_byte(config_vaddr + offset + 5);
            let protocol = read_dma_byte(config_vaddr + offset + 7);
            if class == USB_CLASS_HUB {
                return Some(UsbHubInfo {
                    interface,
                    protocol,
                    ports: 0,
                    multi_tt: protocol == USB_HUB_PROTOCOL_HIGH_SPEED_MULTI_TT,
                    power_mode: 0,
                    pwr_on_2_pwr_good: 0,
                    tt_think_time: 0,
                });
            }
        }
        offset += desc_len;
    }
    None
}

const fn usb_normalize_hub_tt_profile(
    downstream_port: u8,
    hub_multi_tt: bool,
    hub_tt_think_time: u8,
) -> (u8, u8) {
    let tt_port = if hub_multi_tt {
        if downstream_port == 0 {
            1
        } else {
            downstream_port
        }
    } else {
        1
    };
    let tt_ttt_raw = hub_tt_think_time & 0x03;
    let tt_ttt = if tt_ttt_raw > 2 { 2 } else { tt_ttt_raw };
    (tt_port, tt_ttt)
}

fn usb_hub_class_transfer(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    len: usize,
    data_in: bool,
) -> bool {
    usb_hub_class_transfer_with_progress(
        state,
        descriptor,
        device,
        setup,
        len,
        data_in,
        None,
        USB_CONTROL_TRANSFER_SPINS,
    )
}

fn usb_hub_class_transfer_with_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> bool {
    matches!(
        usb_hub_class_transfer_with_progress_outcome(
            state,
            descriptor,
            device,
            setup,
            len,
            data_in,
            progress,
            completion_spins,
        ),
        XhciControlTransferOutcome::Complete(_)
    )
}

fn usb_hub_class_transfer_with_progress_outcome(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    setup: [u8; 8],
    len: usize,
    data_in: bool,
    progress: Option<XhciControlProgress>,
    completion_spins: usize,
) -> XhciControlTransferOutcome {
    xhci_control_transfer_with_progress_and_spins_outcome(
        state,
        descriptor,
        device,
        setup,
        XHCI_DMA_HUB_BUFFER_OFFSET,
        len,
        data_in,
        progress,
        completion_spins,
    )
}

const fn usb_device_is_apple_keyboard_hub(device: &UsbEnumerationDevice) -> bool {
    device.vendor_id == USB_VENDOR_ID_APPLE && device.product_id == USB_DEVICE_ID_APPLE_KEYBOARD_HUB
}

const fn usb_device_keyboard_first_report_optional(device: &UsbEnumerationDevice) -> bool {
    device.vendor_id == USB_VENDOR_ID_APPLE || device.vendor_id == USB_VENDOR_ID_KEYCHRON
}

const fn usb_hub_control_should_try_fallback(
    device: &UsbEnumerationDevice,
    outcome: XhciControlTransferOutcome,
) -> bool {
    matches!(
        outcome,
        XhciControlTransferOutcome::Failed {
            code: XHCI_COMPLETION_STALL_ERROR
        }
    ) && usb_device_is_apple_keyboard_hub(device)
}

const fn usb_hub_port_status_progress(sequence: u32, aux0: u32) -> XhciControlProgress {
    XhciControlProgress {
        sequence,
        aux0,
        doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_DOORBELL_DONE,
        wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_WAIT_BEGIN,
        data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_DATA_EVENT,
        status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT,
        failed: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_FAILED,
        transfer_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_TIMEOUT,
        status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_TIMEOUT,
    }
}

const fn usb_hub_port_index_candidates(
    interface: u8,
    port: u8,
) -> ([u16; USB_HUB_PORT_INDEX_CANDIDATES_MAX], usize) {
    let mut candidates = [0u16; USB_HUB_PORT_INDEX_CANDIDATES_MAX];
    let mut count = 0usize;
    candidates[count] = port as u16;
    count += 1;
    if interface != 0 && count < USB_HUB_PORT_INDEX_CANDIDATES_MAX {
        candidates[count] = ((interface as u16) << 8) | port as u16;
        count += 1;
    }
    let mut alt_interface = 1u8;
    while alt_interface <= 3 && count < USB_HUB_PORT_INDEX_CANDIDATES_MAX {
        let candidate = ((alt_interface as u16) << 8) | port as u16;
        let mut seen = false;
        let mut index = 0usize;
        while index < count {
            if candidates[index] == candidate {
                seen = true;
            }
            index += 1;
        }
        if !seen {
            candidates[count] = candidate;
            count += 1;
        }
        alt_interface += 1;
    }
    (candidates, count)
}

fn usb_hub_set_feature(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    feature: u16,
) -> bool {
    let (candidates, count) = usb_hub_port_index_candidates(interface, port);
    let mut attempt = 0usize;
    while attempt < count {
        let index = candidates[attempt];
        let setup = [
            0x23,
            XHCI_SETUP_SET_FEATURE,
            (feature & 0xff) as u8,
            (feature >> 8) as u8,
            (index & 0xff) as u8,
            (index >> 8) as u8,
            0,
            0,
        ];
        let outcome = usb_hub_class_transfer_with_progress_outcome(
            state,
            descriptor,
            device,
            setup,
            0,
            false,
            None,
            USB_CONTROL_TRANSFER_SPINS,
        );
        match outcome {
            XhciControlTransferOutcome::Complete(_) => return true,
            _ if usb_hub_control_should_try_fallback(device, outcome) => {}
            _ => return false,
        }
        attempt += 1;
    }
    false
}

fn usb_hub_clear_feature(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    feature: u16,
) -> bool {
    let (candidates, count) = usb_hub_port_index_candidates(interface, port);
    let mut attempt = 0usize;
    while attempt < count {
        let index = candidates[attempt];
        let setup = [
            0x23,
            XHCI_SETUP_CLEAR_FEATURE,
            (feature & 0xff) as u8,
            (feature >> 8) as u8,
            (index & 0xff) as u8,
            (index >> 8) as u8,
            0,
            0,
        ];
        let outcome = usb_hub_class_transfer_with_progress_outcome(
            state,
            descriptor,
            device,
            setup,
            0,
            false,
            None,
            USB_CONTROL_TRANSFER_SPINS,
        );
        match outcome {
            XhciControlTransferOutcome::Complete(_) => return true,
            _ if usb_hub_control_should_try_fallback(device, outcome) => {}
            _ => return false,
        }
        attempt += 1;
    }
    false
}

fn usb_hub_get_port_status_with_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    progress: Option<XhciControlProgress>,
) -> Option<UsbHubPortStatus> {
    let (candidates, count) = usb_hub_port_index_candidates(interface, port);
    let mut attempt = 0usize;
    while attempt < count {
        let index = candidates[attempt];
        let setup = [
            0xa3,
            XHCI_SETUP_GET_STATUS,
            0,
            0,
            (index & 0xff) as u8,
            (index >> 8) as u8,
            4,
            0,
        ];
        let outcome = xhci_control_transfer_with_progress_and_spins_outcome_with_data_ioc(
            state,
            descriptor,
            device,
            setup,
            XHCI_DMA_HUB_BUFFER_OFFSET,
            4,
            true,
            progress,
            USB_HUB_PORT_STATUS_CONTROL_TRANSFER_SPINS,
            false,
        );
        match outcome {
            XhciControlTransferOutcome::Complete(_) => {
                let base = match runtime_resource_range(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                ) {
                    Some(range) => range.vaddr as usize + XHCI_DMA_HUB_BUFFER_OFFSET,
                    None => return None,
                };
                let status =
                    u16::from(read_dma_byte(base)) | (u16::from(read_dma_byte(base + 1)) << 8);
                let change =
                    u16::from(read_dma_byte(base + 2)) | (u16::from(read_dma_byte(base + 3)) << 8);
                xhci_publish_hub_port_status_tail_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_PAYLOAD_READ,
                );
                return Some(UsbHubPortStatus {
                    status,
                    change,
                    w_index: index,
                });
            }
            _ if usb_hub_control_should_try_fallback(device, outcome) => {}
            _ => return None,
        }
        attempt += 1;
    }
    None
}

fn usb_hub_clear_port_change_mask(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    change_mask: u16,
) -> bool {
    let mut cleared = true;
    if change_mask & USB_HUB_CHANGE_CONNECTION != 0 {
        cleared &= usb_hub_clear_feature(
            state,
            descriptor,
            device,
            interface,
            port,
            USB_HUB_FEATURE_C_PORT_CONNECTION,
        );
    }
    if change_mask & USB_HUB_CHANGE_ENABLE != 0 {
        cleared &= usb_hub_clear_feature(
            state,
            descriptor,
            device,
            interface,
            port,
            USB_HUB_FEATURE_C_PORT_ENABLE,
        );
    }
    if change_mask & USB_HUB_CHANGE_RESET != 0 {
        cleared &= usb_hub_clear_feature(
            state,
            descriptor,
            device,
            interface,
            port,
            USB_HUB_FEATURE_C_PORT_RESET,
        );
    }
    cleared
}

fn usb_hub_clear_port_change_mask_with_progress(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    change_mask: u16,
) -> bool {
    if change_mask == 0 {
        return true;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_CLEAR_CHANGES_BEGIN,
        aux0,
    );
    let cleared =
        usb_hub_clear_port_change_mask(state, descriptor, device, interface, port, change_mask);
    publish_runtime_progress(
        sequence,
        if cleared {
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_CLEAR_CHANGES_DONE
        } else {
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_CLEAR_CHANGES_FAILED
        },
        aux0,
    );
    cleared
}

fn usb_hub_speed_from_status(status: u16) -> u32 {
    if status & USB_HUB_STATUS_LOW_SPEED != 0 {
        XHCI_SPEED_LOW
    } else if status & USB_HUB_STATUS_HIGH_SPEED != 0 {
        XHCI_SPEED_HIGH
    } else {
        XHCI_SPEED_FULL
    }
}

fn usb_hub_power_settle_spins(pwr_on_2_pwr_good: u8) -> usize {
    USB_HUB_PORT_POWER_SETTLE_SPINS
        .max(usize::from(pwr_on_2_pwr_good).saturating_mul(USB_HUB_PORT_POWER_GOOD_UNIT_SPINS))
}

const fn usb_hub_supports_port_power(power_mode: u8) -> bool {
    match power_mode {
        USB_HUB_POWER_MODE_GANGED | USB_HUB_POWER_MODE_INDIVIDUAL => true,
        USB_HUB_POWER_MODE_NONE => false,
        _ => false,
    }
}

const fn usb_hub_recovery_port_power_enabled(power_mode: u8) -> bool {
    usb_hub_supports_port_power(power_mode)
}

const fn usb_hub_should_defer_port_power(hub: &UsbEnumerationDevice, power_mode: u8) -> bool {
    if !usb_hub_supports_port_power(power_mode) {
        return false;
    }
    power_mode == USB_HUB_POWER_MODE_INDIVIDUAL || usb_device_is_apple_keyboard_hub(hub)
}

const fn usb_hub_eager_port_power_enabled(hub: &UsbEnumerationDevice, power_mode: u8) -> bool {
    usb_hub_supports_port_power(power_mode) && !usb_hub_should_defer_port_power(hub, power_mode)
}

fn usb_hub_port_connected(status: UsbHubPortStatus) -> bool {
    status.status & USB_HUB_STATUS_CONNECTION != 0
}

fn usb_hub_port_ready_after_reset(status: UsbHubPortStatus) -> bool {
    status.status & USB_HUB_STATUS_ENABLE != 0 && status.status & USB_HUB_STATUS_RESET == 0
}

const fn usb_hub_pre_reset_change_clear_mask(change: u16) -> u16 {
    change & USB_HUB_CHANGE_CONNECTION
}

const fn usb_hub_ready_reset_change_clear_mask(status: u16, change: u16) -> u16 {
    if status & USB_HUB_STATUS_ENABLE != 0 && status & USB_HUB_STATUS_RESET == 0 {
        change & USB_HUB_CHANGE_RESET
    } else {
        0
    }
}

const fn usb_hub_delay_ms_from_spins(spins: usize) -> u8 {
    let ms = spins / USB_MSEC_SPINS;
    if ms > u8::MAX as usize {
        u8::MAX
    } else {
        ms as u8
    }
}

fn usb_hub_power_settle_ms(pwr_on_2_pwr_good: u8) -> u8 {
    usb_hub_delay_ms_from_spins(usb_hub_power_settle_spins(pwr_on_2_pwr_good))
}

const fn usb_hub_reset_settle_ms(attempt: usize) -> u8 {
    usb_hub_delay_ms_from_spins(usb_hub_reset_settle_spins(attempt))
}

const fn usb_hub_change_clear_flags(clear_mask: u16) -> u16 {
    (if clear_mask & USB_HUB_CHANGE_CONNECTION != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_CLEAR_CONNECTION
    } else {
        0
    }) | (if clear_mask & USB_HUB_CHANGE_ENABLE != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_CLEAR_ENABLE
    } else {
        0
    }) | (if clear_mask & USB_HUB_CHANGE_RESET != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_CLEAR_RESET
    } else {
        0
    })
}

fn usb_hub_status_sample_flags(
    status: UsbHubPortStatus,
    clear_mask: u16,
    recovery: bool,
    skip_reset: bool,
) -> u16 {
    (if status.status & USB_HUB_STATUS_CONNECTION != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_CONNECTED
    } else {
        0
    }) | (if status.status & USB_HUB_STATUS_ENABLE != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_ENABLED
    } else {
        0
    }) | (if status.status & USB_HUB_STATUS_RESET != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_RESET
    } else {
        0
    }) | (if status.status & USB_HUB_STATUS_LOW_SPEED != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_LOW_SPEED
    } else {
        0
    }) | (if status.status & USB_HUB_STATUS_HIGH_SPEED != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_HIGH_SPEED
    } else {
        0
    }) | (if status.change & USB_HUB_CHANGE_CONNECTION != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_C_CONNECTION
    } else {
        0
    }) | (if status.change & USB_HUB_CHANGE_ENABLE != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_C_ENABLE
    } else {
        0
    }) | (if status.change & USB_HUB_CHANGE_RESET != 0 {
        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_C_RESET
    } else {
        0
    }) | usb_hub_change_clear_flags(clear_mask)
        | (if recovery {
            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_RECOVERY
        } else {
            0
        })
        | (if skip_reset {
            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_SKIP_RESET
        } else {
            0
        })
        | (if usb_hub_port_ready_after_reset(status) {
            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_READY
        } else {
            0
        })
}

fn usb_record_hub_port_status_sample(
    state: &mut UsbRuntimeState,
    hub: &UsbEnumerationDevice,
    port: u8,
    status: UsbHubPortStatus,
    clear_mask: u16,
    stage: u8,
    settle_ms: u8,
    recovery: bool,
    skip_reset: bool,
) {
    state.hub_port_status_sample = UsbHubPortStatusSample {
        valid: true,
        stage,
        hub_slot: hub.slot,
        hub_port: port,
        depth: hub.depth,
        settle_ms,
        w_index: status.w_index,
        status: status.status,
        change: status.change,
        clear_mask,
        flags: usb_hub_status_sample_flags(status, clear_mask, recovery, skip_reset),
        route: hub.route,
    };
}

fn usb_write_u16_le(offset: usize, value: u16) {
    write_ring_byte(offset, (value & 0xff) as u8);
    write_ring_byte(offset + 1, (value >> 8) as u8);
}

fn usb_stage_hub_port_status_sample_frame(state: &UsbRuntimeState) -> DriverFrameDescriptor {
    let sample = state.hub_port_status_sample;
    if !sample.valid {
        return DriverFrameDescriptor::empty();
    }
    let offset = DRIVER_TASK_RING_FRAME_OFFSET;
    write_ring_u32(offset, DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FRAME_MAGIC);
    write_ring_byte(offset + 4, DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FRAME_VERSION);
    write_ring_byte(offset + 5, sample.stage);
    write_ring_byte(offset + 6, sample.hub_slot);
    write_ring_byte(offset + 7, sample.hub_port);
    usb_write_u16_le(offset + 8, sample.w_index);
    write_ring_byte(offset + 10, sample.depth);
    write_ring_byte(offset + 11, sample.settle_ms);
    usb_write_u16_le(offset + 12, sample.status);
    usb_write_u16_le(offset + 14, sample.change);
    usb_write_u16_le(offset + 16, sample.clear_mask);
    usb_write_u16_le(offset + 18, sample.flags);
    write_ring_u32(offset + 20, sample.route);
    DriverFrameDescriptor {
        offset: offset as u32,
        len: DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FRAME_LEN,
        flags: 0,
    }
}

fn usb_hub_port_not_ready_progress(status: UsbHubPortStatus) -> u32 {
    if status.status & USB_HUB_STATUS_RESET != 0 {
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_RESET_ACTIVE
    } else if usb_hub_port_connected(status) {
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_ENABLE_MISSING
    } else {
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_DISCONNECTED
    }
}

fn usb_hub_publish_port_not_ready(sequence: u32, aux0: u32, status: UsbHubPortStatus) {
    publish_runtime_progress(sequence, usb_hub_port_not_ready_progress(status), aux0);
}

fn usb_hub_last_sample_skipped_disconnected(state: &UsbRuntimeState) -> bool {
    let sample = state.hub_port_status_sample;
    sample.valid
        && sample.stage == DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_SKIP_DISCONNECTED
        && sample.flags & DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_CONNECTED == 0
        && sample.flags & DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_READY == 0
}

fn usb_hub_last_sample_requires_attach_recovery(state: &UsbRuntimeState) -> bool {
    let sample = state.hub_port_status_sample;
    sample.valid
        && sample.stage != DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_SKIP_DISCONNECTED
        && sample.flags & DRIVER_RUNTIME_USB_HUB_PORT_STATUS_FLAG_READY == 0
}

fn usb_finish_hub_scan_without_keyboard(sequence: u32, aux0: u32, state: &mut UsbRuntimeState) {
    if state.init_detail == DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
        && usb_hub_last_sample_skipped_disconnected(state)
        && !state.hub_child_address_failure_seen
    {
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_TOPOLOGY_SEEN;
    } else if state.init_detail == DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_TOPOLOGY_SEEN
        && usb_hub_last_sample_requires_attach_recovery(state)
    {
        usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_ATTACH_FAILED);
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SCAN_NO_KEYBOARD,
        aux0,
    );
}

const fn usb_hub_reset_settle_spins(attempt: usize) -> usize {
    if attempt == 0 {
        USB_HUB_PORT_RESET_SETTLE_SPINS
    } else {
        USB_HUB_PORT_RESET_RETRY_SETTLE_SPINS
    }
}

const fn usb_hub_port_reset_recovery_spins() -> usize {
    USB_HUB_PORT_RESET_RECOVERY_SPINS
}

fn usb_recover_disconnected_hub_port(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    hub: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
    power_mode: u8,
    pwr_on_2_pwr_good: u8,
) -> Option<UsbHubPortStatus> {
    if !usb_hub_recovery_port_power_enabled(power_mode) {
        return None;
    }
    let mut last = None;
    for _ in 0..USB_HUB_DISCONNECTED_POWER_KICKS {
        let _ = usb_hub_set_feature(
            state,
            descriptor,
            hub,
            interface,
            port,
            USB_HUB_FEATURE_PORT_POWER,
        );
        usb_spin_wait(usb_hub_power_settle_spins(pwr_on_2_pwr_good));
        if let Some(status) = usb_hub_get_port_status_with_progress(
            state,
            descriptor,
            hub,
            interface,
            port,
            Some(usb_hub_port_status_progress(sequence, aux0)),
        ) {
            let clear_mask = usb_hub_pre_reset_change_clear_mask(status.change);
            usb_record_hub_port_status_sample(
                state,
                hub,
                port,
                status,
                clear_mask,
                DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_RECOVERY_POWER,
                usb_hub_power_settle_ms(pwr_on_2_pwr_good),
                true,
                !usb_hub_port_connected(status),
            );
            let _ = usb_hub_clear_port_change_mask_with_progress(
                sequence, aux0, state, descriptor, hub, interface, port, clear_mask,
            );
            if usb_hub_port_connected(status) {
                return Some(status);
            }
            last = Some(status);
        }
    }
    if let Some(status) = last {
        usb_record_hub_port_status_sample(
            state,
            hub,
            port,
            status,
            usb_hub_pre_reset_change_clear_mask(status.change),
            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_SKIP_DISCONNECTED,
            usb_hub_power_settle_ms(pwr_on_2_pwr_good),
            true,
            true,
        );
        return None;
    }
    None
}

fn usb_hub_reset_port_with_progress(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    hub: &mut UsbEnumerationDevice,
    interface: u8,
    port: u8,
) -> bool {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_BEGIN,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_SET_BEGIN,
        aux0,
    );
    if usb_hub_set_feature(
        state,
        descriptor,
        hub,
        interface,
        port,
        USB_HUB_FEATURE_PORT_RESET,
    ) {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_SET_DONE,
            aux0,
        );
        true
    } else {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_SET_FAILED,
            aux0,
        );
        false
    }
}

fn usb_read_hub_descriptor(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    fallback: UsbHubInfo,
) -> Option<UsbHubInfo> {
    zero_dma_range(
        match runtime_resource_range(
            descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        ) {
            Some(range) => range.vaddr as usize + XHCI_DMA_HUB_BUFFER_OFFSET,
            None => return None,
        },
        USB_HUB_DESCRIPTOR_BYTES,
    );
    let descriptor_type = if fallback.protocol == USB_HUB_PROTOCOL_SUPER_SPEED {
        USB_DESCRIPTOR_SS_HUB
    } else {
        USB_DESCRIPTOR_HUB
    };
    let indices = [0u16, u16::from(fallback.interface)];
    let mut read_ok = false;
    for (attempt, index) in indices.iter().copied().enumerate() {
        if attempt != 0 && index == indices[0] {
            continue;
        }
        let setup = [
            0xa0,
            XHCI_SETUP_GET_DESCRIPTOR,
            0,
            descriptor_type,
            (index & 0xff) as u8,
            (index >> 8) as u8,
            USB_HUB_DESCRIPTOR_BYTES as u8,
            0,
        ];
        if usb_hub_class_transfer_with_progress(
            state,
            descriptor,
            device,
            setup,
            USB_HUB_DESCRIPTOR_BYTES,
            true,
            Some(XhciControlProgress {
                sequence,
                aux0,
                doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_DOORBELL_DONE,
                wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_WAIT_BEGIN,
                data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_DATA_EVENT,
                status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT,
                failed: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_FAILED,
                transfer_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_TIMEOUT,
                status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_TIMEOUT,
            }),
            USB_HUB_DESCRIPTOR_CONTROL_TRANSFER_SPINS,
        ) {
            read_ok = true;
            break;
        }
    }
    if !read_ok {
        return None;
    }
    let base = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?
    .vaddr as usize
        + XHCI_DMA_HUB_BUFFER_OFFSET;
    let ports = read_dma_byte(base + 2);
    let characteristics =
        u16::from(read_dma_byte(base + 3)) | (u16::from(read_dma_byte(base + 4)) << 8);
    (ports != 0).then_some(UsbHubInfo {
        ports,
        power_mode: (characteristics & USB_HUB_CHARACTERISTICS_POWER_MODE_MASK) as u8,
        pwr_on_2_pwr_good: read_dma_byte(base + 5),
        tt_think_time: ((characteristics >> USB_HUB_CHARACTERISTICS_TT_THINK_TIME_SHIFT) & 0x03)
            as u8,
        ..fallback
    })
}

fn usb_activate_hub_multi_tt(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
    interface: u8,
) -> bool {
    let setup = [
        0x01,
        XHCI_SETUP_SET_INTERFACE,
        USB_HUB_MULTI_TT_ALT_SETTING,
        0,
        interface,
        0,
        0,
        0,
    ];
    usb_hub_class_transfer(state, descriptor, device, setup, 0, false)
}

fn xhci_address_topology_device(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    mut device: UsbEnumerationDevice,
    next_device_index: &mut usize,
) -> Option<UsbEnumerationDevice> {
    if *next_device_index >= USB_ENUM_MAX_DEVICES {
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED;
        return None;
    }
    let device_index = *next_device_index;
    device.device_context_offset = xhci_device_context_offset(device_index);
    device.ep0_ring_offset = xhci_ep0_ring_offset(device_index);
    let (packet_candidates, packet_count) = xhci_control_packet_candidates(device.speed);
    let mut recycle_count = 0usize;
    while recycle_count <= USB_ADDRESS_DEVICE_SLOT_RECYCLES {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_ENABLE_SLOT_BEGIN,
            aux0,
        );
        let Some(slot) = xhci_enable_slot(sequence, aux0, state, descriptor) else {
            state.init_detail = if recycle_count == 0 {
                DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED
            } else {
                DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
            };
            return None;
        };
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ADDRESS_ENABLE_SLOT_DONE,
            aux0,
        );
        device.slot = slot;
        for packet in packet_candidates.iter().copied().take(packet_count) {
            if xhci_address_device(
                sequence, aux0, state, descriptor, dma_range, &device, packet,
            ) {
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_ADDRESSED;
                publish_runtime_progress(
                    sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_ADDRESSED,
                    aux0,
                );
                usb_spin_wait(USB_ADDRESS_DEVICE_SETTLE_SPINS);
                *next_device_index = (*next_device_index).saturating_add(1);
                return Some(device);
            }
            state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED;
            xhci_drain_events_preserving_port_changes(state, descriptor);
        }
        let _ = xhci_disable_slot(state, descriptor, slot);
        xhci_drain_events_preserving_port_changes(state, descriptor);
        recycle_count = recycle_count.saturating_add(1);
    }
    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED;
    None
}

fn usb_prepare_hub_port(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    hub: &mut UsbEnumerationDevice,
    hub_info: UsbHubInfo,
    port: u8,
) -> Option<u32> {
    if usb_hub_eager_port_power_enabled(hub, hub_info.power_mode) {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_POWER_BEGIN,
            aux0,
        );
        let _ = usb_hub_set_feature(
            state,
            descriptor,
            hub,
            hub_info.interface,
            port,
            USB_HUB_FEATURE_PORT_POWER,
        );
        usb_spin_wait(usb_hub_power_settle_spins(hub_info.pwr_on_2_pwr_good));
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_POWER_DONE,
            aux0,
        );
    } else {
        usb_spin_wait(usb_hub_power_settle_spins(hub_info.pwr_on_2_pwr_good));
    }
    let mut last = None;
    let mut status_seen = false;
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_BEGIN,
        aux0,
    );
    if let Some(status) = usb_hub_get_port_status_with_progress(
        state,
        descriptor,
        hub,
        hub_info.interface,
        port,
        Some(usb_hub_port_status_progress(sequence, aux0)),
    ) {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_DONE,
            aux0,
        );
        status_seen = true;
        let clear_mask = usb_hub_pre_reset_change_clear_mask(status.change);
        usb_record_hub_port_status_sample(
            state,
            hub,
            port,
            status,
            clear_mask,
            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_INITIAL,
            usb_hub_power_settle_ms(hub_info.pwr_on_2_pwr_good),
            false,
            false,
        );
        if !usb_hub_port_ready_after_reset(status) {
            usb_hub_publish_port_not_ready(sequence, aux0, status);
        }
        let _ = usb_hub_clear_port_change_mask_with_progress(
            sequence,
            aux0,
            state,
            descriptor,
            hub,
            hub_info.interface,
            port,
            clear_mask,
        );
        if !usb_hub_port_connected(status) && status.status & USB_HUB_STATUS_ENABLE == 0 {
            if let Some(recovered) = usb_recover_disconnected_hub_port(
                sequence,
                aux0,
                state,
                descriptor,
                hub,
                hub_info.interface,
                port,
                hub_info.power_mode,
                hub_info.pwr_on_2_pwr_good,
            ) {
                if usb_hub_port_ready_after_reset(recovered) {
                    let clear_mask =
                        usb_hub_ready_reset_change_clear_mask(recovered.status, recovered.change);
                    usb_record_hub_port_status_sample(
                        state,
                        hub,
                        port,
                        recovered,
                        clear_mask,
                        DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_READY,
                        usb_hub_power_settle_ms(hub_info.pwr_on_2_pwr_good),
                        true,
                        false,
                    );
                    let _ = usb_hub_clear_port_change_mask_with_progress(
                        sequence,
                        aux0,
                        state,
                        descriptor,
                        hub,
                        hub_info.interface,
                        port,
                        clear_mask,
                    );
                    publish_runtime_progress(
                        sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_READY,
                        aux0,
                    );
                    return Some(usb_hub_speed_from_status(recovered.status));
                }
                last = Some(recovered);
            } else {
                return None;
            }
        }
    } else {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_FAILED,
            aux0,
        );
    }
    for attempt in 0..USB_HUB_PORT_RETRIES {
        if !usb_hub_reset_port_with_progress(
            sequence,
            aux0,
            state,
            descriptor,
            hub,
            hub_info.interface,
            port,
        ) {
            continue;
        }
        usb_spin_wait(usb_hub_reset_settle_spins(attempt));
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_BEGIN,
            aux0,
        );
        if let Some(status) = usb_hub_get_port_status_with_progress(
            state,
            descriptor,
            hub,
            hub_info.interface,
            port,
            Some(usb_hub_port_status_progress(sequence, aux0)),
        ) {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_DONE,
                aux0,
            );
            status_seen = true;
            last = Some(status);
            if usb_hub_port_ready_after_reset(status) {
                let clear_mask =
                    usb_hub_ready_reset_change_clear_mask(status.status, status.change);
                usb_record_hub_port_status_sample(
                    state,
                    hub,
                    port,
                    status,
                    clear_mask,
                    DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_READY,
                    usb_hub_reset_settle_ms(attempt),
                    false,
                    false,
                );
                let _ = usb_hub_clear_port_change_mask_with_progress(
                    sequence,
                    aux0,
                    state,
                    descriptor,
                    hub,
                    hub_info.interface,
                    port,
                    clear_mask,
                );
                publish_runtime_progress(
                    sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_READY,
                    aux0,
                );
                return Some(usb_hub_speed_from_status(status.status));
            }
            usb_hub_publish_port_not_ready(sequence, aux0, status);
            let clear_mask = usb_hub_pre_reset_change_clear_mask(status.change);
            usb_record_hub_port_status_sample(
                state,
                hub,
                port,
                status,
                clear_mask,
                DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_RESET_POLL,
                usb_hub_reset_settle_ms(attempt),
                false,
                !usb_hub_port_connected(status),
            );
            let _ = usb_hub_clear_port_change_mask_with_progress(
                sequence,
                aux0,
                state,
                descriptor,
                hub,
                hub_info.interface,
                port,
                clear_mask,
            );
            if !usb_hub_port_connected(status) && status.status & USB_HUB_STATUS_ENABLE == 0 {
                if let Some(recovered) = usb_recover_disconnected_hub_port(
                    sequence,
                    aux0,
                    state,
                    descriptor,
                    hub,
                    hub_info.interface,
                    port,
                    hub_info.power_mode,
                    hub_info.pwr_on_2_pwr_good,
                ) {
                    last = Some(recovered);
                    if usb_hub_port_ready_after_reset(recovered) {
                        let clear_mask = usb_hub_ready_reset_change_clear_mask(
                            recovered.status,
                            recovered.change,
                        );
                        usb_record_hub_port_status_sample(
                            state,
                            hub,
                            port,
                            recovered,
                            clear_mask,
                            DRIVER_RUNTIME_USB_HUB_PORT_STATUS_STAGE_READY,
                            usb_hub_power_settle_ms(hub_info.pwr_on_2_pwr_good),
                            true,
                            false,
                        );
                        let _ = usb_hub_clear_port_change_mask_with_progress(
                            sequence,
                            aux0,
                            state,
                            descriptor,
                            hub,
                            hub_info.interface,
                            port,
                            clear_mask,
                        );
                        publish_runtime_progress(
                            sequence,
                            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_READY,
                            aux0,
                        );
                        return Some(usb_hub_speed_from_status(recovered.status));
                    }
                    usb_hub_publish_port_not_ready(sequence, aux0, recovered);
                } else {
                    continue;
                }
            }
        } else {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_FAILED,
                aux0,
            );
        }
    }
    if let Some(status) = last {
        if usb_hub_port_ready_after_reset(status) {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_READY,
                aux0,
            );
            return Some(usb_hub_speed_from_status(status.status));
        }
    } else if !status_seen && port <= USB_HUB_BLIND_PREPARE_PORT_LIMIT {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_READY,
            aux0,
        );
        return Some(XHCI_SPEED_FULL);
    }
    None
}

const fn usb_detail_warrants_hub_child_speed_fallback(detail: u16) -> bool {
    matches!(
        detail,
        DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR_FAILED
    )
}

fn usb_probe_hub_child_candidate(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    child: UsbEnumerationDevice,
    next_device_index: &mut usize,
    depth_remaining: u8,
) -> bool {
    let index_before = *next_device_index;
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_CHILD_PROBE_BEGIN,
        aux0,
    );
    usb_spin_wait(usb_hub_port_reset_recovery_spins());
    let Some(child) = xhci_address_topology_device(
        sequence,
        aux0,
        state,
        descriptor,
        dma_range,
        child,
        next_device_index,
    ) else {
        if state.init_detail == DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED {
            state.hub_child_address_failure_seen = true;
        }
        *next_device_index = index_before;
        return false;
    };
    if usb_probe_device_for_keyboard(
        sequence,
        aux0,
        state,
        descriptor,
        dma_range,
        child,
        next_device_index,
        depth_remaining.saturating_sub(1),
    ) {
        return true;
    }
    let _ = xhci_disable_slot(state, descriptor, child.slot);
    xhci_drain_events_preserving_port_changes(state, descriptor);
    *next_device_index = index_before;
    false
}

fn usb_probe_hub_child_with_speed_fallback(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    hub: &mut UsbEnumerationDevice,
    hub_info: UsbHubInfo,
    port: u8,
    primary_speed: u32,
    next_device_index: &mut usize,
    depth_remaining: u8,
) -> bool {
    let child = hub.child_with_hub_info(port, primary_speed, hub_info);
    if usb_probe_hub_child_candidate(
        sequence,
        aux0,
        state,
        descriptor,
        dma_range,
        child,
        next_device_index,
        depth_remaining,
    ) {
        return true;
    }
    if !usb_detail_warrants_hub_child_speed_fallback(state.init_detail) {
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_CHILD_SPEED_FALLBACK_BEGIN,
        aux0,
    );
    let rearmed_primary_speed =
        usb_prepare_hub_port(sequence, aux0, state, descriptor, hub, hub_info, port)
            .unwrap_or(primary_speed);
    if rearmed_primary_speed != primary_speed {
        let child = hub.child_with_hub_info(port, rearmed_primary_speed, hub_info);
        if usb_probe_hub_child_candidate(
            sequence,
            aux0,
            state,
            descriptor,
            dma_range,
            child,
            next_device_index,
            depth_remaining,
        ) {
            return true;
        }
    }
    for candidate in USB_HUB_CHILD_SPEED_CANDIDATES {
        if candidate == primary_speed || candidate == rearmed_primary_speed {
            continue;
        }
        let _ = usb_prepare_hub_port(sequence, aux0, state, descriptor, hub, hub_info, port);
        let child = hub.child_with_hub_info(port, candidate, hub_info);
        if usb_probe_hub_child_candidate(
            sequence,
            aux0,
            state,
            descriptor,
            dma_range,
            child,
            next_device_index,
            depth_remaining,
        ) {
            return true;
        }
    }
    false
}

fn usb_scan_hub_children(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    mut hub: UsbEnumerationDevice,
    hub_info: UsbHubInfo,
    config_value: u8,
    next_device_index: &mut usize,
    depth_remaining: u8,
) -> bool {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_BEGIN,
        aux0,
    );
    if !usb_set_configuration_with_progress(
        state,
        descriptor,
        &mut hub,
        config_value,
        XhciControlProgress {
            sequence,
            aux0,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_FAILED,
            transfer_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_TIMEOUT,
            status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_TIMEOUT,
        },
    ) {
        usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_SET_CONFIG_FAILED);
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_DONE,
        aux0,
    );
    usb_spin_wait(USB_HUB_SET_CONFIGURATION_SETTLE_SPINS);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_BEGIN,
        aux0,
    );
    let Some(hub_info) =
        usb_read_hub_descriptor(sequence, aux0, state, descriptor, &mut hub, hub_info)
    else {
        usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_DESCRIPTOR_FAILED);
        return false;
    };
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_DONE,
        aux0,
    );
    let hub_multi_tt = if hub_info.multi_tt {
        usb_activate_hub_multi_tt(state, descriptor, &mut hub, hub_info.interface)
    } else {
        false
    };
    let hub_info = UsbHubInfo {
        multi_tt: hub_multi_tt,
        ..hub_info
    };
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_CONTEXT_BEGIN,
        aux0,
    );
    if !xhci_evaluate_hub_context(
        state,
        descriptor,
        dma_range,
        &hub,
        hub_info.ports,
        hub_multi_tt,
    ) {
        usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_CONTEXT_FAILED);
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_CONTEXT_DONE,
        aux0,
    );
    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_TOPOLOGY_SEEN;
    let ports = hub_info.ports.min(15);
    for scan_pass in 0..USB_HUB_CHILD_SCAN_PASSES {
        if scan_pass != 0 {
            xhci_drain_events_preserving_port_changes(state, descriptor);
            usb_spin_wait(USB_HUB_PORT_RESET_RETRY_SETTLE_SPINS);
        }
        for port in 1..=ports {
            let Some(speed) =
                usb_prepare_hub_port(sequence, aux0, state, descriptor, &mut hub, hub_info, port)
            else {
                continue;
            };
            if usb_probe_hub_child_with_speed_fallback(
                sequence,
                aux0,
                state,
                descriptor,
                dma_range,
                &mut hub,
                hub_info,
                port,
                speed,
                next_device_index,
                depth_remaining,
            ) {
                return true;
            }
        }
    }
    usb_finish_hub_scan_without_keyboard(sequence, aux0, state);
    false
}

fn usb_probe_device_for_keyboard(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    mut device: UsbEnumerationDevice,
    next_device_index: &mut usize,
    depth_remaining: u8,
) -> bool {
    if usb_read_device_descriptor(sequence, aux0, state, descriptor, &mut device).is_none() {
        usb_mark_enumeration_fault(
            state,
            DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR_FAILED,
        );
        return false;
    }
    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR;
    let Some((config_len, config_value)) =
        usb_read_configuration(sequence, aux0, state, descriptor, &mut device, dma_range)
    else {
        usb_mark_enumeration_fault(
            state,
            DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR_FAILED,
        );
        return false;
    };
    let config_vaddr = dma_range.vaddr as usize + XHCI_DMA_CONFIG_BUFFER_OFFSET;
    state.keyboard_endpoint_id = 0;
    state.keyboard_endpoint_address = 0;
    state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_NONE;
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_BEGIN,
        aux0,
    );
    let endpoint_parse = usb_parse_keyboard_endpoint(state, config_vaddr, config_len);
    if endpoint_parse == UsbKeyboardEndpointParse::Found {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HID_ENDPOINT_PARSE_FOUND,
            aux0,
        );
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ENDPOINT_SEEN;
        state.keyboard_slot = device.slot;
        state.keyboard_port = device.root_port;
        state.keyboard_ep0_ring_offset = device.ep0_ring_offset;
        usb_reset_keyboard_interrupt_queue(state);
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONFIGURE_ENDPOINT_BEGIN,
            aux0,
        );
        let endpoint_ready =
            xhci_configure_keyboard_endpoint(state, descriptor, dma_range, &device);
        publish_runtime_progress(
            sequence,
            if endpoint_ready {
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONFIGURE_ENDPOINT_DONE
            } else {
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONFIGURE_ENDPOINT_FAILED
            },
            aux0,
        );
        let configured = if endpoint_ready {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_SET_CONFIGURATION_BEGIN,
                aux0,
            );
            let configured = usb_set_configuration(state, descriptor, &mut device, config_value);
            publish_runtime_progress(
                sequence,
                if configured {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_SET_CONFIGURATION_DONE
                } else {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_SET_CONFIGURATION_FAILED
                },
                aux0,
            );
            configured
        } else {
            false
        };
        let protocol_ready = if configured {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONTROL_BEGIN,
                aux0,
            );
            let protocol_ready = usb_hid_attach_control_ready(state, descriptor, &mut device);
            publish_runtime_progress(
                sequence,
                if protocol_ready {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONTROL_DONE
                } else {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_CONTROL_FAILED
                },
                aux0,
            );
            protocol_ready
        } else {
            false
        };
        let mut interrupt_ready = false;
        if configured && endpoint_ready && protocol_ready {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_BEGIN,
                aux0,
            );
            interrupt_ready = xhci_arm_keyboard_interrupt_queue(state, descriptor);
            publish_runtime_progress(
                sequence,
                if interrupt_ready {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_READY
                } else {
                    DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_FAILED
                },
                aux0,
            );
        }
        let ready = configured && endpoint_ready && protocol_ready && interrupt_ready;
        state.ep0_enqueue = device.ep0_enqueue;
        state.ep0_cycle = device.ep0_cycle;
        if ready && usb_device_keyboard_first_report_optional(&device) {
            state.keyboard_first_report_optional = true;
            if state.keyboard_last_report_status == DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_NONE {
                state.keyboard_last_report_status =
                    DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_NO_IDLE_REPORT;
            }
        }
        if !ready {
            usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ATTACH_FAILED);
        }
        return ready;
    }
    if depth_remaining == 0 {
        publish_runtime_progress(sequence, endpoint_parse.missing_phase(), aux0);
        return false;
    }
    let Some(hub_info) = usb_parse_hub_info(config_vaddr, config_len) else {
        publish_runtime_progress(sequence, endpoint_parse.missing_phase(), aux0);
        return false;
    };
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SCAN_BEGIN,
        aux0,
    );
    usb_scan_hub_children(
        sequence,
        aux0,
        state,
        descriptor,
        dma_range,
        device,
        hub_info,
        config_value,
        next_device_index,
        depth_remaining,
    )
}

fn usb_hid_attach_control_ready(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    device: &mut UsbEnumerationDevice,
) -> bool {
    let protocol_ready = usb_set_hid_boot_protocol(state, descriptor, device);
    let idle_ready = usb_set_idle(state, descriptor, device);
    if usb_hid_boot_control_required(state.keyboard_attach_rank) {
        protocol_ready && idle_ready
    } else {
        true
    }
}

fn usb_keyboard_enumerate(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    usb_scan_root_ports_for_keyboard(sequence, aux0, state, descriptor, dma_range)
}

fn xhci_probe_command_path(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    if state.command_path_proven {
        return true;
    }
    if state.command_proof_pending {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_BEGIN,
            aux0,
        );
        let rerings_pending_doorbell = usb_command_proof_should_rering(
            state.command_proof_poll_slices,
            state.command_proof_events_seen,
        );
        if rerings_pending_doorbell {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_DOORBELL_BEGIN,
                aux0,
            );
            if !xhci_ring_doorbell(state, 0, 0) {
                publish_runtime_progress(
                    sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_FAILED,
                    aux0,
                );
                state.command_proof_pending = false;
                state.command_proof_poll_slices = 0;
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
                return false;
            }
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_DOORBELL_DONE,
                aux0,
            );
        }
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_BEGIN,
            aux0,
        );
        match xhci_poll_command_completion(
            state,
            descriptor,
            USB_COMMAND_COMPLETION_SLICE_SPINS,
            XhciEventAckMode::PromptSafe { sequence, aux0 },
            None,
        ) {
            XhciCommandCompletionPoll::Complete(event) => {
                state.command_proof_pending = false;
                state.command_proof_poll_slices = 0;
                state.command_proof_slot = xhci_slot_id(event.control);
                if state.command_proof_slot != 0 {
                    publish_runtime_progress(
                        sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_READY,
                        aux0,
                    );
                    state.command_path_proven = true;
                    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY;
                    true
                } else {
                    publish_runtime_progress(
                        sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_FAILED,
                        aux0,
                    );
                    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
                    false
                }
            }
            XhciCommandCompletionPoll::Failed => {
                publish_runtime_progress(
                    sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_FAILED,
                    aux0,
                );
                state.command_proof_pending = false;
                state.command_proof_poll_slices = 0;
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
                false
            }
            XhciCommandCompletionPoll::CommandFailed(_) => {
                publish_runtime_progress(
                    sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_POLL_FAILED,
                    aux0,
                );
                state.command_proof_pending = false;
                state.command_proof_poll_slices = 0;
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
                false
            }
            XhciCommandCompletionPoll::Pending(pending) => {
                publish_runtime_progress(
                    sequence,
                    xhci_command_proof_pending_progress_phase(pending),
                    aux0,
                );
                state.command_proof_poll_slices = state.command_proof_poll_slices.saturating_add(1);
                if state.command_proof_poll_slices >= USB_COMMAND_PROOF_MAX_POLL_SLICES {
                    state.command_proof_pending = false;
                    state.command_proof_poll_slices = 0;
                    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
                } else {
                    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING;
                }
                false
            }
        }
    } else {
        let command = XhciTrb {
            parameter: 0,
            status: 0,
            control: XHCI_TRB_TYPE_ENABLE_SLOT << 10,
        };
        if !xhci_submit_command_for_proof(sequence, aux0, state, descriptor, command) {
            state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED;
            return false;
        }
        state.command_proof_pending = true;
        state.command_proof_poll_slices = 0;
        state.command_proof_slot = 0;
        state.command_proof_events_seen = 0;
        state.command_proof_last_event_type = 0;
        state.command_proof_ack_failures = 0;
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING;
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_COMMAND_PROOF_RETURN_PENDING,
            aux0,
        );
        false
    }
}

const fn usb_root_port_frontier_publish_required(current_detail: u16, candidate_mask: u32) -> bool {
    current_detail == DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY && candidate_mask != 0
}

fn usb_scan_root_ports_for_keyboard(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> bool {
    let mut next_device_index = 0usize;
    let mut best_detail = state.enumeration_best_detail;
    if !state.enumeration_root_powered {
        if !xhci_power_root_ports(state) {
            state.init_detail = best_detail;
            return false;
        }
        state.enumeration_root_powered = true;
        state.enumeration_root_scan_pass = 0;
        state.enumeration_root_next_port = 1;
        state.enumeration_best_detail = state.init_detail;
        return false;
    }

    if !state.command_path_proven {
        let _ = xhci_probe_command_path(sequence, aux0, state, descriptor);
        usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
        state.enumeration_best_detail = best_detail;
        state.init_detail = best_detail;
        return false;
    }

    if state.enumeration_root_scan_pass >= USB_ROOT_PORT_SCAN_PASSES as u8 {
        state.init_detail = best_detail;
        usb_reset_enumeration_cursor(state);
        state.enumeration_retry_window_exhausted = true;
        return false;
    }

    xhci_drain_events_preserving_port_changes(state, descriptor);
    let candidate_mask = xhci_root_port_candidate_mask(state);
    if usb_root_port_frontier_publish_required(state.init_detail, candidate_mask) {
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ROOT_PORT_CONNECTED;
        usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
        state.enumeration_best_detail = best_detail;
        return false;
    }
    let max_port = state.max_ports.min(u32::BITS as u8);
    if candidate_mask == 0 || state.enumeration_root_next_port > max_port {
        usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
        state.enumeration_best_detail = best_detail;
        state.enumeration_root_scan_pass = state.enumeration_root_scan_pass.saturating_add(1);
        state.enumeration_root_next_port = 1;
        return false;
    }

    for port in state.enumeration_root_next_port.max(1)..=max_port {
        let bit = 1u32 << (port - 1);
        if candidate_mask & bit == 0 {
            continue;
        }
        state.enumeration_root_next_port = port.saturating_add(1);
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_BEGIN,
            aux0,
        );
        if let Some(speed) = xhci_reset_root_port(
            sequence,
            aux0,
            state,
            port,
            state.port_event_candidate_mask & bit != 0,
        ) {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_DONE,
                aux0,
            );
            state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_ROOT_PORT_CONNECTED;
            usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
            state.port_event_candidate_mask &= !bit;
            let root = UsbEnumerationDevice {
                root_port: port,
                route: 0,
                speed,
                depth: 0,
                ..UsbEnumerationDevice::empty()
            };
            let Some(root) = xhci_address_topology_device(
                sequence,
                aux0,
                state,
                descriptor,
                dma_range,
                root,
                &mut next_device_index,
            ) else {
                usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
                state.enumeration_best_detail = best_detail;
                return false;
            };
            usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
            if usb_probe_device_for_keyboard(
                sequence,
                aux0,
                state,
                descriptor,
                dma_range,
                root,
                &mut next_device_index,
                USB_ENUM_MAX_DEPTH,
            ) {
                return true;
            }
            let _ = xhci_disable_slot(state, descriptor, root.slot);
            xhci_drain_events_preserving_port_changes(state, descriptor);
            usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
            state.enumeration_best_detail = best_detail;
            return false;
        }
    }

    usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
    state.enumeration_best_detail = best_detail;
    state.enumeration_root_scan_pass = state.enumeration_root_scan_pass.saturating_add(1);
    state.enumeration_root_next_port = 1;
    usb_remember_best_enumeration_detail(&mut best_detail, state.init_detail);
    state.init_detail = best_detail;
    false
}

fn xhci_queue_keyboard_interrupt_in(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return false;
    };
    let report_len = usb_keyboard_report_request_len(state);
    let trb_index = usize::from(state.kbd_enqueue);
    if trb_index >= XHCI_COMMAND_RING_TRBS - 1 {
        return false;
    }
    if xhci_keyboard_report_slot_for_trb_index(state, trb_index as u16).is_some() {
        return false;
    }
    let Some(report_slot) = xhci_keyboard_free_report_slot(state) else {
        return false;
    };
    let base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
    let Some(kbd_ring_bus) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET)
    else {
        return false;
    };
    let report_offset = xhci_keyboard_report_buffer_offset(report_slot);
    let Some(report_bus) = xhci_dma_bus_addr(descriptor, dma_range, report_offset) else {
        return false;
    };
    zero_dma_range(dma_range.vaddr as usize + report_offset, report_len);
    dma_clean_range(dma_range.vaddr as usize + report_offset, report_len);
    write_xhci_trb(
        base,
        trb_index,
        XhciTrb {
            parameter: report_bus,
            status: report_len as u32,
            control: (XHCI_TRB_TYPE_NORMAL << 10)
                | XHCI_TRB_IOC
                | XHCI_TRB_ISP
                | xhci_cycle_bit(state.kbd_cycle),
        },
    );
    let _ = xhci_advance_transfer_ring(
        base,
        kbd_ring_bus,
        &mut state.kbd_enqueue,
        &mut state.kbd_cycle,
    );
    state.keyboard_report_in_use[report_slot] = true;
    state.keyboard_report_trb_indices[report_slot] = trb_index as u16;
    state.keyboard_transfer_generation = state.keyboard_transfer_generation.wrapping_add(1);
    if state.keyboard_transfer_generation == 0 {
        state.keyboard_transfer_generation = 1;
    }
    state.keyboard_reports_queued = state.keyboard_reports_queued.saturating_add(1);
    state.keyboard_doorbell_pending = true;
    true
}

const fn xhci_keyboard_report_buffer_offset(report_slot: usize) -> usize {
    XHCI_DMA_REPORT_BUFFER_OFFSET + report_slot * USB_KEYBOARD_REPORT_BUFFER_BYTES
}

fn usb_keyboard_report_request_len(state: &UsbRuntimeState) -> usize {
    let endpoint_len = usize::from(state.keyboard_ep_max_packet)
        .clamp(USB_BOOT_REPORT_BYTES, USB_KEYBOARD_REPORT_BUFFER_BYTES);
    if state.keyboard_attach_rank == USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT {
        endpoint_len.min(USB_BOOT_REPORT_BYTES)
    } else {
        endpoint_len
    }
}

fn xhci_keyboard_free_report_slot(state: &UsbRuntimeState) -> Option<usize> {
    if usize::from(state.keyboard_reports_queued) >= USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        return None;
    }
    let mut slot = 0usize;
    while slot < USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        if !state.keyboard_report_in_use[slot] {
            return Some(slot);
        }
        slot += 1;
    }
    None
}

fn xhci_keyboard_interrupt_queue_target(_state: &UsbRuntimeState) -> usize {
    USB_KEYBOARD_ACTIVE_INTERRUPT_QUEUE_DEPTH
}

fn usb_keyboard_active_interrupt_transfer_identity(
    state: &UsbRuntimeState,
) -> Option<UsbKeyboardTransferIdentity> {
    if usize::from(state.keyboard_reports_queued) != USB_KEYBOARD_ACTIVE_INTERRUPT_QUEUE_DEPTH {
        return None;
    }
    let mut identity = None;
    let mut report_slot = 0usize;
    while report_slot < USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        if state.keyboard_report_in_use[report_slot] {
            if identity.is_some() {
                return None;
            }
            identity = Some(UsbKeyboardTransferIdentity {
                slot: state.keyboard_slot,
                endpoint_id: state.keyboard_endpoint_id,
                report_slot: report_slot as u8,
                trb_index: state.keyboard_report_trb_indices[report_slot],
                generation: state.keyboard_transfer_generation,
            });
        }
        report_slot += 1;
    }
    identity
}

fn usb_keyboard_arm_first_transfer_watch(state: &mut UsbRuntimeState) {
    if state.keyboard_transfer_events != 0 || usb_keyboard_has_first_valid_report(state) {
        state.keyboard_first_transfer_watch = None;
        return;
    }
    let Some(identity) = usb_keyboard_active_interrupt_transfer_identity(state) else {
        state.keyboard_first_transfer_watch = None;
        return;
    };
    if state
        .keyboard_first_transfer_watch
        .is_some_and(|watch| watch.identity == identity)
    {
        return;
    }
    state.keyboard_first_transfer_watch = Some(UsbKeyboardFirstTransferWatch {
        identity,
        deadline: runtime_deadline_from_millis_or_iterations(
            USB_KEYBOARD_FIRST_TRANSFER_TIMEOUT_MS,
            USB_KEYBOARD_FIRST_TRANSFER_TIMEOUT_FALLBACK_POLLS,
        ),
    });
}

fn usb_keyboard_first_transfer_liveness_expired(state: &mut UsbRuntimeState) -> bool {
    if !usb_keyboard_poll_ready_state(state)
        || state.keyboard_transfer_events != 0
        || usb_keyboard_has_first_valid_report(state)
    {
        state.keyboard_first_transfer_watch = None;
        return false;
    }
    if state.keyboard_preserved_event_count != 0 || state.keyboard_doorbell_pending {
        return false;
    }
    let Some(identity) = usb_keyboard_active_interrupt_transfer_identity(state) else {
        state.keyboard_first_transfer_watch = None;
        return false;
    };
    if !state
        .keyboard_first_transfer_watch
        .is_some_and(|watch| watch.identity == identity)
    {
        state.keyboard_first_transfer_watch = None;
        return false;
    }
    state
        .keyboard_first_transfer_watch
        .as_mut()
        .is_some_and(|watch| runtime_deadline_expired(&mut watch.deadline))
}

fn xhci_arm_keyboard_interrupt_queue(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let mut queued_any = false;
    let target_depth = xhci_keyboard_interrupt_queue_target(state);
    while usize::from(state.keyboard_reports_queued) < target_depth {
        if !xhci_queue_keyboard_interrupt_in(state, descriptor) {
            break;
        }
        queued_any = true;
    }
    if state.keyboard_valid_report_events == 0 && state.keyboard_reports_queued != 0 {
        state.keyboard_doorbell_pending = true;
    }
    if queued_any || state.keyboard_doorbell_pending {
        dma_store_barrier();
        if xhci_ring_doorbell(state, state.keyboard_slot, state.keyboard_endpoint_id) {
            state.keyboard_doorbell_pending = false;
        } else {
            state.keyboard_doorbell_pending = true;
            return false;
        }
    }
    if usize::from(state.keyboard_reports_queued) < target_depth {
        return false;
    }
    usb_keyboard_arm_first_transfer_watch(state);
    queued_any || state.keyboard_reports_queued != 0
}

fn xhci_drain_keyboard_recovery_events(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) {
    let mut drained = 0usize;
    while drained < USB_KEYBOARD_RECOVERY_EVENT_DRAIN_LIMIT {
        let Some(event) = xhci_next_event(state, descriptor) else {
            break;
        };
        if !xhci_ack_event_dequeue(state, descriptor) {
            break;
        }
        if xhci_trb_type(event.control) == XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT {
            xhci_preserve_port_status_change_event(state, event);
        }
        drained = drained.saturating_add(1);
    }
}

fn xhci_reset_keyboard_transfer_ring(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<u64> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    let base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
    let ring_bus = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET)?;
    zero_dma_range(base, XHCI_COMMAND_RING_BYTES);
    xhci_publish_transfer_ring_link(base, ring_bus, true);
    zero_dma_range(
        dma_range.vaddr as usize + XHCI_DMA_REPORT_BUFFER_OFFSET,
        USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH * USB_KEYBOARD_REPORT_BUFFER_BYTES,
    );
    dma_clean_range(base, XHCI_COMMAND_RING_BYTES);
    dma_clean_range(
        dma_range.vaddr as usize + XHCI_DMA_REPORT_BUFFER_OFFSET,
        USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH * USB_KEYBOARD_REPORT_BUFFER_BYTES,
    );
    state.kbd_enqueue = 0;
    state.kbd_cycle = true;
    usb_clear_keyboard_interrupt_transfer_state(state);
    Some(ring_bus)
}

fn usb_keyboard_mark_matched_transfer_fault(state: &mut UsbRuntimeState, completion_code: u32) {
    if completion_code == XHCI_COMPLETION_STALL_ERROR {
        state.keyboard_endpoint_reset_required = true;
    }
    state.keyboard_last_report_status = DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_RECOVERY_FAILED;
}

fn usb_keyboard_handle_matched_transfer_fault(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    completion_code: u32,
) {
    state.keyboard_last_recovery_reason =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_REASON_MATCHED_TRANSFER_FAULT;
    usb_keyboard_mark_matched_transfer_fault(state, completion_code);
    let _ = xhci_recover_keyboard_interrupt_endpoint(state, descriptor);
}

fn xhci_mark_keyboard_endpoint_recovery_failed(state: &mut UsbRuntimeState) {
    state.keyboard_endpoint_recovery_failures =
        state.keyboard_endpoint_recovery_failures.saturating_add(1);
    state.keyboard_last_report_status = DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_RECOVERY_FAILED;
    if state.keyboard_endpoint_recovery_failures >= USB_KEYBOARD_RECOVERY_REENUMERATE_FAILURES {
        usb_clear_keyboard_interrupt_transfer_state(state);
        state.kbd_enqueue = 0;
        state.kbd_cycle = true;
        state.keyboard_slot = 0;
        state.keyboard_endpoint_id = 0;
        state.keyboard_endpoint_address = 0;
        state.keyboard_interface = 0xff;
        state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_NONE;
        state.keyboard_attach_awaiting_idle = true;
        state.keyboard_control_poll_disabled = false;
        state.keyboard_control_poll_cooldown = 0;
        state.keyboard_led_sync_pending = false;
        state.keyboard_led_sync_cooldown = 0;
        usb_mark_enumeration_fault(state, DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ATTACH_FAILED);
    }
}

fn publish_usb_keyboard_endpoint_recovery_progress(progress: Option<(u32, u32)>, phase: u32) {
    if let Some((sequence, aux0)) = progress {
        publish_runtime_progress(sequence, phase, aux0);
    }
}

fn xhci_mark_keyboard_endpoint_recovery_failed_with_progress(
    state: &mut UsbRuntimeState,
    progress: Option<(u32, u32)>,
) -> bool {
    xhci_mark_keyboard_endpoint_recovery_failed(state);
    publish_usb_keyboard_endpoint_recovery_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_FAILED,
    );
    false
}

fn usb_keyboard_reenumerate_pre_first_report_no_event_with_progress(
    state: &mut UsbRuntimeState,
    progress: Option<(u32, u32)>,
) -> bool {
    state.keyboard_last_recovery_reason =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_REASON_FULL_QUEUE_NO_EVENT;
    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_LIMIT;
    xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress)
}

fn xhci_recover_keyboard_interrupt_endpoint(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    xhci_recover_keyboard_interrupt_endpoint_with_progress(state, descriptor, None)
}

fn xhci_recover_keyboard_interrupt_endpoint_with_progress(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    progress: Option<(u32, u32)>,
) -> bool {
    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_BEGIN;
    publish_usb_keyboard_endpoint_recovery_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_BEGIN,
    );
    if !usb_keyboard_poll_ready_state(state) {
        state.keyboard_last_recovery_stage =
            pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_NOT_READY;
        publish_usb_keyboard_endpoint_recovery_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_FAILED,
        );
        return false;
    }
    if state.keyboard_endpoint_recoveries >= USB_KEYBOARD_HARD_RECOVERY_LIMIT {
        state.keyboard_last_recovery_stage =
            pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_LIMIT;
        return xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress);
    }
    let slot = state.keyboard_slot;
    let endpoint_id = state.keyboard_endpoint_id;
    state.keyboard_control_poll_cooldown = USB_HID_CONTROL_GET_REPORT_COOLDOWN_POLLS;
    state.keyboard_led_sync_cooldown = 0;
    let reset_required = state.keyboard_endpoint_reset_required;

    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_STOP_ENDPOINT;
    let stopped = xhci_enqueue_endpoint_recovery_command(
        state,
        descriptor,
        xhci_stop_endpoint_command(slot, endpoint_id),
        true,
    );
    if !stopped {
        return xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress);
    }
    let reset = if reset_required {
        state.keyboard_last_recovery_stage =
            pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_RESET_ENDPOINT;
        xhci_enqueue_endpoint_recovery_command(
            state,
            descriptor,
            xhci_reset_endpoint_command(slot, endpoint_id),
            false,
        )
    } else {
        true
    };
    if !reset {
        return xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress);
    }

    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_RESET_RING;
    let Some(kbd_ring_bus) = xhci_reset_keyboard_transfer_ring(state, descriptor) else {
        return xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress);
    };
    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_SET_DEQUEUE;
    if !xhci_enqueue_endpoint_recovery_command(
        state,
        descriptor,
        xhci_set_tr_dequeue_pointer_command(slot, endpoint_id, kbd_ring_bus, true),
        false,
    ) {
        return xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress);
    }
    xhci_drain_keyboard_recovery_events(state, descriptor);
    usb_clear_keyboard_interrupt_transfer_state(state);
    state.keyboard_attach_awaiting_idle = true;
    state.keyboard_endpoint_recoveries = state.keyboard_endpoint_recoveries.saturating_add(1);
    state.keyboard_last_report_status = DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_RECOVERY_SUCCESS;
    state.keyboard_transfer_events = 0;
    state.keyboard_unmatched_streak = 0;
    state.keyboard_endpoint_reset_required = false;
    state.keyboard_last_recovery_stage =
        pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_REARM;
    if xhci_arm_keyboard_interrupt_queue(state, descriptor)
        && usize::from(state.keyboard_reports_queued) >= xhci_keyboard_interrupt_queue_target(state)
    {
        state.keyboard_last_recovery_stage =
            pi4_driver_abi::DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_STAGE_READY;
        publish_usb_keyboard_endpoint_recovery_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_READY,
        );
        true
    } else {
        xhci_mark_keyboard_endpoint_recovery_failed_with_progress(state, progress)
    }
}

fn usb_keyboard_endpoint_hard_recovery_due(state: &UsbRuntimeState) -> bool {
    usb_keyboard_poll_ready_state(state)
        && usb_keyboard_has_first_valid_report(state)
        && state.keyboard_endpoint_recoveries < USB_KEYBOARD_HARD_RECOVERY_LIMIT
        && state.keyboard_unmatched_streak >= USB_KEYBOARD_HARD_RECOVERY_UNMATCHED_THRESHOLD
}

fn usb_keyboard_steady_unmatched_recovery_due(state: &UsbRuntimeState) -> bool {
    usb_keyboard_poll_ready_state(state)
        && usb_keyboard_post_first_report_unmatched(state)
        && state.keyboard_endpoint_recoveries < USB_KEYBOARD_HARD_RECOVERY_LIMIT
        && state.keyboard_unmatched_streak >= USB_KEYBOARD_STEADY_UNMATCHED_RECOVERY_THRESHOLD
}

fn usb_keyboard_recovery_aux_unmatched_recovery_due(
    state: &UsbRuntimeState,
    recovery_aux: bool,
) -> bool {
    recovery_aux
        && usb_keyboard_poll_ready_state(state)
        && usb_keyboard_post_first_report_unmatched(state)
        && state.keyboard_endpoint_recoveries < USB_KEYBOARD_HARD_RECOVERY_LIMIT
}

fn usb_keyboard_recovery_aux_full_queue_recovery_due(
    state: &UsbRuntimeState,
    recovery_aux: bool,
) -> bool {
    if !recovery_aux
        || !usb_keyboard_poll_ready_state(state)
        || state.keyboard_endpoint_recoveries >= USB_KEYBOARD_HARD_RECOVERY_LIMIT
        || state.keyboard_preserved_event_count != 0
        || usize::from(state.keyboard_reports_queued) < xhci_keyboard_interrupt_queue_target(state)
    {
        return false;
    }
    if usb_keyboard_has_first_valid_report(state) {
        return !usb_keyboard_post_first_report_unmatched(state);
    }
    false
}

fn usb_keyboard_pre_first_report_full_no_event_reenumeration_due(
    state: &UsbRuntimeState,
    recovery_aux: bool,
) -> bool {
    recovery_aux
        && usb_keyboard_poll_ready_state(state)
        && !usb_keyboard_has_first_valid_report(state)
        && state.keyboard_endpoint_recovery_failures < USB_KEYBOARD_RECOVERY_REENUMERATE_FAILURES
        && state.keyboard_preserved_event_count == 0
        && state.keyboard_transfer_events == 0
        && !state.keyboard_doorbell_pending
        && usize::from(state.keyboard_reports_queued) >= xhci_keyboard_interrupt_queue_target(state)
}

fn usb_keyboard_recovery_aux_reenumeration_due(
    state: &UsbRuntimeState,
    recovery_aux: bool,
) -> bool {
    recovery_aux
        && usb_keyboard_poll_ready_state(state)
        && usb_keyboard_has_first_valid_report(state)
        && state.keyboard_endpoint_recoveries >= USB_KEYBOARD_HARD_RECOVERY_LIMIT
}

fn usb_keyboard_steady_overqueue_recovery_due(state: &UsbRuntimeState) -> bool {
    usb_keyboard_poll_ready_state(state)
        && usb_keyboard_has_first_valid_report(state)
        && state.keyboard_endpoint_recoveries < USB_KEYBOARD_HARD_RECOVERY_LIMIT
        && state.keyboard_preserved_event_count == 0
        && usize::from(state.keyboard_reports_queued) > USB_KEYBOARD_ACTIVE_INTERRUPT_QUEUE_DEPTH
}

fn usb_keyboard_queue_collapse_recovery_due(state: &UsbRuntimeState) -> bool {
    usb_keyboard_poll_ready_state(state)
        && usb_keyboard_has_first_valid_report(state)
        && state.keyboard_endpoint_recoveries < USB_KEYBOARD_HARD_RECOVERY_LIMIT
        && state.keyboard_transfer_events >= USB_KEYBOARD_QUEUE_COLLAPSE_RECOVERY_EVENTS
        && state.keyboard_reports_queued == 0
}

fn xhci_keyboard_transfer_event_matches(state: &UsbRuntimeState, event: XhciTrb) -> bool {
    xhci_trb_type(event.control) == XHCI_TRB_TYPE_TRANSFER_EVENT
        && xhci_slot_id(event.control) == state.keyboard_slot
        && xhci_endpoint_id(event.control) == state.keyboard_endpoint_id
}

fn xhci_preserve_keyboard_transfer_event(state: &mut UsbRuntimeState, event: XhciTrb) -> bool {
    let index = usize::from(state.keyboard_preserved_event_count);
    if index >= USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        return false;
    }
    state.keyboard_preserved_event_parameters[index] = event.parameter;
    state.keyboard_preserved_event_statuses[index] = event.status;
    state.keyboard_preserved_event_controls[index] = event.control;
    state.keyboard_preserved_event_count = state.keyboard_preserved_event_count.saturating_add(1);
    true
}

fn xhci_take_preserved_keyboard_transfer_event(state: &mut UsbRuntimeState) -> Option<XhciTrb> {
    if state.keyboard_preserved_event_count == 0 {
        return None;
    }
    let event = XhciTrb {
        parameter: state.keyboard_preserved_event_parameters[0],
        status: state.keyboard_preserved_event_statuses[0],
        control: state.keyboard_preserved_event_controls[0],
    };
    let count = usize::from(state.keyboard_preserved_event_count);
    let mut index = 1usize;
    while index < count {
        state.keyboard_preserved_event_parameters[index - 1] =
            state.keyboard_preserved_event_parameters[index];
        state.keyboard_preserved_event_statuses[index - 1] =
            state.keyboard_preserved_event_statuses[index];
        state.keyboard_preserved_event_controls[index - 1] =
            state.keyboard_preserved_event_controls[index];
        index += 1;
    }
    state.keyboard_preserved_event_count = state.keyboard_preserved_event_count.saturating_sub(1);
    let clear = usize::from(state.keyboard_preserved_event_count);
    state.keyboard_preserved_event_parameters[clear] = 0;
    state.keyboard_preserved_event_statuses[clear] = 0;
    state.keyboard_preserved_event_controls[clear] = 0;
    Some(event)
}

fn xhci_keyboard_event_trb_index(
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    event: XhciTrb,
) -> Option<u16> {
    let ring_bus = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET)?;
    let completion_ptr = xhci_transfer_event_trb_pointer(event.parameter);
    let delta = completion_ptr.checked_sub(ring_bus)?;
    if delta % XHCI_TRB_BYTES as u64 != 0 {
        return None;
    }
    let index = delta / XHCI_TRB_BYTES as u64;
    if index >= (XHCI_COMMAND_RING_TRBS - 1) as u64 {
        return None;
    }
    Some(index as u16)
}

fn xhci_keyboard_report_slot_from_trb_parameter(
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    trb: XhciTrb,
) -> Option<usize> {
    let report_bus = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_REPORT_BUFFER_OFFSET)?;
    let delta = trb.parameter.checked_sub(report_bus)?;
    if delta % USB_KEYBOARD_REPORT_BUFFER_BYTES as u64 != 0 {
        return None;
    }
    let report_slot = (delta / USB_KEYBOARD_REPORT_BUFFER_BYTES as u64) as usize;
    if report_slot >= USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        return None;
    }
    Some(report_slot)
}

fn xhci_keyboard_report_slot_from_event_trb(
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    event: XhciTrb,
) -> Option<usize> {
    let trb_index = usize::from(xhci_keyboard_event_trb_index(descriptor, dma_range, event)?);
    let base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
    let trb = read_xhci_trb(base, trb_index);
    let report_slot = xhci_keyboard_report_slot_from_trb_parameter(descriptor, dma_range, trb)?;
    state
        .keyboard_report_in_use
        .get(report_slot)
        .copied()
        .unwrap_or(false)
        .then_some(report_slot)
}

fn xhci_keyboard_report_slot_for_event(
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    event: XhciTrb,
) -> Option<usize> {
    let trb_index = xhci_keyboard_event_trb_index(descriptor, dma_range, event)?;
    if let Some(slot) = xhci_keyboard_report_slot_for_trb_index(state, trb_index) {
        return Some(slot);
    }
    xhci_keyboard_report_slot_from_event_trb(state, descriptor, dma_range, event)
}

fn xhci_complete_keyboard_report_slot_by_index(
    state: &mut UsbRuntimeState,
    report_slot: usize,
) -> Option<usize> {
    if report_slot >= USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH
        || !state.keyboard_report_in_use[report_slot]
    {
        return None;
    }
    state.keyboard_report_in_use[report_slot] = false;
    state.keyboard_report_trb_indices[report_slot] = 0;
    state.keyboard_reports_queued = state.keyboard_reports_queued.saturating_sub(1);
    Some(report_slot)
}

fn xhci_complete_keyboard_report_slot(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    event: XhciTrb,
) -> Option<usize> {
    let report_slot = xhci_keyboard_report_slot_for_event(state, descriptor, dma_range, event)?;
    xhci_complete_keyboard_report_slot_by_index(state, report_slot)
}

fn xhci_keyboard_report_slot_for_trb_index(
    state: &UsbRuntimeState,
    trb_index: u16,
) -> Option<usize> {
    let mut slot = 0usize;
    while slot < USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        if state.keyboard_report_in_use[slot]
            && state.keyboard_report_trb_indices[slot] == trb_index
        {
            return Some(slot);
        }
        slot += 1;
    }
    None
}

fn xhci_keyboard_trb_age(next_enqueue: u16, trb_index: u16) -> u16 {
    let ring_slots = (XHCI_COMMAND_RING_TRBS - 1) as u16;
    if trb_index >= ring_slots {
        return 0;
    }
    if next_enqueue >= ring_slots {
        trb_index
    } else if next_enqueue >= trb_index {
        next_enqueue - trb_index
    } else {
        ring_slots - trb_index + next_enqueue
    }
}

#[cfg(test)]
fn xhci_reclaim_oldest_keyboard_report_slot_at_or_above(
    state: &mut UsbRuntimeState,
    target_depth: usize,
) -> bool {
    xhci_reclaim_oldest_keyboard_report_slot_at_or_above_excluding(
        state,
        target_depth,
        &[false; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH],
    )
}

fn xhci_reclaim_oldest_keyboard_report_slot_at_or_above_excluding(
    state: &mut UsbRuntimeState,
    target_depth: usize,
    excluded_slots: &[bool; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH],
) -> bool {
    let target_depth = target_depth.clamp(1, USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH);
    if usize::from(state.keyboard_reports_queued) < target_depth {
        return false;
    }
    let mut selected = None;
    let mut selected_age = 0u16;
    let mut slot = 0usize;
    while slot < USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
        if state.keyboard_report_in_use[slot] && !excluded_slots[slot] {
            let age =
                xhci_keyboard_trb_age(state.kbd_enqueue, state.keyboard_report_trb_indices[slot]);
            if selected.is_none() || age > selected_age {
                selected = Some(slot);
                selected_age = age;
            }
        }
        slot += 1;
    }
    let Some(slot) = selected else {
        if !state.keyboard_report_in_use.iter().any(|&in_use| in_use) {
            state.keyboard_reports_queued = 0;
        }
        return false;
    };
    xhci_complete_keyboard_report_slot_by_index(state, slot).is_some()
}

fn xhci_preserved_keyboard_report_slot_exclusions(
    state: &UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
) -> [bool; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH] {
    let mut excluded = [false; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    let count = usize::from(state.keyboard_preserved_event_count);
    let mut index = 0usize;
    while index < count {
        let event = XhciTrb {
            parameter: state.keyboard_preserved_event_parameters[index],
            status: state.keyboard_preserved_event_statuses[index],
            control: state.keyboard_preserved_event_controls[index],
        };
        if xhci_keyboard_transfer_event_matches(state, event) {
            if let Some(slot) =
                xhci_keyboard_report_slot_for_event(state, descriptor, dma_range, event)
            {
                excluded[slot] = true;
            }
        }
        index += 1;
    }
    excluded
}

fn xhci_recover_unmatched_keyboard_transfer_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    event: XhciTrb,
) {
    state.keyboard_doorbell_pending = false;
    let target_depth = xhci_keyboard_interrupt_queue_target(state);
    let excluded_slots =
        xhci_preserved_keyboard_report_slot_exclusions(state, descriptor, dma_range);
    let _ = xhci_reclaim_oldest_keyboard_report_slot_at_or_above_excluding(
        state,
        target_depth,
        &excluded_slots,
    );
    state.keyboard_transfer_events = state.keyboard_transfer_events.saturating_add(1);
    state.keyboard_unmatched_streak = state.keyboard_unmatched_streak.saturating_add(1);
    if xhci_completion_code(event.status) == XHCI_COMPLETION_STALL_ERROR {
        state.keyboard_endpoint_reset_required = true;
    }
    state.keyboard_last_report_status =
        DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_UNMATCHED_TRANSFER;
}

fn xhci_next_keyboard_transfer_event(
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<(XhciTrb, usize)> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    let mut unmatched_recoveries = 0u8;
    while let Some(event) = xhci_take_preserved_keyboard_transfer_event(state) {
        if let Some(report_slot) =
            xhci_complete_keyboard_report_slot(state, descriptor, dma_range, event)
        {
            state.keyboard_transfer_events = state.keyboard_transfer_events.saturating_add(1);
            state.keyboard_unmatched_streak = 0;
            return Some((event, report_slot));
        } else if xhci_keyboard_transfer_event_matches(state, event) {
            xhci_recover_unmatched_keyboard_transfer_event(state, descriptor, dma_range, event);
            unmatched_recoveries = unmatched_recoveries.saturating_add(1);
            if unmatched_recoveries >= USB_KEYBOARD_UNMATCHED_RECOVERY_EVENTS_PER_POLL {
                return None;
            }
            continue;
        }
    }
    let mut scanned_events = 0usize;
    loop {
        if unmatched_recoveries >= USB_KEYBOARD_UNMATCHED_RECOVERY_EVENTS_PER_POLL {
            return None;
        }
        if scanned_events >= USB_KEYBOARD_EVENT_SCAN_LIMIT {
            return None;
        }
        let event = xhci_next_event(state, descriptor)?;
        let trb_type = xhci_trb_type(event.control);
        if trb_type == XHCI_TRB_TYPE_COMMAND_COMPLETION {
            state.keyboard_command_completion_blocked =
                state.keyboard_command_completion_blocked.saturating_add(1);
            return None;
        }
        scanned_events = scanned_events.saturating_add(1);
        if !xhci_ack_event_dequeue(state, descriptor) {
            return None;
        }
        match trb_type {
            XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT => {
                xhci_preserve_port_status_change_event(state, event);
            }
            XHCI_TRB_TYPE_TRANSFER_EVENT
                if xhci_slot_id(event.control) == state.keyboard_slot
                    && xhci_endpoint_id(event.control) == state.keyboard_endpoint_id =>
            {
                if let Some(report_slot) =
                    xhci_complete_keyboard_report_slot(state, descriptor, dma_range, event)
                {
                    state.keyboard_transfer_events =
                        state.keyboard_transfer_events.saturating_add(1);
                    state.keyboard_unmatched_streak = 0;
                    return Some((event, report_slot));
                }
                xhci_recover_unmatched_keyboard_transfer_event(state, descriptor, dma_range, event);
                unmatched_recoveries = unmatched_recoveries.saturating_add(1);
                if unmatched_recoveries >= USB_KEYBOARD_UNMATCHED_RECOVERY_EVENTS_PER_POLL {
                    return None;
                }
            }
            _ => {}
        }
    }
}

fn usb_wait_status(op_base: usize, mask: u32, expected: u32) -> bool {
    let mut deadline = runtime_deadline_from_legacy_spins(PCIE_POLL_SPINS);
    while !runtime_deadline_expired(&mut deadline) {
        if usb_read32(op_base + XHCI_USBSTS) & mask == expected {
            return true;
        }
        runtime_poll_pause();
    }
    false
}

fn usb_wait_status_with_settle(
    op_base: usize,
    mask: u32,
    expected: u32,
    timeout_ms: u64,
    polls: usize,
    settle_spins: usize,
) -> bool {
    let mut poll = 0usize;
    let mut deadline = runtime_deadline_from_millis_or_iterations(timeout_ms, polls);
    while !runtime_deadline_iteration_cap_reached(&deadline, poll, polls)
        && !runtime_deadline_expired(&mut deadline)
    {
        if usb_read32(op_base + XHCI_USBSTS) & mask == expected {
            return true;
        }
        runtime_spin(settle_spins);
        poll = poll.saturating_add(1);
    }
    false
}

fn usb_wait_command_clear_with_settle(
    op_base: usize,
    mask: u32,
    timeout_ms: u64,
    polls: usize,
    settle_spins: usize,
) -> bool {
    let mut poll = 0usize;
    let mut deadline = runtime_deadline_from_millis_or_iterations(timeout_ms, polls);
    while !runtime_deadline_iteration_cap_reached(&deadline, poll, polls)
        && !runtime_deadline_expired(&mut deadline)
    {
        if usb_read32(op_base + XHCI_USBCMD) & mask == 0 {
            return true;
        }
        runtime_spin(settle_spins);
        poll = poll.saturating_add(1);
    }
    false
}

const fn usb_xhci_reset_command_value(current: u32) -> u32 {
    (current & !XHCI_USBCMD_RUN) | XHCI_USBCMD_HCRST
}

fn usb_xhci_reset_with_settle(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    op_base: usize,
) -> bool {
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_RESET_BEGIN, aux0);
    let halt_command = usb_read32(op_base + XHCI_USBCMD) & !XHCI_USBCMD_RUN;
    usb_write32(op_base + XHCI_USBCMD, halt_command);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_USBCMD,
        halt_command,
    ) {
        return false;
    }
    if !usb_wait_status_with_settle(
        op_base,
        XHCI_USBSTS_HCH,
        XHCI_USBSTS_HCH,
        USB_XHCI_RESET_WAIT_TIMEOUT_MS,
        USB_XHCI_RESET_WAIT_POLLS,
        USB_XHCI_RESET_WAIT_SETTLE_SPINS,
    ) {
        return false;
    }
    let reset_command = usb_xhci_reset_command_value(usb_read32(op_base + XHCI_USBCMD));
    usb_write32(op_base + XHCI_USBCMD, reset_command);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_USBCMD,
        reset_command,
    ) {
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_RESET_WAIT_BEGIN,
        aux0,
    );
    if !usb_wait_command_clear_with_settle(
        op_base,
        XHCI_USBCMD_HCRST,
        USB_XHCI_RESET_WAIT_TIMEOUT_MS,
        USB_XHCI_RESET_WAIT_POLLS,
        USB_XHCI_RESET_WAIT_SETTLE_SPINS,
    ) {
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CNR_WAIT_BEGIN,
        aux0,
    );
    usb_wait_status_with_settle(
        op_base,
        XHCI_USBSTS_CNR,
        0,
        USB_XHCI_RESET_WAIT_TIMEOUT_MS,
        USB_XHCI_RESET_WAIT_POLLS,
        USB_XHCI_RESET_WAIT_SETTLE_SPINS,
    )
}

#[inline(never)]
fn usb_runtime_prepare_controller(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
    state: &mut UsbRuntimeState,
) -> UsbControllerPrepare {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return UsbControllerPrepare::Fault;
    };
    if dma_range.page_count < USB_REQUIRED_DMA_PAGES {
        return UsbControllerPrepare::Fault;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_RANGE_READY,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CAPS_READ_BEGIN,
        aux0,
    );
    let cap_length = usb_read8(XHCI_CAPLENGTH);
    let hcs1 = usb_read32(XHCI_HCSPARAMS1);
    let hcs2 = usb_read32(XHCI_HCSPARAMS2);
    let hcc = usb_read32(XHCI_HCCPARAMS1);
    let db_offset = usb_read32(XHCI_DBOFF) & !0x3;
    let rt_offset = usb_read32(XHCI_RTSOFF) & !0x1f;
    let max_slots = (hcs1 & 0xff) as u8;
    let max_ports = ((hcs1 >> 24) & 0xff) as u8;
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_CAPS_READ, aux0);
    if cap_length == 0 || max_slots == 0 || max_ports == 0 || db_offset == 0 || rt_offset == 0 {
        #[cfg(not(target_os = "none"))]
        {
            state.cap_length = 0x40;
            state.max_slots = 32;
            state.max_ports = 4;
            state.db_offset = 0x1000;
            state.rt_offset = 0x2000;
            state.context_bytes = 32;
            usb_reset_enumeration_cursor(state);
            return UsbControllerPrepare::Ready(DRIVER_RUNTIME_USB_INIT_DETAIL_XHCI_READY);
        }
        #[cfg(target_os = "none")]
        {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_USB_CAPS_INVALID,
                aux0,
            );
            return UsbControllerPrepare::Fault;
        }
    }
    let op_base = cap_length as usize;
    state.context_bytes = if hcc & (1 << 2) != 0 { 64 } else { 32 };
    state.scratchpad_count = (((hcs2 >> 27) & 0x1f) | ((hcs2 >> 16) & 0x3e0)) as usize;
    state.cap_length = cap_length;
    state.max_slots = max_slots;
    state.max_ports = max_ports;
    state.db_offset = db_offset;
    state.rt_offset = rt_offset;
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_HALT_BEGIN, aux0);
    let halt_command = usb_read32(op_base + XHCI_USBCMD) & !XHCI_USBCMD_RUN;
    usb_write32(op_base + XHCI_USBCMD, halt_command);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_USBCMD,
        halt_command,
    ) {
        return UsbControllerPrepare::Fault;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HALT_WAIT_BEGIN,
        aux0,
    );
    if !usb_wait_status(op_base, XHCI_USBSTS_HCH, XHCI_USBSTS_HCH) {
        return UsbControllerPrepare::Fault;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_HALTED, aux0);
    let mut reset_attempt = 0usize;
    while reset_attempt < USB_XHCI_RESET_ATTEMPTS {
        if usb_xhci_reset_with_settle(sequence, aux0, state, op_base) {
            break;
        }
        reset_attempt = reset_attempt.saturating_add(1);
        if reset_attempt >= USB_XHCI_RESET_ATTEMPTS {
            return UsbControllerPrepare::Fault;
        }
        runtime_spin(USB_XHCI_RESET_WAIT_SETTLE_SPINS.saturating_mul(16));
    }
    if reset_attempt >= USB_XHCI_RESET_ATTEMPTS {
        return UsbControllerPrepare::Fault;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_RESET_DONE, aux0);
    UsbControllerPrepare::Dma(dma_range)
}

#[inline(never)]
fn usb_runtime_configure_controller(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
    state: &mut UsbRuntimeState,
) -> Option<u16> {
    let dma_range = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    )?;
    let op_base = state.cap_length as usize;
    let max_slots = state.max_slots;
    let rt_offset = state.rt_offset;
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_DMA_READY, aux0);
    let Some(dcbaa) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_DCBBA_OFFSET) else {
        return None;
    };
    let Some(cmd_ring) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_COMMAND_RING_OFFSET)
    else {
        return None;
    };
    let Some(event_ring) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_EVENT_RING_OFFSET)
    else {
        return None;
    };
    let Some(erst) = xhci_dma_bus_addr(descriptor, dma_range, XHCI_DMA_ERST_OFFSET) else {
        return None;
    };
    xhci_dma_publish_barrier();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_BEGIN,
        aux0,
    );
    usb_write32(op_base + XHCI_CONFIG, max_slots as u32);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_WRITTEN,
        aux0,
    );
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_CONFIG,
        max_slots as u32,
    ) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_FLUSHED,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DCBAAP_BEGIN,
        aux0,
    );
    if !xhci_write64_flush_posted(
        sequence,
        aux0,
        state,
        op_base + XHCI_DCBAAP,
        dcbaa,
        XHCI_FLUSH_STAGE_INIT_LOW,
        XHCI_FLUSH_STAGE_INIT_HIGH,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DCBAAP_LOW_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DCBAAP_HIGH_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DCBAAP_HIGH_FLUSHED,
    ) {
        return None;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_CRCR_BEGIN, aux0);
    if !xhci_write64_flush_posted(
        sequence,
        aux0,
        state,
        op_base + XHCI_CRCR,
        cmd_ring | 1,
        XHCI_FLUSH_STAGE_INIT_LOW,
        XHCI_FLUSH_STAGE_INIT_HIGH,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CRCR_LOW_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CRCR_HIGH_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_CRCR_HIGH_FLUSHED,
    ) {
        return None;
    }
    let int_base = rt_offset as usize + 0x20;
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERSTSZ_BEGIN,
        aux0,
    );
    usb_write32(int_base + XHCI_ERSTSZ, 1);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        int_base + XHCI_ERSTSZ,
        1,
    ) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERSTBA_BEGIN,
        aux0,
    );
    if !xhci_write64_flush_posted(
        sequence,
        aux0,
        state,
        int_base + XHCI_ERSTBA,
        erst,
        XHCI_FLUSH_STAGE_INIT_LOW,
        XHCI_FLUSH_STAGE_INIT_HIGH,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERSTBA_LOW_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERSTBA_HIGH_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERSTBA_HIGH_FLUSHED,
    ) {
        return None;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_ERDP_BEGIN, aux0);
    if !xhci_write64_flush_posted(
        sequence,
        aux0,
        state,
        int_base + XHCI_ERDP,
        event_ring,
        XHCI_FLUSH_STAGE_ERDP_LOW,
        XHCI_FLUSH_STAGE_ERDP_HIGH,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERDP_LOW_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERDP_HIGH_WRITTEN,
        DRIVER_RUNTIME_RING_PROGRESS_USB_ERDP_HIGH_FLUSHED,
    ) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_SCRATCHPAD_BEGIN,
        aux0,
    );
    if !xhci_publish_scratchpad_structures(sequence, aux0, state, descriptor, dma_range) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_DNCTRL_BEGIN,
        aux0,
    );
    usb_write32(op_base + XHCI_DNCTRL, 0);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_DNCTRL,
        0,
    ) {
        return None;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_RINGS_READY, aux0);
    dma_store_barrier();
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_RUN_BEGIN, aux0);
    usb_write32(op_base + XHCI_USBCMD, XHCI_USBCMD_RUN);
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        op_base + XHCI_USBCMD,
        XHCI_USBCMD_RUN,
    ) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_RUN_WAIT_BEGIN,
        aux0,
    );
    if !usb_wait_status(op_base, XHCI_USBSTS_HCH, 0) {
        return None;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_RUN_REQUESTED,
        aux0,
    );
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_IMOD_BEGIN, aux0);
    usb_write32(int_base + XHCI_IMOD, xhci_poll_only_interrupter_imod());
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        int_base + XHCI_IMOD,
        xhci_poll_only_interrupter_imod(),
    ) {
        return None;
    }
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_IMAN_BEGIN, aux0);
    usb_write32(int_base + XHCI_IMAN, xhci_poll_only_interrupter_iman());
    if !xhci_flush_posted_write_progress(
        sequence,
        aux0,
        state,
        XHCI_FLUSH_STAGE_INIT,
        int_base + XHCI_IMAN,
        xhci_poll_only_interrupter_iman(),
    ) {
        return None;
    }
    state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_XHCI_READY;
    Some(DRIVER_RUNTIME_USB_INIT_DETAIL_XHCI_READY)
}

#[inline(never)]
#[cfg(not(target_os = "none"))]
fn usb_runtime_init_hw(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
    state: &mut UsbRuntimeState,
) -> Option<u16> {
    let dma_range = match usb_runtime_prepare_controller(sequence, aux0, descriptor, state) {
        UsbControllerPrepare::Dma(dma_range) => dma_range,
        UsbControllerPrepare::Ready(detail) => return Some(detail),
        UsbControllerPrepare::Fault => return None,
    };
    if !xhci_prepare_dma_structures(sequence, aux0, state, descriptor, dma_range) {
        return None;
    }
    usb_runtime_configure_controller(sequence, aux0, descriptor, state)
}

#[cfg(target_os = "none")]
fn pcie_read32(offset: usize) -> u32 {
    // SAFETY: `service_pcie_root` validates offset alignment and bounds against
    // the mapped PCIe/VL805 MMIO aperture before this read.
    unsafe { core::ptr::read_volatile((DRIVER_TASK_DEVICE_MMIO_VADDR + offset) as *const u32) }
}

#[cfg(not(target_os = "none"))]
fn pcie_read32(_offset: usize) -> u32 {
    0
}

#[cfg(target_os = "none")]
fn pcie_write32(offset: usize, value: u32) {
    // SAFETY: `service_pcie_root` validates offset alignment and bounds against
    // the mapped PCIe/VL805 MMIO aperture before this write.
    unsafe {
        core::ptr::write_volatile((DRIVER_TASK_DEVICE_MMIO_VADDR + offset) as *mut u32, value);
    }
}

#[cfg(not(target_os = "none"))]
fn pcie_write32(_offset: usize, _value: u32) {}

fn pcie_runtime_init_hw(state: &mut PcieRuntimeState) -> bool {
    #[cfg(not(target_os = "none"))]
    {
        state.link_ready = true;
        state.cfg_vendor_device = PCIE_VL805_PCI_VENDOR_DEVICE;
        state.cfg_class_revision = PCIE_VL805_EXPECTED_CLASS_REV;
        true
    }
    #[cfg(target_os = "none")]
    {
        // PCIe/VL805 reset, bridge windows, IRQ quiesce, and config writes are
        // HAL-owned resource-initialization steps. The isolated PCIe runtime
        // adopts the HAL-published aperture and then serves bounded port
        // operations; it must not repeat root-complex setup from the child TCB.
        let descriptor = RUNTIME_DESCRIPTOR.load();
        if !descriptor_resources_ready(&descriptor, HOT_PATH_PCIE_ROOT) {
            return false;
        }
        state.last_status = PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP;
        state.link_ready = true;
        state.cfg_vendor_device = PCIE_VL805_PCI_VENDOR_DEVICE;
        state.cfg_class_revision = PCIE_VL805_EXPECTED_CLASS_REV;
        true
    }
}

#[cfg(target_os = "none")]
fn pcie_runtime_flush_vl805_posted_write() -> bool {
    pcie_write32(PCIE_EXT_CFG_INDEX, PCIE_VL805_PCI_DEV_ADDR);
    let selected = pcie_read32(PCIE_EXT_CFG_INDEX);
    if selected != PCIE_VL805_PCI_DEV_ADDR {
        return false;
    }
    let command_status = pcie_read32(PCIE_EXT_CFG_DATA + PCIE_CFG_COMMAND_STATUS);
    if command_status == 0 || command_status == u32::MAX || command_status == selected {
        return false;
    }
    let _ = pcie_read32(PCIE_EXT_CFG_DATA + PCIE_CFG_BAR0);
    let _ = pcie_read32(PCIE_EXT_CFG_DATA + PCIE_CFG_BAR1);
    let status = pcie_read32(PCIE_MISC_PCIE_STATUS);
    status & (PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP)
        == (PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP)
}

#[cfg(not(target_os = "none"))]
fn pcie_runtime_flush_vl805_posted_write() -> bool {
    true
}

#[cfg(target_os = "none")]
fn sdio_read32(offset: usize) -> u32 {
    // SAFETY: The SDIO runtime maps the declared SDHCI MMIO page at
    // `DRIVER_TASK_DEVICE_MMIO_VADDR`; all offsets used by callers are bounded
    // register constants within that page.
    let value =
        unsafe { core::ptr::read_volatile((DRIVER_TASK_DEVICE_MMIO_VADDR + offset) as *const u32) };
    // Match Linux readl() ordering: no later memory access may be observed
    // before the device register value that authorizes it.
    dma_load_barrier();
    value
}

#[cfg(not(target_os = "none"))]
fn sdio_read32(_offset: usize) -> u32 {
    #[cfg(test)]
    {
        if _offset == SDHCI_INT_STATUS {
            let zero_read = TEST_SDIO_HOST_INT_STATUS_ZERO_READS_REMAINING
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |remaining| {
                    remaining.checked_sub(1)
                })
                .is_ok();
            if zero_read {
                return 0;
            }
            return TEST_SDIO_HOST_INT_STATUS_RESPONSE.load(Ordering::Acquire);
        }
        if _offset == SDHCI_INT_ENABLE {
            return TEST_SDIO_HOST_INT_ENABLE_RESPONSE.load(Ordering::Acquire);
        }
        if _offset == SDHCI_SIGNAL_ENABLE {
            return TEST_SDIO_HOST_SIGNAL_ENABLE_RESPONSE.load(Ordering::Acquire);
        }
    }
    0
}

#[cfg(target_os = "none")]
fn sdio_write32(offset: usize, value: u32) {
    // Raspberry Pi's `mmc-bcm2835` WiFi host integration is 32-bit-only and
    // delays every ordinary register write by at least two clocks at the
    // current SD clock, floored at 400 kHz. FIFO writes use the separate raw
    // path below, matching Linux's `mmc_raw_writel()`.
    // SAFETY: The SDIO runtime maps the declared SDHCI MMIO page at
    // `DRIVER_TASK_DEVICE_MMIO_VADDR`; all offsets used by callers are bounded
    // aligned register constants within that page.
    // Match Linux writel() ordering: publish all preceding memory accesses
    // before the controller observes this register update.
    dma_store_barrier();
    unsafe {
        core::ptr::write_volatile((DRIVER_TASK_DEVICE_MMIO_VADDR + offset) as *mut u32, value);
    }
    // Make the store globally observable before starting the two-current-clock
    // settle interval so a linked-runtime quantum cannot collapse adjacent
    // register writes into the controller's unsupported spacing window.
    device_store_completion_barrier();
    let delay_us = sdio_bcm2835_post_write_delay_us(SDIO_ACTIVE_CLOCK_HZ.load(Ordering::Acquire));
    runtime_settle_micros(
        delay_us,
        (delay_us as usize).saturating_mul(SDHCI_INIT_SPINS / 1_000),
    );
}

#[cfg(not(target_os = "none"))]
fn sdio_write32(_offset: usize, _value: u32) {
    #[cfg(test)]
    {
        if _offset == SDHCI_INT_STATUS {
            let clear_delayed = TEST_SDIO_HOST_INT_STATUS_W1C_FAILURES_REMAINING
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |remaining| {
                    remaining.checked_sub(1)
                })
                .is_ok();
            if !clear_delayed {
                let _ = TEST_SDIO_HOST_INT_STATUS_RESPONSE.fetch_and(!_value, Ordering::AcqRel);
            }
        } else if _offset == SDHCI_INT_ENABLE {
            TEST_SDIO_HOST_INT_ENABLE_RESPONSE.store(_value, Ordering::Release);
        } else if _offset == SDHCI_SIGNAL_ENABLE {
            TEST_SDIO_HOST_SIGNAL_ENABLE_RESPONSE.store(_value, Ordering::Release);
        }
    }
}

#[cfg(target_os = "none")]
fn sdio_write_buffer32(value: u32) {
    // Linux writes the bcm2835 SDHCI FIFO without the ordinary two-SD-clock
    // register delay. The retained owner has already consumed the request's
    // direction-matched ready edge and PRESENT_STATE ownership before this
    // bounded host-block quantum.
    dma_store_barrier();
    // SAFETY: HAL admission maps the bounded SDHCI page only into the SDIO
    // runtime, and SDHCI_BUFFER is an aligned register inside that aperture.
    unsafe {
        core::ptr::write_volatile(
            (DRIVER_TASK_DEVICE_MMIO_VADDR + SDHCI_BUFFER) as *mut u32,
            value,
        );
    }
}

#[cfg(not(target_os = "none"))]
fn sdio_write_buffer32(_value: u32) {}

const fn sdio_merge_u16_word(word: u32, offset: usize, value: u16) -> u32 {
    let shift = ((offset & 0x2) * 8) as u32;
    let mask = 0xffff_u32 << shift;
    (word & !mask) | ((value as u32) << shift)
}

const fn sdio_extract_u16_word(word: u32, offset: usize) -> u16 {
    ((word >> (((offset & 0x2) * 8) as u32)) & 0xffff) as u16
}

const fn sdio_extract_u8_word(word: u32, offset: usize) -> u8 {
    ((word >> (((offset & 0x3) * 8) as u32)) & 0xff) as u8
}

const fn sdio_merge_u8_word(word: u32, offset: usize, value: u8) -> u32 {
    let shift = ((offset & 0x3) * 8) as u32;
    let mask = 0xff_u32 << shift;
    (word & !mask) | ((value as u32) << shift)
}

const fn sdio_bcm2835_post_write_delay_us(clock_hz: u32) -> u32 {
    let effective_hz = if clock_hz < BCM2835_SDIO_MIN_CLOCK_HZ {
        BCM2835_SDIO_MIN_CLOCK_HZ
    } else {
        clock_hz
    };
    (2_000_000 / effective_hz).saturating_add(1)
}

#[cfg(target_os = "none")]
fn sdio_read16(offset: usize) -> u16 {
    let word = if offset == SDHCI_TRANSFER_MODE
        && SDIO_TRANSFER_MODE_SHADOW_VALID.load(Ordering::Acquire)
    {
        SDIO_TRANSFER_MODE_SHADOW.load(Ordering::Acquire)
    } else {
        sdio_read32(offset & !0x3)
    };
    sdio_extract_u16_word(word, offset)
}

#[cfg(not(target_os = "none"))]
fn sdio_read16(_offset: usize) -> u16 {
    #[cfg(test)]
    if _offset == SDHCI_CLOCK_CONTROL && !TEST_SDIO_HOST_CLOCK_STABLE.load(Ordering::Acquire) {
        return 0;
    }
    SDHCI_CLOCK_INT_STABLE
}

#[cfg(target_os = "none")]
fn sdio_write16(offset: usize, value: u16) {
    let aligned = offset & !0x3;
    if offset == SDHCI_COMMAND {
        let word = SDIO_TRANSFER_MODE_SHADOW.load(Ordering::Acquire);
        SDIO_TRANSFER_MODE_SHADOW_VALID.store(false, Ordering::Release);
        sdio_write32(aligned, sdio_merge_u16_word(word, offset, value));
        return;
    }
    if offset == SDHCI_TRANSFER_MODE {
        let word = if SDIO_TRANSFER_MODE_SHADOW_VALID.load(Ordering::Acquire) {
            SDIO_TRANSFER_MODE_SHADOW.load(Ordering::Acquire)
        } else {
            sdio_read32(aligned)
        };
        SDIO_TRANSFER_MODE_SHADOW
            .store(sdio_merge_u16_word(word, offset, value), Ordering::Release);
        SDIO_TRANSFER_MODE_SHADOW_VALID.store(true, Ordering::Release);
        return;
    }
    let word = sdio_read32(aligned);
    sdio_write32(aligned, sdio_merge_u16_word(word, offset, value));
}

#[cfg(not(target_os = "none"))]
fn sdio_write16(_offset: usize, _value: u16) {}

#[cfg(target_os = "none")]
fn sdio_read8(offset: usize) -> u8 {
    sdio_extract_u8_word(sdio_read32(offset & !0x3), offset)
}

#[cfg(not(target_os = "none"))]
fn sdio_read8(offset: usize) -> u8 {
    if offset == SDHCI_SOFTWARE_RESET {
        #[cfg(test)]
        {
            return TEST_SDIO_HOST_RESET_STUCK_MASK.load(Ordering::Acquire) as u8;
        }
        #[cfg(not(test))]
        {
            0
        }
    } else if offset == SDHCI_POWER_CONTROL {
        SDHCI_POWER_330 | SDHCI_POWER_ON
    } else {
        0
    }
}

#[cfg(target_os = "none")]
fn sdio_write8(offset: usize, value: u8) {
    let aligned = offset & !0x3;
    let word = sdio_read32(aligned);
    sdio_write32(aligned, sdio_merge_u8_word(word, offset, value));
}

#[cfg(not(target_os = "none"))]
fn sdio_write8(_offset: usize, _value: u8) {}

fn sdio_software_reset_until_with<I: SdioTransferIo>(
    io: &mut I,
    mask: u8,
    deadline: &mut RuntimeDeadline,
) -> bool {
    io.write8(SDHCI_SOFTWARE_RESET, mask);
    if mask & SDHCI_RESET_ALL != 0 {
        // Match bcm2835_mmc_reset(): issue RESET_ALL using the current write
        // timing, then invalidate the host clock cache immediately. Every
        // subsequent register write uses the 400 kHz floor and the next
        // set_ios turn must reprogram the clock.
        SDIO_ACTIVE_CLOCK_HZ.store(0, Ordering::Release);
        SDIO_REQUESTED_CLOCK_HZ.store(0, Ordering::Release);
        SDIO_TRANSFER_MODE_SHADOW.store(0, Ordering::Release);
        SDIO_TRANSFER_MODE_SHADOW_VALID.store(false, Ordering::Release);
    }
    if io.injected_reset_failure(mask) {
        return false;
    }
    while !io.deadline_expired(deadline) {
        if io.read8(SDHCI_SOFTWARE_RESET) & mask == 0 {
            return true;
        }
        io.poll_pause();
    }
    false
}

fn sdio_wait_for_int_clock_stable_with<I: SdioTransferIo>(io: &mut I) -> bool {
    let mut deadline = runtime_deadline_from_millis_or_iterations(
        BCM2835_SDIO_CLOCK_STABLE_TIMEOUT_MS,
        BCM2835_SDIO_CLOCK_STABLE_FALLBACK_POLLS,
    );
    while !io.deadline_expired(&mut deadline) {
        if io.read16(SDHCI_CLOCK_CONTROL) & SDHCI_CLOCK_INT_STABLE != 0 {
            return true;
        }
        io.poll_pause();
    }
    false
}

fn sdhci_spec300_divider_for_base_clock(base_clock_hz: u32, target_hz: u32) -> u16 {
    if base_clock_hz <= target_hz {
        1
    } else {
        let mut div = 2u16;
        while div < 2046 && (base_clock_hz / u32::from(div)) > target_hz {
            div = div.saturating_add(2);
        }
        div
    }
}

fn sdio_clock_divider_with<I: SdioTransferIo>(io: &mut I, target_hz: u32) -> u16 {
    let version = io.read16(SDHCI_HOST_VERSION) & SDHCI_SPEC_VER_MASK;
    if version >= SDHCI_SPEC_300 {
        sdhci_spec300_divider_for_base_clock(BCM2711_SDIO_EFFECTIVE_BASE_CLOCK_HZ, target_hz)
    } else {
        let mut div = 1u16;
        while div < 256 && (BCM2711_SDIO_EFFECTIVE_BASE_CLOCK_HZ / u32::from(div)) > target_hz {
            div = div.saturating_mul(2);
        }
        div
    }
}

fn sdio_set_clock_hz_with<I: SdioTransferIo>(io: &mut I, target_hz: u32) -> bool {
    if target_hz == 0 {
        SDIO_ACTIVE_CLOCK_HZ.store(0, Ordering::Release);
        SDIO_REQUESTED_CLOCK_HZ.store(0, Ordering::Release);
        io.write16(SDHCI_CLOCK_CONTROL, 0);
        return true;
    }
    let divider = sdio_clock_divider_with(io, target_hz.max(1));
    let encoded_divider = divider >> 1;
    let mut clock = SDHCI_CLOCK_INT_EN;
    clock |= (encoded_divider & SDHCI_DIV_MASK) << SDHCI_DIVIDER_SHIFT;
    clock |= ((encoded_divider & SDHCI_DIV_HI_MASK) >> 8) << SDHCI_DIVIDER_HI_SHIFT;
    io.write16(SDHCI_CLOCK_CONTROL, 0);
    io.write16(SDHCI_CLOCK_CONTROL, clock);
    if !sdio_wait_for_int_clock_stable_with(io) {
        SDIO_ACTIVE_CLOCK_HZ.store(0, Ordering::Release);
        SDIO_REQUESTED_CLOCK_HZ.store(0, Ordering::Release);
        return false;
    }
    io.write16(SDHCI_CLOCK_CONTROL, clock | SDHCI_CLOCK_CARD_EN);
    SDIO_ACTIVE_CLOCK_HZ.store(
        BCM2711_SDIO_EFFECTIVE_BASE_CLOCK_HZ / u32::from(divider.max(1)),
        Ordering::Release,
    );
    SDIO_REQUESTED_CLOCK_HZ.store(target_hz, Ordering::Release);
    true
}

#[cfg(test)]
fn sdio_recover_command_path() -> bool {
    let mut deadline = runtime_deadline_from_millis_or_iterations(
        BCM2835_SDIO_RECOVERY_TIMEOUT_MS,
        BCM2835_SDIO_RECOVERY_FALLBACK_POLLS,
    );
    sdio_recover_command_path_until(&mut deadline)
}

fn sdio_recovery_settle_until_with<I: SdioTransferIo>(
    io: &mut I,
    settle_us: u32,
    fallback_iterations: usize,
    owner_deadline: &mut RuntimeDeadline,
) -> bool {
    let mut settle_deadline =
        runtime_deadline_from_micros_or_legacy_spins(settle_us, fallback_iterations);
    while !io.deadline_expired(owner_deadline) {
        if io.deadline_expired(&mut settle_deadline) {
            return true;
        }
        io.poll_pause();
    }
    false
}

#[cfg(test)]
fn sdio_recovery_clock_cycle_until(clock: u16, owner_deadline: &mut RuntimeDeadline) -> bool {
    let mut io = SdioMmioTransferIo;
    sdio_recovery_clock_cycle_until_with(&mut io, clock, owner_deadline)
}

fn sdio_recovery_clock_cycle_until_with<I: SdioTransferIo>(
    io: &mut I,
    clock: u16,
    owner_deadline: &mut RuntimeDeadline,
) -> bool {
    io.write16(SDHCI_CLOCK_CONTROL, clock & !SDHCI_CLOCK_CARD_EN);
    let settled = sdio_recovery_settle_until_with(
        io,
        SDHCI_CLOCK_RECOVERY_SETTLE_US,
        SDHCI_CLOCK_RECOVERY_SETTLE_SPINS,
        owner_deadline,
    );
    // Restore the saved clock on every exit path. A containment timeout must
    // not turn a recoverable command fault into a permanently disabled card.
    io.write16(SDHCI_CLOCK_CONTROL, clock);
    settled
}

#[cfg(test)]
fn sdio_recover_command_path_until(owner_deadline: &mut RuntimeDeadline) -> bool {
    let mut io = SdioMmioTransferIo;
    sdio_recover_command_path_until_with(&mut io, owner_deadline)
}

fn sdio_recover_command_path_until_with<I: SdioTransferIo>(
    io: &mut I,
    owner_deadline: &mut RuntimeDeadline,
) -> bool {
    // DMA abort and SDHCI recovery share one bounded containment fence, but
    // exhausting that fence must not suppress the immediate host clear/reset.
    // The reset helper issues RESET_CMD | RESET_DATA before consulting the
    // deadline; an already-expired fence therefore performs no polling and
    // receives no replacement time budget.
    let clock = io.read16(SDHCI_CLOCK_CONTROL);
    io.write32(SDHCI_INT_STATUS, SDHCI_INT_COMMAND_DATA_CLEAR_MASK);
    let reset_ok =
        sdio_software_reset_until_with(io, SDHCI_RESET_CMD | SDHCI_RESET_DATA, owner_deadline);
    io.write32(SDHCI_INT_STATUS, SDHCI_INT_COMMAND_DATA_CLEAR_MASK);
    if !sdio_recovery_clock_cycle_until_with(io, clock, owner_deadline) {
        return false;
    }
    let post_clock_reset_ok =
        sdio_software_reset_until_with(io, SDHCI_RESET_CMD | SDHCI_RESET_DATA, owner_deadline);
    io.write32(SDHCI_INT_STATUS, SDHCI_INT_COMMAND_DATA_CLEAR_MASK);
    let present = io.read32(SDHCI_PRESENT_STATE);
    if present & (SDHCI_CMD_INHIBIT | SDHCI_DATA_INHIBIT) != 0
        && !sdio_recovery_clock_cycle_until_with(io, clock, owner_deadline)
    {
        return false;
    }
    reset_ok && post_clock_reset_ok && sdio_wait_inhibit_clear_until_with(io, true, owner_deadline)
}

fn sdio_notification_dpc_ready() -> bool {
    SDIO_RUNTIME_STATE.with_ref(|state| {
        state.dpc_link_ready
            && state.shared_epoch != 0
            && state.irq_handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
            && state.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioCardInterruptRearmResult {
    Rearmed,
    SourcePending(u32),
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioPreissueDpcFenceCondition {
    EmptyMasked,
    EmptyArmed,
    Event(u32),
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioPreissueDpcFenceResult {
    Ready,
    Deferred(u32),
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioRequestIrqPartition {
    NotRequest,
    RequestOnlyAcked(bool),
    RequestAndCard,
}

/// Outcome of the exact BCM2835 DMA channel-4 terminal consumer.
///
/// IRQ116 delivery is both the scheduler wake and the proof that its seL4
/// handler is active. The immutable issued ExternalDma cursor binds that badge
/// to one request before clearing `CS.INT` and releasing the handler mask.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioExternalDmaIrqServiceResult {
    Rejected,
    SourceNotPending,
    SourceClearFailed,
    Acked,
    AckFailed,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioExternalDmaTerminalCommitResult {
    Rejected,
    SourceNotPending,
    SourceClearFailed,
    Committed,
}

#[cfg(any(target_os = "none", test))]
const fn sdio_external_dma_irq_cursor_admitted(
    cursor: SdioExternalDmaRequestCursor,
    shared_epoch: u32,
) -> bool {
    shared_epoch != 0
        && matches!(cursor.phase, SdioExternalDmaRequestPhase::PollIssued)
        && cursor.identity.generation == shared_epoch
        && matches!(cursor.identity.engine, SdioRequestEngine::ExternalDma)
        && cursor.authority.channel_vaddr != 0
        && cursor.issued
        && cursor.request_irq_live
        && !cursor.dma_terminal_interrupt_seen
        && !cursor.dma_irq_ack_failed
}

#[cfg(any(target_os = "none", test))]
const fn sdio_external_dma_late_clear_cursor_admitted(
    cursor: SdioExternalDmaRequestCursor,
    shared_epoch: u32,
) -> bool {
    shared_epoch != 0
        && matches!(cursor.phase, SdioExternalDmaRequestPhase::PollIssued)
        && cursor.identity.generation == shared_epoch
        && matches!(cursor.identity.engine, SdioRequestEngine::ExternalDma)
        && cursor.issued
        && cursor.dma_terminal_interrupt_seen
        && cursor.dma_complete
        && cursor.dma_irq_cs_snapshot & BCM2835_DMA_CS_INT != 0
        && cursor.dma_irq_conblk_snapshot == 0
        && !cursor.dma_irq_acknowledged
        && !cursor.dma_irq_ack_failed
        && !cursor.dma_irq_terminal_invalid
}

/// Commit one exact external-DMA terminal condition without polling or reissue.
///
/// Both the delivered-badge path and the condition-before-sleep path share this
/// one physical-source consumer. It follows Linux's `bcm2835_dma_callback`
/// source order through the durable frontier: snapshot the private channel,
/// W1C `CS.INT` with `INT | ACTIVE`, prove the source clear, and commit terminal
/// evidence. Releasing an activated seL4 handler is deliberately a separate
/// step because a condition sample does not prove that badge 512 was delivered.
#[cfg(any(target_os = "none", test))]
fn sdio_external_dma_terminal_commit_with<I, Commit>(
    mut cursor: SdioExternalDmaRequestCursor,
    shared_epoch: u32,
    io: &mut I,
    mut commit: Commit,
) -> SdioExternalDmaTerminalCommitResult
where
    I: SdioTransferIo,
    Commit: FnMut(SdioExternalDmaRequestCursor),
{
    if !sdio_external_dma_irq_cursor_admitted(cursor, shared_epoch) {
        return SdioExternalDmaTerminalCommitResult::Rejected;
    }

    let channel = cursor.authority.channel_vaddr;
    io.external_dma_load_barrier();
    let dma_cs = io.external_dma_read32(channel + BCM2835_DMA_CS);
    let dma_conblk = io.external_dma_read32(channel + BCM2835_DMA_CONBLK_AD);
    if dma_cs & BCM2835_DMA_CS_INT == 0 {
        // A stale handler delivery cannot borrow the live request's authority.
        // Leave the seL4 source masked so the physical-lifetime watchdog owns
        // fail-closed recovery; do not touch the channel or ACK the cap.
        return SdioExternalDmaTerminalCommitResult::SourceNotPending;
    }

    io.external_dma_write32(
        channel + BCM2835_DMA_CS,
        BCM2835_DMA_CS_INT | BCM2835_DMA_CS_ACTIVE,
    );
    io.external_dma_store_completion_barrier();
    if io.external_dma_read32(channel + BCM2835_DMA_CS) & BCM2835_DMA_CS_INT != 0 {
        cursor.dma_terminal_interrupt_seen = true;
        cursor.dma_complete = false;
        cursor.dma_irq_cs_snapshot = dma_cs;
        cursor.dma_irq_conblk_snapshot = dma_conblk;
        cursor.dma_irq_terminal_invalid = true;
        cursor.failure_snapshot.dma_cs = dma_cs;
        cursor.failure_snapshot.dma_conblk = dma_conblk;
        cursor.failure_snapshot_valid = true;
        // The source was not proven clear, so the handler cap must remain
        // masked. Persist a typed terminal failure so PollIssued enters pair
        // containment instead of later completing with an unusable IRQ lane.
        commit(cursor);
        return SdioExternalDmaTerminalCommitResult::SourceClearFailed;
    }

    cursor.dma_terminal_interrupt_seen = true;
    cursor.dma_complete = dma_conblk == 0;
    cursor.dma_irq_cs_snapshot = dma_cs;
    cursor.dma_irq_conblk_snapshot = dma_conblk;
    cursor.dma_irq_terminal_invalid = dma_conblk != 0;
    cursor.failure_snapshot.dma_cs = dma_cs;
    cursor.failure_snapshot.dma_conblk = dma_conblk;
    cursor.failure_snapshot_valid = true;
    // Commit before any possible IRQHandler_Ack: a redelivery or immediate
    // SDHCI crossing must observe this exact terminal frontier rather than
    // consume CS.INT a second time.
    commit(cursor);
    SdioExternalDmaTerminalCommitResult::Committed
}

/// Consume one badge-delivered external-DMA terminal and release IRQ116.
///
/// Badge delivery proves the seL4 handler is active, so the common physical
/// terminal commit is followed by exactly one `IRQHandler_Ack`. `PollIssued`
/// remains the sole join for SDHCI response/DATA_END and request completion.
#[cfg(any(target_os = "none", test))]
fn sdio_external_dma_irq_service_with<I, Commit, Ack>(
    cursor: SdioExternalDmaRequestCursor,
    shared_epoch: u32,
    io: &mut I,
    mut commit: Commit,
    mut ack: Ack,
) -> SdioExternalDmaIrqServiceResult
where
    I: SdioTransferIo,
    Commit: FnMut(SdioExternalDmaRequestCursor),
    Ack: FnMut() -> bool,
{
    let committed_cursor = core::cell::Cell::new(cursor);
    let mut cursor =
        match sdio_external_dma_terminal_commit_with(cursor, shared_epoch, io, |committed| {
            committed_cursor.set(committed);
            commit(committed);
        }) {
            SdioExternalDmaTerminalCommitResult::Rejected => {
                return SdioExternalDmaIrqServiceResult::Rejected;
            }
            SdioExternalDmaTerminalCommitResult::SourceNotPending => {
                return SdioExternalDmaIrqServiceResult::SourceNotPending;
            }
            SdioExternalDmaTerminalCommitResult::SourceClearFailed => {
                return SdioExternalDmaIrqServiceResult::SourceClearFailed;
            }
            SdioExternalDmaTerminalCommitResult::Committed => committed_cursor.get(),
        };

    if ack() {
        cursor.dma_irq_acknowledged = true;
        commit(cursor);
        SdioExternalDmaIrqServiceResult::Acked
    } else {
        cursor.dma_irq_ack_failed = true;
        commit(cursor);
        SdioExternalDmaIrqServiceResult::AckFailed
    }
}

/// Release a coalesced handler delivery whose channel source was already
/// cleared by the terminal callback before the request cursor was retired.
///
/// This read-only path carries no request authority. Any asserted, active, or
/// erroneous channel state remains masked for fail-closed pair recovery.
#[cfg(any(target_os = "none", test))]
fn sdio_external_dma_late_cleared_irq_with<I, Ack>(
    authority: SdioExternalDmaAuthority,
    io: &mut I,
    mut ack: Ack,
) -> SdioExternalDmaIrqServiceResult
where
    I: SdioTransferIo,
    Ack: FnMut() -> bool,
{
    if authority.channel_vaddr == 0 {
        return SdioExternalDmaIrqServiceResult::Rejected;
    }
    io.external_dma_load_barrier();
    let dma_cs = io.external_dma_read32(authority.channel_vaddr + BCM2835_DMA_CS);
    let dma_conblk = io.external_dma_read32(authority.channel_vaddr + BCM2835_DMA_CONBLK_AD);
    if dma_cs & (BCM2835_DMA_CS_INT | BCM2835_DMA_CS_ERR | BCM2835_DMA_CS_ACTIVE) != 0
        || dma_conblk != 0
    {
        return SdioExternalDmaIrqServiceResult::Rejected;
    }
    if ack() {
        SdioExternalDmaIrqServiceResult::Acked
    } else {
        SdioExternalDmaIrqServiceResult::AckFailed
    }
}

/// Release one delivered badge after an earlier condition-first terminal.
///
/// The badge carries no request identity or history. A condition-first join may
/// already have closed the old episode and a newer DMA may already be active.
/// So long as the current `CS.INT`/error source is clear, ACK only and leave
/// every current-request field untouched; if a current terminal is asserted,
/// the exact cursor consumer must win.
#[cfg(any(target_os = "none", test))]
fn sdio_external_dma_deferred_badge_ack_with<I, Ack>(
    authority: SdioExternalDmaAuthority,
    io: &mut I,
    mut ack: Ack,
) -> SdioExternalDmaIrqServiceResult
where
    I: SdioTransferIo,
    Ack: FnMut() -> bool,
{
    if authority.channel_vaddr == 0 {
        return SdioExternalDmaIrqServiceResult::Rejected;
    }
    io.external_dma_load_barrier();
    let dma_cs = io.external_dma_read32(authority.channel_vaddr + BCM2835_DMA_CS);
    if dma_cs & (BCM2835_DMA_CS_INT | BCM2835_DMA_CS_ERR) != 0 {
        return SdioExternalDmaIrqServiceResult::Rejected;
    }
    if ack() {
        SdioExternalDmaIrqServiceResult::Acked
    } else {
        SdioExternalDmaIrqServiceResult::AckFailed
    }
}

const SDIO_CARD_INTERRUPT_REARM_INT_VERIFY_MASK: u32 =
    SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_PIO_READY_MASK | SDHCI_INT_CARD_INT;

const fn sdio_interrupt_policy_registers(dpc_ready: bool, card_irq_masked: bool) -> (u32, u32) {
    let card_enable = if dpc_ready && !card_irq_masked {
        SDHCI_INT_CARD_INT
    } else {
        0
    };
    // This is the idle policy. One retained request replaces the broad request
    // portion with its exact command/data engine mask in both INT_ENABLE and
    // SIGNAL_ENABLE, while CARD_INT remains an independent DPC source.
    (SDHCI_INT_BCM2835_DMA_ENABLE_MASK | card_enable, card_enable)
}

const SDHCI_INT_REQUEST_POLICY_MASK: u32 =
    SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_PIO_READY_MASK;

const fn sdhci_request_interrupt_mask(identity: SdioExternalDmaRequestIdentity) -> u32 {
    match identity.engine {
        SdioRequestEngine::CommandOnly => SDHCI_INT_CMD_MASK,
        SdioRequestEngine::Pio => {
            (SDHCI_INT_BCM2835_DMA_ENABLE_MASK & !SDHCI_INT_BCM2835_PIO_EXCLUDED_MASK)
                | sdhci_pio_interrupt_ready_mask(identity.write)
        }
        SdioRequestEngine::ExternalDma => SDHCI_INT_BCM2835_DMA_ENABLE_MASK,
    }
}

const fn sdio_request_interrupt_policy_registers(
    base_int_enable: u32,
    base_signal_enable: u32,
    cursor: SdioExternalDmaRequestCursor,
) -> (u32, u32) {
    if !cursor.request_irq_live {
        return (base_int_enable, base_signal_enable);
    }
    let request = sdhci_request_interrupt_mask(cursor.identity);
    let int_enable = (base_int_enable & !SDHCI_INT_REQUEST_POLICY_MASK) | request;
    let signal_enable = base_signal_enable
        | if cursor.request_irq_masked {
            0
        } else {
            request
        };
    (int_enable, signal_enable)
}

fn sdio_current_interrupt_policy_registers(dpc_ready: bool, card_irq_masked: bool) -> (u32, u32) {
    let (base_int_enable, base_signal_enable) =
        sdio_interrupt_policy_registers(dpc_ready, card_irq_masked);
    let cursor = SDIO_RUNTIME_STATE.with_ref(|state| state.external_dma_request);
    sdio_request_interrupt_policy_registers(base_int_enable, base_signal_enable, cursor)
}

fn sdio_program_interrupt_policy() {
    let mut io = SdioMmioTransferIo;
    sdio_program_interrupt_policy_with(&mut io);
}

fn sdio_program_interrupt_policy_with<I: SdioTransferIo>(io: &mut I) {
    let dpc_ready = sdio_notification_dpc_ready();
    let card_irq_masked = SDIO_RUNTIME_STATE.with_ref(|state| state.card_irq_masked);
    let (int_enable, signal_enable) =
        sdio_current_interrupt_policy_registers(dpc_ready, card_irq_masked);
    io.write32(SDHCI_INT_ENABLE, int_enable);
    io.write32(SDHCI_SIGNAL_ENABLE, signal_enable);
}

fn sdio_partition_request_irq_with<I, A>(
    io: &mut I,
    host_int_status: u32,
    ack: A,
) -> SdioRequestIrqPartition
where
    I: SdioTransferIo,
    A: FnOnce(&mut I) -> bool,
{
    let signal_enable = SDIO_RUNTIME_STATE.with_mut(|state| {
        let mut cursor = state.external_dma_request;
        if !cursor.request_irq_live
            || host_int_status & sdhci_request_interrupt_mask(cursor.identity) == 0
        {
            return None;
        }

        // INT_STATUS remains the immutable request owner's evidence. Suppress
        // only this request's kernel signal before acknowledging the shared IRQ
        // cap; PollIssued will take the snapshot, perform the sole W1C, and
        // rearm the same exact signal set if the request is still pending.
        cursor.request_irq_masked = true;
        state.external_dma_request = cursor;
        let dpc_ready = state.dpc_link_ready
            && state.shared_epoch != 0
            && state.irq_handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
            && state.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT;
        let (base_int_enable, base_signal_enable) =
            sdio_interrupt_policy_registers(dpc_ready, state.card_irq_masked);
        let (_, signal_enable) =
            sdio_request_interrupt_policy_registers(base_int_enable, base_signal_enable, cursor);
        Some(signal_enable)
    });
    let Some(signal_enable) = signal_enable else {
        return SdioRequestIrqPartition::NotRequest;
    };

    io.write32(SDHCI_SIGNAL_ENABLE, signal_enable);
    if host_int_status & SDHCI_INT_CARD_INT != 0 {
        SdioRequestIrqPartition::RequestAndCard
    } else {
        SdioRequestIrqPartition::RequestOnlyAcked(ack(io))
    }
}

fn sdio_card_interrupt_policy_readback_matches(
    int_enable: u32,
    signal_enable: u32,
    expected_int_enable: u32,
    expected_signal_enable: u32,
) -> bool {
    int_enable & SDIO_CARD_INTERRUPT_REARM_INT_VERIFY_MASK
        == expected_int_enable & SDIO_CARD_INTERRUPT_REARM_INT_VERIFY_MASK
        && signal_enable & SDIO_CARD_INTERRUPT_REARM_INT_VERIFY_MASK
            == expected_signal_enable & SDIO_CARD_INTERRUPT_REARM_INT_VERIFY_MASK
}

fn sdio_write_card_interrupt_masked_policy_with<I: SdioTransferIo>(
    io: &mut I,
    masked_int: u32,
    masked_signal: u32,
) -> bool {
    io.write32(SDHCI_SIGNAL_ENABLE, masked_signal);
    io.write32(SDHCI_INT_ENABLE, masked_int);
    let signal_readback = io.read32(SDHCI_SIGNAL_ENABLE);
    let int_readback = io.read32(SDHCI_INT_ENABLE);
    sdio_card_interrupt_policy_readback_matches(
        int_readback,
        signal_readback,
        masked_int,
        masked_signal,
    )
}

fn sdio_fail_card_interrupt_rearm_with<I: SdioTransferIo>(
    io: &mut I,
    masked_int: u32,
    masked_signal: u32,
) -> SdioCardInterruptRearmResult {
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.dpc_poisoned = true;
        state.dpc_activation_allowed = false;
    });
    let _ = sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal);
    sdio_record_dpc_health(false);
    SdioCardInterruptRearmResult::Fault
}

fn sdio_rearm_card_interrupt_with<I: SdioTransferIo>(io: &mut I) -> SdioCardInterruptRearmResult {
    let admitted = SDIO_RUNTIME_STATE.with_ref(|state| {
        state.card_irq_masked
            && !state.irq_ack_pending
            && !state.dpc_poisoned
            && state.dpc_activation_allowed
    });
    if !admitted || !sdio_notification_dpc_ready() {
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.card_irq_masked = true;
            state.dpc_poisoned = true;
            state.dpc_activation_allowed = false;
        });
        sdio_program_interrupt_policy_with(io);
        sdio_record_dpc_health(false);
        return SdioCardInterruptRearmResult::Fault;
    }

    let (masked_int, masked_signal) = sdio_current_interrupt_policy_registers(true, true);
    let (unmasked_int, unmasked_signal) = sdio_current_interrupt_policy_registers(true, false);

    let status_before = io.read32(SDHCI_INT_STATUS);
    if status_before & SDHCI_INT_CARD_INT != 0 {
        return if sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal) {
            SdioCardInterruptRearmResult::SourcePending(status_before)
        } else {
            sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal)
        };
    }

    // Establish and read back the masked baseline first. SIGNAL_ENABLE is
    // masked before INT_ENABLE so an already-level source cannot notify the
    // kernel between the two writes. The request-owned PIO ready bit, if any,
    // remains present in INT_ENABLE throughout the transition; its SIGNAL bit
    // remains in the exact armed/masked state owned by the request cursor.
    if !sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal) {
        return sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal);
    }

    // First expose the retained level to INT_STATUS while kernel signalling is
    // still disabled. This closes the condition-before-sleep race for a source
    // that was already asserted while CARD_INT was masked.
    io.write32(SDHCI_INT_ENABLE, unmasked_int);
    let int_readback = io.read32(SDHCI_INT_ENABLE);
    let signal_readback = io.read32(SDHCI_SIGNAL_ENABLE);
    if !sdio_card_interrupt_policy_readback_matches(
        int_readback,
        signal_readback,
        unmasked_int,
        masked_signal,
    ) {
        return sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal);
    }
    let status_after_int_enable = io.read32(SDHCI_INT_STATUS);
    if status_after_int_enable & SDHCI_INT_CARD_INT != 0 {
        return if sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal) {
            SdioCardInterruptRearmResult::SourcePending(status_after_int_enable)
        } else {
            sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal)
        };
    }

    // Only a clear status sample may expose CARD_INT to the kernel IRQ cap.
    // Read back both enables before the final sample; if a source crosses this
    // write, remask it and hand the same durable level to the DPC ring.
    io.write32(SDHCI_SIGNAL_ENABLE, unmasked_signal);
    let int_readback = io.read32(SDHCI_INT_ENABLE);
    let signal_readback = io.read32(SDHCI_SIGNAL_ENABLE);
    if !sdio_card_interrupt_policy_readback_matches(
        int_readback,
        signal_readback,
        unmasked_int,
        unmasked_signal,
    ) {
        return sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal);
    }
    let status_after_signal_enable = io.read32(SDHCI_INT_STATUS);
    if status_after_signal_enable & SDHCI_INT_CARD_INT != 0 {
        return if sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal) {
            SdioCardInterruptRearmResult::SourcePending(status_after_signal_enable)
        } else {
            sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal)
        };
    }

    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = false;
        state.card_irq_rearms = state.card_irq_rearms.saturating_add(1);
    });
    sdio_record_dpc_health(false);
    SdioCardInterruptRearmResult::Rearmed
}

fn sdio_preissue_dpc_fence_condition(generation: u32) -> SdioPreissueDpcFenceCondition {
    let state = SDIO_RUNTIME_STATE.with_ref(|state| *state);
    if generation == 0
        || !state.initialized
        || state.shared_epoch != generation
        || !state.dpc_link_ready
        || state.irq_handler_slot != DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
        || state.peer_notification_slot != DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT
        || !state.dpc_activation_allowed
        || state.irq_ack_pending
        || state.dpc_poisoned
    {
        return SdioPreissueDpcFenceCondition::Fault;
    }
    let ring = sdio_runtime_dpc_ring_snapshot(generation);
    let ring_card_irq_masked = ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED != 0;
    if !ring.valid()
        || ring.epoch != generation
        || ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE == 0
        || ring_card_irq_masked != state.card_irq_masked
        || ring.flags
            & (DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING
                | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN
                | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED)
            != 0
    {
        return SdioPreissueDpcFenceCondition::Fault;
    }
    match dpc_event_ring_peek(&ring, generation) {
        DpcRingConsumeResult::Event(_) if !state.card_irq_masked => {
            // Canonical source publication masks the retained CARD_INT level
            // before committing the event. Event-plus-unmasked is therefore a
            // broken owner invariant, not ordinary DPC backpressure.
            SdioPreissueDpcFenceCondition::Fault
        }
        DpcRingConsumeResult::Event(event) if cyw43_dpc_event_has_source(event.flags) => {
            SdioPreissueDpcFenceCondition::Event(event.host_int_status)
        }
        DpcRingConsumeResult::Event(_)
        | DpcRingConsumeResult::BadEpoch
        | DpcRingConsumeResult::BadSequence => SdioPreissueDpcFenceCondition::Fault,
        DpcRingConsumeResult::Empty if state.card_irq_masked => {
            SdioPreissueDpcFenceCondition::EmptyMasked
        }
        DpcRingConsumeResult::Empty => SdioPreissueDpcFenceCondition::EmptyArmed,
    }
}

fn sdio_preissue_publish_card_interrupt_with<I: SdioTransferIo>(
    io: &mut I,
    host_int_status: u32,
    peer_wake_deferred_to_terminal: bool,
) -> bool {
    let (masked_int, masked_signal) = sdio_interrupt_policy_registers(true, true);
    if !sdio_write_card_interrupt_masked_policy_with(io, masked_int, masked_signal) {
        let _ = sdio_fail_card_interrupt_rearm_with(io, masked_int, masked_signal);
        return false;
    }
    sdio_publish_card_interrupt_event_after_rearm(host_int_status, peer_wake_deferred_to_terminal)
}

fn sdio_establish_preissue_dpc_fence_with<I: SdioTransferIo>(
    io: &mut I,
    generation: u32,
    peer_wake_deferred_to_terminal: bool,
) -> SdioPreissueDpcFenceResult {
    match sdio_preissue_dpc_fence_condition(generation) {
        SdioPreissueDpcFenceCondition::Event(status) => {
            return SdioPreissueDpcFenceResult::Deferred(status);
        }
        SdioPreissueDpcFenceCondition::EmptyArmed => {
            // Do not trust an arm inherited from an earlier control lifetime.
            // Commit a masked durable baseline, then run the same crossing-safe
            // physical transition used after DPC consumption. This repairs
            // stale enable-register drift without adding a scheduler edge.
            SDIO_RUNTIME_STATE.with_mut(|state| state.card_irq_masked = true);
            sdio_record_dpc_health(false);
            if sdio_preissue_dpc_fence_condition(generation)
                != SdioPreissueDpcFenceCondition::EmptyMasked
            {
                return SdioPreissueDpcFenceResult::Fault;
            }
        }
        SdioPreissueDpcFenceCondition::EmptyMasked => {}
        SdioPreissueDpcFenceCondition::Fault => {
            return SdioPreissueDpcFenceResult::Fault;
        }
    }
    match sdio_rearm_card_interrupt_with(io) {
        SdioCardInterruptRearmResult::Rearmed => {}
        SdioCardInterruptRearmResult::SourcePending(status) => {
            return if sdio_publish_card_interrupt_event_after_rearm(
                status,
                peer_wake_deferred_to_terminal,
            ) {
                SdioPreissueDpcFenceResult::Deferred(status)
            } else {
                SdioPreissueDpcFenceResult::Fault
            };
        }
        SdioCardInterruptRearmResult::Fault => {
            return SdioPreissueDpcFenceResult::Fault;
        }
    }

    // The health publication in the rearm helper is not itself authoritative.
    // Re-read the committed ring and the physical enables before admitting any
    // request programming, so a failed health store or state transition cannot
    // be inferred from the earlier MMIO writes.
    match sdio_preissue_dpc_fence_condition(generation) {
        SdioPreissueDpcFenceCondition::Event(status) => {
            return SdioPreissueDpcFenceResult::Deferred(status);
        }
        SdioPreissueDpcFenceCondition::EmptyArmed => {}
        SdioPreissueDpcFenceCondition::EmptyMasked | SdioPreissueDpcFenceCondition::Fault => {
            return SdioPreissueDpcFenceResult::Fault;
        }
    }
    let (expected_int, expected_signal) = sdio_interrupt_policy_registers(true, false);
    if !sdio_card_interrupt_policy_readback_matches(
        io.read32(SDHCI_INT_ENABLE),
        io.read32(SDHCI_SIGNAL_ENABLE),
        expected_int,
        expected_signal,
    ) {
        return SdioPreissueDpcFenceResult::Fault;
    }
    let status = io.read32(SDHCI_INT_STATUS);
    if status & SDHCI_INT_CARD_INT == 0 {
        SdioPreissueDpcFenceResult::Ready
    } else if sdio_preissue_publish_card_interrupt_with(io, status, peer_wake_deferred_to_terminal)
    {
        SdioPreissueDpcFenceResult::Deferred(status)
    } else {
        SdioPreissueDpcFenceResult::Fault
    }
}

fn sdio_linearize_preissue_dpc_fence_with<I: SdioTransferIo>(
    io: &mut I,
    generation: u32,
    cursor: SdioExternalDmaRequestCursor,
) -> SdioPreissueDpcFenceResult {
    match sdio_preissue_dpc_fence_condition(generation) {
        SdioPreissueDpcFenceCondition::Event(status) => {
            return SdioPreissueDpcFenceResult::Deferred(status);
        }
        SdioPreissueDpcFenceCondition::EmptyArmed => {}
        SdioPreissueDpcFenceCondition::EmptyMasked | SdioPreissueDpcFenceCondition::Fault => {
            return SdioPreissueDpcFenceResult::Fault;
        }
    }
    let (base_int, base_signal) = sdio_interrupt_policy_registers(true, false);
    let (expected_int, expected_signal) =
        sdio_request_interrupt_policy_registers(base_int, base_signal, cursor);
    if !sdio_card_interrupt_policy_readback_matches(
        io.read32(SDHCI_INT_ENABLE),
        io.read32(SDHCI_SIGNAL_ENABLE),
        expected_int,
        expected_signal,
    ) {
        return SdioPreissueDpcFenceResult::Fault;
    }
    let status = io.read32(SDHCI_INT_STATUS);
    if status & SDHCI_INT_CARD_INT == 0 {
        SdioPreissueDpcFenceResult::Ready
    } else if sdio_preissue_publish_card_interrupt_with(
        io,
        status,
        cursor.identity.peer_wake_deferred_to_terminal,
    ) {
        SdioPreissueDpcFenceResult::Deferred(status)
    } else {
        SdioPreissueDpcFenceResult::Fault
    }
}

#[cfg(target_os = "none")]
fn runtime_irq_handler_ack(handler_slot: u32) -> bool {
    let mut mr0 = 0;
    let mut mr1 = 0;
    let mut mr2 = 0;
    let mut mr3 = 0;
    // SAFETY: Descriptor admission proves that `handler_slot` is the generated
    // SDIO IRQ-handler cap. This is the exact libsel4 IRQHandler_Ack call shape.
    unsafe {
        let tag = sel4_sys::seL4_MessageInfo::new(
            sel4_sys::invocation_label_IRQAckIRQ as sel4_sys::seL4_Word,
            0,
            0,
            0,
        );
        let output = sel4_sys::seL4_CallWithMRs(
            handler_slot as sel4_sys::seL4_CPtr,
            tag,
            &mut mr0,
            &mut mr1,
            &mut mr2,
            &mut mr3,
        );
        sel4_sys::seL4_MessageInfo_get_label(output) == 0
    }
}

#[cfg(not(target_os = "none"))]
fn runtime_irq_handler_ack(handler_slot: u32) -> bool {
    #[cfg(test)]
    {
        TEST_RUNTIME_IRQ_ACK_CALLS.fetch_add(1, Ordering::AcqRel);
        if handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT {
            TEST_RUNTIME_SDIO_IRQ_ACK_CALLS.fetch_add(1, Ordering::AcqRel);
        } else if handler_slot == DRIVER_TASK_CHILD_SDIO_DMA_IRQ_HANDLER_SLOT {
            TEST_RUNTIME_SDIO_DMA_IRQ_ACK_CALLS.fetch_add(1, Ordering::AcqRel);
        }
        return TEST_RUNTIME_IRQ_ACK_FAILURES_REMAINING
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |remaining| {
                remaining.checked_sub(1)
            })
            .is_err();
    }
    #[cfg(not(test))]
    {
        let _ = handler_slot;
        true
    }
}

#[cfg(test)]
fn sdio_arm_card_interrupt_after_init() -> bool {
    if !sdio_notification_dpc_ready() {
        return false;
    }
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.dpc_activation_allowed = false;
        state.irq_ack_pending = false;
        state.dpc_poisoned = false;
    });
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();
    let handler_slot = SDIO_RUNTIME_STATE.with_ref(|state| state.irq_handler_slot);
    let acked = runtime_irq_handler_ack(handler_slot);
    sdio_record_irq_ack_result(acked);
    if !acked {
        return false;
    }
    // Firmware attach is synchronous inside the linked CYW43 runtime today,
    // so it cannot concurrently service an early firmware CARD_INT. Keep the
    // source masked until CYW43 signals after a successful RELEASE; SDIO then
    // enables the retained level source through the standard unmasked rearm.
    sdio_program_interrupt_policy();
    sdio_record_dpc_health(false);
    true
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioPwrseqTurn {
    Pending,
    Ready,
    Fault { detail: u16, result: u32 },
}

#[cfg(any(target_os = "none", test))]
fn sdio_physical_lifetime_read_once(
    ring: RuntimeRingWindow,
) -> Option<DriverRuntimeSdioPhysicalLifetimeRecord> {
    let offset = usize::from(DRIVER_RUNTIME_SDIO_PHYSICAL_LIFETIME_OFFSET);
    Some(DriverRuntimeSdioPhysicalLifetimeRecord {
        magic: ring.read_u32(
            offset + core::mem::offset_of!(DriverRuntimeSdioPhysicalLifetimeRecord, magic),
        )?,
        begun_epoch: ring.read_u32(
            offset + core::mem::offset_of!(DriverRuntimeSdioPhysicalLifetimeRecord, begun_epoch),
        )?,
        completed_epoch: ring.read_u32(
            offset
                + core::mem::offset_of!(DriverRuntimeSdioPhysicalLifetimeRecord, completed_epoch),
        )?,
        failed_epoch: ring.read_u32(
            offset + core::mem::offset_of!(DriverRuntimeSdioPhysicalLifetimeRecord, failed_epoch),
        )?,
    })
}

#[cfg(any(target_os = "none", test))]
fn sdio_physical_lifetime_snapshot() -> Option<DriverRuntimeSdioPhysicalLifetimeRecord> {
    let address =
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_SDIO_PHYSICAL_LIFETIME_OFFSET);
    driver_task_shared_invalidate_range(
        address,
        usize::from(DRIVER_RUNTIME_SDIO_PHYSICAL_LIFETIME_BYTES),
    );
    let ring = RuntimeRingWindow::local();
    let first = sdio_physical_lifetime_read_once(ring)?;
    driver_task_shared_load_barrier();
    let second = sdio_physical_lifetime_read_once(ring)?;
    DriverRuntimeSdioPhysicalLifetimeRecord::stable_snapshot(first, second)
}

