    #[test]
    fn dpc_publication_orders_body_before_sequence_and_producer() {
        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        enum PublicationStep {
            Sequence(u32),
            Body(DriverRuntimeDpcEventEntry),
            Release,
            Producer(u32),
        }

        let event = DriverRuntimeDpcEventEntry {
            sequence: 17,
            host_int_status: SDHCI_INT_CARD_INT,
            signal_status: DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            reason: DPC_REASON_SDIO_CARD_INTERRUPT,
            flags: DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
        };
        let trace = std::cell::RefCell::new(Vec::new());
        assert!(dpc_event_ring_publish_sequence_last(
            event.sequence,
            event,
            |sequence| {
                trace.borrow_mut().push(PublicationStep::Sequence(sequence));
                true
            },
            |body| {
                trace.borrow_mut().push(PublicationStep::Body(body));
                true
            },
            || trace.borrow_mut().push(PublicationStep::Release),
            |producer| {
                trace.borrow_mut().push(PublicationStep::Producer(producer));
                true
            },
        ));
        assert_eq!(
            trace.into_inner(),
            vec![
                PublicationStep::Sequence(0),
                PublicationStep::Body(event),
                PublicationStep::Release,
                PublicationStep::Sequence(event.sequence),
                PublicationStep::Release,
                PublicationStep::Producer(event.sequence),
            ]
        );
    }

    #[test]
    fn dpc_event_ring_preserves_fifo_order_and_rejects_bad_epoch() {
        assert_eq!(
            core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
            16,
            "the consumer cache clean must target its field, not the ring header"
        );
        let epoch = 0x4359_5301;
        let mut ring = DriverRuntimeDpcEventRing::empty(epoch);
        assert_eq!(
            dpc_event_ring_publish(
                &mut ring,
                epoch,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(1)
        );
        assert_eq!(
            dpc_event_ring_publish(
                &mut ring,
                epoch,
                SDHCI_INT_CARD_INT | SDHCI_INT_RESPONSE,
                0,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(2)
        );
        let first = match dpc_event_ring_peek(&ring, epoch) {
            DpcRingConsumeResult::Event(event) => event,
            other => panic!("expected first event, got {other:?}"),
        };
        assert_eq!(first.sequence, 1);
        assert_eq!(first.host_int_status, SDHCI_INT_CARD_INT);
        assert!(dpc_event_ring_advance(&mut ring, epoch, first.sequence));
        assert_eq!(
            dpc_consumer_wake_route(&ring, epoch),
            DpcConsumerWakeRoute::SelfSignal
        );
        let second = match dpc_event_ring_peek(&ring, epoch) {
            DpcRingConsumeResult::Event(event) => event,
            other => panic!("expected second event, got {other:?}"),
        };
        assert_eq!(second.sequence, 2);
        assert_eq!(
            second.host_int_status,
            SDHCI_INT_CARD_INT | SDHCI_INT_RESPONSE
        );
        assert_eq!(
            dpc_event_ring_peek(&ring, epoch.wrapping_add(1)),
            DpcRingConsumeResult::BadEpoch
        );
        assert!(dpc_event_ring_advance(&mut ring, epoch, second.sequence));
        assert_eq!(
            dpc_consumer_wake_route(&ring, epoch),
            DpcConsumerWakeRoute::OwnerRearm
        );
    }

    #[test]
    fn dpc_owner_health_reports_current_poison_and_preserves_failure_count() {
        let mut ring = DriverRuntimeDpcEventRing::empty(0x4359_5301);
        dpc_event_ring_set_owner_health(&mut ring, true, true, false, true);
        assert!(ring.valid());
        assert_ne!(
            ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED,
            0
        );
        assert_ne!(
            ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING,
            0
        );
        assert_eq!(ring.ack_failures, 1);

        dpc_event_ring_set_owner_health(&mut ring, true, false, true, false);
        assert!(ring.valid());
        assert_eq!(
            ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING,
            0
        );
        assert_ne!(ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED, 0);
        assert_eq!(ring.ack_failures, 1);

        dpc_event_ring_set_owner_health(&mut ring, false, false, false, false);
        assert_eq!(ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED, 0,);
        assert_eq!(ring.ack_failures, 1);
    }

    #[test]
    fn sdio_poison_health_publication_revokes_owner_active() {
        let _guard = test_guard();
        let generation = 0x4359_5303;
        initialize_production_foreground_pair(generation);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_activation_allowed = true;
            state.dpc_poisoned = false;
        });
        sdio_record_dpc_health(false);
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let active = dpc_event_ring_read_at(dpc_base);
        assert_ne!(
            active.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE,
            0,
        );

        // Leave the private activation bit set deliberately: publication must
        // derive owner-active authority from the complete non-poisoned state.
        SDIO_RUNTIME_STATE.with_mut(|state| state.dpc_poisoned = true);
        sdio_record_dpc_health(false);
        let poisoned = dpc_event_ring_read_at(dpc_base);
        assert_ne!(
            poisoned.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED,
            0,
        );
        assert_eq!(
            poisoned.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE,
            0,
        );
    }

    #[test]
    fn control_pre_tx_reuses_only_a_quiescent_generation_long_dpc_lifetime() {
        let generation = 0x4359_5302;
        let mut quiescent = DriverRuntimeDpcEventRing::empty(generation);
        dpc_event_ring_set_owner_active(&mut quiescent, true);
        quiescent.ack_failures = 1;
        assert_eq!(
            cyw43_control_pre_tx_dpc_route(generation, quiescent),
            Cyw43ControlPreTxDpcRoute::ReuseGeneration,
            "recovered history cannot manufacture another activation boundary",
        );

        let mut pending = quiescent;
        assert_eq!(
            dpc_event_ring_publish(
                &mut pending,
                generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(1),
        );
        assert_eq!(
            cyw43_control_pre_tx_dpc_route(generation, pending),
            Cyw43ControlPreTxDpcRoute::ServiceCommittedEvent(1),
            "a durable producer level must run through the existing DPC lane",
        );
        let mut wrapped = DriverRuntimeDpcEventRing::empty(generation);
        dpc_event_ring_set_owner_active(&mut wrapped, true);
        wrapped.producer = u32::MAX;
        wrapped.consumer = u32::MAX;
        assert_eq!(
            dpc_event_ring_publish(
                &mut wrapped,
                generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(0),
        );
        assert_eq!(
            cyw43_control_pre_tx_dpc_route(generation, wrapped),
            Cyw43ControlPreTxDpcRoute::ServiceCommittedEvent(0),
            "wrapped sequence zero remains a valid durable event identity",
        );

        let mut masked = quiescent;
        masked.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED;
        let mut ack_pending = quiescent;
        ack_pending.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING;
        let mut poisoned = quiescent;
        poisoned.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED;
        let mut overrun = quiescent;
        overrun.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN;
        for ring in [
            masked,
            ack_pending,
            poisoned,
            overrun,
            DriverRuntimeDpcEventRing::empty(generation),
            DriverRuntimeDpcEventRing::empty(generation.wrapping_add(1)),
        ] {
            assert_eq!(
                cyw43_control_pre_tx_dpc_route(generation, ring),
                Cyw43ControlPreTxDpcRoute::ActivateOwner,
            );
        }
    }

    #[test]
    fn control_pre_tx_binds_one_event_then_advances_past_reassertion() {
        let _guard = test_guard();
        let generation = 0x4359_5303;
        let parent_sequence = 0x4359_5304;
        initialize_production_foreground_pair(generation);
        let descriptor = stage_cyw43_control_exchange_request(
            0x107,
            1,
            DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN,
            b"bounded-event",
        );
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.initialized = true;
            state.transport_ready = true;
            state.firmware_released = true;
            state.bus_link_ready = true;
            state.dpc_link_ready = true;
            state.dpc_shared_epoch = generation;
            assert!(cyw43_control_exchange_begin(state, descriptor, generation));
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        assert!(dpc_event_ring_set_owner_state_at(
            dpc_base,
            false,
            Some(true),
            false,
            false,
            false,
        ));
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(1),
        );
        assert_eq!(
            CYW43_RUNTIME_STATE.with_mut(|state| {
                let cursor = state.control_exchange;
                cyw43_control_exchange_pre_tx_dpc_turn(state, cursor, parent_sequence)
            }),
            RuntimeCommandTurn::Pending,
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert_eq!(
                state.control_exchange.phase,
                Cyw43ControlExchangePhase::PreTxDpcProbe,
            );
            assert!(state.control_exchange.pre_tx_dpc_event_valid);
            assert_eq!(state.control_exchange.pre_tx_dpc_event_sequence, 1);
        });
        assert_eq!(
            CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.load(Ordering::Acquire),
            parent_sequence,
        );
        assert_eq!(
            CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.load(Ordering::Acquire),
            1,
        );

        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(2),
        );
        assert!(dpc_event_ring_advance_at(dpc_base, generation, 1));
        cyw43_publish_dpc_consumed_watermark(generation, 1);
        assert_eq!(
            CYW43_RUNTIME_STATE.with_mut(|state| {
                let cursor = state.control_exchange;
                cyw43_control_exchange_pre_tx_dpc_turn(state, cursor, parent_sequence)
            }),
            RuntimeCommandTurn::Pending,
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert_eq!(
                state.control_exchange.phase,
                Cyw43ControlExchangePhase::PreTxDrain,
                "a later source assertion cannot keep the same control lifetime in housekeeping",
            );
            assert_eq!(state.control_exchange.pre_tx_dpc_event_sequence, 1);
        });
        assert!(matches!(
            dpc_event_ring_peek_at(dpc_base, generation),
            DpcRingConsumeResult::Event(event) if event.sequence == 2
        ));
    }

    #[test]
    fn control_pre_tx_missing_bound_event_faults_without_reactivation() {
        let _guard = test_guard();
        let generation = 0x4359_5305;
        let parent_sequence = 0x4359_5306;
        initialize_production_foreground_pair(generation);
        let descriptor = stage_cyw43_control_exchange_request(
            0x107,
            1,
            DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN,
            b"missing-event",
        );
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.initialized = true;
            state.transport_ready = true;
            state.firmware_released = true;
            state.bus_link_ready = true;
            state.dpc_link_ready = true;
            state.dpc_shared_epoch = generation;
            assert!(cyw43_control_exchange_begin(state, descriptor, generation));
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        assert!(dpc_event_ring_set_owner_state_at(
            dpc_base,
            false,
            Some(true),
            false,
            false,
            false,
        ));
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(1),
        );
        assert_eq!(
            CYW43_RUNTIME_STATE.with_mut(|state| {
                let cursor = state.control_exchange;
                cyw43_control_exchange_pre_tx_dpc_turn(state, cursor, parent_sequence)
            }),
            RuntimeCommandTurn::Pending,
        );
        dpc_event_ring_initialize_at(dpc_base, generation);
        let turn = CYW43_RUNTIME_STATE.with_mut(|state| {
            let cursor = state.control_exchange;
            cyw43_control_exchange_pre_tx_dpc_turn(state, cursor, parent_sequence)
        });
        let RuntimeCommandTurn::Complete(completion) = turn else {
            panic!("missing immutable event must be terminal: {turn:?}");
        };
        assert_eq!(completion.code, COMPLETION_FAULT);
        assert_eq!(completion.sequence, parent_sequence);
        assert_eq!(completion.result, 1);
        assert!(CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));
        assert!(!CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire));
    }

    #[test]
    fn control_pre_tx_exact_bound_event_is_durable_service_authority() {
        let _guard = test_guard();
        let physical_generation = 0x4359_5301;
        let logical_generation = 1;
        let parent_sequence = 0x4359_5307;
        let (parent, mut descriptor) = install_persistent_control_parent_fixture(
            parent_sequence,
            logical_generation,
            physical_generation,
        );
        descriptor.flags |= DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN;
        assert!(descriptor.valid());
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_descriptor = descriptor;
        });
        CYW43_RUNTIME_STATE.with_mut(|state| {
            assert!(cyw43_control_exchange_begin(
                state,
                descriptor,
                logical_generation,
            ));
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let event_sequence = match dpc_event_ring_publish_at(
            dpc_base,
            physical_generation,
            SDHCI_INT_CARD_INT,
            DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            DPC_REASON_SDIO_CARD_INTERRUPT,
            DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
        ) {
            DpcRingPublishResult::Published(sequence) => sequence,
            other => panic!("pre-TX source event must commit: {other:?}"),
        };
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.control_exchange.pre_tx_dpc_event_valid = true;
            state.control_exchange.pre_tx_dpc_event_sequence = event_sequence;
        });
        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(event_sequence, Ordering::Release);
        CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(parent_sequence, Ordering::Release);

        let event = cyw43_runtime_dpc_event_peek();
        assert!(runtime_cyw43_foreground_dpc_service_due_current(
            parent, event,
        ));
        assert!(cyw43_persistent_parent_transaction_admitted(
            parent,
            logical_generation,
        ));
        assert!(dpc_event_ring_set_owner_health_at(
            dpc_base, true, true, false, false,
        ));
        assert!(cyw43_exact_bound_pre_tx_event_owns_ack_debt(
            parent,
            logical_generation,
            physical_generation,
            dpc_event_ring_read_at(dpc_base),
        ));
        assert!(
            cyw43_persistent_parent_transaction_admitted(parent, logical_generation),
            "the exact bound event owns its already-committed ACK debt",
        );

        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE
            .store(event_sequence.wrapping_add(1), Ordering::Release);
        assert!(!runtime_cyw43_foreground_dpc_service_due_current(
            parent, event,
        ));
        assert!(!cyw43_persistent_parent_transaction_admitted(
            parent,
            logical_generation,
        ));

        let mut wrapped = DriverRuntimeDpcEventRing::empty(physical_generation);
        dpc_event_ring_set_owner_active(&mut wrapped, true);
        wrapped.producer = u32::MAX;
        wrapped.consumer = u32::MAX;
        assert_eq!(
            dpc_event_ring_publish(
                &mut wrapped,
                physical_generation,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(0),
        );
        dpc_event_ring_set_owner_health(&mut wrapped, true, true, false, false);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.control_exchange.pre_tx_dpc_event_sequence = 0;
        });
        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(0, Ordering::Release);
        CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(parent_sequence, Ordering::Release);
        assert!(cyw43_exact_bound_pre_tx_event_owns_ack_debt(
            parent,
            logical_generation,
            physical_generation,
            wrapped,
        ));
        let wrapped_event = dpc_event_ring_peek(&wrapped, physical_generation);
        assert!(CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            CYW43_RUNTIME_STATE.with_ref(|state| {
                runtime_cyw43_foreground_dpc_service_due(transaction, state, false, wrapped_event)
            })
        }));
    }

    #[test]
    fn sdio_masked_dpc_capture_coalesces_until_consumer_advances() {
        let epoch = 0x4359_5301;
        let mut ring = DriverRuntimeDpcEventRing::empty(epoch);
        assert_eq!(
            sdio_dpc_capture_disposition(&ring, epoch, false),
            SdioDpcCaptureDisposition::InspectSource
        );
        assert_eq!(
            dpc_event_ring_publish(
                &mut ring,
                epoch,
                SDHCI_INT_CARD_INT,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(1)
        );
        for _ in 0..128 {
            assert_eq!(
                sdio_dpc_capture_disposition(&ring, epoch, false),
                SdioDpcCaptureDisposition::HoldPending
            );
        }
        assert_eq!(
            sdio_dpc_capture_disposition(&ring, epoch, true),
            SdioDpcCaptureDisposition::InspectSource
        );
        assert_eq!(ring.producer, 1);
        assert_eq!(ring.consumer, 0);
        assert_eq!(ring.overruns, 0);
        assert!(dpc_event_ring_advance(&mut ring, epoch, 1));
        assert_eq!(
            sdio_dpc_capture_disposition(&ring, epoch, false),
            SdioDpcCaptureDisposition::InspectSource
        );
        assert_eq!(
            sdio_dpc_capture_disposition(&ring, epoch.wrapping_add(1), false),
            SdioDpcCaptureDisposition::Fault
        );
    }

