    #[test]
    fn dpc_claim_block_preserves_foreground_child_aperture() {
        let _guard = test_guard();
        let generation = 0x4359_5359;
        initialize_production_foreground_pair(generation);
        let foreground_sequence = 0x8000_5359;
        let foreground = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
            function: 1,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
            addr: cyw43_backplane_function_addr(CYW43_CHIPCOMMON_PMUCONTROL_ADDR),
            data_offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u16,
            len: 4,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT,
            timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        assert!(cyw43_sdio_child_claim(foreground_sequence));
        assert!(sdio_bus_link_write_descriptor_physical(
            CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET,
            foreground,
        ));
        let owner_window =
            RuntimeRingWindow::sdio_owner().expect("test SDIO owner window must be mapped");
        let payload = [0x11, 0x22, 0x33, 0x44];
        for (index, value) in payload.into_iter().enumerate() {
            assert!(owner_window.write_u8(CYW43_SDIO_BUS_LINK_DATA_OFFSET + index, value));
        }

        let mut state = Cyw43RuntimeState::new();
        state.backplane_window_valid = true;
        state.backplane_window = CYW43_SDIO_CORE_BASE & BACKPLANE_WINDOW_MASK;
        let mut cursor = Cyw43DpcCursor::empty();
        cursor.event_sequence = 91;
        cyw43_dpc_prepare_backplane_io(
            &mut state,
            &mut cursor,
            Cyw43DpcAction::FlowAck,
            Cyw43DpcIoKind::BackplaneWrite32,
            CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
            I_HMB_FC_CHANGE,
        );
        let cursor_before = cursor;
        CYW43_DPC_DEFERRED.store(false, Ordering::Release);

        assert_eq!(
            cyw43_dpc_submit_current_io(
                &mut cursor,
                generation,
                Cyw43DpcChildMode::OrdinaryContinuation,
            ),
            Cyw43DpcSubmitResult::DeferredOwner,
        );
        assert_eq!(cursor, cursor_before);
        assert_eq!(
            CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire),
            foreground_sequence,
        );
        assert_eq!(
            sdio_bus_link_read_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET),
            Some(foreground),
        );
        for (index, expected) in payload.into_iter().enumerate() {
            assert_eq!(
                owner_window.read_u8(CYW43_SDIO_BUS_LINK_DATA_OFFSET + index),
                Some(expected),
            );
        }
        assert!(CYW43_DPC_DEFERRED.load(Ordering::Acquire));
        assert!(!CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));
        assert!(cyw43_sdio_child_release_exact(foreground_sequence));
    }

    #[test]
    fn dpc_backplane_cache_is_invalid_until_exact_high_completion() {
        let mut state = Cyw43RuntimeState::new();
        let previous_window = CYW43_RAM_BASE_4345 & BACKPLANE_WINDOW_MASK;
        let requested = CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS;
        let requested_window = requested & BACKPLANE_WINDOW_MASK;
        assert_ne!(previous_window, requested_window);
        state.backplane_window = previous_window;
        state.backplane_window_valid = true;

        let mut cursor = Cyw43DpcCursor::empty();
        cursor.event_sequence = 0x5359;
        cyw43_dpc_prepare_backplane_io(
            &mut state,
            &mut cursor,
            Cyw43DpcAction::CaptureStatus,
            Cyw43DpcIoKind::BackplaneRead32,
            requested,
            0,
        );
        assert_eq!(cursor.io_phase, Cyw43DpcIoPhase::WindowLow);
        assert!(!state.backplane_window_valid);
        assert_eq!(state.backplane_window, previous_window);

        let completion = DriverTaskCompletionRecord::progress(0x8000_5359, 0);
        assert!(!cyw43_dpc_apply_exact_completion(
            &mut state,
            &mut cursor,
            completion,
        ));
        assert_eq!(cursor.io_phase, Cyw43DpcIoPhase::WindowMid);
        assert!(!state.backplane_window_valid);
        assert_eq!(state.backplane_window, previous_window);

        assert!(!cyw43_dpc_apply_exact_completion(
            &mut state,
            &mut cursor,
            completion,
        ));
        assert_eq!(cursor.io_phase, Cyw43DpcIoPhase::WindowHigh);
        assert!(!state.backplane_window_valid);
        assert_eq!(state.backplane_window, previous_window);

        assert!(!cyw43_dpc_apply_exact_completion(
            &mut state,
            &mut cursor,
            completion,
        ));
        assert_eq!(cursor.io_phase, Cyw43DpcIoPhase::Transfer);
        assert!(state.backplane_window_valid);
        assert_eq!(state.backplane_window, requested_window);

        let mut hot_cursor = Cyw43DpcCursor::empty();
        cyw43_dpc_prepare_backplane_io(
            &mut state,
            &mut hot_cursor,
            Cyw43DpcAction::PostStatus,
            Cyw43DpcIoKind::BackplaneRead32,
            requested,
            0,
        );
        assert_eq!(hot_cursor.io_phase, Cyw43DpcIoPhase::Transfer);
        assert!(state.backplane_window_valid);
        assert_eq!(state.backplane_window, requested_window);
    }

    #[test]
    fn dpc_rx_start_uses_linux_frame_indication_and_next_frame_order() {
        assert_eq!(
            cyw43_dpc_rx_start_route(false, I_HMB_FRAME_IND, 0, false),
            Cyw43DpcRxStartRoute::Firstread
        );
        assert_eq!(
            cyw43_dpc_rx_start_route(false, 0, 128, false),
            Cyw43DpcRxStartRoute::NextFrame(128)
        );
        assert_eq!(
            cyw43_dpc_rx_start_route(false, I_HMB_FRAME_IND, 128, false),
            Cyw43DpcRxStartRoute::NextFrame(128)
        );
        assert_eq!(
            cyw43_dpc_rx_start_route(false, 0, 128, true),
            Cyw43DpcRxStartRoute::Firstread
        );
        assert_eq!(
            cyw43_dpc_rx_start_route(false, 0, 0, false),
            Cyw43DpcRxStartRoute::PostStatus
        );
        assert_eq!(
            cyw43_dpc_rx_start_route(true, I_HMB_FRAME_IND, 128, false),
            Cyw43DpcRxStartRoute::PostStatus
        );
    }

    #[test]
    fn dpc_rx_queue_wait_is_fanout_aware_and_resumes_the_same_event_after_pop() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();

        state.rx_queue_count = (CYW43_RX_QUEUE_CAP - 1) as u8;
        assert!(!cyw43_dpc_rx_queue_backpressured(&state));
        state.rx_queue_count = CYW43_RX_QUEUE_CAP as u8;
        assert!(cyw43_dpc_rx_queue_backpressured(&state));

        state.glom_subframe_count = CYW43_RX_GLOM_SUBFRAME_CAP as u8;
        state.rx_queue_count = (CYW43_RX_QUEUE_CAP - CYW43_RX_GLOM_SUBFRAME_CAP) as u8;
        assert!(!cyw43_dpc_rx_queue_backpressured(&state));
        state.rx_queue_count = (CYW43_RX_QUEUE_CAP - CYW43_RX_GLOM_SUBFRAME_CAP + 1) as u8;
        assert!(cyw43_dpc_rx_queue_backpressured(&state));

        let next_frame_len = 128u16;
        state.pending_intstatus = I_HMB_FRAME_IND;
        state.sdpcm_next_frame_len = next_frame_len;
        let mut cursor = Cyw43DpcCursor::empty();
        cursor.event_sequence = 0x4359_d106;
        cyw43_dpc_start_rframe_or_post(&mut state, &mut cursor);
        assert_eq!(cursor.action, Cyw43DpcAction::RxQueueWait);
        assert_eq!(cursor.io_kind, Cyw43DpcIoKind::None);
        assert_eq!(cursor.io_phase, Cyw43DpcIoPhase::Idle);
        assert_eq!(state.sdpcm_next_frame_len, next_frame_len);
        assert_eq!(state.glom_subframe_count, CYW43_RX_GLOM_SUBFRAME_CAP as u8);
        assert_ne!(state.pending_intstatus & I_HMB_FRAME_IND, 0);
        assert_eq!(state.rx_queue_overflows, 0);
        assert_eq!(TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire), 0);

        state.dpc_cursor = cursor;
        state.rx_queue_lens[0] = 1;
        state.rx_queue_flags[0] = cyw43_frame_flags(CYW43_SDPCM_CHANNEL_EVENT, 0);
        state.rx_queue_frames[0][0] = 0xa5;
        CYW43_DPC_DEFERRED.store(false, Ordering::Release);
        assert_eq!(
            cyw43_rx_queue_pop_front(&mut state),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 1,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_EVENT, 0),
            })
        );
        assert_eq!(state.rx_queue_count as usize, CYW43_RX_QUEUE_CAP - 8);
        assert!(CYW43_DPC_DEFERRED.load(Ordering::Acquire));
        assert_eq!(state.dpc_cursor.action, Cyw43DpcAction::RxQueueWait);

        let mut resumed = state.dpc_cursor;
        assert!(!cyw43_dpc_finish_action(&mut state, &mut resumed, 0));
        assert_eq!(resumed.event_sequence, cursor.event_sequence);
        assert_eq!(resumed.action, Cyw43DpcAction::FifoWindow);
        assert_eq!(state.sdpcm_next_frame_len, 0);
        assert_eq!(state.glom_subframe_count, CYW43_RX_GLOM_SUBFRAME_CAP as u8);
        assert_eq!(state.rx_queue_overflows, 0);
        assert_eq!(TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire), 0);
    }

    #[test]
    fn dpc_cursor_serializes_physical_commands_but_allows_exact_queue_delivery() {
        let _guard = test_guard();
        reset_runtime_for_test();
        assert!(!cyw43_post_release_dpc_missing(false, false));
        assert!(!cyw43_post_release_dpc_missing(false, true));
        assert!(!cyw43_post_release_dpc_missing(true, true));
        assert!(cyw43_post_release_dpc_missing(true, false));

        assert!(runtime_command_poll_due(false));
        assert!(!runtime_command_poll_due(true));
        assert_eq!(
            cyw43_dpc_pending_command_route(true, false, false, false, false, false),
            Cyw43DpcPendingCommandRoute::Wait
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(true, false, true, false, false, false),
            Cyw43DpcPendingCommandRoute::FailQuarantined
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(true, false, true, true, false, false),
            Cyw43DpcPendingCommandRoute::ExecuteRecovery
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, false, false, false, false, false),
            Cyw43DpcPendingCommandRoute::Execute
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, false, true, false, false, false),
            Cyw43DpcPendingCommandRoute::FailQuarantined
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, false, true, true, false, false),
            Cyw43DpcPendingCommandRoute::ExecuteRecovery
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, true, false, false, false, false),
            Cyw43DpcPendingCommandRoute::Wait
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, true, true, false, false, false),
            Cyw43DpcPendingCommandRoute::Wait
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(false, true, true, true, false, false),
            Cyw43DpcPendingCommandRoute::Wait
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(true, true, false, false, true, false),
            Cyw43DpcPendingCommandRoute::Execute,
            "a proven non-empty queue pop is software-only even while the DPC child owns SDIO",
        );
        assert_eq!(
            cyw43_dpc_pending_command_route(true, true, true, false, true, false),
            Cyw43DpcPendingCommandRoute::Wait,
            "quarantine always fences queue delivery",
        );

        let watermark = Cyw43ForegroundDpcWatermark::capture(91, 0, 1);
        let dpc_event = |sequence| {
            DpcRingConsumeResult::Event(DriverRuntimeDpcEventEntry {
                sequence,
                host_int_status: SDHCI_INT_CARD_INT,
                signal_status: 0,
                reason: DPC_REASON_SDIO_CARD_INTERRUPT,
                flags: DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            })
        };
        assert!(watermark.belongs_to(91));
        assert!(!watermark.belongs_to(92));
        assert!(cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            dpc_event(1),
            watermark,
            false,
        ));
        // Sequence 2 was published after the retained command's producer
        // watermark. It remains queued, but cannot win this arbitration turn.
        assert!(!cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            dpc_event(2),
            watermark,
            false,
        ));
        assert!(cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            dpc_event(2),
            watermark,
            true,
        ));
        assert!(!cyw43_dpc_command_requires_preflight(
            true,
            true,
            false,
            false,
            dpc_event(1),
            watermark,
            false,
        ));
        assert!(!cyw43_dpc_command_requires_preflight(
            true,
            false,
            true,
            false,
            dpc_event(1),
            watermark,
            false,
        ));
        assert!(!cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            true,
            dpc_event(1),
            watermark,
            false,
        ));
        assert!(!cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            DpcRingConsumeResult::Empty,
            watermark,
            false,
        ));
        assert!(cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            DpcRingConsumeResult::BadSequence,
            watermark,
            false,
        ));

        let recovery = DriverTaskCommandRecord {
            sequence: 91,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_CYW43_WIFI,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: DriverTaskBudgetGrant {
                max_ops: 1,
                max_frames: 0,
                max_bytes: 0,
            },
            frame: DriverFrameDescriptor::empty(),
        };
        assert!(cyw43_dpc_explicit_recovery_command(recovery));
        let mut physical = recovery;
        physical.aux0 = DRIVER_RUNTIME_CYW43_COMMAND_AUX;
        assert!(!cyw43_dpc_explicit_recovery_command(physical));

        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        });
        let transport = cyw43_descriptor_command(92);
        assert!(!cyw43_dpc_explicit_recovery_command(transport));

        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_ETH_TX,
            payload_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
            payload_len: 64,
            total_len: 64,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        });
        assert!(!cyw43_dpc_explicit_recovery_command(
            cyw43_descriptor_command(93)
        ));
    }

    #[test]
    fn active_dpc_child_allows_only_intake_sealed_current_queue_delivery() {
        let _guard = test_guard();
        let generation = 0x4359_d081;
        let parent_sequence = 0x4359_d082;
        let payload = *b"queued-dpc-frame";
        let payload_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x240;
        initialize_production_foreground_pair(generation);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_activation_allowed = true;
            state.card_irq_masked = false;
        });
        sdio_record_dpc_health(false);
        stage_bytes(payload_offset, &payload);

        let mut active_cursor = Cyw43DpcCursor::empty();
        active_cursor.event_sequence = 17;
        active_cursor.action = Cyw43DpcAction::CaptureStatus;
        active_cursor.io_kind = Cyw43DpcIoKind::BackplaneRead32;
        active_cursor.io_phase = Cyw43DpcIoPhase::Transfer;
        active_cursor.io_addr = CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS;
        active_cursor.captured_status = I_HMB_FRAME_IND;
        active_cursor.child = Cyw43DpcChild {
            active: true,
            generation,
            expected_sequence: 0x8000_d083,
            command_result: 4,
            ..Cyw43DpcChild::empty()
        };
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.initialized = true;
            state.transport_ready = true;
            state.firmware_released = true;
            state.bus_link_ready = true;
            state.dpc_link_ready = true;
            state.dpc_cursor = active_cursor;
            assert!(cyw43_rx_queue_push_from_runtime(
                state,
                payload_offset,
                payload.len(),
                cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 23),
            ));
        });
        CYW43_SDIO_CHILD_ACTIVE.store(true, Ordering::Release);
        CYW43_SDIO_CHILD_EXPECTED_SEQUENCE
            .store(active_cursor.child.expected_sequence, Ordering::Release);

        let strict_descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            flags: DRIVER_RUNTIME_CYW43_FLAG_RX_STEADY_TAIL_DRAIN,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        stage_cyw43_descriptor(strict_descriptor);
        let mut command = cyw43_descriptor_command(parent_sequence);
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        command.aux1 = generation;
        let intake = runtime_command_intake_after_pre_admit(command, false);
        assert_eq!(intake.command, command);
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            assert!(transaction.parent_input_sealed);
            assert!(!transaction.active);
            assert!(!transaction.executing);
        });
        assert!(!cyw43_foreground_transaction_active());

        let ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, false));
        assert!(ready);
        let retained_route = CYW43_RUNTIME_STATE.with_ref(|state| {
            cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false)
        });
        assert_eq!(retained_route, Cyw43DpcPendingCommandRoute::Execute);

        let mut stale_generation = command;
        stale_generation.aux1 = generation.wrapping_add(1);
        let stale_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(stale_generation, state, false));
        assert!(!stale_ready);
        let stale_intake = RuntimeCommandIntake {
            command: stale_generation,
            ..intake
        };
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(stale_intake, state, true, true, false, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );

        let mismatched_parent = DriverTaskCommandRecord {
            sequence: command.sequence.wrapping_add(1),
            ..command
        };
        let mismatched_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(mismatched_parent, state, false));
        assert!(!mismatched_ready);
        let mismatched_intake = RuntimeCommandIntake {
            command: mismatched_parent,
            ..intake
        };
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(
                    mismatched_intake,
                    state,
                    true,
                    true,
                    false,
                    false,
                    false,
                )
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );

        let empty_ready = CYW43_RUNTIME_STATE.with_mut(|state| {
            let queue_count = state.rx_queue_count;
            state.rx_queue_count = 0;
            let ready = cyw43_dpc_queue_only_delivery_ready(command, state, false);
            state.rx_queue_count = queue_count;
            ready
        });
        assert!(!empty_ready);
        let empty_route = CYW43_RUNTIME_STATE.with_mut(|state| {
            let queue_count = state.rx_queue_count;
            state.rx_queue_count = 0;
            let route =
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false);
            state.rx_queue_count = queue_count;
            route
        });
        assert_eq!(empty_route, Cyw43DpcPendingCommandRoute::Wait);

        let recovery_ready = CYW43_RUNTIME_STATE.with_mut(|state| {
            state.recovery_required = true;
            let ready = cyw43_dpc_queue_only_delivery_ready(command, state, false);
            state.recovery_required = false;
            ready
        });
        assert!(!recovery_ready);
        let recovery_route = CYW43_RUNTIME_STATE.with_mut(|state| {
            state.recovery_required = true;
            let route =
                cyw43_dpc_pending_intake_route(intake, state, true, true, true, false, false);
            state.recovery_required = false;
            route
        });
        assert_eq!(recovery_route, Cyw43DpcPendingCommandRoute::Wait);
        assert!(!CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, true)));
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(intake, state, true, true, true, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );

        let control_exchange_route = CYW43_RUNTIME_STATE.with_mut(|state| {
            state.control_exchange.phase = Cyw43ControlExchangePhase::WaitCredit;
            let route =
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false);
            state.reset_control_exchange();
            route
        });
        assert_eq!(
            control_exchange_route,
            Cyw43DpcPendingCommandRoute::Wait,
            "an active logical control exchange remains the sole foreground owner",
        );

        let wrong_prompt_route = CYW43_RUNTIME_STATE.with_mut(|state| {
            state.prompt_poll = Cyw43PromptPollCursor {
                phase: Cyw43PromptPollPhase::Queue,
                parent_sequence: command.sequence.wrapping_add(1),
                generation,
                descriptor: strict_descriptor,
            };
            let route =
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false);
            state.prompt_poll.reset();
            route
        });
        assert_eq!(
            wrong_prompt_route,
            Cyw43DpcPendingCommandRoute::Wait,
            "queue delivery cannot adopt another prompt cursor",
        );

        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_descriptor = DriverRuntimeCyw43CommandDescriptor {
                op: DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
                ..DriverRuntimeCyw43CommandDescriptor::empty()
            };
        });
        let control_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, false));
        assert!(control_ready);
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Execute,
            "strict queued op10 is the same software-only delivery lane as op8",
        );

        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_descriptor.flags |= DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD;
        });
        let hintless_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, false));
        assert!(!hintless_ready);
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );

        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_descriptor = DriverRuntimeCyw43CommandDescriptor {
                op: DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
                payload_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
                payload_len: CYW43_CDC_HEADER_BYTES as u16,
                total_len: CYW43_CDC_HEADER_BYTES as u32,
                arg1: 1,
                ..DriverRuntimeCyw43CommandDescriptor::empty()
            };
        });
        let physical_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, false));
        assert!(!physical_ready);
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );

        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_descriptor = strict_descriptor;
            transaction.parent_input_sealed = false;
        });
        let unsealed_ready = CYW43_RUNTIME_STATE
            .with_ref(|state| cyw43_dpc_queue_only_delivery_ready(command, state, false));
        assert!(!unsealed_ready);
        assert_eq!(
            CYW43_RUNTIME_STATE.with_ref(|state| {
                cyw43_dpc_pending_intake_route(intake, state, true, true, false, false, false)
            }),
            Cyw43DpcPendingCommandRoute::Wait,
        );
        CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            transaction.parent_input_sealed = true;
        });

        let snapshots_before = TEST_CYW43_FOREGROUND_STATE_SNAPSHOTS.load(Ordering::Acquire);
        let root_wake_signals_before = TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire);
        let rx_frames_before = CYW43_RUNTIME_STATE.with_ref(|state| state.rx_frames);
        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        });
        assert_eq!(
            read_cyw43_command_descriptor_physical(command.frame),
            Some(DriverRuntimeCyw43CommandDescriptor {
                op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
                ..DriverRuntimeCyw43CommandDescriptor::empty()
            }),
            "DPC-style shared-aperture reuse must not replace the intake-sealed op8 authority",
        );

        let _production_mode = ProductionForegroundModeGuard::enter();
        let turn = service_command_turn(0, command);
        let batch = read_cyw43_rx_batch_for_test();
        assert_eq!(
            turn,
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord {
                sequence: parent_sequence,
                code: COMPLETION_FRAME_READY,
                detail: DRIVER_RUNTIME_CYW43_RX_BATCH_DETAIL,
                result: 1,
                frame: DriverFrameDescriptor {
                    offset: u32::from(DRIVER_RUNTIME_CYW43_RX_BATCH_OFFSET),
                    len: DRIVER_RUNTIME_CYW43_RX_BATCH_RECORD_BYTES,
                    flags: 0,
                },
            }),
        );
        assert!(batch.valid());
        assert_eq!(batch.parent_sequence, parent_sequence);
        assert_eq!(batch.count, 1);
        assert_eq!(batch.remaining, 0);
        assert_eq!(batch.entries[0].len, payload.len() as u16);
        assert_eq!(
            batch.entries[0].flags,
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 23),
        );
        assert_eq!(
            TEST_CYW43_FOREGROUND_STATE_SNAPSHOTS.load(Ordering::Acquire),
            snapshots_before,
            "a proven terminal queue pop must not copy the complete CYW43 state",
        );
        assert_eq!(
            TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire),
            root_wake_signals_before,
            "queue delivery must neither clear nor manufacture the root scheduling edge",
        );
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            assert!(!transaction.active);
            assert!(!transaction.executing);
            assert!(!transaction.parent_input_sealed);
            assert!(!transaction.baseline_state_valid);
        });
        assert!(CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire));
        assert_eq!(
            CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire),
            active_cursor.child.expected_sequence,
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert_eq!(
                state.dpc_cursor, active_cursor,
                "software-only queue delivery preserves the in-flight DPC cursor and child byte-for-byte",
            );
            assert_eq!(state.rx_queue_count, 0);
            assert_eq!(state.rx_frames, rx_frames_before.saturating_add(1));
            assert_eq!(state.service_trace_op, DRIVER_RUNTIME_CYW43_OP_RX_POLL);
            assert_eq!(state.service_trace_reason, CYW43_SERVICE_REASON_RX_POLL);
            assert_eq!(state.service_trace_progress, payload.len() as u32);
        });
        assert_eq!(
            snapshot_runtime_wire::<16>(batch.entries[0].offset as usize),
            payload,
        );

        let hintless_payload = *b"hintless-queued!";
        stage_bytes(payload_offset, &hintless_payload);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            assert!(cyw43_rx_queue_push_from_runtime(
                state,
                payload_offset,
                hintless_payload.len(),
                cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 24),
            ));
        });
        let hintless_descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            flags: DRIVER_RUNTIME_CYW43_FLAG_RX_STEADY_TAIL_DRAIN
                | DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        stage_cyw43_descriptor(hintless_descriptor);
        let mut hintless_command = cyw43_descriptor_command(parent_sequence.wrapping_add(1));
        hintless_command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        hintless_command.aux1 = generation;
        let hintless_intake = runtime_command_intake_after_pre_admit(hintless_command, false);
        assert_eq!(hintless_intake.command, hintless_command);
        let hintless_snapshots_before =
            TEST_CYW43_FOREGROUND_STATE_SNAPSHOTS.load(Ordering::Acquire);
        let hintless_wake_signals_before = TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire);
        assert_eq!(
            service_command_turn(0, hintless_command),
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::frame_ready_with_descriptor(
                hintless_command.sequence,
                DriverFrameDescriptor {
                    offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                    len: hintless_payload.len() as u16,
                    flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 24),
                },
            )),
            "hintless audit authority retains the ordinary foreground path even when data is queued",
        );
        assert_eq!(
            TEST_CYW43_FOREGROUND_STATE_SNAPSHOTS.load(Ordering::Acquire),
            hintless_snapshots_before.saturating_add(1),
            "hintless op8 must retain the full rollback baseline",
        );
        assert_eq!(
            TEST_CYW43_ROOT_WAKE_SIGNALS.load(Ordering::Acquire),
            hintless_wake_signals_before,
            "ordinary queued completion also leaves wake clearing to root",
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert_eq!(state.dpc_cursor, active_cursor);
            assert_eq!(state.rx_queue_count, 0);
        });
        CYW43_SDIO_CHILD_ACTIVE.store(false, Ordering::Release);
        CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.store(0, Ordering::Release);
    }

    #[test]
    fn control_source_probe_widens_only_its_exact_parent_dpc_watermark() {
        let _guard = test_guard();
        let generation = 0x4359_d0a1;
        let parent_sequence = 0x4359_d0a2;
        initialize_production_foreground_pair(generation);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.dpc_shared_epoch = generation;
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let original = cyw43_foreground_dpc_watermark_for_command(
            parent_sequence,
            Cyw43ForegroundDpcWatermark::empty(),
        )
        .ready()
        .expect("initial watermark");
        assert!(!original.includes(1));
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(1),
        );
        assert_eq!(
            cyw43_foreground_dpc_watermark_for_command(parent_sequence, original),
            Cyw43ForegroundDpcWatermarkRefresh::Ready(original),
            "a post-watermark event cannot preempt without the exact probe completion",
        );
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                SDHCI_INT_CARD_INT,
                0,
                DPC_REASON_SDIO_CARD_INTERRUPT,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
            ),
            DpcRingPublishResult::Published(2),
        );

        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(1, Ordering::Release);
        CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(parent_sequence, Ordering::Release);
        let refreshed = cyw43_foreground_dpc_watermark_for_command(parent_sequence, original)
            .ready()
            .expect("exact source event refresh");
        assert!(refreshed.includes(1));
        assert!(!refreshed.includes(2));
        assert_eq!(
            CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.load(Ordering::Acquire),
            0,
        );
        assert_eq!(
            CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.load(Ordering::Acquire),
            0,
        );
        assert_eq!(
            cyw43_foreground_dpc_watermark_for_command(parent_sequence, refreshed),
            Cyw43ForegroundDpcWatermarkRefresh::Ready(refreshed),
        );

        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(2, Ordering::Release);
        CYW43_DPC_WATERMARK_REFRESH_SEQUENCE
            .store(parent_sequence.wrapping_add(1), Ordering::Release);
        assert_eq!(
            cyw43_foreground_dpc_watermark_for_command(parent_sequence, refreshed),
            Cyw43ForegroundDpcWatermarkRefresh::Ready(refreshed),
            "a stale replacement-parent request cannot widen this parent",
        );
    }

    #[test]
    fn source_probe_completion_requires_front_source_event_and_accepts_wrapped_zero() {
        let _guard = test_guard();
        let generation = 0x4359_d0b1;
        let parent_sequence = 0x4359_d0b2;
        let owner_sequence = 0x8359_d0b3;
        initialize_production_foreground_pair(generation);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.dpc_shared_epoch = generation;
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let descriptor = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_DPC_ACTIVATE,
            addr: generation,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_DPC_FORCE_SOURCE_PROBE,
            timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let mut command = stage_sdio_descriptor_service_command(owner_sequence, descriptor);
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        command.aux1 = generation;
        let mut entry = Cyw43ForegroundTraceEntry::empty();
        entry.ticket = Cyw43ForegroundActionTicket {
            parent_sequence,
            generation,
            owner_sequence,
            ordinal: 0,
            issued_turn_id: 1,
        };
        entry.command = command;
        entry.descriptor = descriptor;

        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                0,
            ),
            DpcRingPublishResult::Published(1),
        );
        assert!(
            !cyw43_foreground_completion_matches(
                entry,
                DriverTaskCompletionRecord::progress(owner_sequence, 1),
            ),
            "a committed event without a source flag cannot authorize foreground replay",
        );

        dpc_event_ring_initialize_at(dpc_base, generation);
        for expected_sequence in 1..=2 {
            assert_eq!(
                dpc_event_ring_publish_at(
                    dpc_base,
                    generation,
                    0,
                    0,
                    DPC_REASON_SDIO_SOURCE_PENDING,
                    DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
                ),
                DpcRingPublishResult::Published(expected_sequence),
            );
        }
        assert!(cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 1),
        ));
        assert!(
            !cyw43_foreground_completion_matches(
                entry,
                DriverTaskCompletionRecord::progress(owner_sequence, 2),
            ),
            "a later committed event cannot stand in for the front source event",
        );

        let mut wrapped = DriverRuntimeDpcEventRing::empty(generation);
        wrapped.producer = u32::MAX;
        wrapped.consumer = u32::MAX;
        assert!(dpc_event_ring_encode(
            RuntimeRingWindow::dpc_at(dpc_base).expect("generated DPC ring window"),
            wrapped,
        ));
        let original = Cyw43ForegroundDpcWatermark::capture(parent_sequence, u32::MAX, u32::MAX);
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(0),
        );
        assert!(cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 0),
        ));
        assert!(cyw43_dpc_source_probe_completion_exact(
            DriverTaskCompletionRecord::progress(owner_sequence, 0),
            owner_sequence,
        ));
        CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(0, Ordering::Release);
        CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(parent_sequence, Ordering::Release);
        let refreshed = cyw43_foreground_dpc_watermark_for_command(parent_sequence, original)
            .ready()
            .expect("wrapped source event refresh");
        assert!(refreshed.includes(0));
        assert_eq!(
            CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.load(Ordering::Acquire),
            0,
        );
    }

    #[test]
    fn forced_source_probe_completion_accepts_retained_consumed_watermark_range() {
        let _guard = test_guard();
        let generation = 0x4359_d0c1;
        let parent_sequence = 0x4359_d0c2;
        let owner_sequence = 0x8359_d0c3;
        initialize_production_foreground_pair(generation);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.dpc_shared_epoch = generation;
        });
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(1),
        );
        let descriptor = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_DPC_ACTIVATE,
            addr: generation,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_DPC_FORCE_SOURCE_PROBE,
            timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let mut command = stage_sdio_descriptor_service_command(owner_sequence, descriptor);
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        command.aux1 = generation;
        let mut entry = Cyw43ForegroundTraceEntry::empty();
        entry.ticket = Cyw43ForegroundActionTicket {
            parent_sequence,
            generation,
            owner_sequence,
            ordinal: 0,
            issued_turn_id: 1,
        };
        entry.command = command;
        entry.descriptor = descriptor;
        let completion = DriverTaskCompletionRecord::progress(owner_sequence, 1);

        assert!(cyw43_foreground_completion_matches(entry, completion));
        assert!(dpc_event_ring_advance_at(dpc_base, generation, 1));
        assert!(
            !cyw43_foreground_completion_matches(entry, completion),
            "ring advance alone is not durable DPC-consume authority",
        );

        cyw43_publish_dpc_consumed_watermark(generation, 1);
        assert!(cyw43_foreground_completion_matches(entry, completion));

        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(2),
        );
        assert!(dpc_event_ring_advance_at(dpc_base, generation, 2));
        cyw43_publish_dpc_consumed_watermark(generation, 2);
        assert!(
            cyw43_foreground_completion_matches(entry, completion),
            "consuming N+1 must retain exact authority for retained source event N",
        );
        assert_eq!(
            cyw43_capture_foreground_dpc_watermark_through(parent_sequence, 1),
            Some(Cyw43ForegroundDpcWatermark::capture(parent_sequence, 2, 2,)),
        );
        assert!(!cyw43_dpc_event_sequence_consumed(
            generation.wrapping_add(1),
            1,
        ));
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(3),
        );
        assert!(
            !cyw43_dpc_event_sequence_consumed(generation, 3),
            "a published but unconsumed future event is not watermark authority",
        );
        assert!(
            !cyw43_dpc_event_sequence_consumed(generation, 4),
            "an absent future event is not watermark authority",
        );
        assert!(!cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 4),
        ));

        let mut wrapped = DriverRuntimeDpcEventRing::empty(generation);
        wrapped.producer = u32::MAX - 1;
        wrapped.consumer = u32::MAX - 1;
        assert!(dpc_event_ring_encode(
            RuntimeRingWindow::dpc_at(dpc_base).expect("generated DPC ring window"),
            wrapped,
        ));
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(u32::MAX),
        );
        assert!(dpc_event_ring_advance_at(dpc_base, generation, u32::MAX));
        cyw43_publish_dpc_consumed_watermark(generation, u32::MAX);
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(0),
        );
        assert!(dpc_event_ring_advance_at(dpc_base, generation, 0));
        cyw43_publish_dpc_consumed_watermark(generation, 0);
        assert!(
            cyw43_dpc_event_sequence_consumed(generation, u32::MAX),
            "the bounded consumed range remains valid across sequence wrap",
        );
        assert!(
            !cyw43_dpc_event_sequence_consumed(generation, 1),
            "a post-wrap future sequence cannot alias the consumed range",
        );
        assert!(cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, u32::MAX),
        ));
    }

    #[test]
    fn accepted_source_probe_event_loss_is_one_terminal_generation_fault() {
        let _guard = test_guard();
        for mutation in 0..3u32 {
            let generation = 0x4359_d0c1 + mutation;
            let parent_sequence = 0x4359_d0d1 + mutation;
            let owner_sequence = 0x8359_d0e1 + mutation;
            initialize_production_foreground_pair(generation);
            CYW43_RUNTIME_STATE.with_mut(|state| {
                state.dpc_link_ready = true;
                state.dpc_shared_epoch = generation;
            });
            let dpc_base =
                DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
            let original = cyw43_capture_foreground_dpc_watermark(parent_sequence);
            assert_eq!(
                dpc_event_ring_publish_at(
                    dpc_base,
                    generation,
                    0,
                    0,
                    DPC_REASON_SDIO_SOURCE_PENDING,
                    DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
                ),
                DpcRingPublishResult::Published(1),
            );
            let descriptor = DriverRuntimeSdioCommandDescriptor {
                op: DRIVER_RUNTIME_SDIO_OP_DPC_ACTIVATE,
                addr: generation,
                flags: DriverRuntimeSdioCommandDescriptor::FLAG_DPC_FORCE_SOURCE_PROBE,
                timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
                ..DriverRuntimeSdioCommandDescriptor::empty()
            };
            let mut command = stage_sdio_descriptor_service_command(owner_sequence, descriptor);
            command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
            command.aux1 = generation;
            let mut entry = Cyw43ForegroundTraceEntry::empty();
            entry.ticket = Cyw43ForegroundActionTicket {
                parent_sequence,
                generation,
                owner_sequence,
                ordinal: 0,
                issued_turn_id: 1,
            };
            entry.command = command;
            entry.descriptor = descriptor;
            assert!(
                cyw43_foreground_completion_matches(
                    entry,
                    DriverTaskCompletionRecord::progress(owner_sequence, 1),
                ),
                "case {mutation}: exact completion must be accepted before mutation",
            );

            match mutation {
                0 => {
                    assert!(dpc_event_ring_advance_at(dpc_base, generation, 1));
                }
                1 => {
                    assert!(dpc_event_ring_advance_at(dpc_base, generation, 1));
                    assert_eq!(
                        dpc_event_ring_publish_at(
                            dpc_base,
                            generation,
                            SDHCI_INT_CARD_INT,
                            0,
                            DPC_REASON_SDIO_CARD_INTERRUPT,
                            DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
                        ),
                        DpcRingPublishResult::Published(2),
                    );
                }
                2 => {
                    let mut corrupt = dpc_event_ring_read_at(dpc_base);
                    corrupt.entries[0].flags = 0;
                    assert!(dpc_event_ring_encode(
                        RuntimeRingWindow::dpc_at(dpc_base).expect("generated DPC ring window"),
                        corrupt,
                    ));
                }
                _ => unreachable!(),
            }

            CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.store(1, Ordering::Release);
            CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.store(parent_sequence, Ordering::Release);
            assert_eq!(
                cyw43_foreground_dpc_watermark_for_command(parent_sequence, original),
                Cyw43ForegroundDpcWatermarkRefresh::InvariantFault { event_sequence: 1 },
                "case {mutation}",
            );
            let terminal = cyw43_terminal_foreground_dpc_refresh_fault(parent_sequence, 1);
            assert_eq!(
                terminal,
                DriverTaskCompletionRecord::fault_with_result(
                    parent_sequence,
                    FAULT_CYW43_TRANSPORT_BUS_LINK,
                    1,
                ),
                "case {mutation}",
            );
            assert!(CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));
            assert!(CYW43_DPC_DEFERRED.load(Ordering::Acquire));
            assert_eq!(
                CYW43_DPC_WATERMARK_REFRESH_SEQUENCE.load(Ordering::Acquire),
                0,
            );
            assert_eq!(
                CYW43_DPC_WATERMARK_REFRESH_EVENT_SEQUENCE.load(Ordering::Acquire),
                0,
            );
            CYW43_RUNTIME_STATE.with_ref(|state| {
                assert!(state.recovery_required);
                assert!(!state.initialized);
                assert!(!state.transport_ready);
                assert!(!state.firmware_released);
                assert_eq!(state.dpc_sequence_errors, 1);
            });
            assert_eq!(
                cyw43_foreground_dpc_watermark_for_command(parent_sequence, original),
                Cyw43ForegroundDpcWatermarkRefresh::Ready(original),
                "case {mutation}: cleared marker cannot request repeated continuation grants",
            );
        }
    }

    #[test]
    fn cyw43_foreground_transaction_scope_excludes_runtime_and_engine_init() {
        let physical = cyw43_descriptor_command(0x43);
        assert!(cyw43_command_uses_foreground_transaction(physical));

        let mut command = physical;
        command.aux0 = DRIVER_RUNTIME_ENGINE_INIT_AUX;
        command.frame = DriverFrameDescriptor::empty();
        assert!(!cyw43_command_uses_foreground_transaction(command));

        command = physical;
        command.aux0 = DRIVER_RUNTIME_INIT_AUX;
        command.frame.len = core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16;
        assert!(!cyw43_command_uses_foreground_transaction(command));

        for malformed in [
            DriverTaskCommandRecord {
                sequence: 0,
                ..physical
            },
            DriverTaskCommandRecord {
                opcode: OPCODE_SHUTDOWN,
                ..physical
            },
            DriverTaskCommandRecord {
                arg1: ROLE_SDIO,
                ..physical
            },
            DriverTaskCommandRecord {
                aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
                ..physical
            },
            DriverTaskCommandRecord {
                frame: DriverFrameDescriptor::empty(),
                ..physical
            },
        ] {
            assert!(!cyw43_command_uses_foreground_transaction(malformed));
        }
    }

