    #[test]
    fn dpc_foreground_watermark_bounds_continuously_reasserted_events() {
        let epoch = 0x4359_5301;
        let command_sequence = 0x90;
        let mut ring = DriverRuntimeDpcEventRing::empty(epoch);
        for signal_status in 0..DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32 {
            assert!(matches!(
                dpc_event_ring_publish(
                    &mut ring,
                    epoch,
                    SDHCI_INT_CARD_INT,
                    signal_status,
                    DPC_REASON_SDIO_CARD_INTERRUPT,
                    DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
                ),
                DpcRingPublishResult::Published(_)
            ));
        }

        let mut foreground_quanta = 0usize;
        for phase in 0..8usize {
            // runtime_main takes a fresh snapshot after each retained
            // multi-phase foreground quantum. Events already committed at
            // this point drain first, while every immediate reassertion below
            // is newer than this immutable producer watermark.
            let watermark = Cyw43ForegroundDpcWatermark::capture(
                command_sequence,
                ring.consumer,
                ring.producer,
            );
            let mut drained = 0usize;
            loop {
                let event = dpc_event_ring_peek(&ring, epoch);
                if !cyw43_dpc_command_requires_preflight(
                    true, false, false, false, event, watermark, false,
                ) {
                    break;
                }
                let DpcRingConsumeResult::Event(event) = event else {
                    panic!("valid adversarial ring must expose an event");
                };
                assert!(dpc_event_ring_advance(&mut ring, epoch, event.sequence));
                drained = drained.saturating_add(1);

                // Model a device that republishes CARD_INT as soon as each
                // slot becomes available. This event must remain behind the
                // captured producer watermark for the current arbitration.
                assert!(matches!(
                    dpc_event_ring_publish(
                        &mut ring,
                        epoch,
                        SDHCI_INT_CARD_INT,
                        phase as u32,
                        DPC_REASON_SDIO_CARD_INTERRUPT,
                        DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
                    ),
                    DpcRingPublishResult::Published(_)
                ));
            }
            assert_eq!(drained, DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH);
            assert!(matches!(
                dpc_event_ring_peek(&ring, epoch),
                DpcRingConsumeResult::Event(event)
                    if !watermark.includes(event.sequence)
            ));

            // This is the guaranteed foreground service quantum. The command
            // remains retained, so the next phase re-arms and gives the DPC
            // another bounded batch before foreground progress resumes.
            foreground_quanta = foreground_quanta.saturating_add(1);
        }
        assert_eq!(foreground_quanta, 8);
    }

    #[test]
    fn dpc_foreground_watermark_handles_sequence_wrap_and_bad_ring_fail_closed() {
        let watermark = Cyw43ForegroundDpcWatermark::capture(7, u32::MAX - 1, 1);
        assert!(watermark.includes(u32::MAX));
        assert!(watermark.includes(0));
        assert!(watermark.includes(1));
        assert!(!watermark.includes(2));
        assert!(cyw43_dpc_command_requires_preflight(
            true,
            false,
            false,
            false,
            DpcRingConsumeResult::BadEpoch,
            watermark,
            false,
        ));

        let invalid = Cyw43ForegroundDpcWatermark::capture(
            8,
            0,
            DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32 + 1,
        );
        assert!(!invalid.armed);
        assert!(!invalid.includes(1));
    }

    #[test]
    fn dpc_quarantine_and_post_capture_policy_are_terminal_and_lossless() {
        assert!(!cyw43_dpc_generation_quarantined(false, false));
        assert!(cyw43_dpc_generation_quarantined(true, false));
        assert!(cyw43_dpc_generation_quarantined(false, true));

        assert!(cyw43_dpc_post_capture_has_work(
            true,
            false,
            64,
            I_HMB_HOST_INT
        ));
        assert!(!cyw43_dpc_post_capture_has_work(
            true,
            false,
            64,
            I_HMB_FRAME_IND
        ));
        assert!(cyw43_dpc_post_capture_has_work(
            false,
            true,
            0,
            I_HMB_HOST_INT
        ));
        assert!(cyw43_dpc_post_capture_has_work(
            false,
            true,
            0,
            I_HMB_FC_CHANGE
        ));
        assert!(cyw43_dpc_post_capture_has_work(
            false,
            true,
            0,
            I_HMB_FRAME_IND
        ));
        assert!(cyw43_dpc_post_capture_has_work(false, false, 0, 0));
        assert!(cyw43_dpc_post_capture_has_work(false, true, 64, 0));
        assert!(!cyw43_dpc_post_capture_has_work(false, true, 0, 0));
        assert_eq!(
            cyw43_dpc_latched_causes(
                I_HMB_FRAME_IND | I_HMB_FC_CHANGE | I_HMB_HOST_INT | I_HMB_FC_STATE | I_CHIPACTIVE
            ),
            I_HMB_FRAME_IND | I_HMB_FC_CHANGE | I_HMB_HOST_INT
        );
        for level_only in [I_HMB_FC_STATE, I_CHIPACTIVE, I_HMB_FC_STATE | I_CHIPACTIVE] {
            assert_eq!(cyw43_dpc_latched_causes(level_only), 0);
            assert_eq!(cyw43_dpc_w1c_status(level_only), level_only);
            assert!(cyw43_dpc_status_requires_ack(level_only));
        }
    }

    #[test]
    fn post_core_start_release_failure_requires_generation_recovery() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.transport_ready = true;
        state.firmware_execution_started = true;
        state.firmware_released = true;

        assert!(!cyw43_release_fail_closed(&mut state));
        assert!(state.recovery_required);
        assert!(!state.transport_ready);
        assert!(!state.firmware_released);
        assert!(state.firmware_execution_started);

        let mut pre_start = Cyw43RuntimeState::new();
        pre_start.transport_ready = true;
        assert!(!cyw43_release_fail_closed(&mut pre_start));
        assert!(!pre_start.recovery_required);
        assert!(pre_start.transport_ready);
    }

    #[test]
    fn engine_init_requires_canonical_pair_restart_to_clear_quarantine() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_CYW43_WIFI, ROLE_NET);
        let link = descriptor_notification_dpc_link(&descriptor).expect("CYW43 DPC link");
        let mut state = Cyw43RuntimeState::new();
        state.recovery_required = true;
        state.sdio_transport_enumerated = true;
        state.dpc_shared_epoch = link.shared_epoch;
        state.dpc_cursor.event_sequence = 7;
        state.firmware_execution_started = true;

        assert!(!cyw43_runtime_init(
            92,
            DRIVER_RUNTIME_ENGINE_INIT_AUX,
            &mut state,
            &descriptor,
        ));
        assert_eq!(state.dpc_shared_epoch, link.shared_epoch);
        assert!(state.recovery_required);
        assert_eq!(state.dpc_cursor.event_sequence, 7);
        assert!(state.firmware_execution_started);
        assert!(state.sdio_transport_enumerated);
        assert!(!state.transport_ready);
        assert!(CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));

        state.reset_for_pair_restart();
        CYW43_SDIO_PAIR_RESTART_REQUIRED.store(false, Ordering::Release);
        assert!(cyw43_runtime_init(
            93,
            DRIVER_RUNTIME_ENGINE_INIT_AUX,
            &mut state,
            &descriptor,
        ));
        assert_eq!(state.dpc_shared_epoch, link.shared_epoch);
        assert!(!state.recovery_required);
        assert!(state.initialized);
        assert!(state.bus_link_ready);
        assert!(state.dpc_link_ready);
        assert!(!state.sdio_transport_enumerated);
        assert!(!state.transport_ready);
    }

    #[test]
    fn dpc_child_completion_requires_exact_code_result_and_frame_shape() {
        let child = Cyw43DpcChild {
            expected_code: COMPLETION_FRAME_READY,
            expected_result: 64,
            expected_frame_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
            expected_frame_len: 64,
            read_frame: DriverFrameDescriptor {
                offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
                len: 64,
                flags: 0,
            },
            ..Cyw43DpcChild::empty()
        };
        let exact = DriverTaskCompletionRecord::frame_ready_at(
            81,
            DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
            64,
        );
        assert!(cyw43_dpc_child_completion_matches(child, exact));

        let mut wrong_code = exact;
        wrong_code.code = COMPLETION_PROGRESS;
        assert!(!cyw43_dpc_child_completion_matches(child, wrong_code));
        let mut short_result = exact;
        short_result.result = 32;
        assert!(!cyw43_dpc_child_completion_matches(child, short_result));
        let mut wrong_offset = exact;
        wrong_offset.frame.offset = wrong_offset.frame.offset.saturating_add(1);
        assert!(!cyw43_dpc_child_completion_matches(child, wrong_offset));
        let mut short_frame = exact;
        short_frame.frame.len = 32;
        assert!(!cyw43_dpc_child_completion_matches(child, short_frame));

        let write_child = Cyw43DpcChild {
            expected_code: COMPLETION_PROGRESS,
            expected_result: 1,
            ..Cyw43DpcChild::empty()
        };
        assert!(cyw43_dpc_child_completion_matches(
            write_child,
            DriverTaskCompletionRecord::progress(82, 1)
        ));
        assert!(!cyw43_dpc_child_completion_matches(
            write_child,
            DriverTaskCompletionRecord::progress(82, 0)
        ));
    }

    #[test]
    fn dpc_recovery_rframe_drain_requires_zero_before_nak_and_quarantines_at_bound() {
        assert_eq!(
            cyw43_dpc_recovery_drain_route(0, 1, false),
            Cyw43DpcRecoveryDrainRoute::PostNak
        );

        for completed_polls in 1..4 {
            assert_eq!(
                cyw43_dpc_recovery_drain_route(7, completed_polls, false),
                Cyw43DpcRecoveryDrainRoute::Retry
            );
        }
        assert_eq!(
            cyw43_dpc_recovery_drain_route(0, 4, false),
            Cyw43DpcRecoveryDrainRoute::PostNak
        );

        assert_eq!(
            cyw43_dpc_recovery_drain_route(1, CYW43_RX_SOURCE_RECOVERY_DRAIN_POLLS, false),
            Cyw43DpcRecoveryDrainRoute::Quarantine
        );
        assert_eq!(
            cyw43_dpc_recovery_drain_route(1, 1, true),
            Cyw43DpcRecoveryDrainRoute::Quarantine
        );
        assert!(!cyw43_dpc_recovery_settle_ready(100, 10, 109, 0));
        assert!(cyw43_dpc_recovery_settle_ready(100, 10, 110, 1));
        assert!(!cyw43_dpc_recovery_settle_ready(0, 0, 0, 1));
        assert!(cyw43_dpc_recovery_settle_ready(0, 0, 0, 0));
    }

    #[test]
    fn dpc_backplane_write32_is_one_atomic_incrementing_cmd53() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let sampled = I_HMB_HOST_INT | I_HMB_FC_CHANGE;
        let arriving = I_HMB_FRAME_IND;
        let addr = CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS;
        let transfer = cyw43_dpc_backplane_write32_transfer(addr);
        let payload = cyw43_dpc_backplane_write32_payload(sampled);
        let descriptor = sdio_bus_link_cmd53_descriptor(
            transfer.cmd,
            transfer.arg,
            transfer.flags,
            transfer.frame,
            transfer.block_size,
            transfer.block_count,
            0,
        )
        .expect("DPC W1C word must encode as one SDIO descriptor");

        assert_eq!(descriptor.op, DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE);
        assert_eq!(descriptor.function, 1);
        assert_eq!(descriptor.addr, cyw43_backplane_function_addr(addr));
        assert_eq!(descriptor.len, 4);
        assert_eq!(descriptor.block_size, 0);
        assert_eq!(descriptor.block_count, 0);
        assert_eq!(
            descriptor.flags,
            DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT,
        );
        for (index, value) in payload.into_iter().enumerate() {
            write_runtime_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET + index, value);
        }

        let sequence = 0x8000_6d50;
        let command = stage_sdio_descriptor_service_command(sequence, descriptor);
        let mut io = TestSdioHostIo::new();
        io.use_runtime_payload = true;
        io.command_status = SDHCI_INT_RESPONSE | SDHCI_INT_SPACE_AVAIL;
        io.command_present_set = SDHCI_SPACE_AVAILABLE | SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE;
        io.data_end_after_words = 1;
        let completion = service_sdio_descriptor_command_with_io(command, &mut io);

        assert_eq!(
            completion,
            DriverTaskCompletionRecord::progress(sequence, payload.len() as u32),
        );
        assert_eq!(io.command_issue_count(), 1);
        assert_eq!(&io.fifo[..payload.len()], &payload);
        assert_eq!(
            io.writes[..io.write_count]
                .iter()
                .filter(|write| write.offset == (SDHCI_COMMAND & !0x3))
                .count(),
            1,
            "no bytewise CMD52 acknowledgement may be interposed",
        );

        // A cause that arrives after the status sample but before the single
        // W1C word commits remains asserted. There is no first-byte/tail-byte
        // interval in which the device can observe a partial acknowledgement.
        test_cyw43_sdio_int_status_response(sampled | arriving);
        let committed = u32::from_le_bytes(payload);
        test_cyw43_backplane_write_u32_response(addr, committed);
        assert_eq!(test_cyw43_backplane_read_u32_response(addr), Some(arriving));
    }

    #[test]
    fn dpc_cursor_routes_by_exact_owner_state() {
        let mut cursor = Cyw43DpcCursor::empty();
        assert_eq!(
            cyw43_dpc_turn_route(&cursor),
            Cyw43DpcTurnRoute::CompleteEvent
        );

        cursor.event_sequence = 41;
        cursor.action = Cyw43DpcAction::CaptureStatus;
        cursor.io_kind = Cyw43DpcIoKind::BackplaneRead32;
        cursor.io_phase = Cyw43DpcIoPhase::WindowLow;
        assert_eq!(
            cyw43_dpc_turn_route(&cursor),
            Cyw43DpcTurnRoute::SubmitChild
        );

        cursor.child.active = true;
        cursor.child.expected_sequence = 0x8000_0042;
        assert_eq!(cyw43_dpc_turn_route(&cursor), Cyw43DpcTurnRoute::PollChild);
        assert_eq!(cursor.event_sequence, 41);

        cursor.child = Cyw43DpcChild::empty();
        cursor.action = Cyw43DpcAction::None;
        cursor.io_phase = Cyw43DpcIoPhase::Idle;
        assert_eq!(
            cyw43_dpc_turn_route(&cursor),
            Cyw43DpcTurnRoute::CompleteEvent,
            "a terminal child poll must return before event advance/rearm",
        );

        cursor.child.active = true;
        cursor.child.expected_sequence = 0x8000_0042;
        cursor.child.issued_unknown = true;
        assert_eq!(cyw43_dpc_turn_route(&cursor), Cyw43DpcTurnRoute::Quarantine);
        assert_eq!(cursor.child.expected_sequence, 0x8000_0042);
    }

    #[test]
    fn dpc_cursor_retains_event_until_terminal_state_and_reset() {
        let mut cursor = Cyw43DpcCursor::empty();
        cursor.event_sequence = 7;
        cursor.action = Cyw43DpcAction::FifoWindow;
        cursor.io_kind = Cyw43DpcIoKind::WindowOnly;
        cursor.io_phase = Cyw43DpcIoPhase::Idle;
        assert_eq!(
            cyw43_dpc_turn_route(&cursor),
            Cyw43DpcTurnRoute::AdvanceState
        );
        assert_eq!(cursor.event_sequence, 7);

        cursor.action = Cyw43DpcAction::None;
        assert_eq!(
            cyw43_dpc_turn_route(&cursor),
            Cyw43DpcTurnRoute::CompleteEvent
        );
        cursor.reset();
        assert_eq!(cursor, Cyw43DpcCursor::empty());
    }

