    #[test]
    fn cyw43_fault_frame_state_round_trips_and_clears() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let frame = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: SDIO_FAULT_TELEMETRY_BYTES,
            flags: 0x0012,
        };

        cyw43_record_last_fault_with_result(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED, 0x0300_0001);
        cyw43_record_last_fault_frame(frame);

        assert_eq!(
            cyw43_take_last_fault_detail(),
            Some(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED)
        );
        assert_eq!(cyw43_take_last_fault_result(), 0x0300_0001);
        assert_eq!(cyw43_take_last_fault_frame(), frame);

        cyw43_clear_last_fault();

        assert_eq!(cyw43_take_last_fault_detail(), None);
        assert_eq!(cyw43_take_last_fault_result(), 0);
        assert_eq!(
            cyw43_take_last_fault_frame(),
            DriverFrameDescriptor::empty()
        );
    }

    fn runtime_task_key_for_hot_path(hot_path: u32) -> usize {
        match hot_path {
            HOT_PATH_SERIAL_CONSOLE => 0,
            HOT_PATH_USB_KEYBOARD => 1,
            HOT_PATH_HDMI_TEXT => 2,
            HOT_PATH_GENET_NIC => 3,
            HOT_PATH_CYW43_WIFI => 4,
            HOT_PATH_SDIO_HOST => 7,
            HOT_PATH_PCIE_ROOT => 8,
            _ => 0,
        }
    }

    fn runtime_artifact_hash_for_hot_path(hot_path: u32) -> u32 {
        pi4_driver_abi::driver_runtime_artifact_hash(match hot_path {
            HOT_PATH_SERIAL_CONSOLE => "cohesix/bin/pi4-driver-serial",
            HOT_PATH_USB_KEYBOARD => "cohesix/bin/pi4-driver-usb",
            HOT_PATH_HDMI_TEXT => "cohesix/bin/pi4-driver-hdmi",
            HOT_PATH_GENET_NIC => "cohesix/bin/pi4-driver-genet",
            HOT_PATH_CYW43_WIFI => "cohesix/bin/pi4-driver-cyw43",
            HOT_PATH_SDIO_HOST => "cohesix/bin/pi4-driver-sdio",
            HOT_PATH_PCIE_ROOT => "cohesix/bin/pi4-driver-pcie",
            _ => "cohesix/bin/pi4-driver-runtime",
        })
    }

    fn seal_descriptor_for_test(
        descriptor: DriverRuntimeInitDescriptor,
        hot_path: u32,
    ) -> DriverRuntimeInitDescriptor {
        let task_key = runtime_task_key_for_hot_path(hot_path) as u32;
        let (slot, core, budget, standard_badge, timeout_badge) = match hot_path {
            HOT_PATH_SERIAL_CONSOLE => (10, 1, 500, 0x26e2_0000, 0x26ed_000b),
            HOT_PATH_USB_KEYBOARD => (11, 1, 1_000, 0x26e2_0001, 0x26ed_000c),
            HOT_PATH_HDMI_TEXT => (12, 2, 400, 0x26e2_0002, 0x26ed_000d),
            HOT_PATH_GENET_NIC => (13, 3, 1_000, 0x26e2_0003, 0x26ed_000e),
            HOT_PATH_CYW43_WIFI => (14, 3, 1_500, 0x26e2_0004, 0x26ed_000f),
            HOT_PATH_SDIO_HOST => (15, 3, 1_500, 0x26e2_0005, 0x26ed_0010),
            HOT_PATH_PCIE_ROOT => (16, 2, 400, 0x26e2_0006, 0x26ed_0011),
            _ => (10, 1, 500, 0x26e2_0000, 0x26ed_000b),
        };
        descriptor
            .with_mcs_scheduler(
                task_key,
                slot,
                8,
                core,
                2,
                core,
                budget,
                10_000,
                standard_badge,
                timeout_badge,
            )
            .with_sealed_identity(task_key, runtime_artifact_hash_for_hot_path(hot_path))
    }

    fn descriptor_for(hot_path: u32, role: u32) -> DriverRuntimeInitDescriptor {
        const TEST_CYW43_SDIO_SHARED_EPOCH: u32 = 0x4359_5301;
        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = hot_path;
        descriptor.role_bit = role;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        let (mmio_pages, dma_pages, shared_pages) = match hot_path {
            HOT_PATH_USB_KEYBOARD => (
                USB_REQUIRED_MMIO_PAGES,
                USB_REQUIRED_DMA_PAGES,
                USB_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_HDMI_TEXT => (
                HDMI_REQUIRED_MMIO_PAGES,
                HDMI_REQUIRED_DMA_PAGES,
                HDMI_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_GENET_NIC => (
                GENET_REQUIRED_MMIO_PAGES,
                GENET_REQUIRED_DMA_PAGES,
                GENET_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_CYW43_WIFI => (
                CYW43_REQUIRED_MMIO_PAGES,
                CYW43_REQUIRED_DMA_PAGES,
                CYW43_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_SDIO_HOST => (
                SDIO_REQUIRED_MMIO_PAGES,
                SDIO_REQUIRED_DMA_PAGES,
                SDIO_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_PCIE_ROOT => (PCIE_REQUIRED_MMIO_PAGES, 0, PCIE_REQUIRED_SHARED_PAGES),
            _ => (1, 0, 1),
        };
        let mmio_descriptor_pages =
            mmio_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_MMIO_PAGES as u16);
        let dma_descriptor_pages =
            dma_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_DMA_PAGES as u16);
        let shared_descriptor_pages =
            shared_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_SHARED_PAGES as u16);
        descriptor.mmio_page_count = mmio_descriptor_pages;
        descriptor.dma_page_count = dma_descriptor_pages;
        descriptor.shared_page_count = shared_descriptor_pages;
        for index in 0..usize::from(mmio_descriptor_pages) {
            descriptor.mmio_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x1000_0000 + index * 0x1000);
        }
        for index in 0..usize::from(dma_descriptor_pages) {
            descriptor.dma_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x2000_0000 + index * 0x1000);
        }
        for index in 0..usize::from(shared_descriptor_pages) {
            descriptor.shared_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000 + index * 0x1000);
        }
        let mut range_index = 0usize;
        if mmio_pages != 0 {
            descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_MMIO_MAPPED;
            let primary_mmio_pages = if hot_path == HOT_PATH_SDIO_HOST {
                1
            } else {
                mmio_pages
            };
            descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                match hot_path {
                    HOT_PATH_USB_KEYBOARD => DRIVER_RUNTIME_RESOURCE_TAG_USB_XHCI,
                    HOT_PATH_GENET_NIC => DRIVER_RUNTIME_RESOURCE_TAG_GENET_REGS,
                    HOT_PATH_CYW43_WIFI => DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    HOT_PATH_SDIO_HOST => DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    HOT_PATH_PCIE_ROOT => DRIVER_RUNTIME_RESOURCE_TAG_PCIE_HOST,
                    _ => pi4_driver_abi::DRIVER_RUNTIME_RESOURCE_TAG_GENERIC,
                },
                DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                0x1000_0000,
                u64::from(primary_mmio_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                primary_mmio_pages,
                0,
            );
            range_index += 1;
            if hot_path == HOT_PATH_SDIO_HOST {
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64 + DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    0x1000_1000,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    1,
                    1,
                );
                range_index += 1;
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_BCM2835_DMA,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64
                        + (SDIO_DMA_MMIO_PAGE_INDEX as u64) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    0x1000_2000,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    1,
                    SDIO_DMA_MMIO_PAGE_INDEX as u16,
                );
                range_index += 1;
            }
        }
        if dma_pages != 0 {
            if hot_path == HOT_PATH_SDIO_HOST {
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    0x2000_0000,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    1,
                    SDIO_DMA_PWRSEQ_PAGE_INDEX as u16,
                );
                range_index += 1;
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64
                        + (SDIO_DMA_CONTROL_BLOCK_PAGE_INDEX as u64)
                            * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    0x2000_1000,
                    (1 + SDIO_DMA_BOUNCE_PAGE_COUNT as u64) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    (1 + SDIO_DMA_BOUNCE_PAGE_COUNT) as u16,
                    SDIO_DMA_CONTROL_BLOCK_PAGE_INDEX as u16,
                );
                range_index += 1;
                descriptor.bus_alias_or = BCM2835_DMA_RAM_BUS_ALIAS_OR;
                descriptor.bus_alias_and = BCM2835_DMA_RAM_BUS_ALIAS_AND;
            } else {
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    0x2000_0000,
                    u64::from(dma_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    dma_pages,
                    0,
                );
                range_index += 1;
            }
        }
        if shared_pages != 0 {
            descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                    | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
                if hot_path == HOT_PATH_CYW43_WIFI {
                    DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL
                } else {
                    DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL
                },
                DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                0x4000_0000,
                u64::from(shared_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                shared_pages,
                0,
            );
            range_index += 1;
        }
        descriptor.resource_range_count = range_index as u16;
        match hot_path {
            HOT_PATH_SERIAL_CONSOLE => {
                descriptor.flags &= !DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
                descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND;
                descriptor.irq_count = 1;
                descriptor.irqs[0] = DriverRuntimeIrqDescriptor {
                    irq: DRIVER_RUNTIME_SERIAL_IRQ,
                    badge: DRIVER_RUNTIME_SERIAL_IRQ_BADGE,
                    handler_slot: DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT,
                    notification_slot: DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    trigger: DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL,
                    flags: 0,
                    reserved: 0,
                };
            }
            HOT_PATH_USB_KEYBOARD => {
                descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS;
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_PCIE_ROOT,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
                    0,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                );
            }
            HOT_PATH_CYW43_WIFI => {
                descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS;
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
                    DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
                    DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                )
                .with_notification_dpc(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT,
                    TEST_CYW43_SDIO_SHARED_EPOCH,
                );
            }
            HOT_PATH_SDIO_HOST => {
                descriptor.flags &= !DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
                descriptor.flags |=
                    DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS | DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND;
                descriptor.irq_count = 2;
                descriptor.irqs[0] = DriverRuntimeIrqDescriptor {
                    irq: DRIVER_RUNTIME_SDIO_IRQ,
                    badge: DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                    handler_slot: DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT,
                    notification_slot: DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    trigger: DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL,
                    flags: 0,
                    reserved: 0,
                };
                descriptor.irqs[1] = DriverRuntimeIrqDescriptor {
                    irq: DRIVER_RUNTIME_SDIO_DMA_IRQ,
                    badge: DRIVER_RUNTIME_SDIO_DMA_IRQ_BADGE,
                    handler_slot: DRIVER_TASK_CHILD_SDIO_DMA_IRQ_HANDLER_SLOT,
                    notification_slot: DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    trigger: DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL,
                    flags: 0,
                    reserved: 0,
                };
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
                    DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
                    DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                )
                .with_notification_dpc(
                    HOT_PATH_CYW43_WIFI,
                    DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT,
                    TEST_CYW43_SDIO_SHARED_EPOCH,
                );
            }
            _ => {}
        }
        seal_descriptor_for_test(descriptor, hot_path)
    }

    fn init_runtime_for_test(hot_path: u32, role: u32) {
        let command = DriverTaskCommandRecord {
            sequence: 1,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: hot_path,
            arg1: role,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(hot_path),
                command,
                descriptor_for(hot_path, role)
            ),
            DriverTaskCompletionRecord::progress(1, hot_path)
        );
    }

    fn stage_bytes(offset: usize, bytes: &[u8]) {
        for (index, byte) in bytes.iter().copied().enumerate() {
            write_runtime_payload_byte(offset + index, byte);
        }
    }

    fn stage_sdio_descriptor_service_command(
        sequence: u32,
        desc: DriverRuntimeSdioCommandDescriptor,
    ) -> DriverTaskCommandRecord {
        write_sdio_descriptor_for_test(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
        let transfer_bytes = match sdio_descriptor_effective_transfer_bytes(desc) {
            Some(bytes) => bytes,
            None if sdio_retired_generation_operation_rejection(desc.op).is_some() => 0,
            None => panic!("test stages a supported or explicitly retired SDIO descriptor"),
        };
        DriverTaskCommandRecord {
            sequence,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: 0,
            aux1: 0,
            budget: sdio_bus_link_command_budget(transfer_bytes),
            frame: DriverFrameDescriptor {
                offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
                flags: 0,
            },
        }
    }

    fn sdio_test_pio_block_fifo_accesses(descriptor: DriverRuntimeSdioCommandDescriptor) -> usize {
        let block_bytes = if descriptor.block_count == 0 {
            usize::from(descriptor.len)
        } else {
            usize::from(descriptor.block_size)
        };
        let accesses = block_bytes.div_ceil(core::mem::size_of::<u32>());
        assert!(
            accesses <= usize::from(DRIVER_RUNTIME_SDIO_SERVICE_MAX_OPS),
            "one normalized host block must fit the shared SDIO operation budget",
        );
        accesses
    }

    fn drive_sdio_retained_descriptor_for_test(
        command: DriverTaskCommandRecord,
        descriptor: DriverRuntimeSdioCommandDescriptor,
        io: &mut TestSdioHostIo,
    ) -> DriverTaskCompletionRecord {
        for _ in 0..64 {
            match service_sdio_external_dma_command_turn_with_io(command, descriptor, io) {
                RuntimeCommandTurn::Pending => {
                    let retained = SDIO_RUNTIME_STATE.with_ref(|state| state.external_dma_request);
                    if retained.active()
                        && matches!(retained.identity.engine, SdioRequestEngine::ExternalDma)
                        && io.dma_cs & BCM2835_DMA_CS_INT != 0
                    {
                        assert_eq!(
                            sdio_external_dma_irq_service_with(
                                retained,
                                retained.identity.generation,
                                io,
                                |snapshot| {
                                    SDIO_RUNTIME_STATE.with_mut(|state| {
                                        state.external_dma_request = snapshot;
                                    });
                                },
                                || true,
                            ),
                            SdioExternalDmaIrqServiceResult::Acked,
                            "test driver must service the lifetime-owned DMA IRQ",
                        );
                    }
                }
                RuntimeCommandTurn::Complete(completion) => return completion,
            }
        }
        panic!("retained SDIO descriptor exceeded its test turn bound");
    }

    struct TestReciprocalRecordRing;

    impl RuntimeRingRecordIo for TestReciprocalRecordRing {
        fn read_u16(&self, offset: usize) -> Option<u16> {
            let end = offset.checked_add(core::mem::size_of::<u16>())?;
            (end <= DRIVER_TASK_RING_PAGE_BYTES)
                .then(|| u16::from_le_bytes([read_ring_byte(offset), read_ring_byte(offset + 1)]))
        }

        fn read_u32(&self, offset: usize) -> Option<u32> {
            let end = offset.checked_add(core::mem::size_of::<u32>())?;
            (end <= DRIVER_TASK_RING_PAGE_BYTES).then(|| {
                u32::from_le_bytes([
                    read_ring_byte(offset),
                    read_ring_byte(offset + 1),
                    read_ring_byte(offset + 2),
                    read_ring_byte(offset + 3),
                ])
            })
        }

        fn write_u16(&mut self, offset: usize, value: u16) -> bool {
            let Some(end) = offset.checked_add(core::mem::size_of::<u16>()) else {
                return false;
            };
            if end > DRIVER_TASK_RING_PAGE_BYTES {
                return false;
            }
            write_ring_u16(offset, value);
            true
        }

        fn write_u32(&mut self, offset: usize, value: u32) -> bool {
            let Some(end) = offset.checked_add(core::mem::size_of::<u32>()) else {
                return false;
            };
            if end > DRIVER_TASK_RING_PAGE_BYTES {
                return false;
            }
            write_ring_u32(offset, value);
            true
        }
    }

    fn establish_completed_sdio_physical_lifetime_for_test(epoch: u32) {
        assert_ne!(epoch, 0);
        assert!(sdio_physical_lifetime_publish(
            DriverRuntimeSdioPhysicalLifetimeRecord {
                begun_epoch: epoch,
                completed_epoch: epoch,
                ..DriverRuntimeSdioPhysicalLifetimeRecord::empty()
            }
        ));
    }

    #[test]
    fn sdio_deadline_arm_plan_covers_every_timed_owner_wait() {
        let mut cursor = SdioExternalDmaRequestCursor::idle();
        cursor.deadline = RuntimeDeadline::Counter {
            start: 1_000,
            cycles: 500,
        };
        for phase in [
            SdioExternalDmaRequestPhase::WaitInhibit,
            SdioExternalDmaRequestPhase::ProgramVerifyStatusClear,
            SdioExternalDmaRequestPhase::PollIssued,
            SdioExternalDmaRequestPhase::ContainDmaPollAbort,
            SdioExternalDmaRequestPhase::ContainHostResetPoll1,
            SdioExternalDmaRequestPhase::ContainHostResetPoll2,
            SdioExternalDmaRequestPhase::ContainFinalInhibitPoll,
            SdioExternalDmaRequestPhase::HostConfigClock1Poll,
            SdioExternalDmaRequestPhase::HostConfigClock2Poll,
        ] {
            cursor.phase = phase;
            assert_eq!(
                sdio_deadline_arm_plan(cursor),
                SdioDeadlineArmPlan::Publish {
                    expiry_ticks: 1_500,
                },
                "phase {phase:?} must retain its exact counter wake",
            );
        }

        cursor.deadline = RuntimeDeadline::Counter {
            start: 1_000,
            cycles: 1_000,
        };
        cursor.settle_deadline = RuntimeDeadline::Counter {
            start: 1_100,
            cycles: 100,
        };
        for phase in [
            SdioExternalDmaRequestPhase::ContainClockSettle1,
            SdioExternalDmaRequestPhase::ContainClockSettle2,
        ] {
            cursor.phase = phase;
            assert_eq!(
                sdio_deadline_arm_plan(cursor),
                SdioDeadlineArmPlan::Publish {
                    expiry_ticks: 1_200,
                },
                "phase {phase:?} must wake on the earlier settle condition",
            );
        }
        cursor.settle_deadline = RuntimeDeadline::Counter {
            start: 1_900,
            cycles: 500,
        };
        assert_eq!(
            sdio_deadline_arm_plan(cursor),
            SdioDeadlineArmPlan::Publish {
                expiry_ticks: 2_000,
            },
            "the overall containment bound wins when it expires first",
        );

        cursor.phase = SdioExternalDmaRequestPhase::WaitInhibit;
        cursor.deadline = RuntimeDeadline::Iterations { remaining: 8 };
        assert_eq!(sdio_deadline_arm_plan(cursor), SdioDeadlineArmPlan::Fault);
        cursor.phase = SdioExternalDmaRequestPhase::PreflightDmaStage;
        assert_eq!(sdio_deadline_arm_plan(cursor), SdioDeadlineArmPlan::Clear);
    }

    #[test]
    fn sdio_deadline_arm_publishes_preissue_and_earliest_settle_expiry() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        establish_completed_sdio_physical_lifetime_for_test(8);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            let mut cursor = SdioExternalDmaRequestCursor::idle();
            cursor.phase = SdioExternalDmaRequestPhase::WaitInhibit;
            cursor.identity.sequence = 0x8000_6041;
            cursor.issued = false;
            cursor.deadline = RuntimeDeadline::Counter {
                start: 2_000,
                cycles: 250,
            };
            state.external_dma_request = cursor;
        });

        assert!(sdio_deadline_arm_publish_current());
        let preissue = sdio_deadline_arm_snapshot().expect("preissue deadline arm commits");
        assert_eq!(preissue.physical_lifetime_epoch, 8);
        assert_eq!(preissue.request_sequence, 0x8000_6041);
        assert_eq!(preissue.expiry_ticks(), 2_250);

        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.external_dma_request.phase =
                SdioExternalDmaRequestPhase::ProgramVerifyStatusClear;
            state.external_dma_request.deadline = RuntimeDeadline::Counter {
                start: 2_250,
                cycles: 500,
            };
        });
        assert!(sdio_deadline_arm_publish_current());
        assert_eq!(
            sdio_deadline_arm_snapshot()
                .expect("status-clear deadline arm commits")
                .expiry_ticks(),
            2_750,
        );

        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.external_dma_request.phase = SdioExternalDmaRequestPhase::ContainClockSettle1;
            state.external_dma_request.deadline = RuntimeDeadline::Counter {
                start: 2_500,
                cycles: 1_000,
            };
            state.external_dma_request.settle_deadline = RuntimeDeadline::Counter {
                start: 2_600,
                cycles: 100,
            };
        });
        assert!(sdio_deadline_arm_publish_current());
        assert_eq!(
            sdio_deadline_arm_snapshot()
                .expect("settle deadline arm commits")
                .expiry_ticks(),
            2_700,
        );
        assert!(sdio_deadline_arm_clear());
    }

    #[test]
    fn sdio_deadline_arm_is_exact_commit_last_and_cleared_before_terminal() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        establish_completed_sdio_physical_lifetime_for_test(7);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            let mut cursor = SdioExternalDmaRequestCursor::idle();
            cursor.phase = SdioExternalDmaRequestPhase::PollIssued;
            cursor.identity.sequence = 0x8000_6042;
            cursor.issued = true;
            cursor.deadline = RuntimeDeadline::Counter {
                start: 1_000,
                cycles: 250,
            };
            state.external_dma_request = cursor;
        });

        assert!(sdio_deadline_arm_publish_current());
        let first = sdio_deadline_arm_snapshot().expect("deadline arm commits");
        assert_eq!(first.physical_lifetime_epoch, 7);
        assert_eq!(first.request_sequence, 0x8000_6042);
        assert_eq!(first.expiry_ticks(), 1_250);

        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.external_dma_request.deadline = RuntimeDeadline::Counter {
                start: 1_250,
                cycles: 500,
            };
        });
        assert!(sdio_deadline_arm_publish_current());
        let updated = sdio_deadline_arm_snapshot().expect("updated arm commits");
        assert_eq!(updated.request_sequence, first.request_sequence);
        assert_eq!(updated.expiry_ticks(), 1_750);
        assert_ne!(updated, first);

        assert!(sdio_deadline_arm_clear());
        assert_eq!(sdio_deadline_arm_snapshot(), None);
    }

    #[test]
    fn cyw43_deadline_hint_requires_exact_expired_current_child() {
        let arm = DriverRuntimeSdioDeadlineArm::staged(7, 0x8000_6043, 10_000)
            .commit()
            .expect("deadline arm commits");
        let lifetime = DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 7,
            completed_epoch: 7,
            failed_epoch: 6,
            ..DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        assert!(cyw43_sdio_deadline_hint_admitted(
            arm,
            lifetime,
            true,
            arm.request_sequence,
            false,
            false,
            arm.expiry_ticks(),
        ));
        assert!(!cyw43_sdio_deadline_hint_admitted(
            arm,
            lifetime,
            true,
            arm.request_sequence,
            false,
            false,
            arm.expiry_ticks().wrapping_sub(1),
        ));
        assert!(!cyw43_sdio_deadline_hint_admitted(
            arm,
            lifetime,
            true,
            arm.request_sequence.wrapping_add(1),
            false,
            false,
            arm.expiry_ticks(),
        ));
        assert!(!cyw43_sdio_deadline_hint_admitted(
            arm,
            lifetime,
            true,
            arm.request_sequence,
            true,
            false,
            arm.expiry_ticks(),
        ));
    }

    fn sdio_clock_snapshot_for_test() -> Option<DriverRuntimeSdioClockSnapshot> {
        let ring = RuntimeRingWindow::local();
        let base = usize::from(DRIVER_RUNTIME_SDIO_CLOCK_SNAPSHOT_OFFSET);
        let read = || {
            Some(DriverRuntimeSdioClockSnapshot {
                magic: ring.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, magic),
                )?,
                version: ring.read_u16(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, version),
                )?,
                len: ring
                    .read_u16(base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, len))?,
                sequence: ring.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, sequence),
                )?,
                physical_lifetime_epoch: ring.read_u32(
                    base + core::mem::offset_of!(
                        DriverRuntimeSdioClockSnapshot,
                        physical_lifetime_epoch
                    ),
                )?,
                requested_clock_hz: ring.read_u32(
                    base + core::mem::offset_of!(
                        DriverRuntimeSdioClockSnapshot,
                        requested_clock_hz
                    ),
                )?,
                base_clock_hz: ring.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, base_clock_hz),
                )?,
                effective_clock_hz: ring.read_u32(
                    base + core::mem::offset_of!(
                        DriverRuntimeSdioClockSnapshot,
                        effective_clock_hz
                    ),
                )?,
                timer_clock_hz: ring.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, timer_clock_hz),
                )?,
                divider: ring.read_u16(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, divider),
                )?,
                clock_control: ring.read_u16(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, clock_control),
                )?,
                host_control: ring.read_u8(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, host_control),
                )?,
                cccr_speed: ring.read_u8(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, cccr_speed),
                )?,
                cccr_interface: ring.read_u8(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, cccr_interface),
                )?,
                flags: ring
                    .read_u8(base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, flags))?,
                reserved: ring.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeSdioClockSnapshot, reserved),
                )?,
            })
        };
        DriverRuntimeSdioClockSnapshot::stable_snapshot(read()?, read()?)
    }

