    #[test]
    fn cyw43_production_lane_rejects_legacy_descriptor_and_payload_offsets() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_cyw43_engine_for_test();

        let descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
            payload_offset: (DRIVER_TASK_RING_FRAME_OFFSET
                + core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>())
                as u16,
            payload_len: 16,
            total_len: 16,
            arg0: 0x17,
            arg1: 38,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        assert_ne!(
            cyw43_descriptor_invalid_result(descriptor) & CYW43_DESCRIPTOR_INVALID_PAYLOAD,
            0,
            "the former ring-local parent payload must not remain a fallback lane",
        );

        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            payload_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
            ..descriptor
        });
        let legacy_command = DriverTaskCommandRecord {
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>() as u16,
                flags: 0,
            },
            ..cyw43_descriptor_command(173)
        };
        assert_eq!(
            service_command_turn(0, legacy_command),
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                173,
                FAULT_CYW43_DESCRIPTOR_INVALID,
                CYW43_DESCRIPTOR_INVALID_PAYLOAD,
            )),
        );
        assert_eq!(
            read_cyw43_command_descriptor_physical(legacy_command.frame),
            None,
        );
    }

    fn init_cyw43_engine_for_test() {
        init_runtime_for_test(HOT_PATH_CYW43_WIFI, ROLE_NET);
        // The deterministic host card model starts with Function 1 ready.
        // Delayed/failed readiness tests override these values explicitly.
        test_sdio_cmd52_read_ioex_response(0);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1);
        test_sdio_cmd52_read_cccr_response(SDIO_CCCR_REV_3_00);
        test_sdio_cmd52_read_caps_response(SDIO_CCCR_CAP_SMB);
        test_sdio_cmd52_read_speed_response(SDIO_CCCR_SPEED_SHS | SDIO_CCCR_SPEED_EHS);
        test_sdio_cmd52_read_if_response(SDIO_BUS_WIDTH_4BIT);
        let init = DriverTaskCommandRecord {
            sequence: 70,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_CYW43_WIFI,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_NET_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, init),
            DriverTaskCompletionRecord::progress(70, 1)
        );
        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            arg0: 0,
            arg1: 0,
            reserved: 0,
        });
        let alp_request = SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_ALP_AVAIL_REQ;
        test_sdio_cmd52_read_chipclkcsr_response(alp_request | SBSDIO_ALP_AVAIL);
        let mut transport_ready = false;
        let sequence = 170;
        let turns = CYW43_BACKPLANE_FORCE_ALP_SETTLE_FALLBACK_SPINS
            .saturating_add(CYW43_TRANSPORT_PHASE_LIMIT)
            .saturating_add(64);
        for attempt in 0..turns {
            // Every retained turn belongs to one immutable root command. A
            // new sequence would be a different owner and must be rejected by
            // the lane/F1/backplane cursors rather than treated as progress.
            let completion = service_command(0, cyw43_descriptor_command(sequence));
            assert_eq!(completion.sequence, sequence);
            let lane = CYW43_RUNTIME_STATE.with_ref(|state| state.card_lane);
            let transfer_count = test_sdio_transfer_total_count();
            let last_transfer = transfer_count
                .checked_sub(1)
                .and_then(test_sdio_transfer_record_at);
            assert_eq!(
                completion.code, COMPLETION_PROGRESS,
                "retained transport turn {attempt} returned {completion:?} with lane {lane:?}, transfer_count={transfer_count}, last_transfer={last_transfer:?}, last_failure=0x{:08x}",
                sdio_last_transfer_failure(),
            );
            if completion.detail == DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY {
                assert_eq!(completion.result, 1);
                transport_ready = true;
                break;
            }
            assert_eq!(completion.result, 0);
        }
        assert!(transport_ready);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            assert!(state.transport_ready);
            assert!(!state.firmware_upload_prepared);
            // Most low-level fixtures below exercise the retained legacy
            // physical helpers directly. Linked-DPC tests opt in explicitly
            // so the generated Pi lane and compatibility lane cannot be
            // confused by an implicit test default.
            state.dpc_link_ready = false;
        });
    }

