    #[test]
    fn cyw43_quarantined_engine_init_requests_pair_restart_without_owner_io() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_runtime_for_test(HOT_PATH_CYW43_WIFI, ROLE_NET);
        let descriptor = RUNTIME_DESCRIPTOR.load();
        let link = descriptor_notification_dpc_link(&descriptor).expect("CYW43 DPC link");
        assert!(
            !cyw43_foreground_new_frontier_generation_valid(link.shared_epoch, None),
            "an unpublished owner ring must fail the later delegated frontier",
        );
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.recovery_required = true;
            state.firmware_execution_started = true;
            state.sdio_transport_enumerated = true;
            state.dpc_shared_epoch = link.shared_epoch;
            state.backplane_window = CYW43_ARMCR4_CORE_BASE & BACKPLANE_WINDOW_MASK;
            state.backplane_window_valid = true;
        });
        reset_test_sdio_transfer_log();
        let init = DriverTaskCommandRecord {
            sequence: 94,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_CYW43_WIFI,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };

        let completion = service_command(0, init);

        assert_eq!(
            completion,
            DriverTaskCompletionRecord::fault_with_result(94, FAULT_CYW43_TRANSPORT_BUS_LINK, 0,)
        );
        assert_eq!(test_sdio_transfer_count(|_| true), 0);
        assert!(CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert!(state.recovery_required);
            assert_eq!(state.dpc_shared_epoch, link.shared_epoch);
            assert!(state.firmware_execution_started);
        });
    }

    #[test]
    fn wire_records_match_root_task_layout_sizes() {
        let _guard = test_guard();
        reset_runtime_for_test();
        assert_eq!(core::mem::size_of::<DriverFrameDescriptor>(), 8);
        assert_eq!(core::mem::align_of::<DriverFrameDescriptor>(), 4);
        assert_eq!(core::mem::size_of::<DriverTaskBudgetGrant>(), 8);
        assert_eq!(core::mem::align_of::<DriverTaskBudgetGrant>(), 4);
        assert_eq!(core::mem::size_of::<DriverTaskCommandRecord>(), 40);
        assert_eq!(core::mem::align_of::<DriverTaskCommandRecord>(), 4);
        assert_eq!(core::mem::size_of::<DriverRuntimeContinuationGrant>(), 24);
        assert_eq!(core::mem::align_of::<DriverRuntimeContinuationGrant>(), 4);
        assert_eq!(usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET), 40);
        assert_eq!(usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES), 24);
        assert_eq!(
            usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET)
                + core::mem::size_of::<DriverRuntimeContinuationGrant>(),
            DRIVER_TASK_RING_COMPLETION_OFFSET,
        );
        assert_eq!(core::mem::size_of::<DriverTaskCompletionRecord>(), 20);
        assert_eq!(core::mem::align_of::<DriverTaskCompletionRecord>(), 4);
    }

    #[test]
    fn runtime_staged_completion_preserves_fixed_body_and_hides_commit_sequence() {
        assert_eq!(core::mem::size_of::<DriverTaskCompletionRecord>(), 20);
        assert_eq!(
            core::mem::offset_of!(DriverTaskCompletionRecord, sequence),
            0
        );
        assert_eq!(core::mem::offset_of!(DriverTaskCompletionRecord, code), 4);
        assert_eq!(core::mem::offset_of!(DriverTaskCompletionRecord, detail), 6);
        assert_eq!(core::mem::offset_of!(DriverTaskCompletionRecord, result), 8);
        assert_eq!(core::mem::offset_of!(DriverTaskCompletionRecord, frame), 12);

        let completion = DriverTaskCompletionRecord::fault_with_result_and_frame(
            0x8000_0042,
            FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
            0x1122_3344,
            DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 64,
                flags: 7,
            },
        );
        let staged = runtime_staged_completion(completion);
        assert_eq!(staged.sequence, 0);
        assert_eq!(staged.code, completion.code);
        assert_eq!(staged.detail, completion.detail);
        assert_eq!(staged.result, completion.result);
        assert_eq!(staged.frame, completion.frame);
    }

