    #[test]
    fn notification_service_accepts_only_the_generated_route_badges() {
        assert_eq!(
            DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE & DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            0,
            "the client owner-wake badge must remain disjoint from CARD_INT",
        );
        assert_eq!(
            runtime_notification_service_badge(
                RuntimeNotificationRoute::SdioOwner,
                DRIVER_RUNTIME_RESERVED_ROOT_BADGE
                    | DRIVER_RUNTIME_SDIO_IRQ_BADGE
                    | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            ),
            Some(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        assert_eq!(
            runtime_notification_wake_badge(
                RuntimeNotificationRoute::SdioOwner,
                DRIVER_RUNTIME_SDIO_IRQ_BADGE | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            ),
            DRIVER_RUNTIME_SDIO_IRQ_BADGE | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            "the coalesced wake preserves both typed sources for arbitration",
        );
        for invalid in [
            0,
            1,
            DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
            DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE | 1,
            DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE
                | DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
        ] {
            assert_eq!(
                runtime_notification_wake_badge(RuntimeNotificationRoute::SdioOwner, invalid),
                0,
                "numeric IRQ badge subsets and unknown coalesced bits fail closed",
            );
            let mut gate = RuntimePendingCommandGate::new();
            assert!(
                !retain_runtime_idle_delegated_wake(
                    RuntimeNotificationRoute::SdioOwner,
                    invalid,
                    &mut gate,
                ),
                "a malformed idle badge cannot become a saved owner edge",
            );
            assert!(!gate.has_deferred_delegated_wake());
        }
        assert_eq!(
            runtime_notification_service_badge(
                RuntimeNotificationRoute::SdioOwner,
                DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            ),
            None,
            "the owner wake is scheduling only and never device service",
        );
        assert_eq!(
            runtime_notification_service_badge(
                RuntimeNotificationRoute::Cyw43Client,
                DRIVER_RUNTIME_RESERVED_ROOT_BADGE
                    | DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
            ),
            Some(DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE),
        );
        for badge in [
            0,
            DRIVER_RUNTIME_RESERVED_ROOT_BADGE,
            DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
        ] {
            assert_eq!(
                runtime_notification_service_badge(RuntimeNotificationRoute::SdioOwner, badge),
                None,
            );
        }
        assert_eq!(
            runtime_notification_service_badge(
                RuntimeNotificationRoute::Unavailable,
                DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
            ),
            None,
        );
    }

    #[test]
    fn sdio_owner_typed_notification_requires_grant_and_survives_irq_coalescing() {
        let intake = retained_gate_test_intake(0x8000_0042);
        let generation = intake.command.aux1;
        let grant = retained_gate_test_grant(intake, generation, 1);
        let mut retained = intake;
        let mut gate = RuntimePendingCommandGate::new();
        gate.retain_after_pending_generation(generation);

        let endpoint_wake = runtime_pending_wake_for_route(
            RuntimeNotificationRoute::SdioOwner,
            RuntimeWake::Command(intake),
        );
        assert_eq!(endpoint_wake, RuntimeWake::Command(intake));
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, endpoint_wake, None),
            RuntimePendingWakeRoute::Rejected,
            "an endpoint wake without immutable authority cannot advance the owner",
        );
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, endpoint_wake, Some(grant)),
            RuntimePendingWakeRoute::Rejected,
            "delegated production has no endpoint continuation lane",
        );
        let owner_wake = RuntimeWake::Notification(DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE);
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(grant)),
            RuntimePendingWakeRoute::ContinueForeground,
            "the typed notification plus exact grant advances one retained owner quantum",
        );
        assert_eq!(gate.last_grant_id, 1);
        assert!(!gate.continuation_required());

        gate.retain_after_pending_generation(generation);
        let combined_wake = runtime_pending_wake_for_route(
            RuntimeNotificationRoute::SdioOwner,
            RuntimeWake::Notification(
                DRIVER_RUNTIME_SDIO_IRQ_BADGE | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            ),
        );
        let second = retained_gate_test_grant(intake, generation, 2);
        assert_eq!(
            combined_wake,
            RuntimeWake::Notification(
                DRIVER_RUNTIME_SDIO_IRQ_BADGE | DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE,
            ),
        );
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, combined_wake, Some(second)),
            RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        assert_eq!(
            gate.last_grant_id, 1,
            "device service must leave the exact foreground grant pending",
        );
        assert!(
            gate.take_deferred_delegated_wake(),
            "the combined notification retains the typed owner wake",
        );
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(second)),
            RuntimePendingWakeRoute::ContinueForeground,
            "the post-service scheduler slice spends only the exact grant",
        );
        assert_eq!(
            gate.last_grant_id, 2,
            "the notification is only a wake; the exact grant spends authority",
        );
        gate.retain_after_pending_generation(generation);
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(second)),
            RuntimePendingWakeRoute::Rejected,
            "the typed notification cannot replay a consumed grant",
        );
    }

    #[test]
    fn sdio_owner_preserves_typed_wake_across_older_irq_and_ack_rollback() {
        let intake = retained_gate_test_intake(0x8000_0042);
        let generation = intake.command.aux1;
        let grant = retained_gate_test_grant(intake, generation, 1);
        let owner_wake = RuntimeWake::Notification(DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE);
        let mut retained = intake;
        let mut gate = RuntimePendingCommandGate::new();
        gate.retain_after_pending_generation(generation);
        gate.deferred_service_badge = DRIVER_RUNTIME_SDIO_IRQ_BADGE;

        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(grant)),
            RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
            "an older deferred IRQ receives its one service quantum first",
        );
        assert!(
            gate.take_deferred_delegated_wake(),
            "the newly arrived typed owner wake survives older deferred service",
        );
        let before_ack = gate;
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(grant)),
            RuntimePendingWakeRoute::ContinueForeground,
        );
        assert_eq!(gate.last_grant_id, 1);

        // Model runtime_main's fail-closed rollback when the shared
        // acknowledgement cannot be committed after arbitration accepted the
        // exact grant. The already-consumed notification edge must remain
        // durable for a later stable acknowledgement attempt.
        gate = before_ack;
        gate.restore_deferred_delegated_wake();
        assert!(gate.take_deferred_delegated_wake());
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, owner_wake, Some(grant)),
            RuntimePendingWakeRoute::ContinueForeground,
        );
        assert_eq!(
            gate.last_grant_id, 1,
            "acknowledgement rollback releases no extra owner quantum",
        );
    }

    #[test]
    fn ready_grant_without_saved_edge_preserves_observed_older_irq_order() {
        let intake = retained_gate_test_intake(0x8000_0042);
        let generation = intake.command.aux1;
        let grant = retained_gate_test_grant(intake, generation, 1);
        let mut retained = intake;
        let mut gate = RuntimePendingCommandGate::new();
        gate.retain_after_pending_generation(generation);
        gate.deferred_service_badge = DRIVER_RUNTIME_SDIO_IRQ_BADGE;
        assert!(!gate.has_deferred_delegated_wake());

        // Fused admission discovers the already-observed CARD_INT before it
        // consumes the exact grant or performs foreground I/O.
        assert_eq!(
            runtime_retained_owner_fused_admission(
                &mut gate,
                &mut retained,
                RuntimeWake::None,
                RuntimeRetainedGrantProbe::Ready(grant),
            ),
            RuntimeRetainedOwnerAdmission::Service(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        assert_eq!(gate.last_grant_id, 0, "IRQ cannot spend owner authority");
        assert!(gate.continuation_required());
        assert!(gate.foreground_due_after_service);

        // After exactly one service turn, the same still-unconsumed grant is
        // re-read and admitted by the next fused turn.
        assert_eq!(
            runtime_retained_owner_fused_admission(
                &mut gate,
                &mut retained,
                RuntimeWake::None,
                RuntimeRetainedGrantProbe::Ready(grant),
            ),
            RuntimeRetainedOwnerAdmission::Execute(grant),
        );
        assert_eq!(gate.last_grant_id, 1);
        assert!(!gate.continuation_required());
    }

    #[test]
    fn idle_peer_service_cannot_replay_a_committed_root_command() {
        let intake = endpoint_retained_gate_test_intake(0x8000_0042);
        assert_eq!(
            runtime_idle_service_badge(
                RuntimeNotificationRoute::Cyw43Client,
                DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
            ),
            Some(DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE),
        );
        assert_eq!(
            runtime_command_admission(intake.command, intake.command.sequence),
            RuntimeCommandAdmission::None,
            "peer service does not grant authority to replay the last committed command",
        );

        let fresh = RuntimeCommandIntake {
            command: DriverTaskCommandRecord {
                sequence: intake.command.sequence.wrapping_add(1),
                ..intake.command
            },
            ..intake
        };
        assert_eq!(
            runtime_command_admission(fresh.command, intake.command.sequence),
            RuntimeCommandAdmission::OneWay,
            "only a fresh sequence-last ring commit creates the next issue boundary",
        );
    }

    #[test]
    fn pending_root_command_dpc_arbitration_requires_a_later_exact_grant() {
        let generation = 7;
        let intake = root_retained_gate_test_intake(0x42, generation);
        let mut retained = intake;
        let mut gate = RuntimePendingCommandGate::new();
        // Model the one already-watermarked DPC quantum consumed by the
        // production preflight branch before any fresh foreground action.
        retain_runtime_command_after_arbitration_turn(
            &mut gate,
            intake,
            RuntimeNotificationRoute::Cyw43Client,
        );
        assert_eq!(gate.root_generation, Some(generation));
        assert_eq!(
            gate.route_wake_with_grant(&mut retained, RuntimeWake::Command(intake), None,),
            RuntimePendingWakeRoute::Rejected,
            "the DPC preflight cannot re-enable an endpoint fallback",
        );
        let exact = retained_gate_test_grant(intake, generation, 1);
        let next_phase = runtime_retained_owner_phase_after_wake(
            &mut gate,
            Some(&mut retained),
            RuntimeWake::Notification(DRIVER_RUNTIME_RESERVED_ROOT_BADGE),
        );
        assert_eq!(next_phase, RuntimeRetainedOwnerPhase::CheckGrant);
        gate.set_delegated_owner_phase(next_phase);
        gate.set_delegated_owner_phase(runtime_retained_owner_phase_after_grant(
            RuntimeRetainedGrantProbe::Ready(exact),
        ));
        assert_eq!(
            runtime_retained_owner_prepare_execute(&mut gate, &mut retained, exact),
            RuntimePendingWakeRoute::ContinueForeground,
            "one exact later root grant resumes the retained foreground command",
        );
        assert_eq!(gate.last_grant_id, 1);
    }

    #[test]
    fn issued_unknown_wait_and_reap_preserve_exact_root_grant_lane() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let generation = 9;
        let intake = root_retained_gate_test_intake(0x43, generation);
        let mut retained = intake;
        let child_sequence = 0x8000_4301;
        assert!(cyw43_sdio_child_claim(child_sequence));
        assert!(cyw43_sdio_child_mark_issued_unknown(child_sequence));
        let empty = DriverTaskCompletionRecord::fault(0, FAULT_REJECTED_COMMAND);
        let exact = DriverTaskCompletionRecord::progress(child_sequence, 1);
        let mut gate = RuntimePendingCommandGate::new();
        retain_runtime_command_after_arbitration_turn(
            &mut gate,
            intake,
            RuntimeNotificationRoute::Cyw43Client,
        );

        let admit_root_quantum = |gate: &mut RuntimePendingCommandGate,
                                  retained: &mut RuntimeCommandIntake,
                                  grant_id: u32| {
            let grant = retained_gate_test_grant(intake, generation, grant_id);
            let gate_before_grant = *gate;
            assert_eq!(
                runtime_retained_owner_fused_admission(
                    gate,
                    retained,
                    RuntimeWake::Notification(DRIVER_RUNTIME_RESERVED_ROOT_BADGE),
                    RuntimeRetainedGrantProbe::Ready(grant),
                ),
                RuntimeRetainedOwnerAdmission::Execute(grant),
            );
            assert!(runtime_retained_owner_commit_grant_with(
                gate,
                gate_before_grant,
                grant,
                |id| id == grant_id,
            ));
        };

        for grant_id in 1..=2 {
            admit_root_quantum(&mut gate, &mut retained, grant_id);
            assert_eq!(
                cyw43_sdio_child_reap_stable_completion(child_sequence, empty, empty),
                Cyw43IssuedUnknownReapResult::Waiting,
            );
            retain_runtime_command_after_arbitration_turn(
                &mut gate,
                intake,
                RuntimeNotificationRoute::Cyw43Client,
            );
            assert_eq!(gate.root_generation, Some(generation));
            assert_eq!(gate.last_grant_id, grant_id);
            let mut endpoint_gate = gate;
            let mut endpoint_retained = retained;
            assert_eq!(
                endpoint_gate.route_wake_with_grant(
                    &mut endpoint_retained,
                    RuntimeWake::Command(intake),
                    None,
                ),
                RuntimePendingWakeRoute::Rejected,
                "issued-unknown waiting cannot select an endpoint fallback",
            );
        }

        admit_root_quantum(&mut gate, &mut retained, 3);
        assert_eq!(
            cyw43_sdio_child_reap_stable_completion(child_sequence, exact, exact),
            Cyw43IssuedUnknownReapResult::Reaped {
                sequence: child_sequence,
            },
        );
        retain_runtime_command_after_arbitration_turn(
            &mut gate,
            intake,
            RuntimeNotificationRoute::Cyw43Client,
        );
        admit_root_quantum(&mut gate, &mut retained, 4);
        assert_eq!(
            gate.last_grant_id, 4,
            "the reaped parent can consume a fresh exact grant for its terminal turn",
        );
        assert!(!CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire));
        assert!(!CYW43_SDIO_CHILD_ISSUED_UNKNOWN.load(Ordering::Acquire));
    }

    #[test]
    fn reciprocal_sdio_child_submit_and_polls_require_separate_root_rendezvous() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let generation = 0x4359_5301;
        let desc = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_OCR,
            addr: 0,
            len: SDIO_CMD5,
            timeout_us: 100_000,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let mut command = stage_sdio_descriptor_service_command(0x8000_5d01, desc);
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        command.aux1 = generation;
        let mut io = TestSdioHostIo::new();
        io.command_status = SDHCI_INT_RESPONSE;
        io.command_response = 0x80ff_8000;
        let parent = retained_gate_test_intake(0x8000_0042).command;
        let mut transaction = Cyw43ForegroundTransaction::new();
        transaction.generation = generation;
        assert!(transaction.begin_turn(parent, 1));
        transaction.prepared_sequence = command.sequence;
        transaction.prepared_descriptor = desc;
        transaction.prepared_descriptor_valid = true;
        transaction.prepared_write_len = 0;
        assert!(cyw43_foreground_reserve_frontier(&mut transaction, command));
        let entry = transaction.frontier;
        assert!(transaction.frontier_ticket_valid());
        let mut ring = TestReciprocalRecordRing;

        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, false, false, false, true, false, false,),
            Cyw43ForegroundFrontierRoute::Submit
        );
        assert!(runtime_ring_write_completion_staged(
            &mut ring,
            DriverTaskCompletionRecord::fault(0, FAULT_REJECTED_COMMAND),
        ));
        assert!(runtime_ring_write_command_staged(
            &mut ring,
            cyw43_sdio_bus_link_staged_command(command),
        ));
        transaction.retain_frontier_submit(1, 100);
        assert!(runtime_ring_commit_command_sequence(
            &mut ring,
            command.sequence,
        ));
        assert!(transaction.turn.action_consumed);
        assert!(transaction.turn.pending);
        assert!(!transaction.turn.committed_child_replay_due());
        assert!(transaction.frontier_submitted);
        assert_eq!(io.command_issue_count(), 0);
        let owner_command = runtime_ring_read_command_stable(&ring)
            .expect("sequence-last reciprocal command must be owner-visible");
        assert_eq!(
            runtime_command_admission(owner_command, 0),
            RuntimeCommandAdmission::OneWay,
        );
        assert_eq!(owner_command.sequence, command.sequence);
        assert_eq!(owner_command.frame, command.frame);
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, true, true, false, false),
            Cyw43ForegroundFrontierRoute::Defer,
            "the submit turn cannot also poll its child",
        );

        assert!(transaction.begin_turn(parent, 2));
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Poll,
            "a fresh parent exact-grant turn admits the one completion poll",
        );
        transaction.retain_frontier_completion_poll();
        let (first, second) = runtime_ring_read_completion_stable(&ring)
            .expect("staged reset completion must remain readable");
        assert_eq!(
            Cyw43SdioChildState::new(command.sequence).completion(first, second),
            Cyw43SdioChildCompletion::Waiting,
        );
        transaction.retain_frontier_wait(1, true);
        assert!(transaction.turn.action_consumed);
        assert!(transaction.turn.pending);
        assert!(!transaction.turn.committed_child_replay_due());
        assert!(transaction.frontier_continuation_grant_required);
        assert!(transaction.frontier_continuation_grant_publish);
        assert_eq!(transaction.frontier_grant_id, 1);
        assert_eq!(io.command_issue_count(), 0);

        assert!(transaction.begin_turn(parent, 3));
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, true, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Grant,
            "the completion miss schedules a distinct grant-only parent turn",
        );
        transaction.retain_frontier_grant(1);
        assert!(transaction.turn.action_consumed);
        assert!(transaction.turn.pending);
        assert!(!transaction.frontier_continuation_grant_required);
        assert!(!transaction.frontier_continuation_grant_publish);
        // The reciprocal owner executes the descriptor/controller seam only
        // after the retained grant turn; it is not folded into CYW43's submit
        // or completion-poll quantum.
        let owner_completion = service_sdio_descriptor_command_with_io(owner_command, &mut io);
        assert_eq!(io.command_issue_count(), 1);
        assert_eq!(
            owner_completion,
            DriverTaskCompletionRecord::progress(command.sequence, 0x80ff_8000)
        );
        assert!(cyw43_foreground_completion_matches(entry, owner_completion));
        assert!(runtime_ring_write_completion_staged(
            &mut ring,
            runtime_staged_completion(owner_completion),
        ));
        assert!(runtime_ring_commit_completion_sequence(
            &mut ring,
            owner_completion.sequence,
        ));

        assert!(transaction.begin_turn(parent, 4));
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Poll,
            "a fresh parent exact-grant turn admits the one completion poll",
        );
        transaction.retain_frontier_completion_poll();
        let (first, second) = runtime_ring_read_completion_stable(&ring)
            .expect("owner-published reciprocal completion must be readable");
        let completion = match Cyw43SdioChildState::new(command.sequence).completion(first, second)
        {
            Cyw43SdioChildCompletion::Exact(completion) => completion,
            Cyw43SdioChildCompletion::Waiting => {
                panic!("stable exact owner completion must be admitted")
            }
        };
        assert!(transaction.commit_frontier_completion(completion));
        assert_eq!(transaction.turn.completed_count, 1);
        assert!(transaction.turn.committed_child_replay_due());
        assert!(!transaction.frontier_valid);
        assert_eq!(
            cyw43_foreground_frontier_route(1, 1, true, false, false, true, true, false, false),
            Cyw43ForegroundFrontierRoute::Defer,
            "a terminal poll cannot submit the next reciprocal action in the same turn",
        );
        assert_eq!(io.command_issue_count(), 1);

        assert!(transaction.begin_turn(parent, 5));
        assert!(transaction.turn.committed_child_replay_due());
        transaction.prepared_sequence = command.sequence;
        transaction.prepared_descriptor = desc;
        transaction.prepared_descriptor_valid = true;
        transaction.prepared_write_len = 0;
        assert!(cyw43_foreground_prepared_matches(
            &transaction,
            transaction.entries[0],
            command,
        ));
        assert_eq!(transaction.turn.replay_cached_child(), Some(0));
        assert!(!transaction.turn.committed_child_replay_due());
        assert_eq!(transaction.turn.replay_cached_child(), None);
        assert_eq!(io.command_issue_count(), 1);
    }

    #[test]
    fn transport_f1_block_size_children_each_require_a_fresh_outer_turn() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let data_offset = CYW43_SDIO_BUS_LINK_DATA_OFFSET;
        let base = SDIO_CCCR_FBR_BASE;
        let low = (SDIO_FUNCTION1_BLOCK_SIZE & 0xff) as u8;
        let high = (SDIO_FUNCTION1_BLOCK_SIZE >> 8) as u8;
        let actions = [
            (true, base + SDIO_FBR_BLKSIZE, low),
            (true, base + SDIO_FBR_BLKSIZE + 1, high),
            (false, base + SDIO_FBR_BLKSIZE, low),
            (false, base + SDIO_FBR_BLKSIZE + 1, high),
        ];
        let mut io = TestSdioHostIo::new();
        io.use_runtime_payload = true;
        io.command_status = SDHCI_INT_RESPONSE;
        let mut parent_turn = Cyw43ForegroundTurnState::new();

        for (ordinal, (write, addr, value)) in actions.into_iter().enumerate() {
            if write {
                write_runtime_payload_byte(data_offset, value);
            } else {
                io.command_response = u32::from(value);
            }
            let descriptor = sdio_bus_link_cmd52_descriptor(write, 0, addr, 0)
                .expect("F1 block-size CMD52 descriptor must encode");
            let sequence = 0x8000_6100u32.wrapping_add(ordinal as u32);
            let command = stage_sdio_descriptor_service_command(sequence, descriptor);
            let issue_count_before = io.command_issue_count();
            let completion = service_sdio_descriptor_command_with_io(command, &mut io);
            assert_eq!(io.command_issue_count(), issue_count_before + 1);
            assert_eq!(completion.sequence, sequence);
            assert_eq!(
                completion.code,
                if write {
                    COMPLETION_PROGRESS
                } else {
                    COMPLETION_FRAME_READY
                },
            );

            let entry = Cyw43ForegroundTraceEntry {
                ticket: Cyw43ForegroundActionTicket {
                    parent_sequence: 10,
                    generation: 0x4359_5301,
                    owner_sequence: sequence,
                    ordinal: ordinal as u16,
                    issued_turn_id: (ordinal + 1) as u64,
                },
                command,
                descriptor,
                completion: DriverTaskCompletionRecord::idle(0),
                write_offset: 0,
                write_len: if write { 1 } else { 0 },
                read_offset: 0,
                read_len: 0,
                read_from_owner: false,
                local_read_frame: DriverFrameDescriptor::empty(),
            };
            assert!(cyw43_foreground_completion_matches(entry, completion));

            parent_turn.complete_child_poll();
            assert_eq!(parent_turn.completed_count, (ordinal + 1) as u16);
            assert_eq!(parent_turn.replay_index, parent_turn.completed_count);
            assert!(parent_turn.action_consumed);
            assert!(parent_turn.pending);
            assert_eq!(
                cyw43_foreground_frontier_route(
                    parent_turn.replay_index,
                    parent_turn.completed_count,
                    false,
                    false,
                    false,
                    parent_turn.action_consumed,
                    true,
                    false,
                    false,
                ),
                Cyw43ForegroundFrontierRoute::Defer,
                "the exact child poll cannot issue the next F1 CMD52 in the same turn",
            );
            assert_eq!(
                io.command_issue_count(),
                issue_count_before + 1,
                "the terminal poll turn performs exactly one owner operation",
            );

            parent_turn.begin_turn();
            for replay_index in 0..parent_turn.completed_count {
                assert_eq!(
                    cyw43_foreground_frontier_route(
                        parent_turn.replay_index,
                        parent_turn.completed_count,
                        false,
                        false,
                        false,
                        false,
                        true,
                        false,
                        false,
                    ),
                    Cyw43ForegroundFrontierRoute::Cached,
                    "the fresh parent turn replays each completed prefix locally",
                );
                assert_eq!(parent_turn.replay_cached_child(), Some(replay_index));
            }
            if ordinal + 1 < actions.len() {
                assert_eq!(
                    cyw43_foreground_frontier_route(
                        parent_turn.replay_index,
                        parent_turn.completed_count,
                        false,
                        false,
                        false,
                        false,
                        true,
                        false,
                        false,
                    ),
                    Cyw43ForegroundFrontierRoute::Submit,
                    "only a fresh parent turn may submit the next F1 CMD52",
                );
            }
        }
        assert_eq!(io.command_issue_count(), 4);
        assert_eq!(parent_turn.completed_count, 4);
        assert_eq!(parent_turn.replay_index, 4);
        assert!(!parent_turn.pending);
        assert!(!parent_turn.action_consumed);

        let mut single_child = Cyw43ForegroundTurnState::new();
        single_child.complete_child_poll();
        assert!(single_child.pending);
        single_child.begin_turn();
        assert_eq!(single_child.replay_cached_child(), Some(0));
        assert_eq!(single_child.replay_cached_child(), None);
        assert!(!single_child.pending);
        assert!(!single_child.action_consumed);
    }

    #[test]
