    #[test]
    fn foreground_snapshot_bounds_only_nonempty_parent_payloads() {
        let shared = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME,
            payload_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
            payload_len: 4,
            total_len: 4,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        assert!(shared.valid());
        assert_eq!(
            cyw43_foreground_parent_payload_snapshot(
                shared,
                DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize,
            ),
            Cyw43ForegroundParentPayloadSnapshot::Copy(DriverFrameDescriptor {
                offset: u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE),
                len: 4,
                flags: 0,
            }),
        );

        assert_eq!(
            cyw43_foreground_parent_payload_snapshot(
                DriverRuntimeCyw43CommandDescriptor {
                    payload_offset: 0,
                    ..shared
                },
                DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize,
            ),
            Cyw43ForegroundParentPayloadSnapshot::Reject,
            "a nonempty payload may not alias command/completion metadata",
        );
    }

    #[test]
    fn reciprocal_multiphase_child_alternates_poll_grant_and_poll_outer_turns() {
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, false, false, false, true, false, false,),
            Cyw43ForegroundFrontierRoute::Submit,
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, true, true, false, false),
            Cyw43ForegroundFrontierRoute::Defer,
            "submission consumes its parent outer turn",
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Poll,
            "the next parent turn performs only one completion poll",
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, true, true, true, false, false),
            Cyw43ForegroundFrontierRoute::Defer,
            "a missed poll cannot publish a continuation in the same turn",
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, true, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Grant,
            "a later parent turn publishes and signals one exact continuation",
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, true, true, false, false),
            Cyw43ForegroundFrontierRoute::Defer,
            "the grant turn cannot also poll the owner completion",
        );
        assert_eq!(
            cyw43_foreground_frontier_route(0, 0, true, true, false, false, true, false, false),
            Cyw43ForegroundFrontierRoute::Poll,
            "the following turn resumes the one-poll frontier",
        );
    }

    #[test]
    fn reciprocal_owner_completion_contract_rejects_stale_and_malformed_reads() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let sequence = 0x8000_5d11;
        let desc = sdio_bus_link_cmd52_descriptor(false, 0, SDIO_CCCR_IORX, 0)
            .expect("CMD52 read descriptor must encode");
        let command = stage_sdio_descriptor_service_command(sequence, desc);
        let mut io = TestSdioHostIo::new();
        io.command_status = SDHCI_INT_RESPONSE;
        io.command_response = 0x6d;
        let completion = service_sdio_descriptor_command_with_io(command, &mut io);
        assert_eq!(io.command_issue_count(), 1);

        let entry = Cyw43ForegroundTraceEntry {
            ticket: Cyw43ForegroundActionTicket {
                parent_sequence: 0x77,
                generation: 0x4359_5302,
                owner_sequence: sequence,
                ordinal: 0,
                issued_turn_id: 9,
            },
            command,
            descriptor: desc,
            completion: DriverTaskCompletionRecord::idle(0),
            write_offset: 0,
            write_len: 0,
            read_offset: 0,
            read_len: 0,
            read_from_owner: false,
            local_read_frame: DriverFrameDescriptor::empty(),
        };
        assert!(cyw43_foreground_completion_matches(entry, completion));

        let mut malformed = completion;
        malformed.sequence = sequence.wrapping_sub(1);
        assert!(!cyw43_foreground_completion_matches(entry, malformed));
        malformed = completion;
        malformed.result = 0;
        assert!(!cyw43_foreground_completion_matches(entry, malformed));
        malformed = completion;
        malformed.frame.offset = malformed.frame.offset.wrapping_add(1);
        assert!(!cyw43_foreground_completion_matches(entry, malformed));
        malformed = completion;
        malformed.frame.len = 0;
        assert!(!cyw43_foreground_completion_matches(entry, malformed));
        malformed = completion;
        malformed.detail = FAULT_REJECTED_COMMAND;
        assert!(!cyw43_foreground_completion_matches(entry, malformed));
        assert_eq!(
            io.command_issue_count(),
            1,
            "validation cannot reissue owner I/O"
        );
    }

    #[test]
    fn reciprocal_forced_dpc_completion_requires_its_committed_event_sequence() {
        let _guard = test_guard();
        let generation = 0x4359_d2f1;
        let owner_sequence = 0x8000_d2f1;
        initialize_production_foreground_pair(generation);
        let dpc_base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        assert_eq!(
            dpc_event_ring_publish_at(
                dpc_base,
                generation,
                0,
                0,
                DPC_REASON_SDIO_SOURCE_PENDING,
                DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
            ),
            DpcRingPublishResult::Published(1),
        );
        let descriptor = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_DPC_ACTIVATE,
            addr: generation,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_DPC_FORCE_SOURCE_PROBE,
            timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let mut command = stage_sdio_descriptor_service_command(owner_sequence, descriptor);
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
        command.aux1 = generation;
        let entry = Cyw43ForegroundTraceEntry {
            ticket: Cyw43ForegroundActionTicket {
                parent_sequence: 0x4359_d2f0,
                generation,
                owner_sequence,
                ordinal: 0,
                issued_turn_id: 1,
            },
            command,
            descriptor,
            completion: DriverTaskCompletionRecord::idle(0),
            write_offset: 0,
            write_len: 0,
            read_offset: 0,
            read_len: 0,
            read_from_owner: false,
            local_read_frame: DriverFrameDescriptor::empty(),
        };
        assert!(cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 1),
        ));
        assert!(!cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 0),
        ));
        assert!(!cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence, 2),
        ));
        assert!(!cyw43_foreground_completion_matches(
            entry,
            DriverTaskCompletionRecord::progress(owner_sequence.wrapping_add(1), 1),
        ));
    }

    #[test]
    fn non_cyw43_256_poll_drain_spends_256_endpoint_rendezvous() {
        let mut retained = endpoint_retained_gate_test_intake(0x8000_0256);
        let mut gate = RuntimePendingCommandGate::new();
        let mut admitted_polls = 0usize;
        for _ in 0..256 {
            gate.retain_after_pending();
            assert_eq!(
                gate.route_wake(
                    &mut retained,
                    RuntimeWake::Command(endpoint_retained_gate_test_intake(0x8000_0256)),
                ),
                RuntimePendingWakeRoute::ContinueForeground,
            );
            admitted_polls = admitted_polls.saturating_add(1);
            assert!(!gate.continuation_required());
        }
        assert_eq!(admitted_polls, 256);
    }

    #[test]
    fn reciprocal_sdio_trace_replays_cached_prefix_without_owner_reissue() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let desc = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_OCR,
            addr: 0,
            len: SDIO_CMD5,
            timeout_us: 100_000,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let command = stage_sdio_descriptor_service_command(0x8000_5d02, desc);
        let mut io = TestSdioHostIo::new();
        io.command_status = SDHCI_INT_RESPONSE;
        io.command_response = 0x80ff_8000;
        let completion = service_sdio_descriptor_command_with_io(command, &mut io);
        assert_eq!(io.command_issue_count(), 1);

        assert_eq!(
            cyw43_foreground_frontier_route(0, 1, false, false, false, false, true, false, false,),
            Cyw43ForegroundFrontierRoute::Cached
        );
        let replayed = completion;
        assert_eq!(replayed, completion);
        assert_eq!(io.command_issue_count(), 1, "cached replay is local only");
        assert_eq!(
            cyw43_foreground_frontier_route(1, 1, true, false, false, false, true, false, false,),
            Cyw43ForegroundFrontierRoute::Submit,
            "the cached prefix spends no physical-operation budget",
        );
        let terminal_state_committed = replayed.code == COMPLETION_PROGRESS;
        assert!(terminal_state_committed);
    }

    #[test]
    fn reciprocal_sdio_trace_rejects_mutated_fingerprint_and_issued_unknown_replay() {
        let desc = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
            function: 1,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
            addr: 0x1234,
            data_offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u16,
            len: 4,
            timeout_us: 100_000,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        let command = DriverTaskCommandRecord {
            sequence: 0x8000_5d03,
            opcode: OPCODE_SERVICE,
            flags: DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: 0,
            aux1: 0,
            budget: DriverTaskBudgetGrant {
                max_ops: 1,
                max_frames: 1,
                max_bytes: 4,
            },
            frame: DriverFrameDescriptor {
                offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
                flags: 0,
            },
        };
        let write = [1u8, 2, 3, 4];
        assert!(cyw43_foreground_action_identity_matches(
            command, desc, &write, command, desc, &write,
        ));
        let mut mutated_desc = desc;
        mutated_desc.addr ^= 1;
        let mut mutated_command = command;
        mutated_command.sequence = mutated_command.sequence.wrapping_add(1);
        let mut mutated_write = write;
        mutated_write[3] ^= 1;
        for matches in [
            cyw43_foreground_action_identity_matches(
                command,
                desc,
                &write,
                mutated_command,
                desc,
                &write,
            ),
            cyw43_foreground_action_identity_matches(
                command,
                desc,
                &write,
                command,
                mutated_desc,
                &write,
            ),
            cyw43_foreground_action_identity_matches(
                command,
                desc,
                &write,
                command,
                desc,
                &mutated_write,
            ),
        ] {
            assert!(!matches);
            assert_eq!(
                cyw43_foreground_frontier_route(
                    0, 1, true, true, false, false, matches, false, false,
                ),
                Cyw43ForegroundFrontierRoute::Poison
            );
        }
        assert_eq!(
            cyw43_foreground_frontier_route(0, 1, true, true, false, false, true, false, true),
            Cyw43ForegroundFrontierRoute::Poison,
            "issued-unknown ownership can never replay a cached or frontier action",
        );

        let destination = DriverFrameDescriptor {
            offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
            len: 4,
            flags: 0,
        };
        assert!(cyw43_foreground_read_destination_matches(
            DriverFrameDescriptor::empty(),
            destination,
        ));
        assert!(cyw43_foreground_read_destination_matches(
            destination,
            destination,
        ));
        assert!(!cyw43_foreground_read_destination_matches(
            destination,
            DriverFrameDescriptor {
                offset: destination.offset + 1,
                ..destination
            },
        ));
    }

