    #[test]
    fn runtime_init_descriptor_is_pointer_free_and_role_checked() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_GENET_NIC, ROLE_NET);

        let command = DriverTaskCommandRecord {
            sequence: 14,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_GENET_NIC,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };

        assert!(!command.frame.in_ring_payload());
        assert!(command.frame.in_runtime_init_payload());
        assert!(usize::from(command.frame.len) > MAX_DRIVER_TASK_FRAME_BYTES);
        assert_eq!(DRIVER_RUNTIME_INIT_DESCRIPTOR_APERTURE_BYTES, 1664);
        let mut wrong_offset = command.frame;
        wrong_offset.offset = wrong_offset.offset.saturating_add(1);
        assert!(!wrong_offset.in_runtime_init_payload());
        let mut wrong_len = command.frame;
        wrong_len.len = wrong_len.len.saturating_sub(1);
        assert!(!wrong_len.in_runtime_init_payload());

        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(HOT_PATH_GENET_NIC),
                command,
                descriptor
            ),
            DriverTaskCompletionRecord::progress(14, HOT_PATH_GENET_NIC)
        );

        let mut wrong_role = descriptor;
        wrong_role.role_bit = ROLE_USB;
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(HOT_PATH_GENET_NIC),
                command,
                wrong_role
            ),
            DriverTaskCompletionRecord::fault(14, FAULT_REJECTED_COMMAND)
        );
    }

