    #[test]
    fn cyw43_control_exchange_seals_parent_before_first_dpc_arbitration() {
        let _guard = test_guard();
        initialize_production_foreground_pair(1);
        arm_cyw43_control_exchange_for_test(11);
        let _production_mode = ProductionForegroundModeGuard::enter();
        let cmd = 0x17;
        let id = 38;
        let body = *b"bssid-refresh";
        let descriptor = stage_cyw43_control_exchange_request(cmd, id, 0, &body);
        let mut parent = cyw43_descriptor_command(418);
        parent.aux1 = 1;

        assert!(cyw43_foreground_pre_admit(parent));
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            assert!(transaction.parent_input_sealed);
            assert_eq!(transaction.parent, parent);
            assert_eq!(transaction.parent_descriptor, descriptor);
        });

        // Reproduce the physical Gate-8 interval: root's sequence-last op11
        // record is retained, then a watermarked DPC quantum writes its
        // disjoint front-frame and RX apertures before the first foreground
        // service quantum.
        let prompt_scratch = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
            flags: DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        assert!(prompt_scratch.valid());
        stage_cyw43_descriptor_at(DRIVER_TASK_RING_FRAME_OFFSET, prompt_scratch);
        let payload_base = usize::from(descriptor.payload_offset);
        for index in 0..usize::from(descriptor.payload_len) {
            write_runtime_payload_byte_physical(
                CYW43_RUNTIME_RX_BUFFER_OFFSET + index,
                0xa5 ^ index as u8,
            );
        }
        assert_eq!(
            read_cyw43_command_descriptor_physical(parent.frame),
            Some(descriptor),
        );
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            for index in 0..usize::from(descriptor.payload_len) {
                assert_eq!(
                    read_runtime_payload_byte_physical(payload_base + index),
                    transaction.parent_payload[index],
                    "DPC RX output cannot mutate root's sealed TX payload byte {index}",
                );
            }
        });

        assert_eq!(
            service_command_turn(0, parent),
            RuntimeCommandTurn::Pending,
            "the intake-sealed op11 parent cannot be misrouted as DPC op10 scratch",
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert!(state.control_exchange.active());
            assert_eq!(state.control_exchange.owner_generation, 1);
            assert_eq!(state.control_exchange.expected_cmd, cmd);
            assert_eq!(state.control_exchange.expected_id, id);
        });
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            assert!(transaction.active);
            assert!(transaction.frontier_valid);
            assert!(transaction.frontier_submitted);
            assert!(transaction.parent_input_sealed);
            assert_eq!(transaction.parent_descriptor, descriptor);
            for index in 0..usize::from(descriptor.payload_len) {
                assert_eq!(
                    CYW43_CONTROL_REQUEST.retained_byte(index),
                    transaction.parent_payload[index],
                    "the first private op11 cursor must snapshot the sealed parent payload",
                );
                assert_eq!(
                    read_runtime_payload_byte_physical(payload_base + index),
                    transaction.parent_payload[index],
                    "initial dispatch restores descriptor and payload as one sealed parent",
                );
            }
        });

        stage_cyw43_descriptor_at(DRIVER_TASK_RING_FRAME_OFFSET, prompt_scratch);
        assert_eq!(
            service_command_turn(0, parent),
            RuntimeCommandTurn::Pending,
            "the same seal survives publication of the first exact Function-2 child",
        );
        assert!(CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire));
        let owner_command = RuntimeRingWindow::sdio_owner()
            .and_then(|ring| runtime_ring_read_command_stable(&ring))
            .expect("the sealed parent publishes one stable owner command");
        let owner_descriptor = sdio_bus_link_read_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET)
            .expect("the sealed parent publishes one stable owner descriptor");
        assert_eq!(
            CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.load(Ordering::Acquire),
            owner_command.sequence,
        );
        assert_eq!(owner_descriptor.op, DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE);
        assert_eq!(owner_descriptor.function, 2);
        assert_eq!(owner_descriptor.addr, BACKPLANE_32BIT_FLAG);
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert!(state.control_exchange.active());
            assert_eq!(state.control_exchange.expected_id, id);
        });
        CYW43_FOREGROUND_TRANSACTION.with_ref(|transaction| {
            assert!(transaction.active);
            assert!(transaction.parent_input_sealed);
            assert_eq!(transaction.parent, parent);
            assert_eq!(transaction.parent_descriptor, descriptor);
        });
        assert!(
            !CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire),
            "physical scratch mutation cannot fault an intake-sealed continuation",
        );
    }

    #[test]
    fn cyw43_control_exchange_matches_exact_restage_without_losing_private_request() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = stage_cyw43_control_exchange_request(0x107, 41, 0, b"exact-byte-identity");
        let original = read_runtime_payload_byte(usize::from(descriptor.payload_offset));
        let mut state = Cyw43RuntimeState::new();
        assert!(cyw43_control_exchange_begin(&mut state, descriptor, 73));
        assert_eq!(CYW43_CONTROL_REQUEST.retained_byte(0), original);
        assert!(cyw43_control_exchange_owner_matches(
            state.control_exchange,
            73,
            descriptor,
        ));

        write_runtime_payload_byte(usize::from(descriptor.payload_offset), original ^ 0x80);
        assert!(
            !cyw43_control_exchange_owner_matches(state.control_exchange, 73, descriptor),
            "owner generation alone cannot admit changed payload bytes",
        );
        assert_eq!(CYW43_CONTROL_REQUEST.retained_byte(0), original);
        assert_eq!(
            CYW43_CONTROL_REQUEST.retained_len(),
            usize::from(descriptor.payload_len)
        );
        assert!(CYW43_CONTROL_REQUEST.restore(descriptor.payload_offset, descriptor.payload_len));
        assert_eq!(
            read_runtime_payload_byte(usize::from(descriptor.payload_offset)),
            original,
            "the runtime-owned snapshot restores the exact request before transmit"
        );
        assert!(cyw43_control_exchange_owner_matches(
            state.control_exchange,
            73,
            descriptor,
        ));

        state.reset_control_exchange();
        assert_eq!(state.control_exchange, Cyw43ControlExchangeCursor::idle());
        assert_eq!(CYW43_CONTROL_REQUEST.retained_len(), 0);
        assert_eq!(CYW43_CONTROL_REQUEST.retained_byte(0), 0);
    }

