        let readahead_len = cyw43_sdpcm_readahead_len(packet_len).expect("frame length rounds");
        stage_sdpcm_data_subframe(CYW43_RUNTIME_RX_BUFFER_OFFSET, &packet, 6);
        reset_test_sdio_transfer_log();
