    #[test]
    fn cyw43_asserted_empty_firstread_has_distinct_detail_and_result() {
        let source = Cyw43RxSourceSnapshot {
            probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
            interrupt_enable: SDIO_INTERRUPT_ENABLE_MASK,
            frame_indicated: true,
            host_interrupt: true,
            function2_ready: true,
            ..Cyw43RxSourceSnapshot::empty()
        };
        let reason = Cyw43RxIdleReason::FirstreadSourceAssertedEmpty {
            probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
            source,
        };

        assert!(cyw43_rx_source_asserts_pending_frame(source));
        assert_eq!(
            cyw43_rx_idle_detail(reason),
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY
        );
        assert_eq!(cyw43_rx_idle_result(reason), source.encode());
        assert!(!cyw43_rx_source_asserts_pending_frame(
            Cyw43RxSourceSnapshot::passive(CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16)
        ));
        assert!(cyw43_rx_source_retransmit_ack_seen(
            true,
            Some(HMB_DATA_NAKHANDLED)
        ));
        assert!(!cyw43_rx_source_retransmit_ack_seen(
            false,
            Some(HMB_DATA_NAKHANDLED)
        ));
        assert!(!cyw43_rx_source_retransmit_ack_seen(true, Some(0)));
    }

    #[test]
    fn cyw43_asserted_empty_retries_linux_firstread_before_block_probe() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_cyw43_engine_for_test();
        let event = *b"assoc-event";
        let frame_len = CYW43_SDPCM_HEADER_BYTES + event.len();
        stage_sdpcm_rx_header(
            CYW43_RUNTIME_RX_BUFFER_OFFSET,
            frame_len,
            CYW43_SDPCM_HEADER_BYTES,
            CYW43_SDPCM_CHANNEL_EVENT,
            4,
            false,
        );
        stage_bytes(
            CYW43_RUNTIME_RX_BUFFER_OFFSET + CYW43_SDPCM_HEADER_BYTES,
            &event,
        );
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.firmware_released = true;
        });
        reset_test_sdio_transfer_log();
        let source = Cyw43RxSourceSnapshot {
            probe_len: CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
            interrupt_enable: SDIO_INTERRUPT_ENABLE_MASK,
            frame_indicated: true,
            host_interrupt: true,
            function2_ready: true,
            ..Cyw43RxSourceSnapshot::empty()
        };

        let result = CYW43_RUNTIME_STATE.with_mut(|state| {
            cyw43_runtime_retry_asserted_empty_firstread(
                state,
                CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT,
                93,
                source,
                Cyw43AssertedEmptyPolicy::RequestRetransmit,
            )
        });

        assert_eq!(
            result,
            Some(Cyw43RxPollResult::Frame(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: event.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_EVENT, 4),
            }))
        );
        assert!(test_sdio_cmd53_read_shape_seen(
            2,
            BACKPLANE_32BIT_FLAG,
            CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
            0,
            CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16
        ));
        assert!(!test_sdio_cmd53_read_shape_seen(
            2,
            BACKPLANE_32BIT_FLAG,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
            1,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16
        ));
        assert!(!test_sdio_cmd52_write_seen(
            0,
            SDIO_CCCR_ABORT,
            SDIO_FUNCTION_NUMBER_2
        ));
        assert!(!test_sdio_cmd52_write_seen(
            1,
            SBSDIO_FUNC1_FRAMECTRL,
            SFC_RF_TERM
        ));
    }

    #[test]
    fn cyw43_asserted_empty_poll_never_falls_through_to_block_probe() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_cyw43_engine_for_test();
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.firmware_released = true;
        });
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_ienx_response(SDIO_INTERRUPT_ENABLE_MASK);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);
        test_cyw43_sdio_int_status_response(I_HMB_FRAME_IND | I_CHIPACTIVE);

        let result = CYW43_RUNTIME_STATE.with_mut(|state| {
            cyw43_runtime_poll_rx_detailed(state, CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT, 98, true)
        });
        let Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadSourceAssertedEmpty {
            probe_len,
            source,
        }) = result
        else {
            panic!("expected asserted-empty first-read idle, got {result:?}");
        };

        assert_eq!(probe_len, CYW43_CONTROL_RX_FIRSTREAD_BYTES);
        assert_eq!(
            source.encode(),
            DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_MAGIC
                | CYW43_CONTROL_RX_FIRSTREAD_BYTES as u32
                | ((SDIO_INTERRUPT_ENABLE_MASK as u32)
                    << DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_SHIFT)
                | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FRAME_INDICATED
                | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_HOST_INTERRUPT
                | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FUNCTION2_READY
        );
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert_eq!(state.rx_trace_block_reads, 0);
            assert!(state.rx_trace_firstread_reads >= 1);
        });
        assert!(test_sdio_cmd53_read_shape_seen(
            2,
            BACKPLANE_32BIT_FLAG,
            CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
            0,
            CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16
        ));
        assert!(!test_sdio_cmd53_read_shape_seen(
            2,
            BACKPLANE_32BIT_FLAG,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
            1,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16
        ));
    }

    #[test]
    fn cyw43_service_entry_nakhandled_clears_rxskip_and_relatches_frame() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.rx_retransmit_pending = true;
        state.rxskip = true;
        test_cyw43_sdio_int_status_response(I_HMB_HOST_INT);
        test_cyw43_tohost_mailbox_response(HMB_DATA_NAKHANDLED);
        reset_test_sdio_transfer_log();

        let owner = cyw43_runtime_begin_rx_service(&mut state);

        assert!(owner);
        assert!(!state.rx_retransmit_pending);
        assert!(!state.rxskip);
        assert!(state.rxpending);
        assert_ne!(state.pending_intstatus & I_HMB_FRAME_IND, 0);
        assert_ne!(
            state.rx_trace_flags & CYW43_RX_IDLE_TRACE_FLAG_RETRANSMIT_ACKED,
            0
        );
        assert_eq!(
            state.rx_trace_flags & CYW43_RX_IDLE_TRACE_FLAG_RETRANSMIT_ACK_TIMEOUT,
            0
        );
        assert_eq!(
            test_sdio_cmd53_write_addr_count(1, CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOSBMAILBOX,),
            1
        );
        assert_eq!(test_sdio_cmd53_transfer_count(2, false), 0);
    }

