    #[test]
    fn cyw43_linked_f2_tx_uses_cached_window_without_per_packet_iorx() {
        let _guard = test_guard();
        reset_runtime_for_test();
        reset_test_sdio_transfer_log();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.dpc_link_ready = true;
        state.dpc_shared_epoch = 0x4359_f201;
        state.sdpcm_seq = 7;
        state.backplane_window = CYW43_CHIPCOMMON_BASE & BACKPLANE_WINDOW_MASK;
        state.backplane_window_valid = true;
        let frame = DriverFrameDescriptor {
            offset: CYW43_SDPCM_TX_OFFSET as u32,
            len: 64,
            flags: 0,
        };
        for index in 0..usize::from(frame.len) {
            write_ring_byte(frame.offset as usize + index, index as u8);
        }

        assert_eq!(
            cyw43_function2_execute_tx_transfer_once(&mut state, frame, frame.len, 0, false, false,),
            Cyw43TxTransferResult::Submitted
        );
        assert_eq!(state.f2_tx_phase, CYW43_F2_TX_PHASE_IDLE);
        assert_eq!(
            test_sdio_transfer_count(|record| record.cmd == SDIO_CMD52),
            0,
            "a steady cache hit must not emit window or IORx commands"
        );
        assert_eq!(
            test_sdio_transfer_count(|record| record.cmd == SDIO_CMD53),
            1,
            "the steady packet lane contains only the Function 2 payload"
        );

        reset_test_sdio_transfer_log();
        state.backplane_window = 0;
        state.backplane_window_valid = true;
        for (index, expected_phase) in [
            CYW43_F2_TX_PHASE_WINDOW_MID,
            CYW43_F2_TX_PHASE_WINDOW_HIGH,
            CYW43_F2_TX_PHASE_COMMAND_READY,
        ]
        .into_iter()
        .enumerate()
        {
            assert_eq!(
                cyw43_function2_execute_tx_transfer_once(
                    &mut state, frame, frame.len, 0, false, false,
                ),
                Cyw43TxTransferResult::NotAttempted,
            );
            assert_eq!(state.f2_tx_phase, expected_phase);
            assert_eq!(
                test_sdio_transfer_total_count(),
                index + 1,
                "each cold-window phase consumes one card operation",
            );
        }
        assert_eq!(
            cyw43_function2_execute_tx_transfer_once(&mut state, frame, frame.len, 0, false, false,),
            Cyw43TxTransferResult::Submitted,
        );
        assert_eq!(
            test_sdio_transfer_count(|record| record.cmd == SDIO_CMD52),
            3,
            "a genuine cache miss programs LOW/MID/HIGH exactly once"
        );
        assert_eq!(test_sdio_cmd52_read_count(0, SDIO_CCCR_IORX), 0);
        assert_eq!(test_sdio_cmd53_transfer_count(2, true), 1);
    }

    #[test]
    fn cyw43_linked_control_and_eapol_tx_use_one_cached_window_f2_issue() {
        let _guard = test_guard();
        for (case, op) in [
            DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME,
            DRIVER_RUNTIME_CYW43_OP_ETH_TX,
        ]
        .into_iter()
        .enumerate()
        {
            reset_runtime_for_test();
            init_cyw43_engine_for_test();
            let payload_offset = cyw43_runtime_payload_offset();
            let payload: &[u8] = if op == DRIVER_RUNTIME_CYW43_OP_ETH_TX {
                &[
                    0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x88, 0xa2, 0x9e, 0x66, 0x59, 0x10, 0x88,
                    0x8e, 0x01, 0x03, 0x00, 0x00,
                ]
            } else {
                &[0x07, 0x01, 0x00, 0x00]
            };
            stage_bytes(usize::from(payload_offset), payload);
            CYW43_RUNTIME_STATE.with_mut(|state| {
                state.firmware_released = true;
                state.dpc_link_ready = true;
                state.recovery_required = false;
                state.control_startup_status_drained = true;
                state.sdpcm_seq = 17 + case as u8;
                state.sdpcm_seq_max = state.sdpcm_seq.wrapping_add(2);
                state.backplane_window = CYW43_CHIPCOMMON_BASE & BACKPLANE_WINDOW_MASK;
                state.backplane_window_valid = true;
            });
            stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
                op,
                flags: 0,
                target_addr: 0,
                payload_offset,
                payload_len: payload.len() as u16,
                total_len: payload.len() as u32,
                arg0: 0,
                arg1: 0,
                reserved: 0,
            });
            reset_test_sdio_transfer_log();
            let sequence = 690 + case as u32;
            let command = cyw43_descriptor_command(sequence);

            let completion = service_command(0, command);
            assert_eq!(completion.sequence, sequence);
            assert_eq!(completion.code, COMPLETION_PROGRESS);
            assert_eq!(
                completion.result,
                if op == DRIVER_RUNTIME_CYW43_OP_ETH_TX {
                    (CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + payload.len()) as u32
                } else {
                    (CYW43_SDPCM_HEADER_BYTES + payload.len()) as u32
                }
            );
            assert_eq!(
                test_sdio_transfer_count(|record| record.cmd == SDIO_CMD52),
                0,
                "steady control/data TX must trust the current cached window"
            );
            assert_eq!(
                test_sdio_cmd53_transfer_count(2, true),
                1,
                "typed control/EAPOL TX must publish exactly one Function 2 write"
            );
            CYW43_RUNTIME_STATE.with_ref(|state| {
                assert_eq!(state.f2_tx_phase, CYW43_F2_TX_PHASE_IDLE);
                assert_eq!(state.tx_frames, 1);
            });
        }
    }

    #[test]
    fn cyw43_function2_ready_tolerates_transient_iorx_read_failure() {
        let _guard = test_guard();
        reset_runtime_for_test();
        reset_test_sdio_transfer_log();
        cyw43_record_last_fault_with_result(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED, 0x0300_0001);
        test_sdio_cmd52_read_none_once(0, SDIO_CCCR_IORX);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1 | SDIO_FUNC_READY_2);

        let iordy = cyw43_enable_post_release_function2_poll().unwrap();

        assert_eq!(iordy & SDIO_FUNC_READY_2, SDIO_FUNC_READY_2);
        assert_eq!(cyw43_take_last_fault_detail(), None);
        assert!(test_sdio_cmd52_read_count(0, SDIO_CCCR_IORX) >= 2);
    }

    #[test]
    fn cyw43_function2_ready_timeout_does_not_toggle_ioex_in_place() {
        let _guard = test_guard();
        reset_runtime_for_test();
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_ioex_response(SDIO_FUNC_ENABLE_1);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1);

        assert_eq!(
            cyw43_enable_post_release_function2_poll(),
            Err(FAULT_CYW43_POST_RELEASE_F2_READY)
        );
        assert_eq!(
            test_sdio_transfer_count(|record| {
                record.cmd == SDIO_CMD52
                    && record.arg
                        == sdio_cmd52_arg(
                            true,
                            0,
                            SDIO_CCCR_IOEX,
                            SDIO_FUNC_ENABLE_1 | SDIO_FUNC_ENABLE_2,
                        )
            }),
            1
        );
        assert!(!test_sdio_cmd52_write_seen(
            0,
            SDIO_CCCR_IOEX,
            SDIO_FUNC_ENABLE_1
        ));
        // The bounded transfer log fills before the 3,000-poll deadline; the
        // retained fault detail carries the exact completed poll count.
        assert!(
            test_sdio_cmd52_read_count(0, SDIO_CCCR_IORX) > CYW43_SDIO_F2_READY_IORX_READ_RETRIES
        );
        assert_eq!(
            cyw43_take_last_fault_detail(),
            Some(FAULT_CYW43_POST_RELEASE_F2_READY)
        );
        assert_eq!(
            cyw43_take_last_fault_result(),
            cyw43_f2_ready_fault_detail(
                CYW43_F2_READY_DETAIL_REASON_TIMEOUT,
                0,
                CYW43_SDIO_F2_READY_FALLBACK_POLLS,
                SDIO_FUNC_ENABLE_1 | SDIO_FUNC_ENABLE_2,
                SDIO_FUNC_READY_1,
            )
        );
    }

    #[test]
    fn sdio_runtime_without_mmio_rejects_engine_init_before_register_access() {
        let _guard = test_guard();
        reset_runtime_for_test();

        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = HOT_PATH_SDIO_HOST;
        descriptor.role_bit = ROLE_SDIO;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        descriptor.shared_page_count = 1;
        descriptor.shared_pages[0] = pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000);
        descriptor.resource_range_count = 1;
        descriptor.resource_ranges[0] = DriverRuntimeResourceRangeDescriptor::new(
            DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
            DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
            DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
            DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
            0x4000_0000,
            DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
            1,
            0,
        );
        let descriptor = seal_descriptor_for_test(descriptor, HOT_PATH_SDIO_HOST);
        let runtime_init = DriverTaskCommandRecord {
            sequence: 70,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(HOT_PATH_SDIO_HOST),
                runtime_init,
                descriptor
            ),
            DriverTaskCompletionRecord::progress(70, HOT_PATH_SDIO_HOST)
        );

        let engine_init = DriverTaskCommandRecord {
            sequence: 71,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, engine_init),
            DriverTaskCompletionRecord::fault(
                71,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16
            )
        );
    }

    #[test]
    fn sdio_descriptor_helpers_encode_cmd52_and_cmd53_arguments() {
        assert_eq!(
            sdio_cmd52_arg(false, 1, 0x1234, 0),
            (1 << 28) | (0x1234 << 9)
        );
        assert_eq!(
            sdio_cmd52_arg(true, 2, 0x20, 0x5a),
            (1 << 31) | (2 << 28) | (0x20 << 9) | 0x5a
        );
        assert_eq!(
            sdio_cmd53_arg(true, 2, 0x1_0000, true, 4, 0),
            (1 << 31) | (2 << 28) | (1 << 27) | (1 << 26) | (0x1_0000 << 9) | 4
        );
        assert_eq!(
            sdio_descriptor_response_flags(DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY),
            DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
        );
    }

    #[test]
    fn cyw43_sdio_requests_use_linux_watchdog_and_derived_child_bound() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let flags = DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT
            | DRIVER_RUNTIME_SDIO_FLAG_DATA
            | DRIVER_RUNTIME_SDIO_FLAG_WRITE;
        let frame = DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u32,
            len: SDIO_FUNCTION1_BLOCK_SIZE,
            flags: 0,
        };
        for requested in [
            0,
            1,
            SDIO_OWNER_DESCRIPTOR_DEFAULT_TIMEOUT_US,
            BCM2835_SDIO_REQUEST_TIMEOUT_US,
            u32::MAX,
        ] {
            let desc = sdio_bus_link_cmd53_descriptor(
                SDIO_CMD53,
                sdio_cmd53_arg(true, 1, BACKPLANE_32BIT_FLAG, true, 1, frame.len),
                flags,
                frame,
                SDIO_FUNCTION1_BLOCK_SIZE,
                1,
                requested,
            )
            .expect("valid linked CMD53 descriptor");
            assert_eq!(desc.timeout_us, BCM2835_SDIO_REQUEST_TIMEOUT_US);
            assert!(
                cyw43_sdio_child_wait_timeout_us(desc.op, desc.timeout_us)
                    > BCM2835_SDIO_REQUEST_TIMEOUT_US
            );
        }
        assert_eq!(
            sdio_linux_request_timeout_us(BCM2835_SDIO_REQUEST_TIMEOUT_US + 1),
            BCM2835_SDIO_REQUEST_TIMEOUT_US,
            "caller-provided lifetimes cannot outrun the shared parent bound"
        );
        let expected_child_bound = (BCM2835_SDIO_REQUEST_TIMEOUT_US
            + DRIVER_RUNTIME_SDIO_INHIBIT_TIMEOUT_US)
            * SDIO_DESCRIPTOR_MAX_TRANSFER_ATTEMPTS
            + (BCM2835_SDIO_RECOVERY_TIMEOUT_MS as u32 * 1_000)
                * SDIO_DESCRIPTOR_MAX_CONTAINMENT_ATTEMPTS
            + CYW43_SDIO_CHILD_WAIT_MARGIN_US;
        assert_eq!(
            expected_child_bound,
            DRIVER_RUNTIME_CYW43_SDIO_CHILD_WORST_CASE_US,
        );
        assert_eq!(
            cyw43_sdio_child_wait_timeout_us(
                DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
                BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ),
            expected_child_bound
        );
        assert_eq!(
            sdio_bus_link_cmd52_descriptor(false, 0, SDIO_CCCR_CCCR, 0)
                .expect("valid CMD52 descriptor")
                .timeout_us,
            BCM2835_SDIO_REQUEST_TIMEOUT_US,
            "command-only operations use the same Linux request watchdog"
        );
        assert_eq!(
            sdio_bus_link_card_command_descriptor(
                SDIO_CMD5,
                SDIO_OCR_3V2_3V4,
                DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
                0,
            )
            .expect("valid raw card descriptor")
            .timeout_us,
            BCM2835_SDIO_REQUEST_TIMEOUT_US,
            "enumeration commands use the same Linux request watchdog"
        );
    }

    #[test]
    fn sdio_runtime_request_snapshot_ack_preserves_card_interrupt() {
        let upper_error = 1 << 24;
        let status = SDHCI_INT_RESPONSE
            | SDHCI_INT_DATA_AVAIL
            | SDHCI_INT_DATA_END
            | SDHCI_INT_DMA_END
            | SDHCI_INT_CARD_INT
            | SDHCI_INT_ERROR
            | upper_error;
        assert_eq!(SDHCI_INT_ALL_ERROR_MASK, 0xffff_8000);
        assert_eq!(SDHCI_INT_COMMAND_DATA_CLEAR_MASK & SDHCI_INT_CARD_INT, 0);
        assert_eq!(
            sdhci_request_snapshot_ack_bits(status),
            SDHCI_INT_RESPONSE
                | SDHCI_INT_DATA_AVAIL
                | SDHCI_INT_DATA_END
                | SDHCI_INT_DMA_END
                | SDHCI_INT_ERROR
                | upper_error
        );
        assert_ne!(SDHCI_INT_COMMAND_DATA_CLEAR_MASK & upper_error, 0);
    }

    #[test]
    fn sdio_request_irq_policy_is_exact_for_command_pio_and_external_dma() {
        let _guard = test_guard();
        let mut identity = SdioExternalDmaRequestIdentity::empty();

        identity.engine = SdioRequestEngine::CommandOnly;
        assert_eq!(
            sdhci_request_interrupt_mask(identity),
            SDHCI_INT_CMD_MASK,
            "command-only work must not signal unrelated data sources",
        );

        identity.engine = SdioRequestEngine::Pio;
        identity.write = true;
        let pio_write = sdhci_request_interrupt_mask(identity);
        assert_eq!(pio_write & SDHCI_INT_PIO_READY_MASK, SDHCI_INT_SPACE_AVAIL);
        assert_eq!(pio_write & SDHCI_INT_BCM2835_PIO_EXCLUDED_MASK, 0);
        identity.write = false;
        let pio_read = sdhci_request_interrupt_mask(identity);
        assert_eq!(pio_read & SDHCI_INT_PIO_READY_MASK, SDHCI_INT_DATA_AVAIL);
        assert_eq!(pio_read & SDHCI_INT_BCM2835_PIO_EXCLUDED_MASK, 0);

        identity.engine = SdioRequestEngine::ExternalDma;
        assert_eq!(
            sdhci_request_interrupt_mask(identity),
            SDHCI_INT_BCM2835_DMA_ENABLE_MASK,
        );

        let mut cursor = SdioExternalDmaRequestCursor {
            phase: SdioExternalDmaRequestPhase::PollIssued,
            identity,
            request_irq_live: true,
            request_irq_masked: false,
            ..SdioExternalDmaRequestCursor::idle()
        };
        let (int_enable, signal_enable) = sdio_request_interrupt_policy_registers(
            SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_CARD_INT,
            SDHCI_INT_CARD_INT,
            cursor,
        );
        assert_eq!(
            (int_enable, signal_enable),
            (
                SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_CARD_INT,
                SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_CARD_INT,
            ),
            "an armed request signals only its exact bits beside CARD_INT",
        );
        cursor.request_irq_masked = true;
        let (int_enable, signal_enable) = sdio_request_interrupt_policy_registers(
            SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_CARD_INT,
            SDHCI_INT_CARD_INT,
            cursor,
        );
        assert_eq!(
            int_enable,
            SDHCI_INT_BCM2835_DMA_ENABLE_MASK | SDHCI_INT_CARD_INT,
            "masking delivery must preserve request status latching",
        );
        assert_eq!(
            signal_enable, SDHCI_INT_CARD_INT,
            "request masking must not disturb independent CARD_INT delivery",
        );
    }

    #[test]
    fn sdio_request_irq_masks_before_ack_without_w1c_and_poll_rearms() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let generation = 0x4359_53d1;
        let identity = SdioExternalDmaRequestIdentity {
            sequence: 0x8000_53d1,
            action_fingerprint: 0x53d1_0001,
            generation,
            frame: DriverFrameDescriptor {
                offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u32,
                len: 4,
                flags: 0,
            },
            cmd: SDIO_CMD53,
            flags: DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            block_size: 4,
            block_count: 1,
            write: true,
            owner_timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            engine: SdioRequestEngine::Pio,
            ..SdioExternalDmaRequestIdentity::empty()
        };
        let request_mask = sdhci_request_interrupt_mask(identity);
        let cursor = SdioExternalDmaRequestCursor {
            phase: SdioExternalDmaRequestPhase::PollIssued,
            identity,
            deadline: RuntimeDeadline::Iterations { remaining: 32 },
            request_irq_live: true,
            request_irq_masked: false,
            issued: true,
            ..SdioExternalDmaRequestCursor::idle()
        };
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.shared_epoch = generation;
            state.irq_handler_slot = DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT;
            state.peer_notification_slot = DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT;
            state.card_irq_masked = false;
            state.external_dma_request = cursor;
        });
        let mut io = TestSdioHostIo::new();
        io.set_register(SDHCI_INT_ENABLE, request_mask | SDHCI_INT_CARD_INT);
        io.set_register(SDHCI_SIGNAL_ENABLE, request_mask | SDHCI_INT_CARD_INT);
        io.set_register(SDHCI_INT_STATUS, SDHCI_INT_RESPONSE);
        let ack_observed = core::cell::Cell::new(false);

        assert_eq!(
            sdio_partition_request_irq_with(&mut io, SDHCI_INT_RESPONSE, |io| {
                assert_eq!(
                    io.register(SDHCI_SIGNAL_ENABLE) & request_mask,
                    0,
                    "the exact request signal must be masked before IRQ ACK",
                );
                assert_eq!(
                    io.register(SDHCI_INT_STATUS),
                    SDHCI_INT_RESPONSE,
                    "the IRQ partition may not W1C request-owned status",
                );
                ack_observed.set(true);
                true
            }),
            SdioRequestIrqPartition::RequestOnlyAcked(true),
        );
        assert!(ack_observed.get());
        assert_eq!(io.register(SDHCI_INT_STATUS), SDHCI_INT_RESPONSE);
        SDIO_RUNTIME_STATE.with_ref(|state| {
            assert!(state.external_dma_request.request_irq_masked);
            assert!(state.external_dma_request.request_irq_live);
        });

        let retained = SDIO_RUNTIME_STATE.with_ref(|state| state.external_dma_request);
        assert_eq!(
            sdio_external_dma_poll_issued_with(retained, &mut io),
            RuntimeCommandTurn::Pending,
        );
        assert_eq!(
            io.register(SDHCI_INT_STATUS) & SDHCI_INT_RESPONSE,
            0,
            "only PollIssued consumes the immutable request snapshot",
        );
        assert_eq!(
            io.register(SDHCI_SIGNAL_ENABLE) & request_mask,
            request_mask,
            "a still-pending owner rearms its exact wake sources after W1C",
        );
        SDIO_RUNTIME_STATE.with_ref(|state| {
            assert!(!state.external_dma_request.request_irq_masked);
            assert!(state.external_dma_request.request_irq_live);
        });
    }

    #[test]
    fn sdio_request_and_card_irq_partition_preserves_both_owner_sources() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let generation = 0x4359_53d2;
        let mut identity = SdioExternalDmaRequestIdentity::empty();
        identity.engine = SdioRequestEngine::CommandOnly;
        identity.generation = generation;
        let request_mask = sdhci_request_interrupt_mask(identity);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.shared_epoch = generation;
            state.irq_handler_slot = DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT;
            state.peer_notification_slot = DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT;
            state.card_irq_masked = false;
            state.external_dma_request = SdioExternalDmaRequestCursor {
                phase: SdioExternalDmaRequestPhase::PollIssued,
                identity,
                request_irq_live: true,
                request_irq_masked: false,
                issued: true,
                ..SdioExternalDmaRequestCursor::idle()
            };
        });
        let status = SDHCI_INT_RESPONSE | SDHCI_INT_CARD_INT;
        let mut io = TestSdioHostIo::new();
        io.set_register(SDHCI_SIGNAL_ENABLE, request_mask | SDHCI_INT_CARD_INT);
        io.set_register(SDHCI_INT_STATUS, status);
        let ack_called = core::cell::Cell::new(false);

        assert_eq!(
            sdio_partition_request_irq_with(&mut io, status, |_| {
                ack_called.set(true);
                true
            }),
            SdioRequestIrqPartition::RequestAndCard,
        );
        assert!(
            !ack_called.get(),
            "CARD_INT publication owns the shared ACK"
        );
        assert_eq!(
            io.register(SDHCI_SIGNAL_ENABLE),
            SDHCI_INT_CARD_INT,
            "request delivery is masked while CARD_INT remains independently visible",
        );
        assert_eq!(
            io.register(SDHCI_INT_STATUS),
            status,
            "partitioning never consumes either owner's status evidence",
        );
    }

