    #[test]
    fn cyw43_firmware_stream_accepts_logical_final_tail_padding() {
        const CURRENT: u32 = 589_824;
        const LOGICAL_TAIL: u16 = 19_485;
        const TRANSPORT_TAIL: u16 = 19_488;
        const TOTAL: u32 = CURRENT + LOGICAL_TAIL as u32;
        assert_eq!(
            cyw43_stream_next_bytes(CURRENT, TOTAL, TOTAL, TRANSPORT_TAIL, LOGICAL_TAIL, true,),
            Some(TOTAL)
        );
        assert_eq!(
            cyw43_stream_next_bytes(CURRENT, TOTAL, TOTAL, TRANSPORT_TAIL, LOGICAL_TAIL, false,),
            None
        );
        assert_eq!(
            cyw43_stream_next_bytes(
                CURRENT,
                TOTAL,
                TOTAL,
                TRANSPORT_TAIL + 1,
                LOGICAL_TAIL,
                true,
            ),
            None
        );
        assert_eq!(
            cyw43_stream_next_bytes(CURRENT, TOTAL, TOTAL, TRANSPORT_TAIL, TRANSPORT_TAIL, true,),
            None
        );
    }

    #[test]
    fn cyw43_firmware_stream_rejects_nonzero_tail_padding() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let payload_offset = usize::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE);
        const LOGICAL_TAIL: u16 = 19_485;
        const TRANSPORT_TAIL: u16 = 19_488;
        for index in 0..usize::from(TRANSPORT_TAIL) {
            write_runtime_payload_byte(payload_offset + index, 0);
        }

        assert!(cyw43_runtime_payload_tail_zero(
            payload_offset,
            LOGICAL_TAIL,
            TRANSPORT_TAIL
        ));
        write_runtime_payload_byte(payload_offset + usize::from(LOGICAL_TAIL), 0x5a);
        assert!(!cyw43_runtime_payload_tail_zero(
            payload_offset,
            LOGICAL_TAIL,
            TRANSPORT_TAIL
        ));
    }

    #[test]
    fn cyw43_release_requires_nvram_tail_after_complete_streams() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.transport_ready = true;
        state.firmware_uploaded = true;
        state.nvram_uploaded = true;
        assert!(!cyw43_release_firmware(&mut state, 0, 1));

        state.release.reset();
        state.nvram_tail_uploaded = true;
        test_sdio_cmd52_read_chipclkcsr_response(SBSDIO_ALP_AVAIL | SBSDIO_HT_AVAIL);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1 | SDIO_FUNC_READY_2);
        assert!(cyw43_release_firmware(&mut state, 0, 1));
        let offset = DRIVER_RUNTIME_RING_PROGRESS_OFFSET as usize;
        assert_eq!(read_ring_u32(offset), DRIVER_RUNTIME_RING_PROGRESS_MAGIC);
        assert_eq!(read_ring_u32(offset + 4), 1);
        assert_eq!(
            read_ring_u32(offset + 8),
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_FIRMWARE_READY_DONE
        );
        assert_eq!(read_ring_u32(offset + 12), DRIVER_RUNTIME_CYW43_COMMAND_AUX);
    }

    #[test]
    fn cyw43_core_control_transplant_matches_old_good_pi4_bases() {
        assert_eq!(CYW43_D11_CORE_BASES, [0x1810_1000]);
        assert_eq!(CYW43_ARMCR4_CORE_BASE, 0x1810_2000);
        assert_eq!(CYW43_SOCRAM_CORE_BASE, 0x1810_4000);
        assert_eq!(D11_BCMA_IOCTL_PHYRESET | D11_BCMA_IOCTL_PHYCLOCKEN, 0x0c);
        assert_eq!(
            cyw43_core_reset_prepare_hold_value(ARMCR4_BCMA_IOCTL_CPUHALT),
            0x23
        );
        assert!(!cyw43_socram_core_reset_required_before_armcr4_upload());
        assert!(CYW43_ARMCR4_CONTROL_SETTLE_SPINS < CYW43_CORE_CONTROL_SETTLE_SPINS);
        assert!(cyw43_ai_core_flush_readback_accepted(Some(0x00)));
        assert!(cyw43_ai_core_flush_readback_accepted(Some(0xff)));
        assert!(!cyw43_ai_core_flush_readback_accepted(None));
        assert_eq!(
            cyw43_core_reset_release_route(Some(AI_RESETCTRL_BIT_RESET), 0),
            Cyw43CoreResetReleaseRoute::Retry
        );
        assert_eq!(
            cyw43_core_reset_release_route(Some(0), 1),
            Cyw43CoreResetReleaseRoute::Released
        );
        assert_eq!(
            cyw43_core_reset_release_route(None, 0),
            Cyw43CoreResetReleaseRoute::Uncertain
        );
        assert_eq!(
            cyw43_core_reset_release_route(
                Some(AI_RESETCTRL_BIT_RESET),
                CYW43_CORE_RESET_RELEASE_POLLS - 1,
            ),
            Cyw43CoreResetReleaseRoute::Uncertain
        );
        assert!(cyw43_card_bus_width_readback_matches(
            Some(SDIO_BUS_WIDTH_4BIT),
            SDIO_BUS_WIDTH_4BIT,
        ));
        assert!(!cyw43_card_bus_width_readback_matches(
            Some(0),
            SDIO_BUS_WIDTH_4BIT,
        ));
        let bcm2835_high_speed_control = sdio_bcm2835_host_control_for_flags(
            0,
            DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT
                | DriverRuntimeSdioCommandDescriptor::FLAG_HOST_HIGH_SPEED,
        );
        assert_eq!(bcm2835_high_speed_control, SDHCI_HOST_CONTROL_4BIT);
        assert!(sdio_host_control_readback_matches(
            SDHCI_HOST_CONTROL_4BIT,
            bcm2835_high_speed_control,
        ));
        assert!(!sdio_host_control_readback_matches(
            SDHCI_HOST_CONTROL_4BIT | SDHCI_HOST_CONTROL_HIGH_SPEED,
            bcm2835_high_speed_control,
        ));
    }

    #[test]
    fn cyw43_armcr4_reset_uses_only_function1_cmd52_control_bytes() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.backplane_window = CYW43_ARMCR4_CORE_BASE & BACKPLANE_WINDOW_MASK;
        state.backplane_window_valid = true;
        reset_test_sdio_transfer_log();

        assert!(cyw43_core_reset(
            &mut state,
            CYW43_ARMCR4_CORE_BASE,
            ARMCR4_BCMA_IOCTL_CPUHALT,
            0,
            0,
        ));

        let ioctrl_addr = (CYW43_ARMCR4_CORE_BASE + AI_IOCTRL_OFFSET) & BACKPLANE_ADDRESS_MASK;
        let reset_addr = (CYW43_ARMCR4_CORE_BASE + AI_RESETCTRL_OFFSET) & BACKPLANE_ADDRESS_MASK;
        let ai_cmd52 = |record: TestSdioTransferRecord| {
            record.cmd == SDIO_CMD52
                && ((record.arg >> 28) & 0x7) == 1
                && matches!((record.arg >> 9) & 0x1ffff, addr if addr == ioctrl_addr || addr == reset_addr)
        };
        assert!(test_sdio_transfer_count(ai_cmd52) >= 8);
        assert_eq!(
            test_sdio_transfer_count(|record| {
                record.cmd == SDIO_CMD53
                    && matches!(sdio_cmd53_arg_addr(record.arg), addr if addr == ioctrl_addr || addr == reset_addr)
            }),
            0
        );
        assert!(test_sdio_transfer_seen(|record| {
            record.cmd == SDIO_CMD52
                && record.arg
                    == sdio_cmd52_arg(
                        true,
                        1,
                        ioctrl_addr,
                        ARMCR4_BCMA_IOCTL_CPUHALT | AI_CORE_PRERESET_IOCTRL,
                    )
        }));
        assert!(test_sdio_transfer_seen(|record| {
            record.cmd == SDIO_CMD52
                && record.arg == sdio_cmd52_arg(true, 1, reset_addr, AI_RESETCTRL_BIT_RESET)
        }));
        assert!(test_sdio_transfer_seen(|record| {
            record.cmd == SDIO_CMD52 && record.arg == sdio_cmd52_arg(false, 1, ioctrl_addr, 0)
        }));
        assert!(state.firmware_execution_started);
    }

