    #[test]
    fn cyw43_release_preserves_upload_lane_without_post_activation_mutation() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.transport_ready = true;
        state.firmware_uploaded = true;
        state.nvram_uploaded = true;
        state.nvram_tail_uploaded = true;
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_chipclkcsr_response(SBSDIO_ALP_AVAIL | SBSDIO_HT_AVAIL);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1 | SDIO_FUNC_READY_2);

        assert!(cyw43_release_firmware(&mut state, 0xb83e_f198, 3));

        assert!(!test_sdio_transfer_seen(|record| {
            record.cmd == SDIO_CMD52
                && record.arg == sdio_cmd52_arg(true, 0, SDIO_CCCR_IF, SDIO_BUS_WIDTH_4BIT)
        }));
        let write_index = |addr: u32| {
            test_sdio_first_transfer_index(|record| {
                record.cmd == SDIO_CMD53
                    && record.arg
                        == sdio_cmd53_arg(true, 1, cyw43_backplane_function_addr(addr), true, 0, 4)
            })
            .expect("release write must be present")
        };
        let intstatus = write_index(CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS);
        let reset_vector = write_index(CYW43_FIRMWARE_RESET_VECTOR_ADDR);
        let arm_reset_assert = test_sdio_first_transfer_index(|record| {
            record.cmd == SDIO_CMD52
                && record.arg
                    == sdio_cmd52_arg(
                        true,
                        1,
                        (CYW43_ARMCR4_CORE_BASE + AI_RESETCTRL_OFFSET) & BACKPLANE_ADDRESS_MASK,
                        AI_RESETCTRL_BIT_RESET,
                    )
        })
        .expect("release ARMCR4 reset assert must be present");
        assert!(intstatus < reset_vector);
        assert!(reset_vector < arm_reset_assert);
        // The host test build intentionally stubs the target-only SD-only/HT
        // transaction sequence. Its production request remains the pure Linux
        // HT_AVAIL_REQ value; the observable ordering guarantee here is that
        // no card-width or host-clock mutation follows ARM activation.
        assert_eq!(cyw43_post_release_ht_request_value(), SBSDIO_HT_AVAIL_REQ);
        assert!(state.firmware_execution_started);
    }

    #[test]
    fn sdio_transfer_mode_encodes_generic_multiblock_requests() {
        let byte_write = sdio_transfer_mode(true, 1);
        assert_ne!(byte_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(byte_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(byte_write & SDHCI_TRNS_READ, 0);

        let byte_read = sdio_transfer_mode(false, 1);
        assert_ne!(byte_read & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(byte_read & SDHCI_TRNS_READ, 0);

        let single_write = sdio_transfer_mode(true, 1);
        assert_ne!(single_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(single_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(single_write & SDHCI_TRNS_READ, 0);

        let multiblock_write = sdio_transfer_mode(true, 23);
        assert_ne!(multiblock_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(multiblock_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(multiblock_write & SDHCI_TRNS_READ, 0);

        let multiblock_read = sdio_transfer_mode(false, 23);
        assert_ne!(multiblock_read & SDHCI_TRNS_MULTI, 0);
        assert_ne!(multiblock_read & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn sdio_retained_join_fence_defers_asserted_card_int_before_issue() {
        let _guard = test_guard();
        let generation = 0x4359_6801;
        initialize_production_foreground_pair(generation);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_link_ready = true;
            state.irq_handler_slot = DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT;
            state.peer_notification_slot = DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT;
            state.dpc_activation_allowed = true;
            state.card_irq_masked = false;
        });
        let _production_mode = ProductionForegroundModeGuard::enter();
        sdio_record_dpc_health(false);
        let data_offset = CYW43_SDIO_BUS_LINK_DATA_OFFSET;
        for index in 0..64 {
            write_runtime_payload_byte(data_offset + index, 0x5a ^ index as u8);
        }
        let descriptor = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
            function: 2,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
            addr: BACKPLANE_32BIT_FLAG,
            data_offset: data_offset as u16,
            len: 64,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT
                | DriverRuntimeSdioCommandDescriptor::FLAG_PRE_TX_DPC_FENCE,
            timeout_us: BCM2835_SDIO_REQUEST_TIMEOUT_US,
            ..DriverRuntimeSdioCommandDescriptor::empty()
        };
        assert!(descriptor.valid());
        let sequence = 0x8000_6801;
        let command = stage_sdio_descriptor_service_command(sequence, descriptor);
        let mut io = TestSdioHostIo::new();
        io.use_runtime_payload = true;
        let (int_enable, signal_enable) = sdio_interrupt_policy_registers(true, false);
        io.set_register(SDHCI_INT_ENABLE, int_enable);
        io.set_register(SDHCI_SIGNAL_ENABLE, signal_enable);
        io.set_register(SDHCI_INT_STATUS, SDHCI_INT_CARD_INT);

        let completion = drive_sdio_retained_descriptor_for_test(command, descriptor, &mut io);
        let expected = sdio_transfer_failure_result(
            SDIO_TRANSFER_FAILURE_STAGE_PREISSUE_DPC_FENCE,
            SDHCI_INT_CARD_INT,
        );

        assert_eq!(
            completion,
            DriverTaskCompletionRecord::fault_with_result(
                sequence,
                FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
                expected,
            )
        );
        assert_eq!(completion.frame, DriverFrameDescriptor::empty());
        assert_eq!(io.command_issue_count(), 0);
        assert_eq!(io.dma_started, 0);
        assert_eq!(io.sdhci_buffer_accesses, 0);
        assert_eq!(io.register(SDHCI_INT_STATUS), SDHCI_INT_CARD_INT);
        assert!(
            io.writes[..io.write_count]
                .iter()
                .filter(|write| write.offset == SDHCI_INT_STATUS)
                .all(|write| write.value & SDHCI_INT_CARD_INT == 0),
            "the not-issued terminal must leave CARD_INT for DPC_ACTIVATE",
        );
        assert_eq!(
            io.register(SDHCI_INT_ENABLE) & SDHCI_INT_PIO_READY_MASK,
            0,
            "the temporary PIO source must be removed before the child terminal",
        );
        assert!(!SDIO_RUNTIME_STATE
            .with_ref(|state| { state.external_dma_request.active() || state.dpc_poisoned }));
        assert!(!CYW43_SDIO_PAIR_RESTART_REQUIRED.load(Ordering::Acquire));
        assert_eq!(sdio_last_transfer_failure(), expected);
    }

