    #[test]
    fn sdio_descriptor_production_seam_executes_cmd52_read_and_write_once() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let data_offset = CYW43_SDIO_BUS_LINK_DATA_OFFSET;
        let read_addr = SDIO_CCCR_IORX;
        let read_desc = sdio_bus_link_cmd52_descriptor(false, 0, read_addr, 0)
            .expect("CMD52 read descriptor must encode");
        let read_command = stage_sdio_descriptor_service_command(0x5201, read_desc);
        let mut read_io = TestSdioHostIo::new();
        read_io.use_runtime_payload = true;
        read_io.command_status = SDHCI_INT_RESPONSE;
        read_io.command_response = 0x5a;

        let read_completion = service_sdio_descriptor_command_with_io(read_command, &mut read_io);

        assert_eq!(
            read_completion,
            DriverTaskCompletionRecord::frame_ready_at(0x5201, data_offset as u32, 1)
        );
        assert_eq!(read_runtime_payload_byte(data_offset), 0x5a);
        assert_eq!(
            read_io.register(SDHCI_ARGUMENT),
            sdio_cmd52_arg(false, 0, read_addr, 0)
        );
        assert_eq!(read_io.command_issue_count(), 1);
        assert!(sdio_owner_path_quiescent_with(&mut read_io));

        let write_addr = SBSDIO_DEVICE_CTL;
        let write_value = 0x34;
        write_runtime_payload_byte(data_offset, write_value);
        let write_desc = sdio_bus_link_cmd52_descriptor(true, 1, write_addr, 0)
            .expect("CMD52 write descriptor must encode");
        let write_command = stage_sdio_descriptor_service_command(0x5202, write_desc);
        let mut write_io = TestSdioHostIo::new();
        write_io.use_runtime_payload = true;
        write_io.command_status = SDHCI_INT_RESPONSE;

        let write_completion =
            service_sdio_descriptor_command_with_io(write_command, &mut write_io);

        assert_eq!(
            write_completion,
            DriverTaskCompletionRecord::progress(0x5202, 1)
        );
        assert_eq!(
            write_io.register(SDHCI_ARGUMENT),
            sdio_cmd52_arg(true, 1, write_addr, write_value)
        );
        assert_eq!(write_io.command_issue_count(), 1);
        assert!(sdio_owner_path_quiescent_with(&mut write_io));
        assert_eq!(SDIO_CMD_COUNT.load(Ordering::Acquire), 2);
        assert_eq!(SDIO_RUNTIME_STATE.with_ref(|state| state.commands), 2);
    }

    #[test]
    fn sdio_retained_owner_acks_response_before_reading_r5_once() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let data_offset = CYW43_SDIO_BUS_LINK_DATA_OFFSET;
        let descriptor = sdio_bus_link_cmd52_descriptor(false, 0, SDIO_CCCR_SPEED, 0)
            .expect("CCCR SPEED read descriptor must encode");
        let command = stage_sdio_descriptor_service_command(0x5203, descriptor);
        let mut io = TestSdioHostIo::new();
        io.use_runtime_payload = true;
        io.command_status = SDHCI_INT_RESPONSE | SDHCI_INT_CARD_INT;
        io.command_response = u32::from(SDIO_CCCR_SPEED_SHS);
        io.command_response_visible_after_ack = true;

        let completion = service_sdio_descriptor_command_with_io(command, &mut io);

        assert_eq!(
            completion,
            DriverTaskCompletionRecord::frame_ready_at(command.sequence, data_offset as u32, 1,),
        );
        assert_eq!(read_runtime_payload_byte(data_offset), SDIO_CCCR_SPEED_SHS,);
        assert_eq!(io.command_issue_count(), 1);
        assert_eq!(
            io.response_reads_before_ack, 0,
            "the retained owner must not consume RESPONSE before its request W1C completes",
        );
        assert_eq!(
            io.response_reads_after_ack, 1,
            "one immutable response edge admits exactly one post-W1C RESPONSE read",
        );
        assert_eq!(
            io.register(SDHCI_INT_STATUS),
            SDHCI_INT_CARD_INT,
            "the independent CARD_INT owner remains live",
        );
        assert!(io.writes[..io.write_count]
            .iter()
            .filter(|write| write.offset == SDHCI_INT_STATUS)
            .all(|write| write.value & SDHCI_INT_CARD_INT == 0));
        assert!(sdio_owner_path_quiescent_with(&mut io));
    }

    #[test]
    fn sdio_owner_reciprocal_pullup_clear_is_exactly_once_per_pair_lifetime() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        let data_offset = CYW43_SDIO_BUS_LINK_DATA_OFFSET;
        let first_generation = 0x4359_5301;
        SDIO_RUNTIME_STATE.with_mut(|state| state.shared_epoch = first_generation);
        write_runtime_payload_byte(data_offset, 0);
        let descriptor = sdio_bus_link_cmd52_descriptor(true, 1, SBSDIO_FUNC1_SDIOPULLUP, 0)
            .expect("Linux pull-up clear descriptor must encode");
        let mut first_io = TestSdioHostIo::new();
        first_io.use_runtime_payload = true;
        first_io.command_status = SDHCI_INT_RESPONSE;

        let first = service_sdio_descriptor_command_with_io(
            stage_sdio_descriptor_service_command(0x5210, descriptor),
            &mut first_io,
        );
        assert_eq!(first, DriverTaskCompletionRecord::progress(0x5210, 1));
        assert_eq!(first_io.command_issue_count(), 1);

        let duplicate = service_sdio_descriptor_command_with_io(
            stage_sdio_descriptor_service_command(0x5211, descriptor),
            &mut first_io,
        );
        assert_eq!(
            duplicate,
            DriverTaskCompletionRecord::fault(0x5211, FAULT_REJECTED_COMMAND)
        );
        assert_eq!(first_io.command_issue_count(), 1);

        let next_generation = dpc_generation_next(first_generation);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.reset();
            state.shared_epoch = next_generation;
        });
        let mut next_io = TestSdioHostIo::new();
        next_io.use_runtime_payload = true;
        next_io.command_status = SDHCI_INT_RESPONSE;
        let next = service_sdio_descriptor_command_with_io(
            stage_sdio_descriptor_service_command(0x5212, descriptor),
            &mut next_io,
        );
        assert_eq!(next, DriverTaskCompletionRecord::progress(0x5212, 1));
        assert_eq!(next_io.command_issue_count(), 1);

        let next_duplicate = service_sdio_descriptor_command_with_io(
            stage_sdio_descriptor_service_command(0x5213, descriptor),
            &mut next_io,
        );
        assert_eq!(
            next_duplicate,
            DriverTaskCompletionRecord::fault(0x5213, FAULT_REJECTED_COMMAND)
        );
        assert_eq!(next_io.command_issue_count(), 1);
    }

    #[test]
    fn cyw43_pullup_clear_crosses_real_runtime_ring_controller_seam_once() {
        let _guard = test_guard();
        let pullup_arg = sdio_cmd52_arg(true, 1, SBSDIO_FUNC1_SDIOPULLUP, 0);

        reset_sdio_descriptor_seam_for_test();
        init_cyw43_engine_for_test();
        reset_test_sdio_transfer_log();
        let sequence = 0x5220;
        let generation = 0x4359_5320;
        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        });
        let command = cyw43_descriptor_command(sequence);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.transport_ready = false;
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_HOST_READY;
            state.dpc_shared_epoch = generation;
            state.backplane_attach.parent_sequence = sequence;
            state.backplane_attach.generation = generation;
            state.backplane_attach.phase = Cyw43BackplaneAttachPhase::PullupClear;
            state.backplane_attach.poisoned = false;
        });
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.shared_epoch = generation;
            state.dpc_poisoned = false;
            state.pullup_clear_generation = generation;
            state.pullup_clear_admitted = false;
        });
        {
            let _bridge = enable_real_sdio_controller_bridge();
            assert_eq!(
                service_command_turn(0, command),
                RuntimeCommandTurn::Pending
            );
            assert_eq!(TEST_REAL_SDIO_CONTROLLER_ISSUES.load(Ordering::Acquire), 1);
            assert_eq!(
                test_sdio_transfer_count(|record| {
                    record.cmd == SDIO_CMD52 && record.arg == pullup_arg
                }),
                1
            );
            CYW43_RUNTIME_STATE.with_ref(|state| {
                assert_eq!(
                    state.backplane_attach.phase,
                    Cyw43BackplaneAttachPhase::ChipCommonRead
                );
                assert!(!state.backplane_attach.poisoned);
            });
        }

        reset_sdio_descriptor_seam_for_test();
        init_cyw43_engine_for_test();
        reset_test_sdio_transfer_log();
        let failed_sequence = sequence + 1;
        let failed_generation = generation + 1;
        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        });
        let failed_command = cyw43_descriptor_command(failed_sequence);
        CYW43_RUNTIME_STATE.with_mut(|state| {
            state.transport_ready = false;
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_HOST_READY;
            state.dpc_shared_epoch = failed_generation;
            state.backplane_attach.parent_sequence = failed_sequence;
            state.backplane_attach.generation = failed_generation;
            state.backplane_attach.phase = Cyw43BackplaneAttachPhase::PullupClear;
            state.backplane_attach.poisoned = false;
        });
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.shared_epoch = failed_generation;
            state.dpc_poisoned = false;
            state.pullup_clear_generation = failed_generation;
            state.pullup_clear_admitted = false;
        });
        let _bridge = enable_real_sdio_controller_bridge();
        fail_real_sdio_controller_next_arg_with_r5(pullup_arg, SDIO_R5_ERROR);
        let failure = match service_command_turn(0, failed_command) {
            RuntimeCommandTurn::Complete(completion) => completion,
            RuntimeCommandTurn::Pending => panic!("a rejected pull-up clear must fail closed"),
        };
        assert_eq!(failure.code, COMPLETION_FAULT);
        assert_eq!(TEST_REAL_SDIO_CONTROLLER_ISSUES.load(Ordering::Acquire), 1);
        CYW43_RUNTIME_STATE.with_ref(|state| {
            assert!(state.backplane_attach.poisoned);
            assert!(state.recovery_required);
        });
        assert!(matches!(
            service_command_turn(0, failed_command),
            RuntimeCommandTurn::Complete(_)
        ));
        assert_eq!(
            TEST_REAL_SDIO_CONTROLLER_ISSUES.load(Ordering::Acquire),
            1,
            "a poisoned generation must not replay the controller action"
        );
        assert_eq!(
            test_sdio_transfer_count(|record| {
                record.cmd == SDIO_CMD52 && record.arg == pullup_arg
            }),
            1
        );
    }

    #[test]
    fn sdio_owner_marks_quiesced_command_fault_contained_without_authorizing_replay() {
        let _guard = test_guard();
        reset_sdio_descriptor_seam_for_test();
        SDIO_RUNTIME_STATE.with_mut(|state| state.shared_epoch = 0x4359_52f1);
        let sequence = 0x52f1;
        write_runtime_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET, 0);
        let descriptor = sdio_bus_link_cmd52_descriptor(true, 1, SBSDIO_FUNC1_SDIOPULLUP, 0)
            .expect("Linux pull-up clear descriptor must encode");
        let command = stage_sdio_descriptor_service_command(sequence, descriptor);
        let mut io = TestSdioHostIo::new();
        io.use_runtime_payload = true;
        io.command_status = SDHCI_INT_DATA_CRC;

        let completion = service_sdio_descriptor_command_with_io(command, &mut io);

        assert_eq!(completion.code, COMPLETION_FAULT);
        assert_eq!(completion.detail, FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED);
        assert_eq!(
            completion.result,
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_COMMAND, SDHCI_INT_DATA_CRC,)
        );
        assert_eq!(
            completion.frame.flags,
            DRIVER_RUNTIME_SDIO_FAULT_FRAME_FLAG_CONTAINED
        );
        assert_eq!(io.command_issue_count(), 1);
        assert!(sdio_owner_path_quiescent_with(&mut io));
        assert!(!SDIO_RUNTIME_STATE.with_ref(|state| state.dpc_poisoned));
    }

