    #[test]
    fn usb_dma_descriptor_translates_noncontiguous_scratchpad_tail_page() {
        let mut descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        assert!(usize::from(USB_REQUIRED_DMA_PAGES) <= DRIVER_RUNTIME_INIT_MAX_DMA_PAGES);
        assert_eq!(
            descriptor.dma_page_count,
            pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_DMA_PAGES as u16
        );
        for index in 0..usize::from(USB_REQUIRED_DMA_PAGES) {
            descriptor.dma_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x2000_0000 + index * 0x2000);
        }
        for index in 0..usize::from(descriptor.resource_range_count) {
            if descriptor.resource_ranges[index].kind == DRIVER_RUNTIME_RESOURCE_KIND_DMA {
                descriptor.resource_ranges[index].flags &=
                    !DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS;
            }
        }
        let dma_range = runtime_resource_range(
            &descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )
        .expect("USB descriptor must carry DMA arena range");
        let tail_offset = XHCI_DMA_SCRATCHPAD_OFFSET
            + (XHCI_MAX_SCRATCHPAD_BUFFERS - 1) * DRIVER_TASK_RING_PAGE_BYTES;
        let tail_page = tail_offset / DRIVER_TASK_RING_PAGE_BYTES;
        let expected_paddr = 0x2000_0000 + tail_page * 0x2000;

        assert_eq!(
            xhci_dma_bus_addr(&descriptor, dma_range, tail_offset),
            Some(runtime_bus_addr(&descriptor, expected_paddr as u64))
        );
    }

    #[test]
    fn usb_dma_zero_turn_advances_exactly_one_bounded_chunk() {
        let _guard = test_guard();
        reset_runtime_for_test();
        // SAFETY: `test_guard` serializes the process-local DMA fixture.
        unsafe {
            (*TEST_DMA_BUFFER.0.get()).fill(0xa5);
        }

        let next = xhci_zero_dma_turn(
            1,
            DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX,
            DRIVER_TASK_DMA_BUFFER_VADDR,
            0,
        );

        assert_eq!(next, XHCI_DMA_ZERO_DIAGNOSTIC_CHUNK_BYTES);
        assert_eq!(read_dma_byte(DRIVER_TASK_DMA_BUFFER_VADDR), 0);
        assert_eq!(
            read_dma_byte(DRIVER_TASK_DMA_BUFFER_VADDR + XHCI_DMA_ZERO_DIAGNOSTIC_CHUNK_BYTES - 1),
            0
        );
        assert_eq!(
            read_dma_byte(DRIVER_TASK_DMA_BUFFER_VADDR + XHCI_DMA_ZERO_DIAGNOSTIC_CHUNK_BYTES),
            0xa5
        );
    }

    #[test]
    fn usb_controller_init_cursor_seals_the_complete_parent_command() {
        let command = DriverTaskCommandRecord {
            sequence: 0x5555,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_USB_KEYBOARD,
            arg1: ROLE_USB,
            aux0: DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        let cursor = UsbControllerInitCursor::engine_init(command);
        assert!(cursor.active_for(command));
        assert!(!cursor.active_for(DriverTaskCommandRecord {
            sequence: command.sequence.wrapping_add(1),
            ..command
        }));
        assert!(!cursor.active_for(DriverTaskCommandRecord {
            budget: DriverTaskBudgetGrant {
                max_ops: command.budget.max_ops.saturating_add(1),
                ..command.budget
            },
            ..command
        }));
    }

    #[test]
    fn usb_controller_init_rejects_identity_change_before_another_phase() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_runtime_for_test(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let command = DriverTaskCommandRecord {
            sequence: 0x5656,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_USB_KEYBOARD,
            arg1: ROLE_USB,
            aux0: DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };

        assert_eq!(
            service_command_turn(0, command),
            RuntimeCommandTurn::Pending
        );
        assert_eq!(
            service_command_turn(
                0,
                DriverTaskCommandRecord {
                    sequence: command.sequence.wrapping_add(1),
                    ..command
                }
            ),
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                command.sequence.wrapping_add(1),
                FAULT_REJECTED_COMMAND
            ))
        );
        assert!(!USB_CONTROLLER_INIT_CURSOR.with_ref(UsbControllerInitCursor::active));
    }

    #[test]
    fn usb_hub_topology_helpers_encode_route_tt_and_speed() {
        let root_hub = UsbEnumerationDevice {
            slot: 1,
            root_port: 2,
            speed: XHCI_SPEED_HIGH,
            ..UsbEnumerationDevice::empty()
        };
        let mut second_hub = root_hub.child(3, XHCI_SPEED_HIGH);
        second_hub.slot = 2;
        assert_eq!(second_hub.route, 0x00003);
        assert_eq!(second_hub.depth, 1);
        assert_eq!(second_hub.parent_hub_slot, 1);
        assert_eq!(second_hub.parent_hub_port, 3);

        let keyboard = second_hub.child_with_hub_info(
            4,
            XHCI_SPEED_FULL,
            UsbHubInfo {
                interface: 0,
                protocol: 0,
                ports: 4,
                multi_tt: false,
                power_mode: 0,
                pwr_on_2_pwr_good: 50,
                tt_think_time: 3,
            },
        );
        assert_eq!(keyboard.route, 0x00043);
        assert_eq!(keyboard.root_port, 2);
        assert_eq!(keyboard.parent_hub_slot, 2);
        assert_eq!(keyboard.parent_hub_port, 4);
        assert_eq!(keyboard.parent_tt_port, 1);
        assert_eq!(keyboard.parent_tt_think_time, 2);
        assert_eq!(
            xhci_address_tt_info(&keyboard),
            2 | (1 << XHCI_SLOT_TT_PORT_SHIFT)
        );
        assert_eq!(xhci_address_tt_info(&keyboard) & 0x0003_0000, 0);
        assert_eq!(usb_normalize_hub_tt_profile(4, false, 3), (1, 2));
        assert_eq!(usb_normalize_hub_tt_profile(4, true, 3), (4, 2));
        let multi_tt_keyboard = second_hub.child_with_hub_info(
            4,
            XHCI_SPEED_FULL,
            UsbHubInfo {
                interface: 0,
                protocol: USB_HUB_PROTOCOL_HIGH_SPEED_MULTI_TT,
                ports: 4,
                multi_tt: true,
                power_mode: 0,
                pwr_on_2_pwr_good: 50,
                tt_think_time: 3,
            },
        );
        assert_eq!(multi_tt_keyboard.parent_tt_port, 4);
        assert_eq!(multi_tt_keyboard.parent_tt_think_time, 2);
        assert_eq!(
            xhci_address_tt_info(&multi_tt_keyboard),
            2 | (4 << XHCI_SLOT_TT_PORT_SHIFT)
        );
        assert_eq!(xhci_address_tt_info(&multi_tt_keyboard) & 0x0003_0000, 0);
        assert_eq!(
            usb_hub_speed_from_status(USB_HUB_STATUS_LOW_SPEED),
            XHCI_SPEED_LOW
        );
        assert_eq!(
            usb_hub_speed_from_status(USB_HUB_STATUS_HIGH_SPEED),
            XHCI_SPEED_HIGH
        );
        assert_eq!(usb_hub_speed_from_status(0), XHCI_SPEED_FULL);
        assert_eq!(xhci_default_control_packet(XHCI_SPEED_LOW), 8);
        assert_eq!(xhci_default_control_packet(XHCI_SPEED_FULL), 64);
        assert_eq!(xhci_default_control_packet(XHCI_SPEED_HIGH), 64);
        assert_eq!(
            xhci_control_packet_candidates(XHCI_SPEED_LOW),
            ([8, 0, 0], 1)
        );
        assert_eq!(
            xhci_control_packet_candidates(XHCI_SPEED_FULL),
            ([64, 8, 0], 2)
        );
        assert_eq!(
            xhci_control_packet_candidates(XHCI_SPEED_SUPER),
            ([512, 64, 0], 2)
        );
        assert_eq!(
            usb_hub_port_index_candidates(7, 4),
            ([0x0004, 0x0704, 0x0104, 0x0204, 0x0304], 5)
        );
        assert_eq!(
            usb_hub_port_index_candidates(0, 4),
            ([0x0004, 0x0104, 0x0204, 0x0304, 0x0000], 4)
        );
    }

    #[test]
    fn usb_hub_port_control_fallback_matches_uboot_apple_stall_policy() {
        let apple_keyboard_hub = UsbEnumerationDevice {
            vendor_id: USB_VENDOR_ID_APPLE,
            product_id: USB_DEVICE_ID_APPLE_KEYBOARD_HUB,
            ..UsbEnumerationDevice::empty()
        };
        let generic_hub = UsbEnumerationDevice::empty();

        assert!(usb_hub_control_should_try_fallback(
            &apple_keyboard_hub,
            XhciControlTransferOutcome::Failed {
                code: XHCI_COMPLETION_STALL_ERROR
            }
        ));
        assert!(!usb_hub_control_should_try_fallback(
            &generic_hub,
            XhciControlTransferOutcome::Failed {
                code: XHCI_COMPLETION_STALL_ERROR
            }
        ));
        assert!(!usb_hub_control_should_try_fallback(
            &apple_keyboard_hub,
            XhciControlTransferOutcome::Failed { code: 4 }
        ));
        assert!(!usb_hub_control_should_try_fallback(
            &apple_keyboard_hub,
            XhciControlTransferOutcome::PendingData
        ));
        assert!(!usb_hub_control_should_try_fallback(
            &apple_keyboard_hub,
            XhciControlTransferOutcome::PendingStatus
        ));
        assert!(!usb_hub_control_should_try_fallback(
            &apple_keyboard_hub,
            XhciControlTransferOutcome::Complete(4)
        ));
    }

    #[test]
    fn usb_xhci_reset_wait_matches_uboot_handshake_shape() {
        assert_eq!(USB_XHCI_RESET_WAIT_TIMEOUT_MS, 5_000);
        assert_eq!(USB_XHCI_RESET_WAIT_POLLS, 1_000_000);
        assert_eq!(USB_XHCI_RESET_WAIT_SETTLE_SPINS, 512);
        assert_eq!(USB_XHCI_RESET_ATTEMPTS, 3);
        assert!(USB_XHCI_RESET_WAIT_POLLS < PCIE_POLL_SPINS);
        assert!(
            runtime_millis_to_cycles_at_hz(USB_XHCI_RESET_WAIT_TIMEOUT_MS, 54_000_000)
                > runtime_legacy_spins_to_cycles_at_hz(250_000 * 512, 54_000_000)
        );
        assert_eq!(usb_xhci_reset_command_value(0), XHCI_USBCMD_HCRST);
        assert_eq!(
            usb_xhci_reset_command_value(XHCI_USBCMD_RUN | 0x0000_0040),
            XHCI_USBCMD_HCRST | 0x0000_0040
        );
    }

