    #[test]
    fn usb_ep0_transfer_ring_wrap_republishes_link_before_cycle_toggle() {
        let _guard = test_guard();
        let base = DRIVER_TASK_DMA_BUFFER_VADDR + XHCI_DMA_COMMAND_RING_OFFSET;
        let ring_bus = 0x1200_4000;
        zero_dma_range(base, XHCI_COMMAND_RING_BYTES);

        let mut enqueue = (XHCI_COMMAND_RING_TRBS - 2) as u16;
        let mut cycle = true;
        assert!(xhci_advance_transfer_ring(
            base,
            ring_bus,
            &mut enqueue,
            &mut cycle
        ));

        let link = read_xhci_trb(base, XHCI_COMMAND_RING_TRBS - 1);
        assert_eq!(link.parameter, ring_bus);
        assert_eq!(link.status, 0);
        assert_eq!(link.control, xhci_transfer_ring_link_control(true));
        assert_eq!(enqueue, 0);
        assert!(!cycle);
    }

    #[test]
    fn usb_keyboard_interrupt_ring_wrap_republishes_link_before_cycle_toggle() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let dma_range = runtime_resource_range(
            &descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )
        .expect("USB descriptor has DMA arena");
        let kbd_base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
        let kbd_ring = xhci_dma_bus_addr(&descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET).unwrap();
        zero_dma_range(kbd_base, XHCI_COMMAND_RING_BYTES);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 4;
        state.keyboard_endpoint_id = 3;
        state.kbd_enqueue = (XHCI_COMMAND_RING_TRBS - 2) as u16;
        state.kbd_cycle = true;

        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));

        let link = read_xhci_trb(kbd_base, XHCI_COMMAND_RING_TRBS - 1);
        assert_eq!(link.parameter, kbd_ring);
        assert_eq!(link.status, 0);
        assert_eq!(link.control, xhci_transfer_ring_link_control(true));
        assert_eq!(state.kbd_enqueue, 0);
        assert!(!state.kbd_cycle);
        assert_eq!(state.keyboard_reports_queued, 1);
        assert_eq!(
            state.keyboard_report_trb_indices[0],
            (XHCI_COMMAND_RING_TRBS - 2) as u16
        );
    }

    #[test]
    fn usb_control_setup_stage_can_be_queued_inactive_until_td_is_ready() {
        let active = xhci_control_setup_stage_control(XHCI_TRB_TRANSFER_TYPE_IN, true);
        let inactive = xhci_control_setup_stage_control(XHCI_TRB_TRANSFER_TYPE_IN, false);

        assert_ne!(active & XHCI_TRB_CYCLE, 0);
        assert_eq!(inactive & XHCI_TRB_CYCLE, 0);
        assert_eq!(active & !XHCI_TRB_CYCLE, inactive & !XHCI_TRB_CYCLE);
    }

    #[test]
    fn usb_hub_status_uses_uboot_style_data_stage_interrupt_policy() {
        let default_control = xhci_control_data_stage_control(true, true, true);
        assert_ne!(default_control & XHCI_TRB_IOC, 0);
        assert_ne!(default_control & XHCI_TRB_ISP, 0);
        assert_ne!(default_control & XHCI_TRB_DIR_IN, 0);

        let hub_status_control = xhci_control_data_stage_control(true, false, true);
        assert_eq!(hub_status_control & XHCI_TRB_IOC, 0);
        assert_ne!(hub_status_control & XHCI_TRB_ISP, 0);
        assert_ne!(hub_status_control & XHCI_TRB_DIR_IN, 0);
        assert_eq!(
            hub_status_control & (XHCI_TRB_TYPE_DATA_STAGE << 10),
            XHCI_TRB_TYPE_DATA_STAGE << 10
        );
    }

    #[test]
    fn usb_control_transfer_completion_requires_status_stage_event() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 64,
            data_stage_event_expected: true,
        };
        let data_event = XhciTrb {
            parameter: plan.data_trb | 0x0c,
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 16,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, data_event, false),
            XhciControlTransferEvent::DataStage { transferred: 48 }
        );

        let setup_event = XhciTrb {
            parameter: plan.setup_trb | 0x04,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_event, false),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_event, true),
            XhciControlTransferEvent::Ignore
        );

        let status_event = XhciTrb {
            parameter: plan.status_trb | 0x08,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, status_event, true),
            XhciControlTransferEvent::Complete
        );

        let failed_status = XhciTrb {
            status: 2 << 24,
            ..status_event
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, failed_status, true),
            XhciControlTransferEvent::Fail { code: 2 }
        );
    }

    #[test]
    fn usb_control_transfer_accepts_same_ep_zero_remaining_status_completion() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0,
            status_trb: 0x4010,
            data_len: 0,
            data_stage_event_expected: false,
        };
        let pointer_mismatch_status = XhciTrb {
            parameter: 0x4050,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, false),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, true),
            XhciControlTransferEvent::Complete
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 2, pointer_mismatch_status, true),
            XhciControlTransferEvent::Ignore
        );
        let partial_event = XhciTrb {
            status: (XHCI_COMPLETION_SUCCESS << 24) | 4,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, partial_event, true),
            XhciControlTransferEvent::Ignore
        );
    }

    #[test]
    fn usb_control_transfer_accepts_same_ep_bounded_data_pointer_mismatch() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 64,
            data_stage_event_expected: true,
        };
        let pointer_mismatch_data = XhciTrb {
            parameter: 0x4050,
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 16,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_data, false),
            XhciControlTransferEvent::DataStage { transferred: 48 }
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_data, true),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 2, pointer_mismatch_data, false),
            XhciControlTransferEvent::Ignore
        );
        let impossible_remaining = XhciTrb {
            status: (XHCI_COMPLETION_SUCCESS << 24) | 65,
            ..pointer_mismatch_data
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, impossible_remaining, false),
            XhciControlTransferEvent::Ignore
        );
        let setup_echo = XhciTrb {
            parameter: plan.setup_trb | 0x08,
            status: XHCI_COMPLETION_SUCCESS << 24,
            ..pointer_mismatch_data
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_echo, false),
            XhciControlTransferEvent::Ignore
        );
    }

    #[test]
    fn usb_hub_status_no_data_ioc_accepts_zero_remaining_status_pointer_mismatch() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 4,
            data_stage_event_expected: false,
        };
        let pointer_mismatch_status = XhciTrb {
            parameter: 0x4050,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, false),
            XhciControlTransferEvent::Complete
        );

        let data_pointer_status = XhciTrb {
            parameter: plan.data_trb | 0x08,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, data_pointer_status, false),
            XhciControlTransferEvent::Complete
        );

        let setup_echo = XhciTrb {
            parameter: plan.setup_trb | 0x08,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_echo, false),
            XhciControlTransferEvent::Complete
        );

        let short_packet_data = XhciTrb {
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 2,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, short_packet_data, false),
            XhciControlTransferEvent::DataStage { transferred: 2 }
        );

        let data_ioc_plan = XhciControlTransferPlan {
            data_stage_event_expected: true,
            ..plan
        };
        assert_eq!(
            xhci_classify_control_transfer_event(
                data_ioc_plan,
                3,
                1,
                pointer_mismatch_status,
                false,
            ),
            XhciControlTransferEvent::DataStage { transferred: 4 }
        );
        assert_eq!(
            xhci_classify_control_transfer_event(data_ioc_plan, 3, 1, data_pointer_status, false),
            XhciControlTransferEvent::DataStage { transferred: 4 }
        );
    }

